--[[
	Midnight Helper — Dungeon Coach boss-step bodies, ALL SIX locales
	(fase 6, 12 Jun: deDE/frFR/esES/ptBR toegevoegd — 129 keys ×6).
	Line breaks |n.

	Phase 3, batch 1: Windrunner Spire + Maisara Caverns (Normal difficulty).
	Own MH text in beginner language, cross-referenced against BossHelper
	(MIT) and DungeonHelper on Rob's machine; to be verified by Rob in
	follower runs before this ships in a release. Spell names stay in English
	(proper names policy).

	Batch 2 (11 Jun): the remaining six Season 1 dungeons (Murder Row, Den of
	Nalorakk, The Blinding Vale, Voidscar Arena, Nexus-Point Xenas, Magisters'
	Terrace). Source: DBM-Party-Midnight mods (spell IDs, voice cues, comments)
	cross-checked against Wowhead spell tooltips — every mechanical claim
	traces to one of those two. Not yet run in-game; same verification status
	as batch 1 before Rob's follower runs.

	Batch 3 (11 Jun): the four legacy Season 1 dungeons via DBM-Party-WoD/
	WotLK/Legion/Dragonflight (IsPostMidnight branch = Midnight revamp spells)
	+ Wowhead tooltips.

	{SPELL:id} markup (11 Jun, Robs DungeonHelper-vergelijk): ability-namen
	zijn {SPELL:<id>}-tokens — DelveTipMarkup rendert ze als klikbare,
	client-gelokaliseerde [Spell]-links met hover-tooltip; de live coach
	print ze klikbaar in chat en /mh bossshare verstuurt kale namen.
	Spell-IDs komen uit de DBM-mods (zelfde bron als de mechanics).
	Namen zonder zeker ID blijven platte tekst.
]]

local _, ns = ...

local function merge(target, patch)
	if not target or not patch then
		return
	end
	for k, v in pairs(patch) do
		target[k] = v
	end
end

merge(ns._mhLocales and ns._mhLocales.enUS, {
	-- Windrunner Spire ---------------------------------------------------------
	DGN_TIP_WS_DUO_STEPS = "1. Two bosses — damage them evenly so they die around the same time.|n2. Interrupt Shadow Bolt; step out of the spew circles ({SPELL:472745}) — don't waste floor space.|n3. Cursed ({SPELL:474105})? Have it dispelled fast — or crowd-control the Dark Entity it spawns until it fades.|n4. Hooked by {SPELL:472793} during the shriek? Position so you get pulled THROUGH the ghost lady — that breaks her cast.",
	DGN_TIP_WS_DUO_TANK = "Tank: defensive for {SPELL:472888}; move the bosses when the floor gets cluttered.",
	DGN_TIP_WS_DUO_HEALER = "Healer: big group damage during {SPELL:472736}; dispel {SPELL:474105} quickly.",

	DGN_TIP_WS_EMBER_STEPS = "1. Fire = bad. Drop the fire puddles ({SPELL:466556}) at the edges, keep the middle clean.|n2. At full energy run TO the boss for {SPELL:465904}, then sidestep every Fire Breath.|n3. Old puddles spawn fire twisters — keep dodging.",
	DGN_TIP_WS_EMBER_TANK = "Tank: defensive for {SPELL:466064}.",
	DGN_TIP_WS_EMBER_HEALER = "Healer: heavy group damage during {SPELL:465904}.",

	DGN_TIP_WS_KROLUK_STEPS = "1. Brown circles = bad, step out.|n2. Stack with an ally before {SPELL:1253026} finishes (overlap the purple circles).|n3. Fixated or leaped at ({SPELL:1283247})? Run it away from the group.|n4. When adds spawn (about two thirds and one third health): kill them fast — the Phantasmal Mystic first, and keep interrupting it.",
	DGN_TIP_WS_KROLUK_TANK = "Tank: defensive for {SPELL:467620}; be ready to pick up the second {SPELL:1283247}.",
	DGN_TIP_WS_KROLUK_HEALER = "Healer: group damage during {SPELL:472043}.",

	DGN_TIP_WS_HEART_STEPS = "1. {SPELL:1216042} stacks ticking on you? Step on a windy arrow (Turbulent Arrow) at 2-3 stacks — it clears the DoT and jumps you over the expanding shockwave.|n2. Keep one arrow free for the big blast at full energy ({SPELL:468429}).|n3. Spread a little for {SPELL:1253979} and use the big circles to clear the electric ground.|n4. Targeted by {SPELL:474528}? Stand still and let the others move out; everyone else: step out of the frontal.",
	DGN_TIP_WS_HEART_TANK = "Tank: defensive for {SPELL:472662}; aim the knockback away from the puddles.",
	DGN_TIP_WS_HEART_HEALER = "Healer: top up players with high {SPELL:1216042} stacks first; extra healing after {SPELL:1253979}.",

	-- Maisara Caverns ------------------------------------------------------------
	DGN_TIP_MC_MUROJIN_STEPS = "1. Two bosses (hunter and bird) — kill them close together, or the survivor goes berserk.|n2. Ice traps ({SPELL:1243741}), green circles ({SPELL:1243900}) and the frontal {SPELL:1260643} = bad, stay out.|n3. Targeted by {SPELL:1249478} (the bird dive)? Run INTO an ice trap — the freeze stops the dive. Everyone else: get away from that player.",
	DGN_TIP_MC_MUROJIN_TANK = "Tank: defensive for {SPELL:1266480}.",
	DGN_TIP_MC_MUROJIN_HEALER = "Healer: dispel {SPELL:1246666} (disease) — heavy group damage.",

	DGN_TIP_MC_VORDAZA_STEPS = "1. The boss spawns Unstable Phantoms ({SPELL:1251204}) that chase players. KILL them before they reach anyone — a phantom that reaches its target (or touches another phantom) bursts for heavy damage nearby.|n2. Each phantom killed screams: unavoidable group damage — so kill them ONE at a time.|n3. Dodge {SPELL:1252054}'s frontal surge (it pushes you away), the floating orbs and Soulrot.|n4. Someone wrapped in a Deathshroud? Break them out fast; interrupt {SPELL:1250708} and dodge the swirls during it.",
	DGN_TIP_MC_VORDAZA_TANK = "Tank: defensive for {SPELL:1251554}.",
	DGN_TIP_MC_VORDAZA_HEALER = "Healer: each slain phantom screams ({SPELL:1251813}) = group damage — heal between staggered kills.",

	DGN_TIP_MC_RAKTUL_STEPS = "1. The boss leaps at three players ({SPELL:1252676}) and leaves Soulbind Totems — spread so the totems land apart, don't get crushed, and kill the totems fast.|n2. Stay out of the Chill of Death ground.|n3. Soul phase ({SPELL:1253788}): you're pulled out of your body — crowd-control and interrupt the big adds while you run back to your body.|n4. Dodge the swirls from the Deathgorged Vessel.",
	DGN_TIP_MC_RAKTUL_TANK = "Tank: defensive for {SPELL:1251023}; place the puddles away from the group.",
	DGN_TIP_MC_RAKTUL_HEALER = "Healer: heavy group damage during Deathgorged Vessel and when totems shatter.",

	-- Murder Row (batch 2 — geverifieerd via DBM-Party-Midnight + Wowhead) ------
	DGN_TIP_MR_KYSTIA_STEPS = "1. Kill Nibbles first. Kystia has a fel shield and takes almost no damage while Nibbles is above 20% health.|n2. At 20% Nibbles turns on Kystia with {SPELL:1230304}: Kystia is stunned and takes a lot more damage for a short time. Switch to Kystia now and use your big cooldowns.|n3. {SPELL:1264095}: copies of Kystia appear and cast Felstorm. Interrupt, stun or crowd-control every copy.|n4. Stay out of Nibbles' {SPELL:1253811} cone and out of the fire it leaves on the ground.|n5. On Heroic and harder: {SPELL:474240} - she jumps to a player and explodes. Move away from her.",
	DGN_TIP_MR_KYSTIA_QUICK_DPS = "Hit the pet first, then the boss when the pet is low.",
	DGN_TIP_MR_KYSTIA_QUICK_HEALER = "Remove the spit debuff from players fast, and save a big heal for the switch.",
	DGN_TIP_MR_KYSTIA_QUICK_TANK = "Point the pet's fire cone away from the group.",
	DGN_TIP_MR_KYSTIA_QUICK = "Pet first: Hit the pet Nibbles first. The boss has a shield and takes almost no damage.|nSwitch: When Nibbles is low, she stuns the boss. Now hit the boss hard.|nCopies: Copies of the boss appear. Kick or stun every one.",
	DGN_TIP_MR_KYSTIA_TANK = "Tank: Face Nibbles' {SPELL:1253811} cone away from the group. Keep Kystia and Nibbles close together so your group can cleave both. Kystia's Chaos Barrage hits you hard, so keep a defensive ready.",
	DGN_TIP_MR_KYSTIA_HEALER = "Healer: Dispel Corroding Spittle (magic) quickly, most of all during {SPELL:1264095}. Save a healing cooldown for the burn window after {SPELL:1230304}: the stunned Kystia sends fel bursts at the group.",

	DGN_TIP_MR_ZAEN_STEPS = "1. Crates fall on players ({SPELL:474765}). Step out of the markers. The crates that land are your cover.|n2. {SPELL:1218347}: he aims at everyone he can see. Hide behind a crate before he fires, so he cannot see you. Everyone needs their own crate.|n3. Got {SPELL:1214357}? The bomb explodes after 6 seconds and destroys crates near you. Move it away from the crates you need for cover.|n4. {SPELL:474478}: 3 seconds of heavy damage on the whole group. Be at full health.|n5. On Mythic and Mythic+: green fel crates (Fel-Infused Freight) hurt the whole group all the time. If you have {SPELL:1214357}, take it to a green crate to destroy it, and keep the plain crates.",
	DGN_TIP_MR_ZAEN_QUICK_DPS = "Be behind a crate before the big shot, not after.",
	DGN_TIP_MR_ZAEN_QUICK_HEALER = "Remove the poison from the tank, and have everyone full before the gunfire.",
	DGN_TIP_MR_ZAEN_QUICK_TANK = "Use a defensive when he stabs you, and get the poison removed.",
	DGN_TIP_MR_ZAEN_QUICK = "Crates: Crates fall from the sky. Step out, then use them as walls.|nShot: When he aims at everyone, hide behind a crate so he cannot see you.|nBomb: Got the bomb? Carry it away from the crates you hide behind.",
	DGN_TIP_MR_ZAEN_TANK = "Tank: Use a defensive for {SPELL:1222795}. It also leaves Heartstop Poison, which lowers your max health: get it dispelled or clear it yourself.",
	DGN_TIP_MR_ZAEN_HEALER = "Healer: Dispel Heartstop Poison from the tank after {SPELL:1222795}. Top everyone up before {SPELL:474478}, and heal the bleed on anyone the shot hit.",

	DGN_TIP_MR_XATHUUX_STEPS = "1. {SPELL:1214637}: he throws his axe at a player. If it is you, stand near the boss but away from others. The axe stays and zaps everyone harder and harder: kill it fast.|n2. Infernal Crush ({SPELL:1295452}): circles appear under players. Spread out so you do not hit each other.|n3. {SPELL:474197}: damage on everyone, then for 15 seconds he attacks faster and takes 30% more damage. Use your cooldowns now.|n4. During the rage he leaves fire where he walks ({SPELL:474234}). Stay out of it. The tank walks him slowly along the edge of the room.",
	DGN_TIP_MR_XATHUUX_QUICK_DPS = "Kill the axe first, and save your big attacks for the rage.",
	DGN_TIP_MR_XATHUUX_QUICK_HEALER = "Plan a big heal for the rage, and have the tank full before the big swing.",
	DGN_TIP_MR_XATHUUX_QUICK_TANK = "Use a defensive for his big swing, and walk him slowly along the edge when he rages.",
	DGN_TIP_MR_XATHUUX_QUICK = "Axe: He throws his axe. Put it next to the boss and break it fast.|nCircles: Spread out when circles appear under you.|nRage: When he gets angry he takes more damage. Hit hard and stay out of his fire trail.",
	DGN_TIP_MR_XATHUUX_TANK = "Tank: Use a defensive for {SPELL:473898}; it cuts your healing taken for 8 seconds. Face him away from the group and move him onto the axe so it gets cleaved. During {SPELL:474197}, walk him slowly along the edge so the fire stays out of the middle.",
	DGN_TIP_MR_XATHUUX_HEALER = "Healer: {SPELL:474197} and Infernal Crush often come close together, so plan a cooldown. The tank takes much less healing after {SPELL:473898}; have them topped before it. Every second the axe lives, the group takes more damage.",

	DGN_TIP_MR_LITHIEL_STEPS = "1. Interrupt every Chaos Bolt. Agree on a kick order.|n2. {SPELL:1218203}: circles land on players. Spread 6 yards. Each circle makes Wild Imps: stun or kick them and kill them together.|n3. {SPELL:474408}: a big demon arrives. The tank picks it up, everyone kills it.|n4. {SPELL:1224478}: a fel fire wave rolls through the room. Kill all demons before it reaches them, or they get much faster. Take the Demonic Gateway so the wave misses you; if it hits you, you take more fire damage.|n5. On Mythic and Mythic+: an Infernal chases the tank. It cannot be killed and touching it can kill you. The tank keeps it away from the group and the gateway.",
	DGN_TIP_MR_LITHIEL_QUICK_DPS = "Kick the boss and the imps, and kill all demons before the wave.",
	DGN_TIP_MR_LITHIEL_QUICK_HEALER = "Everyone takes fire damage all fight. Heal anyone the wave hit first.",
	DGN_TIP_MR_LITHIEL_QUICK_TANK = "Grab the demons fast. On Mythic, lead the Infernal away from everyone.",
	DGN_TIP_MR_LITHIEL_QUICK = "Kicks: Stop every Chaos Bolt the boss casts.|nImps: Spread out. Little demons pop out. Stun them and kill them fast.|nWave: Kill all demons before the fire wave, then take the portal so it misses you.",
	DGN_TIP_MR_LITHIEL_TANK = "Tank: Pick up the Vilefiend fast, it hits you hard. Keep the Wild Imps together so they can be cleaved. On Mythic, kite the Infernal away from the group and never near the gateway.",
	DGN_TIP_MR_LITHIEL_HEALER = "Healer: The whole fight has constant fire damage on the group. Anyone hit by {SPELL:1224478} keeps burning and takes more fire damage: heal them first.",

	-- Den of Nalorakk -----------------------------------------------------------
	DGN_TIP_DN_HOARDMONGER_STEPS = "1. {SPELL:1234233}: he throws rotten food for a few seconds. Dodge the hits. Green Rotten Mushrooms then grow on the floor.|n2. Step on every mushroom before it bursts (about 12 seconds). Spread out so none is missed. Each mushroom gives you a poison, so take turns.|n3. {SPELL:1253268} is a frontal cone. Step out of the area it shows. {SPELL:1235118} hits the whole group, so stay topped up.|n4. Three times he runs to a pile of meat, bones or mushrooms and gets a new move. Meat makes his roar stronger. Bones give a slam that leaves broken bones on the floor ({SPELL:1235405}): stay off them. Mushrooms mean more mushrooms to step on.|n5. On Mythic and Mythic+: every new move stays for the rest of the fight, so they add up. Guides take meat first, bones second, mushrooms last.",
	DGN_TIP_DN_HOARDMONGER_QUICK_DPS = "Help step on the mushrooms, and take turns with the others.",
	DGN_TIP_DN_HOARDMONGER_QUICK_HEALER = "Heal big when he roars, and take the poison off the mushroom soakers if you can.",
	DGN_TIP_DN_HOARDMONGER_QUICK_TANK = "Park the boss next to the pile you want: meat, then bones, then mushrooms.",
	DGN_TIP_DN_HOARDMONGER_QUICK = "Mushrooms: Step on the green mushrooms before they pop, and take turns.|nSlam: The boss hits the ground in front of him. Step out of that area.|nPiles: He grabs food from a pile and gets a new trick. Stay off the bones he leaves.",
	DGN_TIP_DN_HOARDMONGER_TANK = "Tank: He runs to the nearest pile, so park him next to the one you want: meat first, bones second, mushrooms last. Keep the bone patches away from where the group stands.",
	DGN_TIP_DN_HOARDMONGER_HEALER = "Healer: Use a healing cooldown on {SPELL:1235118}: it ignores armor and hits everyone. Mushroom soakers get a poison (Toxic Spores): dispel it if your class can, and keep them topped up.",

	DGN_TIP_DN_SENTINEL_STEPS = "1. {SPELL:1235623}: small tornadoes land and wander the room for a long time. Stand together so they drop in one spot, then move away from them.|n2. {SPELL:1235783}: two icicles crash down. Step out of the circles. Each one leaves a Fractured Shivercore add.|n3. The adds cast Winter's Shroud. Interrupt it: every cast makes the whole group take more frost damage. A dead add leaves a Snowdrift: deep snow that slows you, but nothing can move you while you stand in it.|n4. {SPELL:1235656}: a big storm hits everyone and moves players around. Kill one add just before it and stand in its Snowdrift until the storm ends. Then kill the other add.|n5. On Mythic and Mythic+: a dying add drops ice shards (Rimeshatter). Put exactly one player in each shard circle. A missed shard hits the whole group and roots everyone.",
	DGN_TIP_DN_SENTINEL_QUICK_DPS = "Take turns stopping the adds' casts, and kill the first add just before the storm.",
	DGN_TIP_DN_SENTINEL_QUICK_HEALER = "Take the frost debuff off fast, and heal everyone during the storm.",
	DGN_TIP_DN_SENTINEL_QUICK_TANK = "Put the boss on top of one add, and keep him away from the tornadoes.",
	DGN_TIP_DN_SENTINEL_QUICK = "Tornadoes: Stand together so they land in one spot, then walk away.|nAdds: Two ice adds appear. Stop their cast, and kill one just before the storm.|nStorm: Stand in the snow the dead add leaves. Then the storm cannot move you.",
	DGN_TIP_DN_SENTINEL_TANK = "Tank: Drag the boss onto one add so the group cleaves it, and keep the boss clear of the tornadoes. Help interrupt Winter's Shroud.",
	DGN_TIP_DN_SENTINEL_HEALER = "Healer: {SPELL:1235548} is a magic frost damage-over-time: dispel it fast, and heal the ones you cannot dispel. The storm hits everyone, so be ready to heal the group.",

	DGN_TIP_DN_NALORAKK_STEPS = "1. {SPELL:1242860}: three players get a mark. Walk to the edge before it ends: a ghost bear (an Echo) appears where you stand. Put all Echoes together, away from the group. Echoes hurt anyone near them every time he mauls.|n2. {SPELL:1243011}: Nalorakk knocks Zul'jarra down and every Echo charges at her. Stand around her like a wall and block the charges. An Echo that reaches her hurts the whole group.|n3. {SPELL:1243569}: Nalorakk hits the tank again and again. Zul'jarra puts up a shield that halves this damage: everyone stands behind her shield.|n4. Right after that, the tank alone steps into Forceful Slam. Everyone else steps out. If it hits Zul'jarra instead, the whole group takes damage.|n5. On Mythic and Mythic+: blocking an Echo also gives you a bleed that stacks (Spectral Slash). Put one player in each charge lane, and never let two people block the same Echo.",
	DGN_TIP_DN_NALORAKK_QUICK_DPS = "Stand in the path of a ghost bear, one person per bear.",
	DGN_TIP_DN_NALORAKK_QUICK_HEALER = "Heal the tank hard during the big hits, and top everyone up before the roar.",
	DGN_TIP_DN_NALORAKK_QUICK_TANK = "Hide behind her shield, then take the next slam alone.",
	DGN_TIP_DN_NALORAKK_QUICK = "Marks: If you get a mark, walk to the edge. A ghost bear appears there.|nCharge: The ghost bears run at Zul'jarra. Stand in their way to stop them.|nShield: When the boss hits the tank many times, everyone hides behind her shield.",
	DGN_TIP_DN_NALORAKK_TANK = "Tank: {SPELL:1243569} is on you. Stand behind Zul'jarra's shield and use a defensive. Then step alone into Forceful Slam, away from the group.",
	DGN_TIP_DN_NALORAKK_HEALER = "Healer: The tank takes big hits during {SPELL:1243569}, then Forceful Slam. Top the group up before Forceful Roar. On Mythic+, watch the bleed stacks on the players who block Echoes.",

	-- The Blinding Vale -----------------------------------------------------------
	DGN_TIP_BV_TRINITY_STEPS = "1. The three bosses share one health bar. The tank stacks them together and everyone hits all three. Kick Kezkitt's Light Bolt.|n2. {SPELL:1234753} hits the tank and leaves three green circles. Do not stand in them yet. Lekshi then dashes through all three circles ({SPELL:1234850}) - stay out of that line.|n3. When {SPELL:1235564} starts, one player stands in each circle (the tank plus two others) until the beam ends. An empty circle makes the whole group take big damage later.|n4. After the beam the circles turn into burning ground ({SPELL:1235828}). Step out; the tank moves the bosses to clean ground. {SPELL:1261276} makes a random player bleed: use a defensive or clear the bleed.|n5. On Mythic and Mythic+: after Thornblade, Lekshi jumps to that player and sprays thorns around them. That player moves away from the group, then runs out of the thorns. Bedrock Slam also sends pulses of damage through the whole group.",
	DGN_TIP_BV_TRINITY_QUICK_DPS = "Hit all three bosses together, and kick Kezkitt's bolt.",
	DGN_TIP_BV_TRINITY_QUICK_HEALER = "Keep the players in the circles alive, and heal the player who bleeds.",
	DGN_TIP_BV_TRINITY_QUICK_TANK = "Use a defensive on the big slam, then move the three bosses off the burning ground.",
	DGN_TIP_BV_TRINITY_QUICK = "Three bosses: They share one health bar. Stack them and hit all three.|nCircles: When the beam comes, one player stands in each circle until it stops.|nDash: Stay out of the line between the circles, and leave the circles when they burn.",
	DGN_TIP_BV_TRINITY_TANK = "Tank: Use a defensive for {SPELL:1234753}. Keep the three stacked for cleave, stand in one circle during the beam, then move the bosses off the burning ground before the next slam.",
	DGN_TIP_BV_TRINITY_HEALER = "Healer: The three circle soakers take ticking damage - keep them up, and heal the {SPELL:1261276} bleed. On Mythic, save a cooldown for the group pulses after Bedrock Slam.",

	DGN_TIP_BV_IKUZZ_STEPS = "1. {SPELL:1236746} hits everyone and knocks you back. Stand so you do not fly off an edge or into roots.|n2. {SPELL:1236709}: he roars and hurts the whole group for 6 seconds. Use a defensive if you are low.|n3. {SPELL:1237091}: he chases one player for 10 seconds. That player runs and leads him over the roots on the ground - his steps crush them. If he catches you, you bleed and get stunned ({SPELL:1272290}).|n4. From 50% health he frenzies: he moves faster and hurts the group all the time. Save cooldowns for this.|n5. On Mythic and Mythic+: after the stomp, roots grab every player a few seconds later, and more roots grow during the roar. Move back to the boss so the group can cleave the roots, or use a freedom spell.",
	DGN_TIP_BV_IKUZZ_QUICK_DPS = "Break the roots fast, and if he chases you, run over the roots.",
	DGN_TIP_BV_IKUZZ_QUICK_HEALER = "Save your big heals for when he is at half health.",
	DGN_TIP_BV_IKUZZ_QUICK_TANK = "Keep the boss close to players stuck in roots, so everyone can break them.",
	DGN_TIP_BV_IKUZZ_QUICK = "Stomp: He knocks everyone back. Do not stand near an edge.|nChase: He chases one player. That player runs over the roots so he crushes them.|nHalf health: He gets faster and hits harder. Use your big spells now.",
	DGN_TIP_BV_IKUZZ_TANK = "Tank: Keep Ikuzz close to rooted players so everyone can cleave the roots, and away from edges for the knockback.",
	DGN_TIP_BV_IKUZZ_HEALER = "Healer: The stomp and {SPELL:1236709} hit the whole group. Save your big cooldowns for the 50% frenzy, above all when he roars during it. A caught player takes big damage - top them fast.",

	DGN_TIP_BV_RUIA_STEPS = "1. Moonkin form (100 to 70%): kick Warden's Wrath - it hits the tank. Dodge the {SPELL:1240098} circles.|n2. {SPELL:1239825} marks a few players. Move away from the group before it ends: beams then shoot out from you. Stay out of the beams - they silence you.|n3. Bear form (70 to 40%): {SPELL:1240222} marks a few players and fires cones at them. Marked players spread and keep their cone off others. A second hit hurts much more.|n4. {SPELL:1241058} makes players bleed until they are healed to full health.|n5. At 40% health, {SPELL:1241067}: he casts all of this every 8 seconds until he dies. Use your cooldowns and Bloodlust here.",
	DGN_TIP_BV_RUIA_QUICK_DPS = "Kick his spell in moonkin form, and save your big spells for 40 percent.",
	DGN_TIP_BV_RUIA_QUICK_HEALER = "A bleeding player keeps bleeding until you heal them all the way up.",
	DGN_TIP_BV_RUIA_QUICK_TANK = "Make sure his spell gets kicked in moonkin form, and use defensives in bear form.",
	DGN_TIP_BV_RUIA_QUICK = "Moonkin: Kick his spell, dodge the circles, and walk away from the group if you get the beam mark.|nBear: If you are marked, move away so your cone hits nobody else.|n40%: He does everything at once. Use your big spells now.",
	DGN_TIP_BV_RUIA_TANK = "Tank: In moonkin form his melee is replaced by Warden's Wrath - make sure it gets kicked. In bear form his melee hits twice as hard (Mangling Claws), so use your defensives there.",
	DGN_TIP_BV_RUIA_HEALER = "Healer: {SPELL:1241058} only stops when a player is at full health - heal one target to full, then the next. Save cooldowns for the 40% phase.",

	DGN_TIP_BV_ZIEKKET_STEPS = "1. {SPELL:1246372}: lashers sprout. The tank gathers them; everyone cleaves them and kicks Lightspore Shot.|n2. A lasher at 1% health sinks into the ground and cannot be hurt. It wakes up stronger at the next {SPELL:1246372}, and then it cannot be kicked or stunned.|n3. {SPELL:1253690} aims a beam at a player. If it is you, turn so the beam runs through every sleeping lasher - that kills them for good. It leaves slowing pools ({SPELL:1246753}); step out of them.|n4. {SPELL:1247685} hits the tank hard, knocks back and bleeds. The whole group takes pulsing damage all fight.|n5. On Mythic and Mythic+: {SPELL:1246858} sends orbs toward Ziekket. Step into them before they reach him, and share them out (about two or three each) - each orb gives you a stacking damage-over-time. An orb that reaches him hurts the group and shields him.",
	DGN_TIP_BV_ZIEKKET_QUICK_DPS = "Kick the lashers' shots, and stop hitting a lasher once it sleeps.",
	DGN_TIP_BV_ZIEKKET_QUICK_HEALER = "The whole group takes damage all fight, so keep healing everyone.",
	DGN_TIP_BV_ZIEKKET_QUICK_TANK = "Gather the lashers together, and use a defensive on the big spike hit.",
	DGN_TIP_BV_ZIEKKET_QUICK = "Lashers: Hit them until they sink into the ground. Then they sleep.|nBeam: If the beam aims at you, point it through the sleeping lashers. That kills them for good.|nMythic orbs: Touch the glowing balls before they reach the boss, and share them out.",
	DGN_TIP_BV_ZIEKKET_TANK = "Tank: Gather each lasher wave for cleave, near the edge. Use a defensive for {SPELL:1247685} - it knocks you back and bleeds. Move out of the Lightsap pools.",
	DGN_TIP_BV_ZIEKKET_HEALER = "Healer: The group takes damage all fight, so keep healing everyone. On Mythic, watch the orb soakers - their stacks hurt, and a missed orb hits the whole group.",

	-- Voidscar Arena ----------------------------------------------------------------
	DGN_TIP_VA_TAZRAH_STEPS = "1. {SPELL:1222098}: a shade dashes through each player in a line. Spread out loosely near the edge of the room, so your line does not hit anyone else.|n2. {SPELL:1296963} leaves puddles on the ground. Drop them near the edge and close together, and never stand in them.|n3. {SPELL:1300259}: the puddles shoot out orbs. Keep moving around the room and dodge every orb.|n4. On Mythic and Mythic+: {SPELL:1225011} - two shards fly at one player, and each bursts on the first player it hits. Do not step into shards aimed at someone else.",
	DGN_TIP_VA_TAZRAH_QUICK_DPS = "Keep hitting the boss while you dodge.",
	DGN_TIP_VA_TAZRAH_QUICK_HEALER = "Heal everyone up before the puddles come.",
	DGN_TIP_VA_TAZRAH_QUICK_TANK = "Use a defensive when he knocks you back, and don't land in a puddle.",
	DGN_TIP_VA_TAZRAH_QUICK = "Dash: A ghost runs at you in a line. Stand near the wall, a bit apart from your friends.|nPuddles: Drop your dark puddles near the wall, close together. Never stand in them.|nOrbs: The puddles shoot balls. Keep walking around the room and dodge them.",
	DGN_TIP_VA_TAZRAH_TANK = "Tank: {SPELL:1297017} hits you hard and knocks you back. Use a defensive and do not get knocked into a puddle. Tank near a wall and turn slowly around the room, so the middle stays free.",
	DGN_TIP_VA_TAZRAH_HEALER = "Healer: Top everyone up before each {SPELL:1296963} cast; {SPELL:1300259} hurts the whole group. Heal players hit by a dash, it keeps hurting them for a while.",

	DGN_TIP_VA_ATROXUS_STEPS = "1. {SPELL:1262497} hits the whole group. About 3 seconds later a Toxic Creeper crawls out ({SPELL:1222371}). Kill it fast.|n2. {SPELL:1263977} is a frontal aimed at a random player. Stay close to the boss so you can step out of it quickly.|n3. {SPELL:1226120} splashes poison around the boss. Dodge the hits and stay out of the poison puddles it leaves.|n4. On Mythic and Mythic+: the Creeper has Toxic Aura - it hurts everyone within 8 yards until it dies. Kill it even faster; ranged players keep away from it.",
	DGN_TIP_VA_ATROXUS_QUICK_DPS = "When the Creeper comes out, hit it first.",
	DGN_TIP_VA_ATROXUS_QUICK_HEALER = "Remove poisons from the tank and from anyone who stood in a puddle.",
	DGN_TIP_VA_ATROXUS_QUICK_TANK = "The Creeper chases you: walk away from it so it can't bite you.",
	DGN_TIP_VA_ATROXUS_QUICK = "Roar: The boss roars and a small monster, the Creeper, crawls out. Everyone hits it until it dies.|nBreath: The boss breathes at a random player. Stand close, and step out of it.|nPoison: Step away from the poison splashes and the puddles.",
	DGN_TIP_VA_ATROXUS_TANK = "Tank: The Creeper fixates you. Kite it and do not let it hit you - every bite adds a Sickening Bite stack, and the stacks make {SPELL:1222642} deadly. Keep it close to the boss so DPS can hit both, and use a defensive for the claw.",
	DGN_TIP_VA_ATROXUS_HEALER = "Healer: Dispel poisons: the {SPELL:1222642} poison on the tank and Mind-Numbing Poison from the puddles. On Mythic and Mythic+, use a healing cooldown while the Creeper is alive.",

	DGN_TIP_VA_CHARONUS_STEPS = "1. {SPELL:1282770}: some players are marked, and a few seconds later a gravity well appears under them. It pulls you in and hurts. Move out, but stay next to one - you need it for the orbs. Its center gives Atomized: no damage and no healing for a short time.|n2. {SPELL:1263982}: an orb chases 3 players. Its debuff hurts and slows you more every second. Walk past a gravity well so your orb follows you into it - that destroys both. Do not stop inside. Each player uses a different well.|n3. {SPELL:1227264} hits everyone, knocks you back and leaves a 20-second damage effect. Stand apart from each other, and make sure you will not land in a well.|n4. On Mythic and Mythic+: {SPELL:1222758} - projectiles fly toward a random player and knock back whoever they touch. If it is you, keep running; everyone else steps out of the path.",
	DGN_TIP_VA_CHARONUS_QUICK_DPS = "Wait next to a hole, so a ball chasing you falls in fast.",
	DGN_TIP_VA_CHARONUS_QUICK_HEALER = "Heal the players with a ball chasing them first.",
	DGN_TIP_VA_CHARONUS_QUICK_TANK = "Use a defensive for his big hit and point it away from your friends.",
	DGN_TIP_VA_CHARONUS_QUICK = "Wells: Dark holes appear on the floor. They pull you in, so stay near one but not inside.|nOrbs: If a ball chases you, walk past a hole so the ball falls in.|nBlast: The boss pushes everyone back. Stand apart, and don't fly into a hole.",
	DGN_TIP_VA_CHARONUS_TANK = "Tank: {SPELL:1311923} is a frontal tank hit. Use a defensive and point it away from the group. Keep the boss in the middle of the three gravity wells, and do not turn him through players.",
	DGN_TIP_VA_CHARONUS_HEALER = "Healer: Heal the players with an orb first - the longer they carry it, the harder it hits. After {SPELL:1227264} the whole group has a 20-second damage effect, and the gravity wells pulse damage while they last.",

	-- Nexus-Point Xenas ---------------------------------------------------------------
	DGN_TIP_NX_KASRETH_STEPS = "1. Got {SPELL:1251785}? Step INTO a leyline beam ({SPELL:1251183}) — it clears the debuff (short stun, worth it).|n2. Everyone else: do NOT cross the leylines (damage + stacking slow).|n3. Full energy = {SPELL:1257509}: big impact zone, get clear — arcane spills ({SPELL:1264048}) linger afterwards.",
	DGN_TIP_NX_KASRETH_TANK = "Tank: hold the boss away from the leylines.",
	DGN_TIP_NX_KASRETH_HEALER = "Healer: Sparkburn ticks on everyone after each detonation.",

	DGN_TIP_NX_NYSARRA_STEPS = "1. Spread out — {SPELL:1249020} strikes splash 14 yards.|n2. Kill the Null Vanguard adds ({SPELL:1252703}) FAST: anything still alive gets devoured ({SPELL:1271684}), heals her and bursts the group.|n3. Dodge the {SPELL:1264439}.",
	DGN_TIP_NX_NYSARRA_TANK = "Tank: she leaps at you with a slash combo ({SPELL:1247937}) — defensive, brace for the finisher.",
	DGN_TIP_NX_NYSARRA_HEALER = "Healer: spread damage after {SPELL:1249020}; group burst if adds survive the devour.",

	DGN_TIP_NX_LOTHRAXION_STEPS = "1. {SPELL:1255503}: spread — impacts splash 8 yards and spawn Fractured Images.|n2. {SPELL:1257567}: he hides among his images and they all channel — find the REAL Lothraxion and interrupt him.|n3. Images flicker around with knockbacks ({SPELL:1255531}); stay off the {SPELL:1255310} on the floor.",
	DGN_TIP_NX_LOTHRAXION_TANK = "Tank: {SPELL:1255335} is a double slash that carves ground scars — aim it away from the group.",
	DGN_TIP_NX_LOTHRAXION_HEALER = "Healer: Holy DoTs after every {SPELL:1255503}; steady damage until the Guile interrupt lands.",

	-- Magisters' Terrace ---------------------------------------------------------------
	DGN_TIP_MT_ARCANOTRON_STEPS = "1. When it refuels ({SPELL:474345}), Energy Orbs get drawn toward it — intercept them; meanwhile it takes +20% damage: burst window!|n2. Shackled players ({SPELL:1214038}) are rooted (magic) — dispel or break them out.|n3. {SPELL:1214081} knocks everyone back and leaves residue at its feet — step out of it.",
	DGN_TIP_MT_ARCANOTRON_TANK = "Tank: {SPELL:474496} launches you — keep your back clear.",
	DGN_TIP_MT_ARCANOTRON_HEALER = "Healer: dispel {SPELL:1214038} (magic root) quickly.",

	DGN_TIP_MT_SERANEL_STEPS = "1. {SPELL:1225193} pacifies everyone OUTSIDE the Suppression Zone ({SPELL:1224903}) — step IN the zone for the wave (but the zone silences you, so don't linger).|n2. Purge/spellsteal his {SPELL:1248689} (+100% attack speed) whenever it's up.|n3. {SPELL:1225787} bounces to a nearby player — spread.",
	DGN_TIP_MT_SERANEL_TANK = "Tank: an unpurged Ward doubles his attack speed — defensive until it's gone.",
	DGN_TIP_MT_SERANEL_HEALER = "Healer: marked players tick; remember you can't cast inside the zone.",

	DGN_TIP_MT_GEMELLUS_STEPS = "1. {SPELL:1223847} (at the start and at half health): he splits into three.|n2. {SPELL:1253709}: linked to one of them? RUN over and touch it — that breaks the link and removes his absorb shield.|n3. {SPELL:1224299} pulls you in — run back out.",
	DGN_TIP_MT_GEMELLUS_TANK = "Tank: regroup the trio after each {SPELL:1223847} so linked players can reach theirs.",
	DGN_TIP_MT_GEMELLUS_HEALER = "Healer: linked players take +20% damage until they break their link.",

	DGN_TIP_MT_DEGENTRIUS_STEPS = "1. {SPELL:1215897}: void DoTs with different durations — when yours expires, Entropy Orbs launch from YOUR position, so walk away from the group first.|n2. {SPELL:1215087} bounces to 4 spots — SOAK an impact (one player each), or it erupts in Void Destruction.|n3. {SPELL:1280113} smashes the tank and knocks away anyone within 8 yards — give the tank space.",
	DGN_TIP_MT_DEGENTRIUS_TANK = "Tank: defensive for {SPELL:1280113}; tank him away from the group.",
	DGN_TIP_MT_DEGENTRIUS_HEALER = "Healer: Entropy DoTs tick hard — keep carriers up while they reposition.",

	-- Skyreach (batch 3 — Midnight-revamp abilities via DBM + Wowhead) ----------
	DGN_TIP_SR_RANJIT_STEPS = "1. {SPELL:1258148} flies in a straight line in front of him — step aside.|n2. {SPELL:156793}: an impact in the middle plus roaming wind vortexes that launch you — keep weaving.|n3. {SPELL:153757} hits everyone with a bleed — be topped up.|n4. {SPELL:1252733} blasts its targets away — mind what's behind you.",
	DGN_TIP_SR_RANJIT_TANK = "Tank: keep him clear of the vortex paths.",
	DGN_TIP_SR_RANJIT_HEALER = "Healer: group damage plus bleeds after every {SPELL:153757}.",

	DGN_TIP_SR_ARAKNATH_STEPS = "1. {SPELL:154162}: constructs beam light into the boss and HEAL him — stand in a beam to block it.|n2. {SPELL:154115}: a one-sided arm slam — getting hit stacks a brutal damage-taken debuff.|n3. {SPELL:154135} hits everyone — be ready.",
	DGN_TIP_SR_ARAKNATH_TANK = "Tank: never soak the beams yourself — his smash lands during the soak.",
	DGN_TIP_SR_ARAKNATH_HEALER = "Healer: beam-soakers tick steadily; group heal at {SPELL:154135}.",

	DGN_TIP_SR_RUKHRAN_STEPS = "1. {SPELL:1253527}: feathers fly everywhere for 3 seconds — break line of sight behind a pillar.|n2. {SPELL:1253510} hits the group and summons a Sunwing that fixates someone and pulses fire — kill it fast; fixated player keeps distance.|n3. Repeat — quills behind cover, bird down quickly.",
	DGN_TIP_SR_RUKHRAN_TANK = "Tank: defensive for {SPELL:1253519} (big hit + burn DoT).",
	DGN_TIP_SR_RUKHRAN_HEALER = "Healer: pulsing group damage while a Sunwing lives — call for its kill.",

	DGN_TIP_SR_VIRYX_STEPS = "1. {SPELL:154396}: a 3-second cast that nukes the tank — KICK it, every time.|n2. {SPELL:1253998}: a Solar Zealot grabs a player to drop them off the balcony — free them fast.|n3. {SPELL:1253531} on you? Run it out wide — it leaves Blazing Ground.",
	DGN_TIP_SR_VIRYX_TANK = "Tank: every {SPELL:154396} that slips through hurts — keep the kick order tight.",
	DGN_TIP_SR_VIRYX_HEALER = "Healer: {SPELL:1253538} puts fire DoTs on several players at once.",

	-- Pit of Saron ----------------------------------------------------------------
	DGN_TIP_PS_GARFROST_STEPS = "1. {SPELL:1262029}: the forge pulses stacking frost — HIDE BEHIND a saronite ore chunk, it blocks the blast.|n2. {SPELL:1261546} slams everything around the main target — stay 5+ yards off the tank; near ore the slam breaks ore instead of stunning.|n3. {SPELL:1261847} hits everyone and shatters ALL ore — fresh ore follows via {SPELL:1261286}.|n4. Stay out of the {SPELL:1261799}.",
	DGN_TIP_PS_GARFROST_TANK = "Tank: park yourself next to an ore chunk — {SPELL:1261546} then smashes the ore, not you.",
	DGN_TIP_PS_GARFROST_HEALER = "Healer: group spike at {SPELL:1261847}; stacking frost on anyone caught without cover.",

	DGN_TIP_PS_KRICKICK_STEPS = "1. {SPELL:1264363}: Ick fixates and chases a player, splattering Blight and Plague Globs — run wide; the rest keeps hitting.|n2. {SPELL:1264027}: Krick teleports to a ritual circle and summons Shades — switch and kill them.|n3. {SPELL:1264336}: dodge the wave and the globs rolling at you.|n4. Never stand in the Blight ({SPELL:1264299}).",
	DGN_TIP_PS_KRICKICK_TANK = "Tank: {SPELL:1264287} drops a pool on you — aim it at the edge.",
	DGN_TIP_PS_KRICKICK_HEALER = "Healer: keep the chased player rolling; group damage at {SPELL:1264336}.",

	DGN_TIP_PS_TYRANNUS_STEPS = "1. {SPELL:1262772} freezes Bone Piles around its target — stand near piles when marked: frozen piles can't raise adds.|n2. {SPELL:1263406} raises the remaining piles — kill Plaguespreaders first.|n3. Keep dodging {SPELL:1263756} and Rimefang's {SPELL:1276948}.|n4. {SPELL:1276648} = group hit + DoT, and infused piles spawn nastier adds.",
	DGN_TIP_PS_TYRANNUS_TANK = "Tank: {SPELL:1262582} launches you and stacks +200% shadow taken — defensive and brace.",
	DGN_TIP_PS_TYRANNUS_HEALER = "Healer: group DoTs after {SPELL:1276648}; tank spike right after Brand.",

	-- Seat of the Triumvirate --------------------------------------------------------
	DGN_TIP_ST_ZURAAL_STEPS = "1. {SPELL:1268916} hits everything in FRONT of him — never stand before the boss.|n2. {SPELL:1263304} (full energy): he drags everyone in, then bursts with a knockback — run out in time; adds get dragged in too.|n3. {SPELL:1263399} spawns Coalesced Void adds — clear them before Crashing Void.|n4. {SPELL:1263282} leaves Void Sludge ({SPELL:244588}) — keep the floor clean.",
	DGN_TIP_ST_ZURAAL_TANK = "Tank: defensive for {SPELL:1263440} (triple swipe).",
	DGN_TIP_ST_ZURAAL_HEALER = "Healer: big group hit at {SPELL:1263304}.",

	DGN_TIP_ST_SAPRISH_STEPS = "1. Void Bombs ({SPELL:247175}) land on player spots — do NOT touch them; drop them at the edges.|n2. {SPELL:1280064}: shades dash at every player and detonate bombs they cross — angle your dash line clear of bombs.|n3. {SPELL:1263523} ignites ALL bombs at once — the fewer bombs, the gentler it gets.|n4. Kick Shadewing's {SPELL:248831} (group hit + disorient).",
	DGN_TIP_ST_SAPRISH_TANK = "Tank: keep the trio together; Darkfang's pounce ({SPELL:245738}) leaves its victim bleeding.",
	DGN_TIP_ST_SAPRISH_HEALER = "Healer: pounce victims bleed; group burst at {SPELL:1263523}.",

	DGN_TIP_ST_NEZHAR_STEPS = "1. {SPELL:1263528} knocks everyone back — watch your footing near storms.|n2. {SPELL:1263538} and the {SPELL:1277358} add chaos — kill tentacles, dodge the Umbral Waves from the gate.|n3. {SPELL:1263532} zones tick hard, inside is worse — out, fast.|n4. {SPELL:244750} nukes the tank — kick it when you can.",
	DGN_TIP_ST_NEZHAR_TANK = "Tank: brace for {SPELL:244750} whenever a kick is down.",
	DGN_TIP_ST_NEZHAR_HEALER = "Healer: {SPELL:1263542} = several rot DoTs ticking at once.",

	DGN_TIP_ST_LURA_STEPS = "1. Notes of Despair keep radiating ({SPELL:1265421}) until silenced — steer your {SPELL:1265426} THROUGH the notes (it also hits allies in the line, so angle it clear of them).|n2. {SPELL:1265689}: 20 seconds of pain around every active note — break notes fast.|n3. {SPELL:1264151}: rotating void beams — move with the gaps.|n4. {SPELL:1266003} is a deadly 10-second channel — every defensive you have, and heal through it.",
	DGN_TIP_ST_LURA_TANK = "Tank: after {SPELL:1266001} everyone gets knocked around — regroup quickly.",
	DGN_TIP_ST_LURA_HEALER = "Healer: {SPELL:1265421} group hits plus note auras — breaking notes IS the healing plan.",

	-- Algeth'ar Academy ----------------------------------------------------------------
	DGN_TIP_AA_VEXAMUS_STEPS = "1. {SPELL:385974} drift toward the boss — soak them, one player each (small hit); every orb HE absorbs blasts the whole group.|n2. {SPELL:386173}: carry yours out — it pops into a {SPELL:386201} pool.|n3. Full energy = {SPELL:388537}: group hit plus repeated eruptions under players — keep moving.",
	DGN_TIP_AA_VEXAMUS_TANK = "Tank: {SPELL:385958} bursts everything in front of him — defensive, face him away.",
	DGN_TIP_AA_VEXAMUS_HEALER = "Healer: bomb carriers tick; group damage for every orb that reaches the boss.",

	DGN_TIP_AA_ANCIENT_STEPS = "1. {SPELL:388796}: seeds erupt under everyone for 4 seconds — dodge; missed seeds leave dormant Lashers.|n2. At full energy ({SPELL:388923}) ALL dormant Lashers wake at once — clear them beforehand.|n3. {SPELL:388623} throws a branch that becomes a big add — kill it and KICK its {SPELL:396640}.",
	DGN_TIP_AA_ANCIENT_TANK = "Tank: {SPELL:388544} doubles the physical damage you take — defensive every time.",
	DGN_TIP_AA_ANCIENT_HEALER = "Healer: cleanse {SPELL:389033} (poison) before it stacks high.",

	DGN_TIP_AA_CRAWTH_STEPS = "1. {SPELL:377004} erupts under every player and interrupts casts — STOP casting, then spread.|n2. {SPELL:377034}: she eyes someone and wing-blasts a cone that way — step out.|n3. {SPELL:377182}: score in a goal — the fire goal stuns her and she takes 75% extra damage.",
	DGN_TIP_AA_CRAWTH_TANK = "Tank: defensive for {SPELL:376997} (hit + 10s bleed).",
	DGN_TIP_AA_CRAWTH_HEALER = "Healer: heavy group damage after the screech; the tank bleeds.",

	DGN_TIP_AA_DORAGOSA_STEPS = "1. {SPELL:374341} on you? Walk it away from the group — it bursts 8 yards wide.|n2. {SPELL:388820} drags everyone in, then explodes — RUN OUT before the blast.|n3. {SPELL:389011} stacks from every mechanic you eat — at 3 stacks it bursts into an Arcane Rift; stay clean.|n4. Stay off the {SPELL:389007} ground.",
	DGN_TIP_AA_DORAGOSA_TANK = "Tank: defensive for {SPELL:1282251}.",
	DGN_TIP_AA_DORAGOSA_HEALER = "Healer: watch {SPELL:389011} stacks — carriers tick harder per stack.",
	DGN_TIP_AA_ANCIENT_DPS = "DPS: Clear the dormant Lashers before full energy, or they all wake at once. Kill the thrown branch add and kick its cast.",
	DGN_TIP_AA_CRAWTH_DPS = "DPS: Stop casting when the ground erupts - it interrupts you anyway - then spread. Score in the fire goal: it stuns her and she takes 75% extra damage.",
	DGN_TIP_AA_DORAGOSA_DPS = "DPS: Walk your debuff away from the group; it bursts 8 yards wide. Every mechanic you eat stacks, and at 3 it becomes an Arcane Rift.",
	DGN_TIP_AA_VEXAMUS_DPS = "DPS: Soak the orbs one player each: every orb he absorbs blasts the whole group. Carry your own bolt out before it pools.",
	DGN_TIP_BV_IKUZZ_DPS = "DPS: Cleave the roots quickly. Fixated? Run, and lead him over roots instead of into empty space - do not let him catch you.",
	DGN_TIP_BV_RUIA_DPS = "DPS: Kick Warden's Wrath in moonkin form. Save your cooldowns for 40%, when everything fires every 8 seconds.",
	DGN_TIP_BV_TRINITY_DPS = "DPS: Hit all three bosses - they share one health bar, so cleave. Kick Light Bolt, and take a circle during the beam when your group needs a soaker.",
	DGN_TIP_BV_ZIEKKET_DPS = "DPS: Kick Lightspore Shot. Do not waste damage on sleeping lashers - only the beam kills them. On Mythic, take your share of orbs.",
	DGN_TIP_DN_HOARDMONGER_DPS = "DPS: Help step on the mushrooms, and take turns so no one gets too many poison stacks. Stay off the bone patches.",
	DGN_TIP_DN_NALORAKK_DPS = "DPS: When the Echoes charge, help wall off Zul'jarra: one player per Echo. With a mark, walk to the edge next to the other Echoes.",
	DGN_TIP_DN_SENTINEL_DPS = "DPS: Split the interrupts so every Winter's Shroud gets stopped. Kill the first add just before the storm, the second one after it.",
	DGN_TIP_MC_MUROJIN_DPS = "DPS: Both bosses have to die close together - watch the two health bars and swap early, because a lone survivor goes berserk.",
	DGN_TIP_MC_RAKTUL_DPS = "DPS: Totems first, then back to the boss. In the soul phase your damage barely counts - spend that time on crowd-control and interrupts.",
	DGN_TIP_MC_VORDAZA_DPS = "DPS: The phantoms are your job: kill them before they reach anyone, but one at a time - every death is group damage nobody can dodge.",
	DGN_TIP_MR_KYSTIA_DPS = "DPS: Nibbles first, not Kystia. When Nibbles reaches 20%, switch to Kystia and use your cooldowns. Interrupt or stun the copies from {SPELL:1264095}.",
	DGN_TIP_MR_LITHIEL_DPS = "DPS: Kick Chaos Bolt and the Wild Imps. Kill every demon before {SPELL:1224478} touches it.",
	DGN_TIP_MR_XATHUUX_DPS = "DPS: Swap to the axe as soon as it lands. Save your cooldowns for {SPELL:474197}: he takes 30% more damage then.",
	DGN_TIP_MR_ZAEN_DPS = "DPS: Be behind a crate before {SPELL:1218347} fires, not after. With {SPELL:1214357}, walk away from the plain crates; on Mythic, take it to a green crate.",
	DGN_TIP_MT_ARCANOTRON_DPS = "DPS: Intercept the Energy Orbs during the refuel, and save your cooldowns for it: he takes +20% damage in that window.",
	DGN_TIP_MT_DEGENTRIUS_DPS = "DPS: Soak one Unstable Void Essence impact each, or it erupts. When your Entropy DoT is about to expire, walk out of the group first.",
	DGN_TIP_MT_GEMELLUS_DPS = "DPS: Break your link before you resume - every point you put into his absorb shield is wasted.",
	DGN_TIP_MT_SERANEL_DPS = "DPS: Purge or spellsteal the Hastening Ward every time it lands. Step into the Suppression Zone for the wave, then get out - it silences you.",
	DGN_TIP_NX_KASRETH_DPS = "DPS: Clear your debuff by stepping into a leyline beam - the short stun costs less than keeping it. Otherwise never cross a leyline.",
	DGN_TIP_NX_LOTHRAXION_DPS = "DPS: When he hides among his images, find the real one and interrupt him - damage on the images is wasted.",
	DGN_TIP_NX_NYSARRA_DPS = "DPS: Adds over boss, every time - she heals off any you leave standing. Swap the moment they appear rather than finishing your cast on her.",
	DGN_TIP_PS_GARFROST_DPS = "DPS: Ore is cover: get behind a chunk for the forge pulse. Stay 5+ yards off the tank so the slam does not catch you too.",
	DGN_TIP_PS_KRICKICK_DPS = "DPS: When Krick teleports to a ritual circle, switch to the Shades. Fixated by Ick? Run wide - everyone else keeps hitting.",
	DGN_TIP_PS_TYRANNUS_DPS = "DPS: Marked? Stand near Bone Piles so they freeze; frozen piles cannot raise adds. When piles do rise, Plaguespreaders die first.",
	DGN_TIP_SR_ARAKNATH_DPS = "DPS: Block the construct beams with your body - every beam that lands heals him back up.",
	DGN_TIP_SR_RANJIT_DPS = "DPS: A positional fight, not a target one: step aside for the line, weave around the vortexes, and mind what is behind you when it blasts.",
	DGN_TIP_SR_RUKHRAN_DPS = "DPS: Quills mean a pillar, every time. Then kill the Sunwing quickly; whoever it fixates keeps their distance.",
	DGN_TIP_SR_VIRYX_DPS = "DPS: Kick the tank nuke every single time - it is a 3-second cast. Free anyone the Solar Zealot grabs before they go off the balcony.",
	DGN_TIP_ST_LURA_DPS = "DPS: Steer your beam through the Notes of Despair - they keep radiating until silenced - and angle it clear of allies, because it hits them too.",
	DGN_TIP_ST_NEZHAR_DPS = "DPS: Kill the tentacles and kick the tank nuke when you can. The zones tick hard, so get out fast rather than pushing for uptime.",
	DGN_TIP_ST_SAPRISH_DPS = "DPS: Kick Shadewing's cast, and drop your Void Bombs at the edges - the fewer bombs on the floor, the gentler the mass ignite.",
	DGN_TIP_ST_ZURAAL_DPS = "DPS: Clear the Coalesced Void adds before Crashing Void, or they get dragged in with you. Never stand in front of him.",
	DGN_TIP_VA_ATROXUS_DPS = "DPS: Swap to the Toxic Creeper the moment it appears after each roar. Kill it, then go back to the boss.",
	DGN_TIP_VA_CHARONUS_DPS = "DPS: Before the orbs come, stand next to a gravity well. If an orb chases you, lead it in at once; a speed or freedom spell or a defensive helps when the slow stacks get high.",
	DGN_TIP_VA_TAZRAH_DPS = "DPS: Stay on the boss. The Ethereal Shades only make the dash lines, and current guides do not ask you to kill them.",
	DGN_TIP_WS_DUO_DPS = "DPS: Split your damage so both die close together, and keep Shadow Bolt interrupted. Crowd-control the Dark Entity a curse spawns instead of chasing it down.",
	DGN_TIP_WS_EMBER_DPS = "DPS: Drop your fire puddles at the edges so the middle stays clean, and sidestep the breath rather than running out of range.",
	DGN_TIP_WS_HEART_DPS = "DPS: Take a windy arrow at 2-3 stacks, but leave one free for the full-energy blast.",
	DGN_TIP_WS_KROLUK_DPS = "DPS: Adds come at roughly two thirds and one third health: swap straight onto them, Phantasmal Mystic first, and keep it interrupted.",
	-- Altar of Fangs (Season 2, patch 12.1) --------------------------------------
	-- Written 6 Aug from the mechanics in DBM-Party-Midnight/AltarofFangs: the spell
	-- ids and DBM's own alert TYPE per ability (defensive / soak / fixate / switch /
	-- move) are facts, the wording is ours. Rob measured bosses 1 and 2 in a follower
	-- run the same evening; Zul'jan is unverified in play because a bug (four totems
	-- down, one beam still lit) blocked the way to him.
	--
	-- ✅ RE-CHECKED against DBM 12.1.7 (1 Sep 2026), which is a real confirmation rather
	-- than a re-read: a freshly shipped version still carries all four ids we quote, for
	-- the one boss Rob has never reached.
	-- ➕ It also has one ACTIVE ability we had missed -- 1301231 Bloodletting, registered
	-- with DBM's own "watchfeet" cue, so a floor effect. Added as step 3.
	-- ⚠️ Two more ids in that file are NOT taken: 1283247 (Reckless Leap) and 470966 are
	-- commented out in DBM itself. If they disable it, that is a decision by people who
	-- play the fight, and copying a line they switched off would be reading their file
	-- rather than their judgement.
	-- 📌 Rob's point, and he is right: DBM is not a random grep through another addon. Its
	-- ids and alert types are maintained and tested. What it cannot give is what a player
	-- should DO -- that sentence is ours, and for this boss still unconfirmed in play.
	DGN_TIP_AF_RAVI_STEPS = "1. {SPELL:1307894} hits the whole group and drops rubble. Be at full health and step out of the circles on the ground.|n2. When her energy runs out, Rav'i eats from a carrion pile and gets a shield ({SPELL:1309522}). Everyone attacks her and breaks the shield fast: the group takes damage until it breaks.|n3. If she eats from a pile with {SPELL:1307921} on it, she gets {SPELL:1307765} and hits much harder. The tank keeps her away from those piles.|n4. {SPELL:1296220}: spread out. Dodge the three waves of {SPELL:1296050}.|n5. On Mythic and Mythic+: while she eats, she throws chunks of meat (Messy Eater). Step into them to catch them; every missed chunk hurts the group.",
	DGN_TIP_AF_RAVI_QUICK_DPS = "Break the shield fast, and spread out when the three shots come.",
	DGN_TIP_AF_RAVI_QUICK_HEALER = "Top everyone up before the stomp and heal until the shield is gone.",
	DGN_TIP_AF_RAVI_QUICK_TANK = "Pull her away from the piles with fresh meat before she eats.",
	DGN_TIP_AF_RAVI_QUICK = "Stomp: The whole group gets hit and rocks fall. Be at full health and step out of the circles.|nShield: When she eats, she gets a shield. Everyone hits her hard until it breaks.|nMeat: The tank keeps her away from the fresh meat, or she hits much harder.",
	DGN_TIP_AF_RAVI_DPS = "DPS: Switch to Rav'i the moment the shield appears and break it with your burst. Spread out for {SPELL:1296220}.",
	DGN_TIP_AF_RAVI_TANK = "Tank: Before Rav'i eats, drag her to a carrion pile without {SPELL:1307921}, so she never gets {SPELL:1307765}. Use a defensive for her heavy melee hits (Hydrastrike).",
	DGN_TIP_AF_RAVI_HEALER = "Healer: Top the group up before {SPELL:1307894}, and heal hard until the shield breaks. If you can remove a disease, cleanse players hit by {SPELL:1296050}.",
	DGN_TIP_AF_COIL_STEPS = "1. Interrupt {SPELL:1310547}. It comes as three casts in a row, so plan three kicks. Every missed kick makes the group weaker and slower.|n2. Dodge {SPELL:1299940}: a charge in a line and a poison cone. If the cone targets you, aim it away from the group.|n3. {SPELL:1299053}: vines tie you to the boss and the damage keeps rising. Everyone runs more than 10 yards away from the boss at the same time to snap the vines.|n4. The boss then splits into 5 snakes. Hit them hard: that damage counts against the boss. When they merge back ({SPELL:1300686}), do not stand in their way.|n5. On Mythic and Mythic+: each snake chases a player ({SPELL:1300503}). Run from it and slow or stun it; do not let it touch you.",
	DGN_TIP_AF_COIL_QUICK_DPS = "Kick when it is your turn and use your big attacks on the snakes.",
	DGN_TIP_AF_COIL_QUICK_HEALER = "The poison hurts all fight; when the vines come, tell everyone to run.",
	DGN_TIP_AF_COIL_QUICK_TANK = "Take a defensive for the tail hit and pull the snakes together.",
	DGN_TIP_AF_COIL_QUICK = "Kicks: The boss casts three times in a row. Stop every cast.|nVines: Vines tie you to the boss. Everyone runs far away from it at the same time.|nSnakes: The boss breaks into snakes. Hit them hard, then get out of the way when they join up again.",
	DGN_TIP_AF_COIL_DPS = "DPS: Take your turn in the kick order for {SPELL:1310547}. Save your big cooldowns for the 5 snakes, not the boss.",
	DGN_TIP_AF_COIL_HEALER = "Healer: {SPELL:1299154} is group damage that ticks all fight long. Heal hard while the vines are up, but the real fix is that everyone runs.",
	DGN_TIP_AF_COIL_TANK = "Tank: Use a defensive for {SPELL:1298949}. When the boss splits, pull the snakes together so the group can hit them all at once.",
	DGN_TIP_AF_ZULJAN_STEPS = "1. {SPELL:1300876}: four snake heads shoot beams at Zul'jan. Stand in a beam, between the head and the boss, to block it. Agree before the pull who takes which beam. Every beam that reaches him makes him stronger for the rest of the fight.|n2. Blocking a beam gives you Ritual Venom. It bursts for big damage when it runs out, so clear it before that.|n3. To clear it, step into a {SPELL:1301413} axe line on purpose: that removes all your venom. With no venom, stay out of that line.|n4. Clearing venom leaves a blood pool ({SPELL:1301231}). Step out of it. Dodge the bouncing axes of {SPELL:1301111}.|n5. On Mythic and Mythic+: Ritual Venom stacks up. Clear all of it in one axe line before it runs out.",
	DGN_TIP_AF_ZULJAN_QUICK_DPS = "Stand in your beam, then use the axe line to clear your venom.",
	DGN_TIP_AF_ZULJAN_QUICK_HEALER = "Heal big during the beams and watch who still has venom.",
	DGN_TIP_AF_ZULJAN_QUICK_TANK = "Use a defensive for the double hit and leave your blood pools at the edge.",
	DGN_TIP_AF_ZULJAN_QUICK = "Beams: Snake heads shoot beams at the boss. Stand in one so it does not reach him.|nVenom: A beam gives you venom. Walk into the thrown axe line to wash it off, but only if you have venom.|nFloor: Step out of blood pools and run from the bouncing axes.",
	DGN_TIP_AF_ZULJAN_DPS = "DPS: Hold your beam spot for the whole ritual. Then clear your venom in the next axe line.",
	DGN_TIP_AF_ZULJAN_HEALER = "Healer: Use a big cooldown during each ritual. Watch who has Ritual Venom and make sure they clear it before it bursts.",
	DGN_TIP_AF_ZULJAN_TANK = "Tank: Use a defensive for {SPELL:1301350}; it hits you twice. His hits also clear your venom and leave blood pools, so drop those at the edge of the room.",
	DGN_TIP_KR_COUNCIL_STEPS = "1. The council fights one at a time: Kula, then Aka'ali, then Zanazal. A beaten councilor comes back now and then to use one ability. The fight ends when Zanazal dies.|n2. Kula: step away from her for {SPELL:266206} and dodge the axes that roll around afterwards. {SPELL:266231} makes a random player bleed - use a defensive.|n3. Aka'ali: {SPELL:267494} charges at one player. Everyone stacks on that player to split the damage.|n4. Zanazal: interrupt {SPELL:267273}. When he calls totems ({SPELL:267060}), kill the Explosive Totem first, then the Thundering Totem, then the Torrent Totem.",
	DGN_TIP_KR_COUNCIL_QUICK_DPS = "Stand in the charge stack, kick the poison, and kill the exploding totem first.",
	DGN_TIP_KR_COUNCIL_QUICK_HEALER = "Heal the axe bleed, and have everyone full before the charge.",
	DGN_TIP_KR_COUNCIL_QUICK_TANK = "When Aka'ali slaps you away, run from her until the debuff is gone.",
	DGN_TIP_KR_COUNCIL_QUICK = "Kula: Step away from her spin and dodge the flying axes.|nAka'ali: She charges one player. Everyone stands on that player to share the hit.|nZanazal: Kick his poison spell and kill the exploding totem first.",
	DGN_TIP_KR_COUNCIL_DPS = "DPS: Stand in the {SPELL:267494} stack, keep kicking {SPELL:267273}, and swap to the Explosive Totem the moment it appears.",
	DGN_TIP_KR_COUNCIL_HEALER = "Healer: Heal the {SPELL:266231} bleed and top everyone before {SPELL:267494}. On Zanazal, {SPELL:1305810} jumps between players, and Poison Nova ticks on everyone if it is not kicked.",
	DGN_TIP_KR_COUNCIL_TANK = "Tank: {SPELL:266237} knocks you back and makes you take much more physical damage. Kite Aka'ali until the debuff is gone, or use a big defensive.",
	DGN_TIP_KR_DAZAR_STEPS = "1. Phase 1: Dazar fights with his raptor Reban. Kill Reban first and interrupt his {SPELL:269369}, a fear. Reban jumps on a player with {SPELL:269230} and bites in a cone - step out of it.|n2. {SPELL:1303115}: Dazar leaps at two players. Those two spread out so they do not hit each other.|n3. At 80% health Dazar rides his raptor T'zala. Now {SPELL:1303327} leaps at four players and also hits the whole group - spread out and be topped up.|n4. {SPELL:1303267} hits the whole group and burns for 15 seconds. Right after, spears drop where players stand - keep moving and dodge the Impaling Spear circles.|n5. On Mythic and Mythic+: {SPELL:1303267} also powers up his swings - they send a wave of gold forward. The tank faces him away from the group.",
	DGN_TIP_KR_DAZAR_QUICK_DPS = "Kill the small raptor first and kick its roar.",
	DGN_TIP_KR_DAZAR_QUICK_HEALER = "Save your big heals for the gold hit and the raptor jumps.",
	DGN_TIP_KR_DAZAR_QUICK_TANK = "Use your biggest defensive for the sword combo, and keep the king facing away.",
	DGN_TIP_KR_DAZAR_QUICK = "Raptor: Kill the small raptor first and kick its scary roar.|nMounted: The king rides his big raptor. Spread out when it jumps, and be at full health.|nGold: A big fire hit on everyone, then spears fall where you stand. Keep moving.",
	DGN_TIP_KR_DAZAR_DPS = "DPS: Kill Reban first and kick {SPELL:269369}. Keep open space so the leap targets can spread and you can dodge the spears.",
	DGN_TIP_KR_DAZAR_HEALER = "Healer: Save your big cooldowns for {SPELL:1303267} and {SPELL:1303327}. Watch the bleeds from Impaling Spear and {SPELL:1303488}.",
	DGN_TIP_KR_DAZAR_TANK = "Tank: Big defensive for {SPELL:268586} - the hits get stronger toward the end. Once T'zala is in, {SPELL:1303488} hits you too and makes you take more physical damage, so plan your cooldowns across both. Face Dazar away from the group.",
	DGN_TIP_KR_MCHIMBA_STEPS = "1. {SPELL:267618}: the boss drains one player. Everyone else steps out of the acid circles it splashes. If it is on you, use a defensive. When it ends you stay slow and weak until you are healed above 90% health.|n2. {SPELL:1311956} targets a player and leaves burning ground. Drop it at the edge, away from the boss and the coffins.|n3. {SPELL:1312146} hits the whole group and opens coffins: two Half-Finished Mummies come out. Kill them and interrupt their Wretched Discharge.|n4. {SPELL:267702}: a player is locked in one of the coffins. If it is you, press the Struggle button so your coffin shakes. Everyone else: find the shaking coffin and click it fast. Every empty coffin he opens first lets out a Finished Mummy.",
	DGN_TIP_KR_MCHIMBA_QUICK_DPS = "Kick the mummies and help find the shaking coffin.",
	DGN_TIP_KR_MCHIMBA_QUICK_HEALER = "Heal the drained player to almost full, that removes the slow.",
	DGN_TIP_KR_MCHIMBA_QUICK_TANK = "Grab the mummies and keep them next to the boss.",
	DGN_TIP_KR_MCHIMBA_QUICK = "Drain: If the boss drains you, use a defensive. Everyone else steps out of the acid circles.|nFire: Put your fire puddle at the edge, away from the boss and the coffins.|nCoffin: A friend gets locked in a coffin. Find the one that shakes and click it fast.",
	DGN_TIP_KR_MCHIMBA_DPS = "DPS: Kick the mummies' Wretched Discharge. During {SPELL:267702}, go to the coffins and look for the shaking one - do not click at random.",
	DGN_TIP_KR_MCHIMBA_HEALER = "Healer: Switch to the {SPELL:267618} target at once, and heal them above 90% afterwards - that ends the slow. Top the group before {SPELL:1312146}. Wretched Discharge is a disease you can dispel.",
	DGN_TIP_KR_MCHIMBA_TANK = "Tank: Pick up the mummies and stack them near Mchimba for cleave. Do not park them in front of a coffin.",
	DGN_TIP_KR_SERPENT_STEPS = "1. {SPELL:265773} puts burning gold on two players. When it ends you leave a pool of {SPELL:265914} where you stand - walk to the edge first and drop it next to the other pools.|n2. {SPELL:265923} wakes the pools up as Animated Gold that crawls to the boss. Kill, slow or stun them before any reaches him - each one that gets there gives him a shield and more damage.|n3. {SPELL:1311987}: five seconds of damage on the whole group that also pushes you back. Be topped up and use a defensive.|n4. Never stand in the gold pools.",
	DGN_TIP_KR_SERPENT_QUICK_DPS = "Kill the gold blobs first - none of them may reach the boss.",
	DGN_TIP_KR_SERPENT_QUICK_HEALER = "Heal the two gold-burn players, and save a big heal for the wind.",
	DGN_TIP_KR_SERPENT_QUICK_TANK = "Use a defensive for the tail hit, and pull the boss away from the gold blobs.",
	DGN_TIP_KR_SERPENT_QUICK = "Gold: When your gold burn ends you leave a pool. Drop it at the edge, next to the other pools.|nAdds: The pools wake up and crawl to the boss. Kill them before they touch him.|nWind: A strong wind hurts everyone and pushes you back. Be at full health.",
	DGN_TIP_KR_SERPENT_DPS = "DPS: Animated Gold first, the boss second. Use slows, stuns and cleave, and keep all pools together so the adds wake up in one clump.",
	DGN_TIP_KR_SERPENT_HEALER = "Healer: Heal the two {SPELL:265773} targets through the burn. Use a healing cooldown for {SPELL:1311987}.",
	DGN_TIP_KR_SERPENT_TANK = "Tank: Defensive for {SPELL:265910}. When the Animated Gold wakes up, pull the boss away from it so the DPS have more time.",
	DGN_TIP_RL_KOKIA_STEPS = "1. Molten Boulder ({SPELL:372110}): Kokia throws a burning boulder that rolls in a straight line and then explodes. Step out of its path and stay away from the spot where it stops. It knocks back anyone it touches.|n2. Ritual of Blazebinding ({SPELL:372864}): a fire add, the Blazebound Firestorm, appears on a player and burns everyone within 12 yards. If it is on you, step away from the group but stay close to the boss.|n3. Everyone switches to the Blazebound Firestorm right away and interrupts its Blaze Volley.|n4. Before the add dies, move at least 20 yards away from it. Its death blast (Burnout) hits very hard.|n5. On Mythic and Mythic+: burning ground ({SPELL:372820}) stays on the floor. Step out of it, and move the fight slowly around the room so there is always free space.",
	DGN_TIP_RL_KOKIA_QUICK_DPS = "Hit the fire add first, kick its spells, and run away before it dies.",
	DGN_TIP_RL_KOKIA_QUICK_HEALER = "The fire add burns everyone and the tank bleeds, so heal hard and stay away when it dies.",
	DGN_TIP_RL_KOKIA_QUICK_TANK = "Use a defensive for every hit combo and walk the boss slowly around the room.",
	DGN_TIP_RL_KOKIA_QUICK = "Boulder: A fire boulder rolls in a straight line, so step out of its way.|nFire add: When a fire monster appears, everyone hits it and stops its spells.|nAdd dies: Run far away from it before it dies, because it explodes.",
	DGN_TIP_RL_KOKIA_DPS = "DPS: Switch to the Blazebound Firestorm the moment it spawns and kick its Blaze Volley. Melee: run 20 yards out before it dies.",
	DGN_TIP_RL_KOKIA_HEALER = "Healer: The add's Inferno cast burns the whole group, and Searing Blows leaves a bleed on the tank. Stay out of the add's death blast yourself.",
	DGN_TIP_RL_KOKIA_TANK = "Tank: Use a defensive for every Searing Blows ({SPELL:372858}): four fast hits that stack a bleed. Keep Kokia near the add so DPS can cleave, but walk out of its 20-yard death blast. Move her slowly around the room to keep free space.",
	DGN_TIP_RL_KYRAKKA_STEPS = "1. Erkhart fights on the ground while his dragon Kyrakka flies around the platform. Hit Kyrakka whenever she is in range: she should die first. Dodge her fire cone ({SPELL:381525}).|n2. Inferno Spit ({SPELL:381602}): 2 players burn for 6 seconds, then explode and leave fire on the floor ({SPELL:384773}). If it is you, walk to the edge, away from the group, before it ends.|n3. Winds of Change ({SPELL:381517}): wind pushes players and the fire, in a fixed order (northwest, southwest, southeast, northeast). Walk against it and don't get blown into fire. Drop your fire where the wind carries it away from the group.|n4. When one of them reaches about 40 to 50% health (guides differ), Kyrakka lands and Erkhart rides her. Now 3 players get Inferno Spit. Save cooldowns for this part.|n5. On Mythic and Mythic+: Interrupting Cloudburst ({SPELL:381516}) hits everyone and locks your spells for 2 seconds. Stop casting just before it lands.",
	DGN_TIP_RL_KYRAKKA_QUICK_DPS = "Hit the dragon first, and on Mythic stop casting just before the storm hits everyone.",
	DGN_TIP_RL_KYRAKKA_QUICK_HEALER = "Remove the tank's debuff after every big hit and heal the burning players.",
	DGN_TIP_RL_KYRAKKA_QUICK_TANK = "Use a defensive for his big hit, and ask the healer to remove the debuff.",
	DGN_TIP_RL_KYRAKKA_QUICK = "Dragon: Hit the dragon whenever you can reach her, and dodge her fire breath.|nFire: If you are burning, walk to the edge so your fire lands away from the group.|nWind: The wind pushes you and the fire, so walk against it and stay out of flames.",
	DGN_TIP_RL_KYRAKKA_DPS = "DPS: Hit Kyrakka whenever you can reach her and save burst for when she lands. On Mythic and Mythic+, casters stop casting before Interrupting Cloudburst.",
	DGN_TIP_RL_KYRAKKA_HEALER = "Healer: Dispel Stormslam off the tank after every hit, before the next one. Inferno Spit targets take heavy damage, so heal them up. On Mythic and Mythic+, stop casting before Interrupting Cloudburst.",
	DGN_TIP_RL_KYRAKKA_TANK = "Tank: Use a defensive for every Stormslam ({SPELL:381512}). It leaves a stacking magic debuff that makes you take more nature damage, so ask for a dispel. Move Erkhart out of fire quickly after each wind.",
	DGN_TIP_RL_MELIDRUSSA_STEPS = "1. Hailburst ({SPELL:1307297}): she hits the whole group and throws an ice mine at every player. Stand together near one edge so the mines land in one spot. Never touch a mine: it throws you up and slows your attacks and spells by half for 20 seconds.|n2. Chillstorm ({SPELL:1307308}): a frost storm lands on a player and pulls everyone toward its middle. If it is on you, run away from the group. Stay out of the middle ({SPELL:372963}): frost damage there is doubled. After 7 seconds it explodes and pushes everyone away, so do not stand with mines behind you.|n3. At 66% and 33% health she calls Infused Whelps ({SPELL:373046}). Kill them fast.|n4. Interrupt Frigid Shard, the spell she casts at the tank.|n5. On Mythic and Mythic+: after the whelps she hides in an ice shield (Ice Bulwark) and pulses frost damage on everyone that keeps growing (Frost Overload). Break the shield fast, then interrupt her. Guides say the kick works once the shield is gone.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_DPS = "Kill the baby dragons first, and on Mythic break her ice shield.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_HEALER = "Heal the whole group through the ice blasts and the storm.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_TANK = "Grab the baby dragons at once and kick the spell she casts at you.",
	DGN_TIP_RL_MELIDRUSSA_QUICK = "Mines: Stand together near one edge when she throws ice, and never touch the mines.|nStorm: If the storm is on you, run away from everyone and stay out of its middle.|nWhelps: Kill the baby dragons fast, and on Mythic also break her ice shield.",
	DGN_TIP_RL_MELIDRUSSA_DPS = "DPS: Switch to the whelps as soon as they spawn. On Mythic and Mythic+, save burst to break the ice shield, then kick Frost Overload.",
	DGN_TIP_RL_MELIDRUSSA_HEALER = "Healer: Hailburst and Chillstorm hit the whole group, and the storm explodes at the end. Top people up before the blast. On Mythic and Mythic+, the shield phase adds frost damage on everyone that keeps growing until the shield breaks.",
	DGN_TIP_RL_MELIDRUSSA_TANK = "Tank: Pick up the Infused Whelps at once and keep them on the boss for cleave. Their hits stack Cold Claws on you; too many stacks freeze you, so they must die fast. Kick Frigid Shard if no one else does.",
	DGN_TIP_TS_ADDERIS_STEPS = "1. Storm Blessed shields one of the two bosses, and that boss takes almost no damage. Hit the one WITHOUT the shield (Adderis on the pull) and swap as soon as the shield moves.|n2. {SPELL:1311805}: if you are marked, walk to the edge and drop your pool there. The pools silence you, so stay out of them.|n3. {SPELL:1289059}: everyone gets knocked back. Spread out a little and stand so the push does not throw you into a pool.|n4. {SPELL:1288049} comes right after the knockback: run back and stack on the boss to share the hit, then walk out together before the second blast.",
	DGN_TIP_TS_ADDERIS_QUICK_DPS = "Only hit the boss without the shield, and swap fast when it moves.",
	DGN_TIP_TS_ADDERIS_QUICK_HEALER = "Heal the players hit by wind, and top everyone up before the push.",
	DGN_TIP_TS_ADDERIS_QUICK_TANK = "Use a defensive for Overload, and keep both bosses close together.",
	DGN_TIP_TS_ADDERIS_QUICK = "Shield: Hit the boss without the shield, and swap when the shield jumps.|nPools: If you are marked, drop your pool at the edge and stay out of pools.|nPush: After the push, run back and stand together on the boss to share the hit.",
	DGN_TIP_TS_ADDERIS_DPS = "DPS: Never hit the shielded boss - it takes almost no damage. Swap the moment the shield moves, even in the middle of your rotation.",
	DGN_TIP_TS_ADDERIS_HEALER = "Healer: Spot-heal the players hit by Gust. The knockback straight into the group soak is the most dangerous moment - have everyone topped up before it.",
	DGN_TIP_TS_ADDERIS_TANK = "Tank: Use a defensive for {SPELL:1311804}. Keep both bosses close together so the group can swap without running through pools.",
	DGN_TIP_TS_AVATAR_STEPS = "1. You win by healing the Avatar to full health, not by killing her. First kill the Essence Defilers: their {SPELL:1301202} stops all healing on her.|n2. Kill the Corrupted Guardian. It leaves three Corrupted Lifeforce orbs: three different DPS each grab one, quickly. A grabbed orb heals the Avatar; a missed orb explodes on the whole group.|n3. Twisted Hexxers: interrupt Flame Shock. Got {SPELL:1311981}? Walk away from the group before it ends, and leave its zone there.|n4. Once the Defilers are dead, heal the Avatar. Faithless Tormentors spawn and chase the healer: stun and slow them and bring them below 25% health - the Avatar then eats them and heals herself.",
	DGN_TIP_TS_AVATAR_QUICK_DPS = "Kill the Defilers first, then grab one orb each.",
	DGN_TIP_TS_AVATAR_QUICK_HEALER = "Heal the Avatar once the Defilers are dead, and keep running from the chasers.",
	DGN_TIP_TS_AVATAR_QUICK_TANK = "Hold the big add in a corner, and stay away from the orbs.",
	DGN_TIP_TS_AVATAR_QUICK = "Goal: Kill the Defilers first, then heal the Avatar to full to win.|nOrbs: When the big add dies, three DPS each grab one orb, fast.|nChasers: Stun the adds that chase the healer and hit them low; the Avatar then eats them.",
	DGN_TIP_TS_AVATAR_DPS = "DPS: Kill the Essence Defilers first, then the Guardian. Grab one orb each (it gives you {SPELL:1300877}, so use a defensive), kick Flame Shock, and stun and AoE the Tormentors down.",
	DGN_TIP_TS_AVATAR_HEALER = "Healer: Heal the Avatar as soon as the Defilers are dead - that is how the fight is won. Tormentors run at you and every hit lowers your healing, so keep moving. Leave the orbs to the DPS.",
	DGN_TIP_TS_AVATAR_TANK = "Tank: Hold the Corrupted Guardian in a corner away from the group and use a defensive for Tainted Strike. Do not grab orbs: {SPELL:1300877} makes you take much more physical damage.",
	DGN_TIP_TS_GALVAZZT_STEPS = "1. {SPELL:1291618}: three spires shoot beams at Galvazzt. Stand in a beam, between the spire and the boss, so he does not gain energy.|n2. Share the beams: one player per beam, and take turns between sets. Blocking a beam gives you {SPELL:266923}: damage over time and more physical damage taken.|n3. Never leave a beam open. At full energy he casts Consume Charge, which hits the group hard and often wipes it.|n4. {SPELL:1309525}: damage on the whole group, and it leaves an {SPELL:1291815} on the ground. Step out of it.",
	DGN_TIP_TS_GALVAZZT_QUICK_DPS = "Stay in your beam, even if you cannot hit the boss from there.",
	DGN_TIP_TS_GALVAZZT_QUICK_HEALER = "Keep the players in the beams alive.",
	DGN_TIP_TS_GALVAZZT_QUICK_TANK = "Stay out of the beams, and move the boss away from the zones on the ground.",
	DGN_TIP_TS_GALVAZZT_QUICK = "Beams: Stand in a beam, between the tower and the boss, so he cannot charge up.|nTurns: One player per beam, take turns, and never leave a beam open.|nFloor: After the big group hit, step out of the zone on the ground.",
	DGN_TIP_TS_GALVAZZT_DPS = "DPS: Your beam comes before your damage - do not step out of it to hit the boss. Take turns with the others and use a defensive on your turn.",
	DGN_TIP_TS_GALVAZZT_HEALER = "Healer: The beam soakers take steady damage - keep them high, and take a beam yourself when needed. Have a cooldown ready for {SPELL:1309525}.",
	DGN_TIP_TS_GALVAZZT_TANK = "Tank: Do not soak the beams - {SPELL:266923} makes you take much more physical damage. Move the boss away from each {SPELL:1291815}, to a spot where the beams stay easy to reach.",
	DGN_TIP_TS_MEREKTHA_STEPS = "1. {SPELL:1290029}: snakes tie up some players. If you are marked, stand close to the others near the boss, so one AoE stun or crowd control breaks every knot. Then kill the snakes.|n2. {SPELL:1289109}: if you are marked, walk to the edge of the room and drop the pool there, not in the middle.|n3. {SPELL:1293048}: damage on the whole group plus a knockback. Do not stand where the push throws you into a pool.|n4. {SPELL:1289205} and {SPELL:264172}: adds hatch, then she goes under the ground and cannot be hit. Dodge her path (it stuns you), interrupt Poison Spit from the Toxic Vipers, and kill all the adds - that brings her back up.",
	DGN_TIP_TS_MEREKTHA_QUICK_DPS = "When she goes under the ground, kill all the adds fast; that brings her back.",
	DGN_TIP_TS_MEREKTHA_QUICK_HEALER = "Save a cooldown for the storm that hits everyone.",
	DGN_TIP_TS_MEREKTHA_QUICK_TANK = "Use a defensive for her big bite, and grab the adds when she goes under the ground.",
	DGN_TIP_TS_MEREKTHA_QUICK = "Snakes: If snakes tie you up, stand close to the others so one stun frees everyone.|nSpit: If you are marked, drop your pool at the edge of the room.|nUnderground: She hides under the ground. Dodge her path and kill all the adds to bring her back.",
	DGN_TIP_TS_MEREKTHA_DPS = "DPS: Free tied-up players first with a stun or AoE crowd control. During Burrow, kill every add fast - the phase ends when they are all dead - and kick Poison Spit.",
	DGN_TIP_TS_MEREKTHA_HEALER = "Healer: {SPELL:1293048} hits the whole group - plan a cooldown for it. If a Poison Spit gets through, dispel the poison if you can.",
	DGN_TIP_TS_MEREKTHA_TANK = "Tank: Use a defensive for every {SPELL:1290797}. During Burrow, pick up the adds and park the Storm Serpent at the edge, because it leaves pools too.",
})

merge(ns._mhLocales and ns._mhLocales.itIT, {
	-- Windrunner Spire ---------------------------------------------------------
	DGN_TIP_WS_DUO_STEPS = "1. Due boss — danneggiali in modo uniforme così muoiono più o meno insieme.|n2. Interrompi Shadow Bolt; esci dai cerchi di vomito ({SPELL:472745}) — non sprecare spazio sul pavimento.|n3. Cursed ({SPELL:474105})? Falla dispellare in fretta — oppure CC la Dark Entity che genera finché non svanisce.|n4. Agganciato da {SPELL:472793} durante l'urlo? Posizionati in modo da venire tirato ATTRAVERSO la dama spettrale — questo interrompe il suo cast.",
	DGN_TIP_WS_DUO_TANK = "Tank: difensiva per {SPELL:472888}; sposta i boss quando il pavimento si affolla.",
	DGN_TIP_WS_DUO_HEALER = "Healer: grandi danni al gruppo durante {SPELL:472736}; dispella {SPELL:474105} in fretta.",

	DGN_TIP_WS_EMBER_STEPS = "1. Fuoco = male. Posiziona le pozze di fuoco ({SPELL:466556}) ai bordi, tieni pulito il centro.|n2. A piena energia corri VERSO il boss per {SPELL:465904}, poi schiva di lato ogni Fire Breath.|n3. Le vecchie pozze generano vortici di fuoco — continua a schivare.",
	DGN_TIP_WS_EMBER_TANK = "Tank: difensiva per {SPELL:466064}.",
	DGN_TIP_WS_EMBER_HEALER = "Healer: forti danni al gruppo durante {SPELL:465904}.",

	DGN_TIP_WS_KROLUK_STEPS = "1. Cerchi marroni = male, esci.|n2. Raggruppati con un alleato prima che {SPELL:1253026} finisca (sovrapponi i cerchi viola).|n3. Fissato o bersaglio del balzo ({SPELL:1283247})? Portalo lontano dal gruppo.|n4. Quando spawnano gli add (a circa due terzi e un terzo di health): uccidili in fretta — prima il Phantasmal Mystic, e continua a interromperlo.",
	DGN_TIP_WS_KROLUK_TANK = "Tank: difensiva per {SPELL:467620}; sii pronto a prendere il secondo {SPELL:1283247}.",
	DGN_TIP_WS_KROLUK_HEALER = "Healer: danni al gruppo durante {SPELL:472043}.",

	DGN_TIP_WS_HEART_STEPS = "1. Stack di {SPELL:1216042} che ticchettano su di te? Cammina su una freccia di vento (Turbulent Arrow) a 2-3 stack — rimuove il DoT e ti fa saltare oltre l'onda d'urto in espansione.|n2. Tieni una freccia libera per la grande esplosione a piena energia ({SPELL:468429}).|n3. Distanziati un po' per {SPELL:1253979} e usa i cerchi grandi per ripulire il terreno elettrico.|n4. Bersaglio di {SPELL:474528}? Resta fermo e lascia che gli altri si spostino; tutti gli altri: uscite dal frontale.",
	DGN_TIP_WS_HEART_TANK = "Tank: difensiva per {SPELL:472662}; orienta il knockback lontano dalle pozze.",
	DGN_TIP_WS_HEART_HEALER = "Healer: cura prima i giocatori con tanti stack di {SPELL:1216042}; cure extra dopo {SPELL:1253979}.",

	-- Maisara Caverns ------------------------------------------------------------
	DGN_TIP_MC_MUROJIN_STEPS = "1. Due boss (cacciatore e uccello) — uccidili a breve distanza l'uno dall'altro, o il sopravvissuto va in berserk.|n2. Trappole di ghiaccio ({SPELL:1243741}), cerchi verdi ({SPELL:1243900}) e il frontale {SPELL:1260643} = male, stai fuori.|n3. Bersaglio di {SPELL:1249478} (la picchiata dell'uccello)? Corri DENTRO una trappola di ghiaccio — il congelamento ferma la picchiata. Tutti gli altri: allontanatevi da quel giocatore.",
	DGN_TIP_MC_MUROJIN_TANK = "Tank: difensiva per {SPELL:1266480}.",
	DGN_TIP_MC_MUROJIN_HEALER = "Healer: dispella {SPELL:1246666} (malattia) — forti danni al gruppo.",

	DGN_TIP_MC_VORDAZA_STEPS = "1. Il boss genera Unstable Phantoms ({SPELL:1251204}) che inseguono i giocatori. UCCIDILI prima che raggiungano qualcuno — un fantasma che raggiunge il suo bersaglio (o tocca un altro fantasma) esplode con forti danni nelle vicinanze.|n2. Ogni fantasma ucciso urla: danni al gruppo inevitabili — quindi uccidili UNO alla volta.|n3. Schiva l'ondata frontale di {SPELL:1252054} (ti spinge via), gli orb fluttuanti e Soulrot.|n4. Qualcuno avvolto in un Deathshroud? Liberalo in fretta; interrompi {SPELL:1250708} e schiva i vortici durante.",
	DGN_TIP_MC_VORDAZA_TANK = "Tank: difensiva per {SPELL:1251554}.",
	DGN_TIP_MC_VORDAZA_HEALER = "Healer: ogni fantasma ucciso urla ({SPELL:1251813}) = danni al gruppo — cura tra le uccisioni scaglionate.",

	DGN_TIP_MC_RAKTUL_STEPS = "1. Il boss balza su tre giocatori ({SPELL:1252676}) e lascia Soulbind Totems — distanziatevi così i totem atterrano separati, non farti schiacciare, e uccidi i totem in fretta.|n2. Stai fuori dal terreno di Chill of Death.|n3. Fase dell'anima ({SPELL:1253788}): vieni estratto dal tuo corpo — CC e interrompi i grandi add mentre corri verso il tuo corpo.|n4. Schiva i vortici della Deathgorged Vessel.",
	DGN_TIP_MC_RAKTUL_TANK = "Tank: difensiva per {SPELL:1251023}; posiziona le pozze lontano dal gruppo.",
	DGN_TIP_MC_RAKTUL_HEALER = "Healer: forti danni al gruppo durante la Deathgorged Vessel e quando i totem si frantumano.",

	-- Murder Row ----------------------------------------------------------------
	DGN_TIP_MR_KYSTIA_STEPS = "1. Uccidi prima Nibbles. Kystia ha uno scudo fel e non subisce quasi danni finché Nibbles è sopra il 20% di salute.|n2. Al 20% Nibbles si rivolta contro Kystia con {SPELL:1230304}: Kystia viene stordita e subisce molti più danni per poco tempo. Passa su Kystia ora e usa i tuoi grandi cooldown.|n3. {SPELL:1264095}: compaiono copie di Kystia che lanciano Felstorm. Interrompi, stunna o fai CC su ogni copia.|n4. Stai fuori dal cono {SPELL:1253811} di Nibbles e dal fuoco che lascia a terra.|n5. In Eroico e superiori: {SPELL:474240} - salta su un giocatore ed esplode. Allontanati da lei.",
	DGN_TIP_MR_KYSTIA_QUICK_DPS = "Colpisci prima il pet, poi il boss quando il pet ha poca salute.",
	DGN_TIP_MR_KYSTIA_QUICK_HEALER = "Togli in fretta il debuff dello sputo dai giocatori, e tieni una grande cura per il cambio.",
	DGN_TIP_MR_KYSTIA_QUICK_TANK = "Punta il cono di fuoco del pet lontano dal gruppo.",
	DGN_TIP_MR_KYSTIA_QUICK = "Pet: colpisci prima il pet Nibbles. Il boss ha uno scudo e non subisce quasi danni.|nCambio: quando Nibbles ha poca salute, stordisce il boss. Ora colpisci forte il boss.|nCopie: compaiono copie del boss. Interrompi o stordisci ognuna.",
	DGN_TIP_MR_KYSTIA_TANK = "Tank: orienta il cono {SPELL:1253811} di Nibbles lontano dal gruppo. Tieni Kystia e Nibbles vicine così il gruppo può colpirle entrambe in cleave. Chaos Barrage di Kystia ti colpisce forte, quindi tieni pronta una difensiva.",
	DGN_TIP_MR_KYSTIA_HEALER = "Healer: dispella Corroding Spittle (magia) in fretta, soprattutto durante {SPELL:1264095}. Tieni un cooldown di cura per la finestra di burst dopo {SPELL:1230304}: Kystia stordita manda esplosioni fel sul gruppo.",

	DGN_TIP_MR_ZAEN_STEPS = "1. Delle casse cadono sui giocatori ({SPELL:474765}). Esci dai segnalini. Le casse atterrate sono il tuo riparo.|n2. {SPELL:1218347}: mira a tutti quelli che vede. Nasconditi dietro una cassa prima che spari, così non ti vede. Ognuno ha bisogno della sua cassa.|n3. Hai {SPELL:1214357}? La bomba esplode dopo 6 secondi e distrugge le casse vicino a te. Portala lontano dalle casse che ti servono come riparo.|n4. {SPELL:474478}: 3 secondi di forti danni su tutto il gruppo. Sii al massimo della salute.|n5. In Mitico e Mythic+: le casse fel verdi (Fel-Infused Freight) fanno male a tutto il gruppo di continuo. Se hai {SPELL:1214357}, portala vicino a una cassa verde per distruggerla, e conserva le casse normali.",
	DGN_TIP_MR_ZAEN_QUICK_DPS = "Sii dietro una cassa prima del grande sparo, non dopo.",
	DGN_TIP_MR_ZAEN_QUICK_HEALER = "Togli il veleno dal tank, e porta tutti al massimo prima della raffica di colpi.",
	DGN_TIP_MR_ZAEN_QUICK_TANK = "Usa una difensiva quando ti pugnala, e fatti togliere il veleno.",
	DGN_TIP_MR_ZAEN_QUICK = "Casse: cadono casse dal cielo. Spostati, poi usale come muri.|nSparo: quando mira a tutti, nasconditi dietro una cassa così non ti vede.|nBomba: hai la bomba? Portala lontano dalle casse dietro cui ti nascondi.",
	DGN_TIP_MR_ZAEN_TANK = "Tank: usa una difensiva per {SPELL:1222795}. Lascia anche Heartstop Poison, che riduce la tua salute massima: fattelo dispellare o rimuovilo da solo.",
	DGN_TIP_MR_ZAEN_HEALER = "Healer: dispella Heartstop Poison dal tank dopo {SPELL:1222795}. Porta tutti al massimo prima di {SPELL:474478}, e cura il bleed su chi è stato colpito dallo sparo.",

	DGN_TIP_MR_XATHUUX_STEPS = "1. {SPELL:1214637}: lancia la sua ascia su un giocatore. Se sei tu, stai vicino al boss ma lontano dagli altri. L'ascia resta a terra e fulmina tutti sempre più forte: distruggila in fretta.|n2. Infernal Crush ({SPELL:1295452}): compaiono cerchi sotto i giocatori. Distanziatevi per non colpirvi a vicenda.|n3. {SPELL:474197}: danni su tutti, poi per 15 secondi attacca più veloce e subisce il 30% di danni in più. Usa i tuoi cooldown ora.|n4. Durante la furia lascia fuoco dove cammina ({SPELL:474234}). Stai fuori dal fuoco. Il tank lo porta piano lungo il bordo della stanza.",
	DGN_TIP_MR_XATHUUX_QUICK_DPS = "Distruggi prima l'ascia, e tieni i tuoi attacchi più forti per la furia.",
	DGN_TIP_MR_XATHUUX_QUICK_HEALER = "Prepara una grande cura per la furia, e porta il tank al massimo prima del grande fendente.",
	DGN_TIP_MR_XATHUUX_QUICK_TANK = "Usa una difensiva per il suo grande fendente, e portalo piano lungo il bordo quando è in furia.",
	DGN_TIP_MR_XATHUUX_QUICK = "Ascia: lancia la sua ascia. Mettila vicino al boss e rompila in fretta.|nCerchi: quando compare un cerchio sotto di te, allontanati dagli altri.|nFuria: quando si arrabbia subisce più danni. Colpisci forte e stai fuori dalla sua scia di fuoco.",
	DGN_TIP_MR_XATHUUX_TANK = "Tank: usa una difensiva per {SPELL:473898}; riduce le cure che ricevi per 8 secondi. Orientalo lontano dal gruppo e spostalo sopra l'ascia così viene colpita in cleave. Durante {SPELL:474197}, portalo piano lungo il bordo così il fuoco resta fuori dal centro.",
	DGN_TIP_MR_XATHUUX_HEALER = "Healer: {SPELL:474197} e Infernal Crush arrivano spesso vicini, quindi pianifica un cooldown. Il tank riceve molte meno cure dopo {SPELL:473898}; portalo al massimo prima. Ogni secondo che l'ascia resta viva, il gruppo subisce più danni.",

	DGN_TIP_MR_LITHIEL_STEPS = "1. Interrompi ogni Chaos Bolt. Decidete un ordine degli interrupt.|n2. {SPELL:1218203}: dei cerchi atterrano sui giocatori. Distanziatevi di 6 yard. Ogni cerchio crea Wild Imps: stunnali o interrompili e uccideteli insieme.|n3. {SPELL:474408}: arriva un grosso demone. Il tank lo prende, tutti lo uccidono.|n4. {SPELL:1224478}: un'onda di fuoco fel attraversa la stanza. Uccidi tutti i demoni prima che li raggiunga, o diventano molto più veloci. Prendi il Demonic Gateway per evitare l'onda; se ti colpisce, subisci più danni da fuoco.|n5. In Mitico e Mythic+: un Infernal insegue il tank. Non può essere ucciso e toccarlo può ucciderti. Il tank lo tiene lontano dal gruppo e dal gateway.",
	DGN_TIP_MR_LITHIEL_QUICK_DPS = "Interrompi il boss e gli imp, e uccidi tutti i demoni prima dell'onda.",
	DGN_TIP_MR_LITHIEL_QUICK_HEALER = "Tutti subiscono danni da fuoco per tutto lo scontro. Cura per primo chi è stato colpito dall'onda.",
	DGN_TIP_MR_LITHIEL_QUICK_TANK = "Prendi in fretta i demoni. In Mitico, porta l'Infernal lontano da tutti.",
	DGN_TIP_MR_LITHIEL_QUICK = "Interrupt: ferma ogni Chaos Bolt che il boss lancia.|nImp: allontanati dagli altri. Escono piccoli demoni. Stordiscili e uccidili in fretta.|nOnda: uccidi tutti i demoni prima dell'onda di fuoco, poi prendi il portale per evitarla.",
	DGN_TIP_MR_LITHIEL_TANK = "Tank: prendi in fretta il Vilefiend, ti colpisce forte. Tieni i Wild Imps raggruppati così possono essere colpiti in cleave. In Mitico, kita l'Infernal lontano dal gruppo e mai vicino al gateway.",
	DGN_TIP_MR_LITHIEL_HEALER = "Healer: per tutto lo scontro il gruppo subisce danni da fuoco costanti. Chi viene colpito da {SPELL:1224478} continua a bruciare e subisce più danni da fuoco: curalo per primo.",

	-- Den of Nalorakk -----------------------------------------------------------
	DGN_TIP_DN_HOARDMONGER_STEPS = "1. {SPELL:1234233}: per qualche secondo lancia cibo marcio. Schiva gli impatti. Poi sul pavimento crescono Rotten Mushrooms verdi.|n2. Calpesta ogni fungo prima che scoppi (circa 12 secondi). Distanziatevi così non se ne perde nessuno. Ogni fungo ti dà un veleno, quindi fate a turno.|n3. {SPELL:1253268} è un cono frontale. Esci dall'area che mostra. {SPELL:1235118} colpisce tutto il gruppo, quindi resta al massimo della salute.|n4. Per tre volte corre verso un mucchio di carne, ossa o funghi e ottiene una nuova mossa. La carne rende il suo ruggito più forte. Le ossa danno uno schianto che lascia ossa rotte a terra ({SPELL:1235405}): non camminarci sopra. I funghi significano più funghi da calpestare.|n5. In Mitico e Mythic+: ogni nuova mossa resta per il resto dello scontro, quindi si sommano. Le guide prendono prima la carne, poi le ossa, infine i funghi.",
	DGN_TIP_DN_HOARDMONGER_QUICK_DPS = "Aiuta a calpestare i funghi, e fai a turno con gli altri.",
	DGN_TIP_DN_HOARDMONGER_QUICK_HEALER = "Cura forte quando ruggisce, e se puoi togli il veleno a chi calpesta i funghi.",
	DGN_TIP_DN_HOARDMONGER_QUICK_TANK = "Parcheggia il boss accanto al mucchio che vuoi: carne, poi ossa, poi funghi.",
	DGN_TIP_DN_HOARDMONGER_QUICK = "Funghi: calpesta i funghi verdi prima che scoppino, e fate a turno.|nSchianto: il boss colpisce il terreno davanti a sé. Esci da quell'area.|nMucchi: prende cibo da un mucchio e impara un nuovo trucco. Non camminare sulle ossa che lascia.",
	DGN_TIP_DN_HOARDMONGER_TANK = "Tank: corre verso il mucchio più vicino, quindi parcheggialo accanto a quello che vuoi: prima la carne, poi le ossa, infine i funghi. Tieni le zone di ossa lontane da dove sta il gruppo.",
	DGN_TIP_DN_HOARDMONGER_HEALER = "Healer: usa un cooldown di cura su {SPELL:1235118}: ignora l'armatura e colpisce tutti. Chi soaka i funghi riceve un veleno (Toxic Spores): dispellalo se la tua classe può, e tienili al massimo.",

	DGN_TIP_DN_SENTINEL_STEPS = "1. {SPELL:1235623}: piccoli tornado atterrano e vagano per la stanza a lungo. State vicini così cadono in un solo punto, poi allontanatevi.|n2. {SPELL:1235783}: due ghiaccioli precipitano. Esci dai cerchi. Ognuno lascia un add Fractured Shivercore.|n3. Gli add lanciano Winter's Shroud. Interrompilo: ogni cast fa subire a tutto il gruppo più danni da gelo. Un add morto lascia uno Snowdrift: neve alta che ti rallenta, ma finché ci stai dentro niente può spostarti.|n4. {SPELL:1235656}: una grande tempesta colpisce tutti e sposta i giocatori. Uccidi un add poco prima e resta nel suo Snowdrift finché la tempesta non finisce. Poi uccidi l'altro add.|n5. In Mitico e Mythic+: un add che muore lascia cadere frammenti di ghiaccio (Rimeshatter). Metti esattamente un giocatore in ogni cerchio di frammento. Un frammento mancato colpisce tutto il gruppo e immobilizza tutti.",
	DGN_TIP_DN_SENTINEL_QUICK_DPS = "Fate a turno per fermare i cast degli add, e uccidi il primo add poco prima della tempesta.",
	DGN_TIP_DN_SENTINEL_QUICK_HEALER = "Togli in fretta il debuff di gelo, e cura tutti durante la tempesta.",
	DGN_TIP_DN_SENTINEL_QUICK_TANK = "Metti il boss sopra un add, e tienilo lontano dai tornado.",
	DGN_TIP_DN_SENTINEL_QUICK = "Tornado: state vicini così cadono in un solo punto, poi allontanatevi.|nAdd: compaiono due add di ghiaccio. Ferma il loro cast, e uccidine uno poco prima della tempesta.|nTempesta: stai nella neve che lascia l'add morto. Così la tempesta non può spostarti.",
	DGN_TIP_DN_SENTINEL_TANK = "Tank: trascina il boss sopra un add così il gruppo lo colpisce in cleave, e tieni il boss lontano dai tornado. Aiuta a interrompere Winter's Shroud.",
	DGN_TIP_DN_SENTINEL_HEALER = "Healer: {SPELL:1235548} è un DoT magico di gelo: dispellalo in fretta, e cura quelli che non puoi dispellare. La tempesta colpisce tutti, quindi sii pronto a curare il gruppo.",

	DGN_TIP_DN_NALORAKK_STEPS = "1. {SPELL:1242860}: tre giocatori ricevono un marchio. Vai al bordo prima che finisca: dove ti trovi compare un orso fantasma (un Echo). Mettete tutti gli Echo insieme, lontano dal gruppo. Gli Echo fanno male a chi è vicino ogni volta che lui sbrana.|n2. {SPELL:1243011}: Nalorakk butta a terra Zul'jarra e ogni Echo carica verso di lei. State intorno a lei come un muro e bloccate le cariche. Un Echo che la raggiunge fa male a tutto il gruppo.|n3. {SPELL:1243569}: Nalorakk colpisce il tank ancora e ancora. Zul'jarra alza uno scudo che dimezza questi danni: tutti stanno dietro il suo scudo.|n4. Subito dopo, solo il tank entra in Forceful Slam. Tutti gli altri escono. Se colpisce invece Zul'jarra, tutto il gruppo subisce danni.|n5. In Mitico e Mythic+: bloccare un Echo ti dà anche un bleed che si accumula (Spectral Slash). Metti un giocatore in ogni corsia di carica, e non lasciare mai che due persone blocchino lo stesso Echo.",
	DGN_TIP_DN_NALORAKK_QUICK_DPS = "Mettiti sulla strada di un orso fantasma, una persona per orso.",
	DGN_TIP_DN_NALORAKK_QUICK_HEALER = "Cura forte il tank durante i grossi colpi, e porta tutti al massimo prima del ruggito.",
	DGN_TIP_DN_NALORAKK_QUICK_TANK = "Nasconditi dietro lo scudo di Zul'jarra, poi prendi da solo lo slam successivo.",
	DGN_TIP_DN_NALORAKK_QUICK = "Marchi: se ricevi un marchio, vai al bordo. Lì compare un orso fantasma.|nCarica: gli orsi fantasma corrono verso Zul'jarra. Mettiti sulla loro strada per fermarli.|nScudo: quando il boss colpisce il tank tante volte, tutti si nascondono dietro lo scudo di Zul'jarra.",
	DGN_TIP_DN_NALORAKK_TANK = "Tank: {SPELL:1243569} è su di te. Stai dietro lo scudo di Zul'jarra e usa una difensiva. Poi entra da solo in Forceful Slam, lontano dal gruppo.",
	DGN_TIP_DN_NALORAKK_HEALER = "Healer: il tank subisce grossi colpi durante {SPELL:1243569}, poi Forceful Slam. Porta il gruppo al massimo prima di Forceful Roar. In Mythic+, controlla gli stack di bleed sui giocatori che bloccano gli Echo.",

	-- The Blinding Vale ---------------------------------------------------------
	DGN_TIP_BV_TRINITY_STEPS = "1. I tre boss condividono una sola barra della salute. Il tank li raggruppa e tutti colpiscono tutti e tre. Interrompi Light Bolt di Kezkitt.|n2. {SPELL:1234753} colpisce il tank e lascia tre cerchi verdi. Non entrarci ancora. Poi Lekshi scatta attraverso tutti e tre i cerchi ({SPELL:1234850}) - stai fuori da quella linea.|n3. Quando inizia {SPELL:1235564}, un giocatore sta in ogni cerchio (il tank più altri due) finché il raggio non finisce. Un cerchio vuoto fa subire più tardi grossi danni a tutto il gruppo.|n4. Dopo il raggio i cerchi diventano terreno in fiamme ({SPELL:1235828}). Esci; il tank sposta i boss su terreno pulito. {SPELL:1261276} fa sanguinare un giocatore a caso: usa una difensiva o rimuovi il bleed.|n5. In Mitico e Mythic+: dopo Thornblade, Lekshi salta su quel giocatore e sparge spine attorno a lui. Quel giocatore si allontana dal gruppo, poi esce dalle spine. Bedrock Slam manda anche impulsi di danni attraverso tutto il gruppo.",
	DGN_TIP_BV_TRINITY_QUICK_DPS = "Colpisci tutti e tre i boss insieme, e interrompi il dardo di Kezkitt.",
	DGN_TIP_BV_TRINITY_QUICK_HEALER = "Tieni vivi i giocatori nei cerchi, e cura il giocatore che sanguina.",
	DGN_TIP_BV_TRINITY_QUICK_TANK = "Usa una difensiva sul grande slam, poi sposta i tre boss fuori dal terreno in fiamme.",
	DGN_TIP_BV_TRINITY_QUICK = "Tre boss: condividono una barra della salute. Raggruppali e colpisci tutti e tre.|nCerchi: quando arriva il raggio, un giocatore sta in ogni cerchio finché non si ferma.|nScatto: stai fuori dalla linea tra i cerchi, ed esci dai cerchi quando bruciano.",
	DGN_TIP_BV_TRINITY_TANK = "Tank: usa una difensiva per {SPELL:1234753}. Tieni i tre raggruppati per il cleave, stai in un cerchio durante il raggio, poi sposta i boss fuori dal terreno in fiamme prima del prossimo slam.",
	DGN_TIP_BV_TRINITY_HEALER = "Healer: i tre che soakano i cerchi subiscono danni continui - tienili su, e cura il bleed di {SPELL:1261276}. In Mitico, tieni un cooldown per gli impulsi di gruppo dopo Bedrock Slam.",

	DGN_TIP_BV_IKUZZ_STEPS = "1. {SPELL:1236746} colpisce tutti e ti respinge. Posizionati in modo da non volare giù da un bordo o dentro le radici.|n2. {SPELL:1236709}: ruggisce e fa male a tutto il gruppo per 6 secondi. Usa una difensiva se hai poca salute.|n3. {SPELL:1237091}: insegue un giocatore per 10 secondi. Quel giocatore corre e lo porta sopra le radici a terra - i suoi passi le schiacciano. Se ti prende, sanguini e vieni stordito ({SPELL:1272290}).|n4. Dal 50% di salute va in frenesia: si muove più veloce e fa male al gruppo di continuo. Tieni i cooldown per questo momento.|n5. In Mitico e Mythic+: qualche secondo dopo il pestone le radici afferrano ogni giocatore, e durante il ruggito crescono altre radici. Torna vicino al boss così il gruppo può colpire le radici in cleave, o usa un'abilità di liberazione.",
	DGN_TIP_BV_IKUZZ_QUICK_DPS = "Rompi in fretta le radici, e se ti insegue, corri sopra le radici.",
	DGN_TIP_BV_IKUZZ_QUICK_HEALER = "Tieni le tue cure più forti per quando è a metà salute.",
	DGN_TIP_BV_IKUZZ_QUICK_TANK = "Tieni il boss vicino ai giocatori bloccati dalle radici, così tutti possono romperle.",
	DGN_TIP_BV_IKUZZ_QUICK = "Pestone: respinge tutti. Non stare vicino a un bordo.|nInseguimento: insegue un giocatore. Quel giocatore corre sopra le radici così lui le schiaccia.|nMetà salute: diventa più veloce e colpisce più forte. Usa ora le tue abilità più forti.",
	DGN_TIP_BV_IKUZZ_TANK = "Tank: tieni Ikuzz vicino ai giocatori bloccati dalle radici così tutti possono colpire le radici in cleave, e lontano dai bordi per il knockback.",
	DGN_TIP_BV_IKUZZ_HEALER = "Healer: il pestone e {SPELL:1236709} colpiscono tutto il gruppo. Tieni i grandi cooldown per la frenesia al 50%, soprattutto quando ruggisce durante la frenesia. Un giocatore preso subisce grossi danni - curalo in fretta.",

	DGN_TIP_BV_RUIA_STEPS = "1. Forma moonkin (dal 100 al 70%): interrompi Warden's Wrath - colpisce il tank. Schiva i cerchi di {SPELL:1240098}.|n2. {SPELL:1239825} marchia alcuni giocatori. Allontanati dal gruppo prima che finisca: poi da te partono dei raggi. Stai fuori dai raggi - ti silenziano.|n3. Forma orso (dal 70 al 40%): {SPELL:1240222} marchia alcuni giocatori e spara coni verso di loro. I giocatori marchiati si distanziano e tengono il proprio cono lontano dagli altri. Un secondo colpo fa molto più male.|n4. {SPELL:1241058} fa sanguinare i giocatori finché non vengono curati al massimo della salute.|n5. Al 40% di salute, {SPELL:1241067}: lancia tutto questo ogni 8 secondi finché non muore. Usa qui i tuoi cooldown e Bloodlust.",
	DGN_TIP_BV_RUIA_QUICK_DPS = "Interrompi il suo incantesimo in forma moonkin, e tieni le tue abilità più forti per il 40 percento.",
	DGN_TIP_BV_RUIA_QUICK_HEALER = "Un giocatore che sanguina continua a sanguinare finché non lo curi fino al massimo.",
	DGN_TIP_BV_RUIA_QUICK_TANK = "Assicurati che il suo incantesimo venga interrotto in forma moonkin, e usa le difensive in forma orso.",
	DGN_TIP_BV_RUIA_QUICK = "Moonkin: interrompi il suo incantesimo, schiva i cerchi, e allontanati dal gruppo se ricevi il marchio del raggio.|nOrso: se sei marchiato, allontanati così il tuo cono non colpisce nessun altro.|n40%: fa tutto insieme. Usa ora le tue abilità più forti.",
	DGN_TIP_BV_RUIA_TANK = "Tank: in forma moonkin i suoi colpi in mischia sono sostituiti da Warden's Wrath - assicurati che venga interrotto. In forma orso i suoi colpi in mischia fanno il doppio (Mangling Claws), quindi usa lì le tue difensive.",
	DGN_TIP_BV_RUIA_HEALER = "Healer: {SPELL:1241058} si ferma solo quando un giocatore è al massimo della salute - cura un bersaglio fino al massimo, poi il successivo. Tieni i cooldown per la fase al 40%.",

	DGN_TIP_BV_ZIEKKET_STEPS = "1. {SPELL:1246372}: spuntano delle lasher. Il tank le raggruppa; tutti le colpiscono in cleave e interrompono Lightspore Shot.|n2. Una lasher all'1% di salute sprofonda nel terreno e non subisce danni. Si risveglia più forte al prossimo {SPELL:1246372}, e allora non può essere interrotta né stordita.|n3. {SPELL:1253690} punta un raggio su un giocatore. Se sei tu, girati così il raggio passa su ogni lasher dormiente - così muoiono per sempre. Lascia pozze che rallentano ({SPELL:1246753}); esci da quelle pozze.|n4. {SPELL:1247685} colpisce forte il tank, lo respinge e lo fa sanguinare. Tutto il gruppo subisce danni a impulsi per tutto lo scontro.|n5. In Mitico e Mythic+: {SPELL:1246858} manda orb verso Ziekket. Entraci prima che lo raggiungano, e divideteveli (circa due o tre a testa) - ogni orb ti dà un DoT che si accumula. Un orb che lo raggiunge fa male al gruppo e gli dà uno scudo.",
	DGN_TIP_BV_ZIEKKET_QUICK_DPS = "Interrompi i colpi delle lasher, e smetti di colpire una lasher quando dorme.",
	DGN_TIP_BV_ZIEKKET_QUICK_HEALER = "Tutto il gruppo subisce danni per tutto lo scontro, quindi continua a curare tutti.",
	DGN_TIP_BV_ZIEKKET_QUICK_TANK = "Raggruppa le lasher, e usa una difensiva sul grande colpo di spine.",
	DGN_TIP_BV_ZIEKKET_QUICK = "Lasher: colpiscile finché non sprofondano nel terreno. Poi dormono.|nRaggio: se il raggio punta su di te, fallo passare sulle lasher che dormono. Così muoiono per sempre.|nOrb Mitico: tocca le sfere luminose prima che raggiungano il boss, e dividile con gli altri.",
	DGN_TIP_BV_ZIEKKET_TANK = "Tank: raggruppa ogni ondata di lasher per il cleave, vicino al bordo. Usa una difensiva per {SPELL:1247685} - ti respinge e ti fa sanguinare. Esci dalle pozze di Lightsap.",
	DGN_TIP_BV_ZIEKKET_HEALER = "Healer: il gruppo subisce danni per tutto lo scontro, quindi continua a curare tutti. In Mitico, controlla chi soaka gli orb - i loro stack fanno male, e un orb mancato colpisce tutto il gruppo.",

	-- Voidscar Arena ------------------------------------------------------------
	DGN_TIP_VA_TAZRAH_STEPS = "1. {SPELL:1222098}: un'ombra scatta in linea attraverso ogni giocatore. Distanziatevi un po' vicino al bordo della stanza, così la tua linea non colpisce nessun altro.|n2. {SPELL:1296963} lascia pozze a terra. Lasciale vicino al bordo e vicine tra loro, e non starci mai dentro.|n3. {SPELL:1300259}: le pozze sparano orb. Continua a muoverti per la stanza e schiva ogni orb.|n4. In Mitico e Mythic+: {SPELL:1225011} - due frammenti volano verso un giocatore, e ognuno esplode sul primo giocatore che colpisce. Non entrare nei frammenti diretti a qualcun altro.",
	DGN_TIP_VA_TAZRAH_QUICK_DPS = "Continua a colpire il boss mentre schivi.",
	DGN_TIP_VA_TAZRAH_QUICK_HEALER = "Porta tutti al massimo prima che arrivino le pozze.",
	DGN_TIP_VA_TAZRAH_QUICK_TANK = "Usa una difensiva quando ti respinge, e non finire in una pozza.",
	DGN_TIP_VA_TAZRAH_QUICK = "Scatto: un fantasma corre verso di te in linea. Stai vicino al muro, un po' lontano dai tuoi amici.|nPozze: lascia le tue pozze scure vicino al muro, vicine tra loro. Non starci mai dentro.|nSfere: le pozze sparano sfere. Continua a camminare per la stanza e schivale.",
	DGN_TIP_VA_TAZRAH_TANK = "Tank: {SPELL:1297017} ti colpisce forte e ti respinge. Usa una difensiva e non farti spingere in una pozza. Tanka vicino a un muro e gira piano per la stanza, così il centro resta libero.",
	DGN_TIP_VA_TAZRAH_HEALER = "Healer: porta tutti al massimo prima di ogni cast di {SPELL:1296963}; {SPELL:1300259} fa male a tutto il gruppo. Cura i giocatori colpiti da uno scatto, perché continua a fargli male per un po'.",

	DGN_TIP_VA_ATROXUS_STEPS = "1. {SPELL:1262497} colpisce tutto il gruppo. Circa 3 secondi dopo striscia fuori un Toxic Creeper ({SPELL:1222371}). Uccidilo in fretta.|n2. {SPELL:1263977} è un frontale diretto a un giocatore a caso. Stai vicino al boss così puoi uscirne in fretta.|n3. {SPELL:1226120} schizza veleno attorno al boss. Schiva gli impatti e stai fuori dalle pozze di veleno che lascia.|n4. In Mitico e Mythic+: il Creeper ha Toxic Aura - fa male a tutti entro 8 yard finché non muore. Uccidilo ancora più in fretta; chi attacca a distanza gli sta lontano.",
	DGN_TIP_VA_ATROXUS_QUICK_DPS = "Quando esce il Creeper, colpisci prima lui.",
	DGN_TIP_VA_ATROXUS_QUICK_HEALER = "Togli i veleni dal tank e da chi è stato in una pozza.",
	DGN_TIP_VA_ATROXUS_QUICK_TANK = "Il Creeper ti insegue: allontanati così non può morderti.",
	DGN_TIP_VA_ATROXUS_QUICK = "Ruggito: il boss ruggisce e striscia fuori un piccolo mostro, il Creeper. Tutti lo colpiscono finché non muore.|nSoffio: il boss soffia verso un giocatore a caso. Stai vicino, ed esci dal soffio.|nVeleno: allontanati dagli schizzi di veleno e dalle pozze.",
	DGN_TIP_VA_ATROXUS_TANK = "Tank: il Creeper ti fissa. Kitalo e non farti colpire - ogni morso aggiunge uno stack di Sickening Bite, e gli stack rendono {SPELL:1222642} mortale. Tienilo vicino al boss così i DPS possono colpirli entrambi, e usa una difensiva per l'artigliata.",
	DGN_TIP_VA_ATROXUS_HEALER = "Healer: dispella i veleni: il veleno di {SPELL:1222642} sul tank e Mind-Numbing Poison dalle pozze. In Mitico e Mythic+, usa un cooldown di cura mentre il Creeper è vivo.",

	DGN_TIP_VA_CHARONUS_STEPS = "1. {SPELL:1282770}: alcuni giocatori vengono marchiati, e qualche secondo dopo sotto di loro compare un pozzo gravitazionale. Ti attira dentro e fa male. Esci, ma resta accanto a uno - ti serve per gli orb. Il suo centro dà Atomized: niente danni e niente cure per poco tempo.|n2. {SPELL:1263982}: un orb insegue 3 giocatori. Il suo debuff fa male e ti rallenta sempre di più ogni secondo. Passa accanto a un pozzo gravitazionale così il tuo orb ti segue e ci finisce dentro - questo li distrugge entrambi. Non fermarti dentro. Ogni giocatore usa un pozzo diverso.|n3. {SPELL:1227264} colpisce tutti, ti respinge e lascia un effetto di danni di 20 secondi. State distanti tra voi, e assicurati di non atterrare in un pozzo.|n4. In Mitico e Mythic+: {SPELL:1222758} - dei proiettili volano verso un giocatore a caso e respingono chi toccano. Se sei tu, continua a correre; tutti gli altri escono dal percorso.",
	DGN_TIP_VA_CHARONUS_QUICK_DPS = "Aspetta accanto a un buco, così una sfera che ti insegue ci cade dentro subito.",
	DGN_TIP_VA_CHARONUS_QUICK_HEALER = "Cura prima i giocatori inseguiti da una sfera.",
	DGN_TIP_VA_CHARONUS_QUICK_TANK = "Usa una difensiva per il suo grande colpo e orientalo lontano dai tuoi amici.",
	DGN_TIP_VA_CHARONUS_QUICK = "Pozzi: sul pavimento compaiono buchi scuri. Ti attirano dentro, quindi stai vicino a uno ma non dentro.|nSfere: se una sfera ti insegue, passa accanto a un buco così la sfera ci cade dentro.|nEsplosione: il boss spinge tutti indietro. Stai lontano dagli altri, e non volare dentro un buco.",
	DGN_TIP_VA_CHARONUS_TANK = "Tank: {SPELL:1311923} è un colpo frontale sul tank. Usa una difensiva e orientalo lontano dal gruppo. Tieni il boss al centro dei tre pozzi gravitazionali, e non girarlo attraverso i giocatori.",
	DGN_TIP_VA_CHARONUS_HEALER = "Healer: cura prima i giocatori con un orb - più a lungo lo portano, più forte colpisce. Dopo {SPELL:1227264} tutto il gruppo ha un effetto di danni di 20 secondi, e i pozzi gravitazionali pulsano danni finché durano.",

	-- Nexus-Point Xenas ---------------------------------------------------------
	DGN_TIP_NX_KASRETH_STEPS = "1. Hai {SPELL:1251785}? Cammina DENTRO un raggio di leyline ({SPELL:1251183}) — rimuove il debuff (breve stun, ne vale la pena).|n2. Tutti gli altri: NON attraversate le leyline (danni + rallentamento crescente).|n3. Piena energia = {SPELL:1257509}: grande zona d'impatto, allontanati — le fuoriuscite arcane ({SPELL:1264048}) restano dopo.",
	DGN_TIP_NX_KASRETH_TANK = "Tank: tieni il boss lontano dalle leyline.",
	DGN_TIP_NX_KASRETH_HEALER = "Healer: Sparkburn ticchetta su tutti dopo ogni detonazione.",

	DGN_TIP_NX_NYSARRA_STEPS = "1. Distanziatevi — i colpi di {SPELL:1249020} schizzano per 14 yard.|n2. Uccidi gli add Null Vanguard ({SPELL:1252703}) IN FRETTA: tutto ciò che resta vivo viene divorato ({SPELL:1271684}), la cura e fa esplodere il gruppo.|n3. Schiva {SPELL:1264439}.",
	DGN_TIP_NX_NYSARRA_TANK = "Tank: balza su di te con una combo di fendenti ({SPELL:1247937}) — difensiva, preparati al finisher.",
	DGN_TIP_NX_NYSARRA_HEALER = "Healer: danni distribuiti dopo {SPELL:1249020}; esplosione di gruppo se gli add sopravvivono al divoramento.",

	DGN_TIP_NX_LOTHRAXION_STEPS = "1. {SPELL:1255503}: distanziatevi — gli impatti schizzano per 8 yard e generano Fractured Images.|n2. {SPELL:1257567}: si nasconde tra le sue immagini e canalizzano tutte — trova il VERO Lothraxion e interrompilo.|n3. Le immagini sfarfallano in giro con knockback ({SPELL:1255531}); stai fuori da {SPELL:1255310} sul pavimento.",
	DGN_TIP_NX_LOTHRAXION_TANK = "Tank: {SPELL:1255335} è un doppio fendente che incide cicatrici nel terreno — orientalo lontano dal gruppo.",
	DGN_TIP_NX_LOTHRAXION_HEALER = "Healer: DoT Holy dopo ogni {SPELL:1255503}; danni costanti finché non scatta l'interrupt su Guile.",

	-- Magisters' Terrace --------------------------------------------------------
	DGN_TIP_MT_ARCANOTRON_STEPS = "1. Quando si rifornisce ({SPELL:474345}), gli Energy Orbs vengono attratti verso di lui — intercettali; nel frattempo subisce +20% danni: finestra di burst!|n2. I giocatori incatenati ({SPELL:1214038}) sono immobilizzati (magic) — dispella o liberali.|n3. {SPELL:1214081} respinge tutti e lascia residui ai suoi piedi — esci da essi.",
	DGN_TIP_MT_ARCANOTRON_TANK = "Tank: {SPELL:474496} ti lancia — tieni le spalle libere.",
	DGN_TIP_MT_ARCANOTRON_HEALER = "Healer: dispella {SPELL:1214038} (root magic) in fretta.",

	DGN_TIP_MT_SERANEL_STEPS = "1. {SPELL:1225193} pacifica tutti FUORI dalla Suppression Zone ({SPELL:1224903}) — entra nella zona per l'onda (ma la zona ti silenzia, quindi non indugiare).|n2. Purge/spellsteal il suo {SPELL:1248689} (+100% velocità d'attacco) ogni volta che è attivo.|n3. {SPELL:1225787} rimbalza su un giocatore vicino — distanziatevi.",
	DGN_TIP_MT_SERANEL_TANK = "Tank: un Ward non rimosso raddoppia la sua velocità d'attacco — difensiva finché non sparisce.",
	DGN_TIP_MT_SERANEL_HEALER = "Healer: i giocatori marcati ticchettano; ricorda che non puoi lanciare dentro la zona.",

	DGN_TIP_MT_GEMELLUS_STEPS = "1. {SPELL:1223847} (all'inizio e a metà salute): si divide in tre.|n2. {SPELL:1253709}: collegato a uno di loro? CORRI a toccarlo — questo spezza il legame e rimuove il suo scudo di assorbimento.|n3. {SPELL:1224299} ti attira — ricorri fuori.",
	DGN_TIP_MT_GEMELLUS_TANK = "Tank: raggruppa il trio dopo ogni {SPELL:1223847} così i giocatori collegati possono raggiungere il loro.",
	DGN_TIP_MT_GEMELLUS_HEALER = "Healer: i giocatori collegati subiscono +20% danni finché non spezzano il legame.",

	DGN_TIP_MT_DEGENTRIUS_STEPS = "1. {SPELL:1215897}: DoT void con durate diverse — quando il tuo scade, gli Entropy Orbs partono dalla TUA posizione, quindi allontanati prima dal gruppo.|n2. {SPELL:1215087} rimbalza su 4 punti — SOAK un impatto (un giocatore ciascuno), o erutta in Void Destruction.|n3. {SPELL:1280113} colpisce il tank e respinge chiunque entro 8 yard — dai spazio al tank.",
	DGN_TIP_MT_DEGENTRIUS_TANK = "Tank: difensiva per {SPELL:1280113}; tankalo lontano dal gruppo.",
	DGN_TIP_MT_DEGENTRIUS_HEALER = "Healer: i DoT Entropy ticchettano forte — tieni su i portatori mentre si riposizionano.",

	-- Skyreach ------------------------------------------------------------------
	DGN_TIP_SR_RANJIT_STEPS = "1. {SPELL:1258148} vola in linea retta davanti a lui — spostati di lato.|n2. {SPELL:156793}: un impatto al centro più vortici di vento vaganti che ti lanciano — continua a serpeggiare.|n3. {SPELL:153757} colpisce tutti con un bleed — sii al massimo.|n4. {SPELL:1252733} scaglia via i suoi bersagli — attento a cosa hai dietro.",
	DGN_TIP_SR_RANJIT_TANK = "Tank: tienilo lontano dai percorsi dei vortici.",
	DGN_TIP_SR_RANJIT_HEALER = "Healer: danni al gruppo più bleed dopo ogni {SPELL:153757}.",

	DGN_TIP_SR_ARAKNATH_STEPS = "1. {SPELL:154162}: i costrutti irradiano luce nel boss e lo CURANO — stai in un raggio per bloccarlo.|n2. {SPELL:154115}: una bracciata da un lato — farsi colpire accumula un brutale debuff di danni subiti.|n3. {SPELL:154135} colpisce tutti — sii pronto.",
	DGN_TIP_SR_ARAKNATH_TANK = "Tank: non soakare mai i raggi tu stesso — il suo smash arriva durante il soak.",
	DGN_TIP_SR_ARAKNATH_HEALER = "Healer: chi soaka i raggi ticchetta costantemente; cura di gruppo a {SPELL:154135}.",

	DGN_TIP_SR_RUKHRAN_STEPS = "1. {SPELL:1253527}: le piume volano ovunque per 3 secondi — spezza la linea di vista dietro un pilastro.|n2. {SPELL:1253510} colpisce il gruppo ed evoca un Sunwing che fissa qualcuno e pulsa fuoco — uccidilo in fretta; il giocatore fissato mantiene la distanza.|n3. Ripeti — penne dietro la copertura, uccello giù in fretta.",
	DGN_TIP_SR_RUKHRAN_TANK = "Tank: difensiva per {SPELL:1253519} (grande colpo + DoT da bruciatura).",
	DGN_TIP_SR_RUKHRAN_HEALER = "Healer: danni al gruppo pulsanti finché vive un Sunwing — chiedi che venga ucciso.",

	DGN_TIP_SR_VIRYX_STEPS = "1. {SPELL:154396}: un cast di 3 secondi che annienta il tank — KICKALO, ogni volta.|n2. {SPELL:1253998}: un Solar Zealot afferra un giocatore per buttarlo giù dal balcone — liberalo in fretta.|n3. {SPELL:1253531} su di te? Portalo lontano e largo — lascia Blazing Ground.",
	DGN_TIP_SR_VIRYX_TANK = "Tank: ogni {SPELL:154396} che passa fa male — tieni stretto l'ordine dei kick.",
	DGN_TIP_SR_VIRYX_HEALER = "Healer: {SPELL:1253538} mette DoT di fuoco su più giocatori contemporaneamente.",

	-- Pit of Saron --------------------------------------------------------------
	DGN_TIP_PS_GARFROST_STEPS = "1. {SPELL:1262029}: la forgia pulsa gelo crescente — NASCONDITI DIETRO un blocco di minerale di saronite, blocca l'esplosione.|n2. {SPELL:1261546} colpisce tutto attorno al bersaglio principale — stai a 5+ yard dal tank; vicino al minerale lo smash rompe il minerale invece di stunnare.|n3. {SPELL:1261847} colpisce tutti e frantuma TUTTO il minerale — nuovo minerale arriva via {SPELL:1261286}.|n4. Stai fuori da {SPELL:1261799}.",
	DGN_TIP_PS_GARFROST_TANK = "Tank: posizionati accanto a un blocco di minerale — {SPELL:1261546} poi rompe il minerale, non te.",
	DGN_TIP_PS_GARFROST_HEALER = "Healer: picco di gruppo a {SPELL:1261847}; gelo crescente su chi viene preso senza copertura.",

	DGN_TIP_PS_KRICKICK_STEPS = "1. {SPELL:1264363}: Ick fissa e insegue un giocatore, spargendo Blight e Plague Glob — corri largo; il resto continua a colpire.|n2. {SPELL:1264027}: Krick si teletrasporta a un cerchio rituale ed evoca Shades — cambia e uccidile.|n3. {SPELL:1264336}: schiva l'onda e i glob che rotolano verso di te.|n4. Non stare mai nel Blight ({SPELL:1264299}).",
	DGN_TIP_PS_KRICKICK_TANK = "Tank: {SPELL:1264287} lascia una pozza su di te — orientala verso il bordo.",
	DGN_TIP_PS_KRICKICK_HEALER = "Healer: tieni il giocatore inseguito in movimento; danni al gruppo a {SPELL:1264336}.",

	DGN_TIP_PS_TYRANNUS_STEPS = "1. {SPELL:1262772} congela le Bone Piles attorno al suo bersaglio — stai vicino alle pile quando sei marcato: le pile congelate non possono rianimare add.|n2. {SPELL:1263406} rianima le pile rimanenti — uccidi prima i Plaguespreaders.|n3. Continua a schivare {SPELL:1263756} e {SPELL:1276948} di Rimefang.|n4. {SPELL:1276648} = colpo al gruppo + DoT, e le pile infuse generano add più cattivi.",
	DGN_TIP_PS_TYRANNUS_TANK = "Tank: {SPELL:1262582} ti lancia e accumula +200% shadow subito — difensiva e preparati.",
	DGN_TIP_PS_TYRANNUS_HEALER = "Healer: DoT di gruppo dopo {SPELL:1276648}; picco sul tank subito dopo Brand.",

	-- Seat of the Triumvirate ---------------------------------------------------
	DGN_TIP_ST_ZURAAL_STEPS = "1. {SPELL:1268916} colpisce tutto DAVANTI a lui — non stare mai davanti al boss.|n2. {SPELL:1263304} (piena energia): trascina tutti dentro, poi esplode con un knockback — esci in tempo; anche gli add vengono trascinati dentro.|n3. {SPELL:1263399} genera add Coalesced Void — eliminali prima di Crashing Void.|n4. {SPELL:1263282} lascia Void Sludge ({SPELL:244588}) — tieni pulito il pavimento.",
	DGN_TIP_ST_ZURAAL_TANK = "Tank: difensiva per {SPELL:1263440} (triplo fendente).",
	DGN_TIP_ST_ZURAAL_HEALER = "Healer: grande colpo al gruppo a {SPELL:1263304}.",

	DGN_TIP_ST_SAPRISH_STEPS = "1. Le Void Bomb ({SPELL:247175}) atterrano sulle posizioni dei giocatori — NON toccarle; lasciale ai bordi.|n2. {SPELL:1280064}: le shade scattano verso ogni giocatore e fanno detonare le bombe che attraversano — angola la linea del tuo scatto lontano dalle bombe.|n3. {SPELL:1263523} accende TUTTE le bombe insieme — meno bombe ci sono, più è leggero.|n4. Kicka {SPELL:248831} di Shadewing (colpo al gruppo + disorientamento).",
	DGN_TIP_ST_SAPRISH_TANK = "Tank: tieni unito il trio; il balzo di Darkfang ({SPELL:245738}) lascia la sua vittima sanguinante.",
	DGN_TIP_ST_SAPRISH_HEALER = "Healer: le vittime del balzo sanguinano; esplosione di gruppo a {SPELL:1263523}.",

	DGN_TIP_ST_NEZHAR_STEPS = "1. {SPELL:1263528} respinge tutti — attento a dove metti i piedi vicino alle tempeste.|n2. {SPELL:1263538} e l'add {SPELL:1277358} aggiungono caos — uccidi i tentacoli, schiva le Umbral Wave dal cancello.|n3. Le zone {SPELL:1263532} ticchettano forte, dentro è peggio — fuori, in fretta.|n4. {SPELL:244750} annienta il tank — kickalo quando puoi.",
	DGN_TIP_ST_NEZHAR_TANK = "Tank: preparati a {SPELL:244750} ogni volta che un kick è in cooldown.",
	DGN_TIP_ST_NEZHAR_HEALER = "Healer: {SPELL:1263542} = diversi DoT di marcescenza che ticchettano insieme.",

	DGN_TIP_ST_LURA_STEPS = "1. Le Notes of Despair continuano a irradiare ({SPELL:1265421}) finché non vengono silenziate — guida il tuo {SPELL:1265426} ATTRAVERSO le note (colpisce anche gli alleati in linea, quindi angolalo lontano da loro).|n2. {SPELL:1265689}: 20 secondi di dolore attorno a ogni nota attiva — rompi le note in fretta.|n3. {SPELL:1264151}: raggi void rotanti — muoviti con i varchi.|n4. {SPELL:1266003} è una canalizzazione letale di 10 secondi — ogni difensiva che hai, e cura attraverso.",
	DGN_TIP_ST_LURA_TANK = "Tank: dopo {SPELL:1266001} tutti vengono sbalzati in giro — raggruppatevi in fretta.",
	DGN_TIP_ST_LURA_HEALER = "Healer: {SPELL:1265421} colpisce il gruppo più le aure delle note — rompere le note È il piano di cura.",

	-- Algeth'ar Academy ---------------------------------------------------------
	DGN_TIP_AA_VEXAMUS_STEPS = "1. {SPELL:385974} si dirigono verso il boss — soakali, un giocatore ciascuno (piccolo colpo); ogni orb che LUI assorbe fa esplodere tutto il gruppo.|n2. {SPELL:386173}: porta il tuo fuori — diventa una pozza {SPELL:386201}.|n3. Piena energia = {SPELL:388537}: colpo al gruppo più eruzioni ripetute sotto i giocatori — continua a muoverti.",
	DGN_TIP_AA_VEXAMUS_TANK = "Tank: {SPELL:385958} fa esplodere tutto davanti a lui — difensiva, orientalo lontano.",
	DGN_TIP_AA_VEXAMUS_HEALER = "Healer: i portatori di bomba ticchettano; danni al gruppo per ogni orb che raggiunge il boss.",

	DGN_TIP_AA_ANCIENT_STEPS = "1. {SPELL:388796}: i semi eruttano sotto tutti per 4 secondi — schiva; i semi mancati lasciano Lasher dormienti.|n2. A piena energia ({SPELL:388923}) TUTTE le Lasher dormienti si svegliano insieme — eliminale prima.|n3. {SPELL:388623} lancia un ramo che diventa un grande add — uccidilo e KICKA il suo {SPELL:396640}.",
	DGN_TIP_AA_ANCIENT_TANK = "Tank: {SPELL:388544} raddoppia i danni fisici che subisci — difensiva ogni volta.",
	DGN_TIP_AA_ANCIENT_HEALER = "Healer: cura {SPELL:389033} (veleno) prima che si accumuli troppo.",

	DGN_TIP_AA_CRAWTH_STEPS = "1. {SPELL:377004} erutta sotto ogni giocatore e interrompe i cast — SMETTI di lanciare, poi distanziatevi.|n2. {SPELL:377034}: punta qualcuno e soffia un cono d'ali in quella direzione — esci.|n3. {SPELL:377182}: segna in una porta — la porta del fuoco la stunna e subisce 75% danni extra.",
	DGN_TIP_AA_CRAWTH_TANK = "Tank: difensiva per {SPELL:376997} (colpo + bleed di 10s).",
	DGN_TIP_AA_CRAWTH_HEALER = "Healer: forti danni al gruppo dopo lo strillo; il tank sanguina.",

	DGN_TIP_AA_DORAGOSA_STEPS = "1. {SPELL:374341} su di te? Portalo lontano dal gruppo — esplode largo 8 yard.|n2. {SPELL:388820} trascina tutti dentro, poi esplode — CORRI FUORI prima dell'esplosione.|n3. {SPELL:389011} si accumula da ogni meccanica che incassi — a 3 stack esplode in un Arcane Rift; resta pulito.|n4. Stai fuori dal terreno {SPELL:389007}.",
	DGN_TIP_AA_DORAGOSA_TANK = "Tank: difensiva per {SPELL:1282251}.",
	DGN_TIP_AA_DORAGOSA_HEALER = "Healer: attento agli stack di {SPELL:389011} — i portatori ticchettano più forte per stack.",
	DGN_TIP_KR_COUNCIL_STEPS = "1. Il consiglio combatte uno alla volta: Kula, poi Aka'ali, poi Zanazal. Un membro sconfitto torna ogni tanto per usare un'abilità. Lo scontro finisce quando muore Zanazal.|n2. Kula: allontanati da lei per {SPELL:266206} e dopo schiva le asce che rotolano in giro. {SPELL:266231} fa sanguinare un giocatore a caso: usa una difensiva.|n3. Aka'ali: {SPELL:267494} carica un giocatore. Tutti si raggruppano su quel giocatore per dividere i danni.|n4. Zanazal: interrompi {SPELL:267273}. Quando evoca i totem ({SPELL:267060}), uccidi prima l'Explosive Totem, poi il Thundering Totem, poi il Torrent Totem.",
	DGN_TIP_KR_COUNCIL_QUICK_DPS = "Stai nel gruppo della carica, interrompi il veleno e uccidi prima il totem che esplode.",
	DGN_TIP_KR_COUNCIL_QUICK_HEALER = "Cura il sanguinamento delle asce e porta tutti al massimo prima della carica.",
	DGN_TIP_KR_COUNCIL_QUICK_TANK = "Quando Aka'ali ti scaglia via, scappa da lei finché il debuff non sparisce.",
	DGN_TIP_KR_COUNCIL_QUICK = "Kula: Allontanati quando gira su se stessa e schiva le asce volanti.|nAka'ali: Carica un giocatore. Tutti stanno su quel giocatore per dividere il colpo.|nZanazal: Interrompi il suo incantesimo di veleno e uccidi prima il totem che esplode.",
	DGN_TIP_KR_COUNCIL_DPS = "DPS: stai nel gruppo di {SPELL:267494}, continua a interrompere {SPELL:267273} e passa all'Explosive Totem appena compare.",
	DGN_TIP_KR_COUNCIL_HEALER = "Healer: cura il bleed di {SPELL:266231} e porta tutti al massimo prima di {SPELL:267494}. Su Zanazal, {SPELL:1305810} salta tra i giocatori, e Poison Nova ticchetta su tutti se non viene interrotta.",
	DGN_TIP_KR_COUNCIL_TANK = "Tank: {SPELL:266237} ti respinge e ti fa subire molti più danni fisici. Stai lontano da Aka'ali finché il debuff non sparisce, o usa una grande difensiva.",
	DGN_TIP_KR_DAZAR_STEPS = "1. Fase 1: Dazar combatte con il suo raptor Reban. Uccidi prima Reban e interrompi il suo {SPELL:269369}, una paura. Reban salta su un giocatore con {SPELL:269230} e morde a cono: esci dal cono.|n2. {SPELL:1303115}: Dazar balza su due giocatori. Quei due si distanziano così non si colpiscono a vicenda.|n3. All'80% di salute Dazar cavalca il suo raptor T'zala. Ora {SPELL:1303327} balza su quattro giocatori e colpisce anche tutto il gruppo: distanziatevi e siate al massimo della salute.|n4. {SPELL:1303267} colpisce tutto il gruppo e brucia per 15 secondi. Subito dopo cadono lance dove stanno i giocatori: continua a muoverti e schiva i cerchi di Impaling Spear.|n5. In Mitico e Mythic+: {SPELL:1303267} potenzia anche i suoi colpi, che mandano un'onda d'oro in avanti. Il tank lo tiene girato lontano dal gruppo.",
	DGN_TIP_KR_DAZAR_QUICK_DPS = "Uccidi prima il raptor piccolo e interrompi il suo ruggito.",
	DGN_TIP_KR_DAZAR_QUICK_HEALER = "Tieni le grandi cure per il colpo d'oro e per i salti del raptor.",
	DGN_TIP_KR_DAZAR_QUICK_TANK = "Usa la tua difensiva più forte per la combo di spada e tieni il re girato dall'altra parte.",
	DGN_TIP_KR_DAZAR_QUICK = "Raptor: Uccidi prima il raptor piccolo e interrompi il suo ruggito che fa paura.|nIn sella: Il re cavalca il suo grande raptor. Allontanati dagli altri quando salta e sii al massimo della salute.|nOro: Un grande colpo di fuoco su tutti, poi cadono lance dove stai. Continua a muoverti.",
	DGN_TIP_KR_DAZAR_DPS = "DPS: uccidi prima Reban e interrompi {SPELL:269369}. Tieni spazio libero così i bersagli del balzo possono distanziarsi e tu puoi schivare le lance.",
	DGN_TIP_KR_DAZAR_HEALER = "Healer: tieni i grandi cooldown per {SPELL:1303267} e {SPELL:1303327}. Attento ai bleed di Impaling Spear e {SPELL:1303488}.",
	DGN_TIP_KR_DAZAR_TANK = "Tank: grande difensiva per {SPELL:268586}: i colpi diventano più forti verso la fine. Quando arriva T'zala, anche {SPELL:1303488} colpisce te e ti fa subire più danni fisici, quindi dividi i cooldown tra i due. Tieni Dazar girato lontano dal gruppo.",
	DGN_TIP_KR_MCHIMBA_STEPS = "1. {SPELL:267618}: il boss risucchia la vita a un giocatore. Tutti gli altri escono dai cerchi di acido che schizza. Se tocca a te, usa una difensiva. Quando finisce resti lento e debole finché non vieni curato sopra il 90% di salute.|n2. {SPELL:1311956} prende di mira un giocatore e lascia terreno in fiamme. Lascialo al bordo, lontano dal boss e dalle bare.|n3. {SPELL:1312146} colpisce tutto il gruppo e apre delle bare: escono due Half-Finished Mummies. Uccidile e interrompi il loro Wretched Discharge.|n4. {SPELL:267702}: un giocatore viene chiuso in una delle bare. Se sei tu, premi il pulsante Struggle così la tua bara trema. Tutti gli altri: trovate la bara che trema e cliccatela in fretta. Ogni bara vuota che il boss apre prima fa uscire una Finished Mummy.",
	DGN_TIP_KR_MCHIMBA_QUICK_DPS = "Interrompi le mummie e aiuta a trovare la bara che trema.",
	DGN_TIP_KR_MCHIMBA_QUICK_HEALER = "Cura quasi al massimo il giocatore risucchiato: così il rallentamento sparisce.",
	DGN_TIP_KR_MCHIMBA_QUICK_TANK = "Prendi le mummie e tienile vicino al boss.",
	DGN_TIP_KR_MCHIMBA_QUICK = "Risucchio: Se il boss risucchia la tua vita, usa una difensiva. Gli altri escono dai cerchi di acido.|nFuoco: Metti la tua pozza di fuoco al bordo, lontano dal boss e dalle bare.|nBara: Un amico viene chiuso in una bara. Trova quella che trema e cliccala in fretta.",
	DGN_TIP_KR_MCHIMBA_DPS = "DPS: interrompi il Wretched Discharge delle mummie. Durante {SPELL:267702}, vai alle bare e cerca quella che trema: non cliccare a caso.",
	DGN_TIP_KR_MCHIMBA_HEALER = "Healer: passa subito al bersaglio di {SPELL:267618} e dopo curalo sopra il 90%: così il rallentamento finisce. Porta il gruppo al massimo prima di {SPELL:1312146}. Wretched Discharge è una malattia che puoi dispellare.",
	DGN_TIP_KR_MCHIMBA_TANK = "Tank: prendi le mummie e raggruppale vicino a Mchimba per il cleave. Non lasciarle davanti a una bara.",
	DGN_TIP_KR_SERPENT_STEPS = "1. {SPELL:265773} mette oro ardente su due giocatori. Quando finisce lasci una pozza di {SPELL:265914} dove ti trovi: prima vai al bordo e lasciala accanto alle altre pozze.|n2. {SPELL:265923} risveglia le pozze come Animated Gold, che striscia verso il boss. Uccidili, rallentali o stordiscili prima che lo raggiungano: ognuno che arriva gli dà uno scudo e più danni.|n3. {SPELL:1311987}: cinque secondi di danni su tutto il gruppo che ti spingono anche indietro. Sii al massimo della salute e usa una difensiva.|n4. Non stare mai nelle pozze d'oro.",
	DGN_TIP_KR_SERPENT_QUICK_DPS = "Uccidi prima le macchie d'oro: nessuna deve raggiungere il boss.",
	DGN_TIP_KR_SERPENT_QUICK_HEALER = "Cura i due giocatori che bruciano d'oro e tieni una grande cura per il vento.",
	DGN_TIP_KR_SERPENT_QUICK_TANK = "Usa una difensiva per il colpo di coda e allontana il boss dalle macchie d'oro.",
	DGN_TIP_KR_SERPENT_QUICK = "Oro: Quando il tuo oro smette di bruciare lasci una pozza. Mettila al bordo, vicino alle altre.|nAdd: Le pozze si svegliano e strisciano verso il boss. Uccidile prima che lo tocchino.|nVento: Un vento forte fa male a tutti e ti spinge indietro. Sii al massimo della salute.",
	DGN_TIP_KR_SERPENT_DPS = "DPS: prima l'Animated Gold, poi il boss. Usa rallentamenti, stun e cleave, e tieni tutte le pozze vicine così gli add si risvegliano in un unico gruppo.",
	DGN_TIP_KR_SERPENT_HEALER = "Healer: cura i due bersagli di {SPELL:265773} mentre bruciano. Usa un cooldown di cura per {SPELL:1311987}.",
	DGN_TIP_KR_SERPENT_TANK = "Tank: difensiva per {SPELL:265910}. Quando l'Animated Gold si risveglia, allontana il boss da lì così i DPS hanno più tempo.",
	DGN_TIP_RL_KOKIA_STEPS = "1. Molten Boulder ({SPELL:372110}): Kokia lancia un masso infuocato che rotola in linea retta e poi esplode. Esci dal suo percorso e stai lontano dal punto dove si ferma. Respinge chiunque tocchi.|n2. Ritual of Blazebinding ({SPELL:372864}): un add di fuoco, il Blazebound Firestorm, compare su un giocatore e brucia tutti entro 12 yard. Se è su di te, allontanati dal gruppo ma resta vicino al boss.|n3. Tutti passano subito al Blazebound Firestorm e interrompono il suo Blaze Volley.|n4. Prima che l'add muoia, allontanati di almeno 20 yard. La sua esplosione di morte (Burnout) colpisce molto forte.|n5. In Mitico e Mythic+: il terreno in fiamme ({SPELL:372820}) resta sul pavimento. Esci da lì e sposta lo scontro lentamente per la stanza, così c'è sempre spazio libero.",
	DGN_TIP_RL_KOKIA_QUICK_DPS = "Colpisci prima l'add di fuoco, interrompi i suoi incantesimi e scappa prima che muoia.",
	DGN_TIP_RL_KOKIA_QUICK_HEALER = "L'add di fuoco brucia tutti e il tank sanguina, quindi cura forte e stai lontano quando muore.",
	DGN_TIP_RL_KOKIA_QUICK_TANK = "Usa una difensiva per ogni serie di colpi e sposta il boss lentamente per la stanza.",
	DGN_TIP_RL_KOKIA_QUICK = "Masso: Un masso di fuoco rotola in linea retta, quindi togliti dalla sua strada.|nMostro: Quando compare un mostro di fuoco, tutti lo colpiscono e fermano i suoi incantesimi.|nEsplosione: Scappa lontano dall'add prima che muoia, perché esplode.",
	DGN_TIP_RL_KOKIA_DPS = "DPS: passa al Blazebound Firestorm appena compare e interrompi il suo Blaze Volley. Melee: allontanatevi di 20 yard prima che muoia.",
	DGN_TIP_RL_KOKIA_HEALER = "Healer: il cast Inferno dell'add brucia tutto il gruppo, e Searing Blows lascia un bleed sul tank. Stai fuori anche tu dall'esplosione di morte dell'add.",
	DGN_TIP_RL_KOKIA_TANK = "Tank: usa una difensiva per ogni Searing Blows ({SPELL:372858}): quattro colpi rapidi che accumulano un bleed. Tieni Kokia vicino all'add così i DPS possono fare cleave, ma esci dalla sua esplosione di morte di 20 yard. Spostala lentamente per la stanza per tenere spazio libero.",
	DGN_TIP_RL_KYRAKKA_STEPS = "1. Erkhart combatte a terra mentre il suo drago Kyrakka vola intorno alla piattaforma. Colpisci Kyrakka ogni volta che è a portata: deve morire lei per prima. Schiva il suo cono di fuoco ({SPELL:381525}).|n2. Inferno Spit ({SPELL:381602}): 2 giocatori bruciano per 6 secondi, poi esplodono e lasciano fuoco a terra ({SPELL:384773}). Se sei tu, vai al bordo, lontano dal gruppo, prima che finisca.|n3. Winds of Change ({SPELL:381517}): il vento spinge i giocatori e il fuoco, in un ordine fisso (nord-ovest, sud-ovest, sud-est, nord-est). Cammina controvento e non farti spingere nel fuoco. Lascia il tuo fuoco dove il vento lo porta lontano dal gruppo.|n4. Quando uno dei due arriva a circa il 40-50% di salute (le guide non concordano), Kyrakka atterra ed Erkhart la cavalca. Ora 3 giocatori ricevono Inferno Spit. Tieni i cooldown per questa parte.|n5. In Mitico e Mythic+: Interrupting Cloudburst ({SPELL:381516}) colpisce tutti e blocca i tuoi incantesimi per 2 secondi. Smetti di castare poco prima che arrivi.",
	DGN_TIP_RL_KYRAKKA_QUICK_DPS = "Colpisci prima il drago, e in Mitico smetti di castare poco prima che la tempesta colpisca tutti.",
	DGN_TIP_RL_KYRAKKA_QUICK_HEALER = "Togli il debuff al tank dopo ogni grande colpo e cura i giocatori che bruciano.",
	DGN_TIP_RL_KYRAKKA_QUICK_TANK = "Usa una difensiva per il suo grande colpo e chiedi all'healer di togliere il debuff.",
	DGN_TIP_RL_KYRAKKA_QUICK = "Drago: Colpisci il drago ogni volta che puoi raggiungerlo e schiva il suo soffio di fuoco.|nFuoco: Se stai bruciando, vai al bordo così il tuo fuoco cade lontano dal gruppo.|nVento: Il vento spinge te e il fuoco, quindi cammina controvento e stai fuori dalle fiamme.",
	DGN_TIP_RL_KYRAKKA_DPS = "DPS: colpisci Kyrakka ogni volta che puoi raggiungerla e tieni il burst per quando atterra. In Mitico e Mythic+, i caster smettono di castare prima di Interrupting Cloudburst.",
	DGN_TIP_RL_KYRAKKA_HEALER = "Healer: dispella Stormslam dal tank dopo ogni colpo, prima del successivo. I bersagli di Inferno Spit subiscono molti danni, quindi curali. In Mitico e Mythic+, smetti di castare prima di Interrupting Cloudburst.",
	DGN_TIP_RL_KYRAKKA_TANK = "Tank: usa una difensiva per ogni Stormslam ({SPELL:381512}). Lascia un debuff magico cumulabile che ti fa subire più danni da natura, quindi chiedi un dispel. Sposta Erkhart fuori dal fuoco in fretta dopo ogni vento.",
	DGN_TIP_RL_MELIDRUSSA_STEPS = "1. Hailburst ({SPELL:1307297}): colpisce tutto il gruppo e lancia una mina di ghiaccio su ogni giocatore. State insieme vicino a un bordo così le mine cadono in un solo punto. Non toccare mai una mina: ti lancia in aria e rallenta di metà i tuoi attacchi e incantesimi per 20 secondi.|n2. Chillstorm ({SPELL:1307308}): una tempesta di gelo cade su un giocatore e attira tutti verso il suo centro. Se è su di te, allontanati dal gruppo. Stai fuori dal centro ({SPELL:372963}): lì i danni da gelo sono doppi. Dopo 7 secondi esplode e spinge via tutti, quindi non stare con le mine alle spalle.|n3. Al 66% e al 33% di salute evoca gli Infused Whelps ({SPELL:373046}). Uccidili in fretta.|n4. Interrompi Frigid Shard, l'incantesimo che lancia sul tank.|n5. In Mitico e Mythic+: dopo i whelp si nasconde in uno scudo di ghiaccio (Ice Bulwark) e pulsa su tutti danni da gelo che continuano a crescere (Frost Overload). Rompi lo scudo in fretta, poi interrompila. Le guide dicono che l'interruzione funziona quando lo scudo è sparito.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_DPS = "Uccidi prima i draghetti, e in Mitico rompi il suo scudo di ghiaccio.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_HEALER = "Cura tutto il gruppo durante le esplosioni di ghiaccio e la tempesta.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_TANK = "Prendi subito i draghetti e interrompi l'incantesimo che lancia su di te.",
	DGN_TIP_RL_MELIDRUSSA_QUICK = "Mine: Stai con gli altri vicino a un bordo quando lancia il ghiaccio e non toccare mai le mine.|nTempesta: Se la tempesta è su di te, scappa da tutti e stai fuori dal suo centro.|nDraghetti: Uccidi in fretta i draghetti, e in Mitico rompi anche il suo scudo di ghiaccio.",
	DGN_TIP_RL_MELIDRUSSA_DPS = "DPS: passa ai whelp appena compaiono. In Mitico e Mythic+, tieni il burst per rompere lo scudo di ghiaccio, poi interrompi Frost Overload.",
	DGN_TIP_RL_MELIDRUSSA_HEALER = "Healer: Hailburst e Chillstorm colpiscono tutto il gruppo, e la tempesta esplode alla fine. Porta tutti al massimo prima dell'esplosione. In Mitico e Mythic+, la fase dello scudo aggiunge su tutti danni da gelo che crescono finché lo scudo non si rompe.",
	DGN_TIP_RL_MELIDRUSSA_TANK = "Tank: prendi subito gli Infused Whelps e tienili sul boss per il cleave. I loro colpi accumulano Cold Claws su di te; troppi stack ti congelano, quindi devono morire in fretta. Interrompi Frigid Shard se nessun altro lo fa.",
	DGN_TIP_TS_ADDERIS_STEPS = "1. Storm Blessed mette uno scudo su uno dei due boss, e quel boss non subisce quasi danni. Colpisci quello SENZA scudo (Adderis a inizio scontro) e cambia appena lo scudo si sposta.|n2. {SPELL:1311805}: se sei marcato, vai al bordo e lascia lì la tua pozza. Le pozze ti silenziano, quindi stanne fuori.|n3. {SPELL:1289059}: tutti vengono respinti. Distanziatevi un po' e posizionati in modo che la spinta non ti butti in una pozza.|n4. {SPELL:1288049} arriva subito dopo il knockback: torna indietro e raggruppati sul boss per dividere il colpo, poi uscite insieme prima della seconda esplosione.",
	DGN_TIP_TS_ADDERIS_QUICK_DPS = "Colpisci solo il boss senza scudo e cambia in fretta quando lo scudo si sposta.",
	DGN_TIP_TS_ADDERIS_QUICK_HEALER = "Cura i giocatori colpiti dal vento e porta tutti al massimo prima della spinta.",
	DGN_TIP_TS_ADDERIS_QUICK_TANK = "Usa una difensiva per Overload e tieni i due boss vicini.",
	DGN_TIP_TS_ADDERIS_QUICK = "Scudo: Colpisci il boss senza scudo e cambia quando lo scudo salta.|nPozze: Se sei marcato, lascia la tua pozza al bordo e stai fuori dalle pozze.|nSpinta: Dopo la spinta, torna indietro e stai con gli altri sul boss per dividere il colpo.",
	DGN_TIP_TS_ADDERIS_DPS = "DPS: non colpire mai il boss con lo scudo, non subisce quasi danni. Cambia appena lo scudo si sposta, anche a metà della tua rotazione.",
	DGN_TIP_TS_ADDERIS_HEALER = "Healer: cura i giocatori colpiti da Gust. Il knockback seguito subito dal soak di gruppo è il momento più pericoloso: porta tutti al massimo prima.",
	DGN_TIP_TS_ADDERIS_TANK = "Tank: usa una difensiva per {SPELL:1311804}. Tieni i due boss vicini così il gruppo può cambiare bersaglio senza passare nelle pozze.",
	DGN_TIP_TS_AVATAR_STEPS = "1. Vinci curando l'Avatar fino al massimo, non uccidendola. Prima uccidi gli Essence Defilers: il loro {SPELL:1301202} blocca tutte le cure su di lei.|n2. Uccidi il Corrupted Guardian. Lascia tre orb Corrupted Lifeforce: tre DPS diversi ne prendono uno ciascuno, in fretta. Un orb preso cura l'Avatar; un orb mancato esplode su tutto il gruppo.|n3. Twisted Hexxers: interrompi Flame Shock. Hai {SPELL:1311981}? Allontanati dal gruppo prima che finisca e lascia lì la sua zona.|n4. Quando i Defilers sono morti, cura l'Avatar. Compaiono i Faithless Tormentors che inseguono l'healer: stordiscili, rallentali e portali sotto il 25% di salute. Allora l'Avatar li mangia e si cura.",
	DGN_TIP_TS_AVATAR_QUICK_DPS = "Uccidi prima i Defilers, poi prendi un orb a testa.",
	DGN_TIP_TS_AVATAR_QUICK_HEALER = "Cura l'Avatar quando i Defilers sono morti e continua a scappare dagli inseguitori.",
	DGN_TIP_TS_AVATAR_QUICK_TANK = "Tieni l'add grande in un angolo e stai lontano dagli orb.",
	DGN_TIP_TS_AVATAR_QUICK = "Obiettivo: Uccidi prima i Defilers, poi cura l'Avatar al massimo per vincere.|nOrb: Quando muore l'add grande, tre DPS prendono un orb ciascuno, in fretta.|nInseguitori: Stordisci gli add che inseguono l'healer e portali a poca vita; poi l'Avatar li mangia.",
	DGN_TIP_TS_AVATAR_DPS = "DPS: uccidi prima gli Essence Defilers, poi il Guardian. Prendi un orb a testa (ti dà {SPELL:1300877}, quindi usa una difensiva), interrompi Flame Shock e abbatti i Tormentors con stun e AoE.",
	DGN_TIP_TS_AVATAR_HEALER = "Healer: cura l'Avatar appena i Defilers sono morti: è così che si vince. I Tormentors corrono verso di te e ogni colpo riduce le tue cure, quindi continua a muoverti. Lascia gli orb ai DPS.",
	DGN_TIP_TS_AVATAR_TANK = "Tank: tieni il Corrupted Guardian in un angolo lontano dal gruppo e usa una difensiva per Tainted Strike. Non prendere gli orb: {SPELL:1300877} ti fa subire molti più danni fisici.",
	DGN_TIP_TS_GALVAZZT_STEPS = "1. {SPELL:1291618}: tre guglie sparano raggi su Galvazzt. Mettiti in un raggio, tra la guglia e il boss, così lui non guadagna energia.|n2. Dividetevi i raggi: un giocatore per raggio, e datevi il cambio tra una serie e l'altra. Bloccare un raggio ti dà {SPELL:266923}: danni nel tempo e più danni fisici subiti.|n3. Non lasciare mai un raggio libero. A piena energia lancia Consume Charge, che colpisce forte il gruppo e spesso lo stermina.|n4. {SPELL:1309525}: danni su tutto il gruppo, e lascia {SPELL:1291815} a terra. Esci da lì.",
	DGN_TIP_TS_GALVAZZT_QUICK_DPS = "Resta nel tuo raggio, anche se da lì non puoi colpire il boss.",
	DGN_TIP_TS_GALVAZZT_QUICK_HEALER = "Tieni in vita i giocatori nei raggi.",
	DGN_TIP_TS_GALVAZZT_QUICK_TANK = "Stai fuori dai raggi e sposta il boss lontano dalle zone a terra.",
	DGN_TIP_TS_GALVAZZT_QUICK = "Raggi: Mettiti in un raggio, tra la torre e il boss, così lui non si carica.|nTurni: Un giocatore per raggio, datevi il cambio e non lasciare mai un raggio libero.|nPavimento: Dopo il grande colpo sul gruppo, esci dalla zona a terra.",
	DGN_TIP_TS_GALVAZZT_DPS = "DPS: il tuo raggio viene prima dei tuoi danni: non uscirne per colpire il boss. Datevi il cambio e usa una difensiva quando tocca a te.",
	DGN_TIP_TS_GALVAZZT_HEALER = "Healer: chi soaka i raggi subisce danni costanti: tienili alti, e prendi tu un raggio se serve. Tieni pronto un cooldown per {SPELL:1309525}.",
	DGN_TIP_TS_GALVAZZT_TANK = "Tank: non soakare i raggi: {SPELL:266923} ti fa subire molti più danni fisici. Sposta il boss lontano da ogni {SPELL:1291815}, in un punto dove i raggi restano facili da raggiungere.",
	DGN_TIP_TS_MEREKTHA_STEPS = "1. {SPELL:1290029}: dei serpenti legano alcuni giocatori. Se sei marcato, stai vicino agli altri accanto al boss, così un solo stun o CC ad area spezza tutti i nodi. Poi uccidi i serpenti.|n2. {SPELL:1289109}: se sei marcato, vai al bordo della stanza e lascia lì la pozza, non al centro.|n3. {SPELL:1293048}: danni su tutto il gruppo più un knockback. Non stare dove la spinta ti butta in una pozza.|n4. {SPELL:1289205} e {SPELL:264172}: si schiudono degli add, poi lei va sottoterra e non può essere colpita. Schiva il suo percorso (ti stordisce), interrompi Poison Spit dei Toxic Vipers e uccidi tutti gli add: così lei torna su.",
	DGN_TIP_TS_MEREKTHA_QUICK_DPS = "Quando va sottoterra, uccidi in fretta tutti gli add: così lei torna.",
	DGN_TIP_TS_MEREKTHA_QUICK_HEALER = "Tieni un cooldown per la tempesta che colpisce tutti.",
	DGN_TIP_TS_MEREKTHA_QUICK_TANK = "Usa una difensiva per il suo grande morso e prendi gli add quando va sottoterra.",
	DGN_TIP_TS_MEREKTHA_QUICK = "Serpenti: Se i serpenti ti legano, stai vicino agli altri così un solo stun libera tutti.|nSputo: Se sei marcato, lascia la tua pozza al bordo della stanza.|nSottoterra: Lei si nasconde sottoterra. Schiva il suo percorso e uccidi tutti gli add per farla tornare.",
	DGN_TIP_TS_MEREKTHA_DPS = "DPS: libera prima i giocatori legati con uno stun o un CC ad area. Durante Burrow, uccidi in fretta ogni add (la fase finisce quando sono tutti morti) e interrompi Poison Spit.",
	DGN_TIP_TS_MEREKTHA_HEALER = "Healer: {SPELL:1293048} colpisce tutto il gruppo: prepara un cooldown. Se un Poison Spit passa, dispella il veleno se puoi.",
	DGN_TIP_TS_MEREKTHA_TANK = "Tank: usa una difensiva per ogni {SPELL:1290797}. Durante Burrow, prendi gli add e porta lo Storm Serpent al bordo, perché lascia anche lui delle pozze.",
})

merge(ns._mhLocales and ns._mhLocales.nlNL, {
	-- Windrunner Spire ----------------------------------------------------------
	DGN_TIP_WS_DUO_STEPS = "1. Twee bosses — beschadig ze gelijkmatig zodat ze ongeveer tegelijk doodgaan.|n2. Interrupt Shadow Bolt; stap uit de spuugcirkels ({SPELL:472745}) — verspil geen vloerruimte.|n3. Vervloekt ({SPELL:474105})? Laat 'm snel dispellen — of CC de Dark Entity die eruit spawnt tot 'ie verdwijnt.|n4. Gegrepen door {SPELL:472793} tijdens de schreeuw? Ga zo staan dat je DWARS DOOR de spookdame getrokken wordt — dat breekt haar cast.",
	DGN_TIP_WS_DUO_TANK = "Tank: defensive voor {SPELL:472888}; verplaats de bosses als de vloer te vol raakt.",
	DGN_TIP_WS_DUO_HEALER = "Healer: veel groepsschade tijdens {SPELL:472736}; dispel {SPELL:474105} snel.",

	DGN_TIP_WS_EMBER_STEPS = "1. Vuur = slecht. Leg de vuurplassen ({SPELL:466556}) aan de randen, houd het midden schoon.|n2. Op volle energie: ren NAAR de boss voor {SPELL:465904} en stap daarna elke Fire Breath opzij.|n3. Oude plassen spawnen vuurhozen — blijf ontwijken.",
	DGN_TIP_WS_EMBER_TANK = "Tank: defensive voor {SPELL:466064}.",
	DGN_TIP_WS_EMBER_HEALER = "Healer: zware groepsschade tijdens {SPELL:465904}.",

	DGN_TIP_WS_KROLUK_STEPS = "1. Bruine cirkels = slecht, stap eruit.|n2. Ga bij een maatje staan vóór {SPELL:1253026} afloopt (overlap de paarse cirkels).|n3. Gefixeerd of doelwit van de sprong ({SPELL:1283247})? Ren 'm wég van de groep.|n4. Spawnen er adds (rond tweederde en eenderde health): maak ze snel dood — de Phantasmal Mystic eerst, en blijf 'm interrupten.",
	DGN_TIP_WS_KROLUK_TANK = "Tank: defensive voor {SPELL:467620}; sta klaar om de tweede {SPELL:1283247} op te vangen.",
	DGN_TIP_WS_KROLUK_HEALER = "Healer: groepsschade tijdens {SPELL:472043}.",

	DGN_TIP_WS_HEART_STEPS = "1. Tikken de {SPELL:1216042}-stacks op je? Stap op een windpijl (Turbulent Arrow) bij 2-3 stacks — die haalt de DoT weg én springt je over de uitdijende schokgolf.|n2. Houd één pijl over voor de grote knal op volle energie ({SPELL:468429}).|n3. Spreid licht voor {SPELL:1253979} en gebruik de grote cirkels om de elektrische vloer schoon te vegen.|n4. Doelwit van {SPELL:474528}? Blijf stilstaan en laat de rest wegstappen; iedereen anders: uit de frontal.",
	DGN_TIP_WS_HEART_TANK = "Tank: defensive voor {SPELL:472662}; richt de knockback wég van de plassen.",
	DGN_TIP_WS_HEART_HEALER = "Healer: spelers met hoge {SPELL:1216042}-stacks eerst bijhealen; extra healing na {SPELL:1253979}.",

	-- Maisara Caverns -------------------------------------------------------------
	DGN_TIP_MC_MUROJIN_STEPS = "1. Twee bosses (jager en vogel) — maak ze dicht bij elkaar dood, anders gaat de overlever berserk.|n2. IJsvallen ({SPELL:1243741}), groene cirkels ({SPELL:1243900}) en de frontale {SPELL:1260643} = slecht, blijf eruit.|n3. Doelwit van {SPELL:1249478} (de duikvlucht)? Ren een ijsval IN — de freeze stopt de duik. De rest: weg bij die speler.",
	DGN_TIP_MC_MUROJIN_TANK = "Tank: defensive voor {SPELL:1266480}.",
	DGN_TIP_MC_MUROJIN_HEALER = "Healer: dispel {SPELL:1246666} (disease) — zware groepsschade.",

	DGN_TIP_MC_VORDAZA_STEPS = "1. De boss spawnt Unstable Phantoms ({SPELL:1251204}) die spelers achtervolgen. MAAK ZE DOOD vóór ze iemand bereiken — een fantoom dat zijn doelwit bereikt (of een ander fantoom raakt) knalt voor zware schade in de buurt.|n2. Elk gedood fantoom schreeuwt: onvermijdbare groepsschade — dood ze dus ÉÉN tegelijk.|n3. Ontwijk de frontale golf van {SPELL:1252054} (die duwt je weg), de zwevende orbs en Soulrot.|n4. Zit iemand in een Deathshroud? Sla 'm er snel uit; interrupt {SPELL:1250708} en ontwijk de swirls ondertussen.",
	DGN_TIP_MC_VORDAZA_TANK = "Tank: defensive voor {SPELL:1251554}.",
	DGN_TIP_MC_VORDAZA_HEALER = "Healer: elk gedood fantoom schreeuwt ({SPELL:1251813}) = groepsschade — heal bij tussen de gespreide kills.",

	DGN_TIP_MC_RAKTUL_STEPS = "1. De boss springt naar drie spelers ({SPELL:1252676}) en laat Soulbind Totems achter — spreid zodat de totems uit elkaar landen, word niet geplet, en maak de totems snel dood.|n2. Blijf uit de Chill of Death-vloer.|n3. Zielfase ({SPELL:1253788}): je wordt uit je lichaam getrokken — CC en kick de grote adds terwijl je terugrent naar je lichaam.|n4. Ontwijk de swirls van het Deathgorged Vessel.",
	DGN_TIP_MC_RAKTUL_TANK = "Tank: defensive voor {SPELL:1251023}; leg de plassen wég van de groep.",
	DGN_TIP_MC_RAKTUL_HEALER = "Healer: zware groepsschade tijdens Deathgorged Vessel en wanneer totems breken.",

	-- Murder Row (batch 2 — geverifieerd via DBM-Party-Midnight + Wowhead) ------
	DGN_TIP_MR_KYSTIA_STEPS = "1. Dood Nibbles eerst. Kystia heeft een fel-schild en krijgt bijna geen schade zolang Nibbles boven 20% health is.|n2. Op 20% keert Nibbles zich tegen Kystia met {SPELL:1230304}: Kystia is gestund en krijgt korte tijd veel meer schade. Wissel nu naar Kystia en gebruik je grote cooldowns.|n3. {SPELL:1264095}: er verschijnen kopieën van Kystia die Felstorm casten. Interrupt, stun of crowd-control elke kopie.|n4. Blijf uit Nibbles' {SPELL:1253811}-kegel en uit het vuur dat de kegel op de grond achterlaat.|n5. Op Heroic en zwaarder: {SPELL:474240} - ze springt naar een speler en ontploft. Ga bij haar weg.",
	DGN_TIP_MR_KYSTIA_QUICK_DPS = "Sla eerst het pet, en daarna de boss als het pet bijna dood is.",
	DGN_TIP_MR_KYSTIA_QUICK_HEALER = "Haal de spuug-debuff snel van spelers af, en bewaar een grote heal voor de wissel.",
	DGN_TIP_MR_KYSTIA_QUICK_TANK = "Richt de vuurkegel van het pet van de groep af.",
	DGN_TIP_MR_KYSTIA_QUICK = "Pet eerst: Sla eerst Nibbles, het pet van de boss. De boss heeft een schild en krijgt bijna geen schade.|nWissel: Is Nibbles bijna dood, dan stunt ze de boss. Sla nu de boss hard.|nKopieën: Er verschijnen kopieën van de boss. Kick of stun ze allemaal.",
	DGN_TIP_MR_KYSTIA_TANK = "Tank: Richt Nibbles' {SPELL:1253811}-kegel van de groep af. Houd Kystia en Nibbles dicht bij elkaar zodat je groep ze allebei kan cleaven. Kystia's Chaos Barrage raakt je hard, dus houd een defensive klaar.",
	DGN_TIP_MR_KYSTIA_HEALER = "Healer: Dispel Corroding Spittle (magic) snel, vooral tijdens {SPELL:1264095}. Bewaar een heal-cooldown voor het burn-venster na {SPELL:1230304}: de gestunde Kystia stuurt fel-knallen naar de groep.",

	DGN_TIP_MR_ZAEN_STEPS = "1. Er vallen kratten op spelers ({SPELL:474765}). Stap uit de markers. De kratten die landen zijn je dekking.|n2. {SPELL:1218347}: hij mikt op iedereen die hij kan zien. Verstop je achter een krat voordat hij schiet, zodat hij je niet ziet. Iedereen heeft een eigen krat nodig.|n3. {SPELL:1214357} op jou? De bom ontploft na 6 seconden en vernielt kratten in de buurt. Breng hem weg van de kratten die je nodig hebt als dekking.|n4. {SPELL:474478}: 3 seconden zware schade op de hele groep. Sta op volle health.|n5. Op Mythic en Mythic+: groene fel-kratten (Fel-Infused Freight) doen de hele groep constant pijn. Heb je {SPELL:1214357}, breng hem dan naar een groene krat om die te vernielen, en spaar de gewone kratten.",
	DGN_TIP_MR_ZAEN_QUICK_DPS = "Sta achter een krat vóór het grote schot, niet erna.",
	DGN_TIP_MR_ZAEN_QUICK_HEALER = "Haal het gif van de tank af, en zorg dat iedereen vol staat vóór het geweervuur.",
	DGN_TIP_MR_ZAEN_QUICK_TANK = "Gebruik een defensive als hij je steekt, en laat het gif weghalen.",
	DGN_TIP_MR_ZAEN_QUICK = "Kratten: Er vallen kratten uit de lucht. Stap opzij en gebruik ze daarna als muur.|nSchot: Mikt hij op iedereen, verstop je dan achter een krat zodat hij je niet ziet.|nBom: Heb je de bom? Draag hem weg van de kratten waar je achter schuilt.",
	DGN_TIP_MR_ZAEN_TANK = "Tank: Gebruik een defensive voor {SPELL:1222795}. Die laat ook Heartstop Poison achter, dat je max health verlaagt: laat het dispellen of haal het zelf weg.",
	DGN_TIP_MR_ZAEN_HEALER = "Healer: Dispel Heartstop Poison van de tank na {SPELL:1222795}. Heal iedereen vol vóór {SPELL:474478}, en heal de bleed op iedereen die door het schot geraakt is.",

	DGN_TIP_MR_XATHUUX_STEPS = "1. {SPELL:1214637}: hij gooit zijn bijl naar een speler. Ben jij het, ga dan dicht bij de boss staan maar weg van de anderen. De bijl blijft liggen en zapt iedereen steeds harder: sloop hem snel.|n2. Infernal Crush ({SPELL:1295452}): er verschijnen cirkels onder spelers. Ga uit elkaar zodat je elkaar niet raakt.|n3. {SPELL:474197}: schade op iedereen, daarna valt hij 15 seconden sneller aan en krijgt hij 30% meer schade. Gebruik nu je cooldowns.|n4. Tijdens de woede laat hij vuur achter waar hij loopt ({SPELL:474234}). Blijf eruit. De tank loopt hem langzaam langs de rand van de zaal.",
	DGN_TIP_MR_XATHUUX_QUICK_DPS = "Dood eerst de bijl, en bewaar je grote aanvallen voor de woede.",
	DGN_TIP_MR_XATHUUX_QUICK_HEALER = "Plan een grote heal voor de woede, en heal de tank vol vóór de grote zwaai.",
	DGN_TIP_MR_XATHUUX_QUICK_TANK = "Gebruik een defensive voor zijn grote zwaai, en loop hem langzaam langs de rand als hij woedend is.",
	DGN_TIP_MR_XATHUUX_QUICK = "Bijl: Hij gooit zijn bijl. Leg hem naast de boss en sloop hem snel.|nCirkels: Ga uit elkaar als er cirkels onder je verschijnen.|nWoede: Wordt hij boos, dan krijgt hij meer schade. Sla hard en blijf uit zijn vuurspoor.",
	DGN_TIP_MR_XATHUUX_TANK = "Tank: Gebruik een defensive voor {SPELL:473898}; die verlaagt 8 seconden de healing die je krijgt. Richt hem van de groep af en zet hem op de bijl zodat die meegecleaved wordt. Loop hem tijdens {SPELL:474197} langzaam langs de rand zodat het vuur uit het midden blijft.",
	DGN_TIP_MR_XATHUUX_HEALER = "Healer: {SPELL:474197} en Infernal Crush komen vaak vlak na elkaar, dus plan een cooldown. De tank krijgt veel minder healing na {SPELL:473898}; heal hem vol vóór die klap. Elke seconde dat de bijl leeft, krijgt de groep meer schade.",

	DGN_TIP_MR_LITHIEL_STEPS = "1. Interrupt elke Chaos Bolt. Spreek een kick-volgorde af.|n2. {SPELL:1218203}: er landen cirkels op spelers. Ga 6 yards uit elkaar. Elke cirkel maakt Wild Imps: stun of kick ze en dood ze samen.|n3. {SPELL:474408}: er komt een grote demon. De tank pakt hem op, iedereen doodt hem.|n4. {SPELL:1224478}: een golf fel-vuur rolt door de zaal. Dood alle demonen voordat die hen bereikt, anders worden ze veel sneller. Neem de Demonic Gateway zodat de golf je mist; raakt hij je, dan krijg je meer vuurschade.|n5. Op Mythic en Mythic+: een Infernal jaagt op de tank. Hij kan niet dood en aanraken kan je doden. De tank houdt hem weg van de groep en de gateway.",
	DGN_TIP_MR_LITHIEL_QUICK_DPS = "Kick de boss en de imps, en dood alle demonen vóór de golf.",
	DGN_TIP_MR_LITHIEL_QUICK_HEALER = "Iedereen krijgt het hele gevecht vuurschade. Heal eerst wie door de golf geraakt is.",
	DGN_TIP_MR_LITHIEL_QUICK_TANK = "Pak de demonen snel op. Leid op Mythic de Infernal weg van iedereen.",
	DGN_TIP_MR_LITHIEL_QUICK = "Kicks: Stop elke Chaos Bolt die de boss cast.|nImps: Ga uit elkaar. Er komen kleine demonen tevoorschijn. Stun ze en dood ze snel.|nGolf: Dood alle demonen vóór de vuurgolf, en neem dan het portaal zodat hij je mist.",
	DGN_TIP_MR_LITHIEL_TANK = "Tank: Pak de Vilefiend snel op, die slaat je hard. Houd de Wild Imps bij elkaar zodat ze gecleaved kunnen worden. Kite op Mythic de Infernal weg van de groep en nooit in de buurt van de gateway.",
	DGN_TIP_MR_LITHIEL_HEALER = "Healer: Het hele gevecht ligt er constant vuurschade op de groep. Wie door {SPELL:1224478} geraakt is, blijft branden en krijgt meer vuurschade: heal die eerst.",

	-- Den of Nalorakk -----------------------------------------------------------
	DGN_TIP_DN_HOARDMONGER_STEPS = "1. {SPELL:1234233}: hij gooit een paar seconden met rot voedsel. Ontwijk de inslagen. Daarna groeien er groene Rotten Mushrooms op de vloer.|n2. Stap op elke paddenstoel voordat hij knapt (ongeveer 12 seconden). Verdeel je zodat er geen een gemist wordt. Elke paddenstoel geeft je gif, dus wissel elkaar af.|n3. {SPELL:1253268} is een frontale kegel. Stap uit het gebied dat hij aanwijst. {SPELL:1235118} raakt de hele groep, dus blijf vol.|n4. Drie keer rent hij naar een stapel vlees, botten of paddenstoelen en krijgt hij een nieuwe move. Vlees maakt zijn roar sterker. Botten geven een slam die gebroken botten op de vloer laat ({SPELL:1235405}): blijf ervan af. Paddenstoelen betekenen meer paddenstoelen om op te stappen.|n5. Op Mythic en Mythic+: elke nieuwe move blijft de rest van het gevecht, dus ze stapelen. Gidsen nemen eerst vlees, dan botten, paddenstoelen als laatste.",
	DGN_TIP_DN_HOARDMONGER_QUICK_DPS = "Help op de paddenstoelen te stappen, en wissel af met de anderen.",
	DGN_TIP_DN_HOARDMONGER_QUICK_HEALER = "Heal flink als hij brult, en haal het gif van de paddenstoel-soakers af als je kunt.",
	DGN_TIP_DN_HOARDMONGER_QUICK_TANK = "Parkeer de boss naast de stapel die je wilt: vlees, dan botten, dan paddenstoelen.",
	DGN_TIP_DN_HOARDMONGER_QUICK = "Paddenstoelen: Stap op de groene paddenstoelen voordat ze knappen, en wissel af.|nKlap: De boss slaat op de grond voor zich. Stap uit dat gebied.|nStapels: Hij pakt eten van een stapel en krijgt een nieuwe truc. Blijf van de botten af die hij achterlaat.",
	DGN_TIP_DN_HOARDMONGER_TANK = "Tank: Hij rent naar de dichtstbijzijnde stapel, dus parkeer hem naast de stapel die je wilt: eerst vlees, dan botten, paddenstoelen als laatste. Houd de bottenplekken weg van waar de groep staat.",
	DGN_TIP_DN_HOARDMONGER_HEALER = "Healer: Gebruik een heal-cooldown op {SPELL:1235118}: die negeert armor en raakt iedereen. Paddenstoel-soakers krijgen gif (Toxic Spores): dispel het als je class dat kan, en houd ze vol.",

	DGN_TIP_DN_SENTINEL_STEPS = "1. {SPELL:1235623}: kleine tornado's landen en dwalen lang door de zaal. Sta bij elkaar zodat ze op één plek vallen, en loop er dan van weg.|n2. {SPELL:1235783}: twee ijspegels storten neer. Stap uit de cirkels. Elke pegel laat een Fractured Shivercore-add achter.|n3. De adds casten Winter's Shroud. Interrupt het: elke cast laat de hele groep meer frost-schade krijgen. Een dode add laat een Snowdrift achter: diepe sneeuw die je vertraagt, maar niets kan je verplaatsen zolang je erin staat.|n4. {SPELL:1235656}: een grote storm raakt iedereen en verplaatst spelers. Dood één add vlak ervoor en sta in zijn Snowdrift tot de storm voorbij is. Dood daarna de andere add.|n5. Op Mythic en Mythic+: een stervende add laat ijsscherven vallen (Rimeshatter). Zet precies één speler in elke scherfcirkel. Een gemiste scherf raakt de hele groep en root iedereen.",
	DGN_TIP_DN_SENTINEL_QUICK_DPS = "Stop om de beurt de casts van de adds, en dood de eerste add vlak vóór de storm.",
	DGN_TIP_DN_SENTINEL_QUICK_HEALER = "Haal de frost-debuff snel weg, en heal iedereen tijdens de storm.",
	DGN_TIP_DN_SENTINEL_QUICK_TANK = "Zet de boss boven op één add, en houd hem weg van de tornado's.",
	DGN_TIP_DN_SENTINEL_QUICK = "Tornado's: Sta bij elkaar zodat ze op één plek landen, en loop dan weg.|nAdds: Er komen twee ijs-adds. Stop hun cast, en dood er één vlak vóór de storm.|nStorm: Sta in de sneeuw die de dode add achterlaat. Dan kan de storm je niet verplaatsen.",
	DGN_TIP_DN_SENTINEL_TANK = "Tank: Sleep de boss op één add zodat de groep die cleavet, en houd de boss uit de tornado's. Help Winter's Shroud te interrupten.",
	DGN_TIP_DN_SENTINEL_HEALER = "Healer: {SPELL:1235548} is een magic frost-DoT: dispel hem snel, en heal wie je niet kunt dispellen. De storm raakt iedereen, dus sta klaar om de groep te healen.",

	DGN_TIP_DN_NALORAKK_STEPS = "1. {SPELL:1242860}: drie spelers krijgen een markering. Loop naar de rand voordat die afloopt: waar je staat verschijnt een spookbeer (een Echo). Zet alle Echoes bij elkaar, weg van de groep. Echoes doen iedereen in de buurt pijn elke keer dat Nalorakk uithaalt.|n2. {SPELL:1243011}: Nalorakk slaat Zul'jarra neer en elke Echo stormt op haar af. Ga als een muur om haar heen staan en blok de charges. Een Echo die haar bereikt doet de hele groep pijn.|n3. {SPELL:1243569}: Nalorakk slaat de tank keer op keer. Zul'jarra zet een schild neer dat deze schade halveert: iedereen staat achter haar schild.|n4. Direct daarna stapt alleen de tank in Forceful Slam. Iedereen anders stapt eruit. Raakt het Zul'jarra, dan krijgt de hele groep schade.|n5. Op Mythic en Mythic+: een Echo blokken geeft je ook een stapelende bleed (Spectral Slash). Zet één speler in elke charge-baan, en laat nooit twee mensen dezelfde Echo blokken.",
	DGN_TIP_DN_NALORAKK_QUICK_DPS = "Ga in het pad van een spookbeer staan, één persoon per beer.",
	DGN_TIP_DN_NALORAKK_QUICK_HEALER = "Heal de tank hard tijdens de grote klappen, en heal iedereen vol vóór de roar.",
	DGN_TIP_DN_NALORAKK_QUICK_TANK = "Verstop je achter haar schild, en vang daarna de volgende slam alleen op.",
	DGN_TIP_DN_NALORAKK_QUICK = "Markering: Krijg je een markering, loop dan naar de rand. Daar verschijnt een spookbeer.|nAanval: De spookberen rennen naar Zul'jarra. Ga in hun pad staan om ze te stoppen.|nSchild: Slaat de boss de tank vaak achter elkaar, dan verstopt iedereen zich achter haar schild.",
	DGN_TIP_DN_NALORAKK_TANK = "Tank: {SPELL:1243569} is op jou. Sta achter het schild van Zul'jarra en gebruik een defensive. Stap daarna alleen in Forceful Slam, weg van de groep.",
	DGN_TIP_DN_NALORAKK_HEALER = "Healer: De tank krijgt grote klappen tijdens {SPELL:1243569}, en daarna Forceful Slam. Heal de groep vol vóór Forceful Roar. Let op Mythic+ op de bleed-stacks van de spelers die Echoes blokken.",

	-- The Blinding Vale -----------------------------------------------------------
	DGN_TIP_BV_TRINITY_STEPS = "1. De drie bosses delen één health-balk. De tank zet ze bij elkaar en iedereen raakt alle drie. Kick de Light Bolt van Kezkitt.|n2. {SPELL:1234753} raakt de tank en laat drie groene cirkels achter. Ga er nog niet in staan. Daarna dasht Lekshi door alle drie de cirkels ({SPELL:1234850}) - blijf uit die lijn.|n3. Begint {SPELL:1235564}, dan staat er één speler in elke cirkel (de tank plus twee anderen) tot de beam stopt. Een lege cirkel laat de hele groep later zware schade krijgen.|n4. Na de beam worden de cirkels brandende grond ({SPELL:1235828}). Stap eruit; de tank zet de bosses op schone grond. {SPELL:1261276} laat een willekeurige speler bloeden: gebruik een defensive of haal de bleed weg.|n5. Op Mythic en Mythic+: na Thornblade springt Lekshi naar die speler en sproeit doorns om hem heen. Die speler loopt weg van de groep en rent dan uit de doorns. Bedrock Slam stuurt ook schadepulsen door de hele groep.",
	DGN_TIP_BV_TRINITY_QUICK_DPS = "Raak alle drie de bosses tegelijk, en kick de bolt van Kezkitt.",
	DGN_TIP_BV_TRINITY_QUICK_HEALER = "Houd de spelers in de cirkels in leven, en heal de speler die bloedt.",
	DGN_TIP_BV_TRINITY_QUICK_TANK = "Gebruik een defensive voor de grote slam, en zet de drie bosses daarna van de brandende grond af.",
	DGN_TIP_BV_TRINITY_QUICK = "Drie bosses: Ze delen één health-balk. Zet ze bij elkaar en raak ze alle drie.|nCirkels: Komt de beam, dan staat er één speler in elke cirkel tot hij stopt.|nDash: Blijf uit de lijn tussen de cirkels, en ga uit de cirkels als ze branden.",
	DGN_TIP_BV_TRINITY_TANK = "Tank: Gebruik een defensive voor {SPELL:1234753}. Houd de drie bij elkaar voor cleave, sta tijdens de beam in één cirkel, en zet de bosses daarna van de brandende grond af vóór de volgende slam.",
	DGN_TIP_BV_TRINITY_HEALER = "Healer: De drie cirkel-soakers krijgen tikkende schade - houd ze op de been, en heal de bleed van {SPELL:1261276}. Bewaar op Mythic een cooldown voor de groepspulsen na Bedrock Slam.",

	DGN_TIP_BV_IKUZZ_STEPS = "1. {SPELL:1236746} raakt iedereen en slingert je weg. Ga zo staan dat je niet van een rand of in wortels vliegt.|n2. {SPELL:1236709}: hij brult en doet de hele groep 6 seconden pijn. Gebruik een defensive als je laag staat.|n3. {SPELL:1237091}: hij jaagt 10 seconden op één speler. Die speler rent en leidt hem over de wortels op de grond - zijn stappen pletten ze. Pakt hij je, dan bloed je en word je gestund ({SPELL:1272290}).|n4. Vanaf 50% health raakt hij in frenzy: hij beweegt sneller en doet de groep constant pijn. Bewaar hier cooldowns voor.|n5. Op Mythic en Mythic+: een paar seconden na de stamp grijpen wortels elke speler, en tijdens de roar groeien er meer wortels. Ga terug naar de boss zodat de groep de wortels kan cleaven, of gebruik een freedom-spell.",
	DGN_TIP_BV_IKUZZ_QUICK_DPS = "Breek de wortels snel, en jaagt hij op jou, ren dan over de wortels.",
	DGN_TIP_BV_IKUZZ_QUICK_HEALER = "Bewaar je grote heals voor als hij op halve health is.",
	DGN_TIP_BV_IKUZZ_QUICK_TANK = "Houd de boss dicht bij spelers die vastzitten in wortels, zodat iedereen ze kan breken.",
	DGN_TIP_BV_IKUZZ_QUICK = "Stamp: Hij slingert iedereen weg. Sta niet bij een rand.|nJacht: Hij jaagt op één speler. Die speler rent over de wortels zodat hij ze plet.|nHalve health: Hij wordt sneller en slaat harder. Gebruik nu je grote spells.",
	DGN_TIP_BV_IKUZZ_TANK = "Tank: Houd Ikuzz dicht bij gewortelde spelers zodat iedereen de wortels kan cleaven, en weg van randen vanwege de knockback.",
	DGN_TIP_BV_IKUZZ_HEALER = "Healer: De stamp en {SPELL:1236709} raken de hele groep. Bewaar je grote cooldowns voor de frenzy op 50%, vooral als hij daarin brult. Een gepakte speler krijgt zware schade - heal die snel vol.",

	DGN_TIP_BV_RUIA_STEPS = "1. Moonkin-vorm (100 tot 70%): kick Warden's Wrath - dat raakt de tank. Ontwijk de cirkels van {SPELL:1240098}.|n2. {SPELL:1239825} markeert een paar spelers. Loop weg van de groep voordat het afloopt: daarna schieten er stralen uit je. Blijf uit de stralen - ze silencen je.|n3. Beervorm (70 tot 40%): {SPELL:1240222} markeert een paar spelers en vuurt kegels op ze af. Gemarkeerde spelers gaan uit elkaar en houden hun kegel van anderen af. Een tweede treffer doet veel meer pijn.|n4. {SPELL:1241058} laat spelers bloeden tot ze vol geheald zijn.|n5. Op 40% health, {SPELL:1241067}: hij cast dit allemaal elke 8 seconden tot hij dood is. Gebruik hier je cooldowns en Bloodlust.",
	DGN_TIP_BV_RUIA_QUICK_DPS = "Kick zijn spell in moonkin-vorm, en bewaar je grote spells voor 40 procent.",
	DGN_TIP_BV_RUIA_QUICK_HEALER = "Een bloedende speler blijft bloeden tot je hem helemaal vol healt.",
	DGN_TIP_BV_RUIA_QUICK_TANK = "Zorg dat zijn spell gekickt wordt in moonkin-vorm, en gebruik defensives in beervorm.",
	DGN_TIP_BV_RUIA_QUICK = "Moonkin: Kick zijn spell, ontwijk de cirkels, en loop weg van de groep als je de straal-markering krijgt.|nBeer: Ben je gemarkeerd, ga dan weg zodat je kegel niemand anders raakt.|n40%: Hij doet alles tegelijk. Gebruik nu je grote spells.",
	DGN_TIP_BV_RUIA_TANK = "Tank: In moonkin-vorm vervangt Warden's Wrath zijn melee - zorg dat die gekickt wordt. In beervorm slaat zijn melee twee keer zo hard (Mangling Claws), dus gebruik daar je defensives.",
	DGN_TIP_BV_RUIA_HEALER = "Healer: {SPELL:1241058} stopt pas als een speler op volle health staat - heal één doelwit vol, dan de volgende. Bewaar cooldowns voor de 40%-fase.",

	DGN_TIP_BV_ZIEKKET_STEPS = "1. {SPELL:1246372}: er schieten lashers op. De tank verzamelt ze; iedereen cleavet ze en kickt Lightspore Shot.|n2. Een lasher op 1% health zakt in de grond en kan geen schade krijgen. Hij wordt sterker wakker bij de volgende {SPELL:1246372}, en dan kan hij niet gekickt of gestund worden.|n3. {SPELL:1253690} richt een beam op een speler. Ben jij het, draai dan zo dat de beam door elke slapende lasher loopt - dat doodt ze voorgoed. Hij laat vertragende plassen achter ({SPELL:1246753}); stap eruit.|n4. {SPELL:1247685} raakt de tank hard, slingert hem weg en laat hem bloeden. De hele groep krijgt het hele gevecht pulserende schade.|n5. Op Mythic en Mythic+: {SPELL:1246858} stuurt orbs naar Ziekket. Stap erin voordat ze hem bereiken, en verdeel ze (ongeveer twee of drie per persoon) - elke orb geeft je een stapelende DoT. Een orb die hem bereikt doet de groep pijn en geeft hem een schild.",
	DGN_TIP_BV_ZIEKKET_QUICK_DPS = "Kick de schoten van de lashers, en stop met slaan zodra een lasher slaapt.",
	DGN_TIP_BV_ZIEKKET_QUICK_HEALER = "De hele groep krijgt het hele gevecht schade, dus blijf iedereen healen.",
	DGN_TIP_BV_ZIEKKET_QUICK_TANK = "Verzamel de lashers, en gebruik een defensive voor de grote stekelklap.",
	DGN_TIP_BV_ZIEKKET_QUICK = "Lashers: Sla ze tot ze in de grond zakken. Dan slapen ze.|nBeam: Mikt de beam op jou, stuur hem dan door de slapende lashers. Dat doodt ze voorgoed.|nMythic-orbs: Raak de gloeiende ballen aan voordat ze de boss bereiken, en verdeel ze.",
	DGN_TIP_BV_ZIEKKET_TANK = "Tank: Verzamel elke lasher-golf voor cleave, bij de rand. Gebruik een defensive voor {SPELL:1247685} - die slingert je weg en laat je bloeden. Ga uit de Lightsap-plassen.",
	DGN_TIP_BV_ZIEKKET_HEALER = "Healer: De groep krijgt het hele gevecht schade, dus blijf iedereen healen. Let op Mythic op de orb-soakers - hun stacks doen pijn, en een gemiste orb raakt de hele groep.",

	-- Voidscar Arena ----------------------------------------------------------------
	DGN_TIP_VA_TAZRAH_STEPS = "1. {SPELL:1222098}: een schim dasht in een lijn door elke speler. Sta losjes verspreid bij de rand van de zaal, zodat jouw lijn niemand anders raakt.|n2. {SPELL:1296963} laat plassen achter op de grond. Leg ze bij de rand en dicht bij elkaar, en sta er nooit in.|n3. {SPELL:1300259}: de plassen schieten orbs af. Blijf rondlopen door de zaal en ontwijk elke orb.|n4. Op Mythic en Mythic+: {SPELL:1225011} - twee scherven vliegen naar één speler, en elke scherf barst op de eerste speler die hij raakt. Stap niet in scherven die op iemand anders gericht zijn.",
	DGN_TIP_VA_TAZRAH_QUICK_DPS = "Blijf de boss slaan terwijl je ontwijkt.",
	DGN_TIP_VA_TAZRAH_QUICK_HEALER = "Heal iedereen vol voordat de plassen komen.",
	DGN_TIP_VA_TAZRAH_QUICK_TANK = "Gebruik een defensive als hij je wegslingert, en land niet in een plas.",
	DGN_TIP_VA_TAZRAH_QUICK = "Dash: Een geest rent in een lijn op je af. Sta bij de muur, een beetje los van je vrienden.|nPlassen: Leg je donkere plassen bij de muur, dicht bij elkaar. Sta er nooit in.|nBallen: De plassen schieten ballen. Blijf door de zaal lopen en ontwijk ze.",
	DGN_TIP_VA_TAZRAH_TANK = "Tank: {SPELL:1297017} raakt je hard en slingert je weg. Gebruik een defensive en laat je niet in een plas slingeren. Tank bij een muur en draai langzaam de zaal rond, zodat het midden vrij blijft.",
	DGN_TIP_VA_TAZRAH_HEALER = "Healer: Heal iedereen vol vóór elke {SPELL:1296963}-cast; {SPELL:1300259} doet de hele groep pijn. Heal spelers die door een dash geraakt zijn, want die blijft ze een tijdje pijn doen.",

	DGN_TIP_VA_ATROXUS_STEPS = "1. {SPELL:1262497} raakt de hele groep. Ongeveer 3 seconden later kruipt er een Toxic Creeper uit ({SPELL:1222371}). Dood hem snel.|n2. {SPELL:1263977} is een frontal gericht op een willekeurige speler. Blijf dicht bij de boss zodat je er snel uit kunt stappen.|n3. {SPELL:1226120} spat gif rond de boss. Ontwijk de inslagen en blijf uit de gifplassen die het achterlaat.|n4. Op Mythic en Mythic+: de Creeper heeft Toxic Aura - die doet iedereen binnen 8 yards pijn tot hij dood is. Dood hem nog sneller; ranged spelers blijven uit zijn buurt.",
	DGN_TIP_VA_ATROXUS_QUICK_DPS = "Komt de Creeper eruit, sla hem dan eerst.",
	DGN_TIP_VA_ATROXUS_QUICK_HEALER = "Haal gif weg bij de tank en bij iedereen die in een plas stond.",
	DGN_TIP_VA_ATROXUS_QUICK_TANK = "De Creeper jaagt op jou: loop ervan weg zodat hij je niet kan bijten.",
	DGN_TIP_VA_ATROXUS_QUICK = "Brul: De boss brult en er kruipt een klein monster uit, de Creeper. Iedereen slaat hem tot hij dood is.|nAdem: De boss ademt naar een willekeurige speler. Sta dichtbij, en stap eruit.|nGif: Stap weg van de gifspatten en de plassen.",
	DGN_TIP_VA_ATROXUS_TANK = "Tank: De Creeper fixeert jou. Kite hem en laat hem je niet raken - elke beet geeft een Sickening Bite-stack, en de stacks maken {SPELL:1222642} dodelijk. Houd hem dicht bij de boss zodat de DPS allebei kunnen raken, en gebruik een defensive voor de klauw.",
	DGN_TIP_VA_ATROXUS_HEALER = "Healer: Dispel de poisons: die van {SPELL:1222642} op de tank en Mind-Numbing Poison uit de plassen. Op Mythic en Mythic+ gebruik je een heal-cooldown zolang de Creeper leeft.",

	DGN_TIP_VA_CHARONUS_STEPS = "1. {SPELL:1282770}: sommige spelers worden gemarkeerd, en een paar seconden later verschijnt er een gravity well onder ze. Die trekt je naar binnen en doet pijn. Ga eruit, maar blijf ernaast - je hebt hem nodig voor de orbs. Het midden geeft Atomized: korte tijd geen schade en geen healing.|n2. {SPELL:1263982}: een orb jaagt op 3 spelers. Zijn debuff doet pijn en vertraagt je elke seconde meer. Loop langs een gravity well zodat je orb je erin volgt - dat vernietigt ze allebei. Blijf er niet in staan. Elke speler gebruikt een andere well.|n3. {SPELL:1227264} raakt iedereen, slingert je weg en laat een schade-effect van 20 seconden achter. Sta los van elkaar, en zorg dat je niet in een well landt.|n4. Op Mythic en Mythic+: {SPELL:1222758} - projectielen vliegen naar een willekeurige speler en slingeren iedereen weg die ze raken. Ben jij het, blijf dan rennen; iedereen anders stapt uit het pad.",
	DGN_TIP_VA_CHARONUS_QUICK_DPS = "Wacht naast een gat, zodat een bal die op jou jaagt er snel in valt.",
	DGN_TIP_VA_CHARONUS_QUICK_HEALER = "Heal eerst de spelers die door een bal achternagezeten worden.",
	DGN_TIP_VA_CHARONUS_QUICK_TANK = "Gebruik een defensive voor zijn grote klap en richt hem van je vrienden af.",
	DGN_TIP_VA_CHARONUS_QUICK = "Gaten: Er verschijnen donkere gaten op de vloer. Ze trekken je naar binnen, dus blijf bij een gat maar niet erin.|nBallen: Jaagt er een bal op jou, loop dan langs een gat zodat de bal erin valt.|nKlap: De boss duwt iedereen weg. Sta los van elkaar, en vlieg niet in een gat.",
	DGN_TIP_VA_CHARONUS_TANK = "Tank: {SPELL:1311923} is een frontale tank-klap. Gebruik een defensive en richt hem van de groep af. Houd de boss in het midden van de drie gravity wells, en draai hem niet door spelers heen.",
	DGN_TIP_VA_CHARONUS_HEALER = "Healer: Heal eerst de spelers met een orb - hoe langer ze hem dragen, hoe harder hij raakt. Na {SPELL:1227264} heeft de hele groep een schade-effect van 20 seconden, en de gravity wells pulseren schade zolang ze er zijn.",

	-- Nexus-Point Xenas ---------------------------------------------------------------
	DGN_TIP_NX_KASRETH_STEPS = "1. {SPELL:1251785} op jou? Stap IN een leyline-straal ({SPELL:1251183}) — die haalt de debuff weg (korte stun, prima ruil).|n2. De rest: kruis de leylines NIET (schade + stapelende slow).|n3. Volle energie = {SPELL:1257509}: grote inslagzone, maak ruimte — daarna blijven arcane spills ({SPELL:1264048}) liggen.",
	DGN_TIP_NX_KASRETH_TANK = "Tank: houd de boss weg van de leylines.",
	DGN_TIP_NX_KASRETH_HEALER = "Healer: Sparkburn tikt op iedereen na elke detonatie.",

	DGN_TIP_NX_NYSARRA_STEPS = "1. Spreid — de klappen van {SPELL:1249020} splashen 14 yards.|n2. Maak de Null Vanguard-adds ({SPELL:1252703}) SNEL dood: wat nog leeft wordt verslonden ({SPELL:1271684}), healt haar en knalt op de groep.|n3. Ontwijk de {SPELL:1264439}.",
	DGN_TIP_NX_NYSARRA_TANK = "Tank: ze springt op je af met een slash-combo ({SPELL:1247937}) — defensive, zet je schrap voor de finisher.",
	DGN_TIP_NX_NYSARRA_HEALER = "Healer: spreidschade na {SPELL:1249020}; groepsknal als adds de verslinding overleven.",

	DGN_TIP_NX_LOTHRAXION_STEPS = "1. {SPELL:1255503}: spreid — inslagen splashen 8 yards en spawnen Fractured Images.|n2. {SPELL:1257567}: hij verstopt zich tussen zijn evenbeelden en allemaal channelen ze — vind de ÉCHTE Lothraxion en interrupt hem.|n3. Evenbeelden flikkeren rond met knockbacks ({SPELL:1255531}); blijf van de {SPELL:1255310} op de vloer.",
	DGN_TIP_NX_LOTHRAXION_TANK = "Tank: {SPELL:1255335} is een dubbele slash die littekens in de grond kerft — richt 'm van de groep af.",
	DGN_TIP_NX_LOTHRAXION_HEALER = "Healer: Holy-DoTs na elke {SPELL:1255503}; gestage schade tot de Guile-interrupt zit.",

	-- Magisters' Terrace ---------------------------------------------------------------
	DGN_TIP_MT_ARCANOTRON_STEPS = "1. Bij het bijtanken ({SPELL:474345}) worden Energy Orbs naar 'm toe getrokken — onderschep ze; ondertussen krijgt hij +20% schade: burst-window!|n2. Geketende spelers ({SPELL:1214038}) staan vastgeworteld (magic) — dispel of sla ze los.|n3. {SPELL:1214081} slingert iedereen weg en laat residu achter bij z'n voeten — stap eruit.",
	DGN_TIP_MT_ARCANOTRON_TANK = "Tank: {SPELL:474496} lanceert je — houd je rug vrij.",
	DGN_TIP_MT_ARCANOTRON_HEALER = "Healer: dispel {SPELL:1214038} (magic root) snel.",

	DGN_TIP_MT_SERANEL_STEPS = "1. {SPELL:1225193} pacificeert iedereen BUITEN de Suppression Zone ({SPELL:1224903}) — sta IN de zone tijdens de wave (maar de zone silencet je, dus blijf er niet hangen).|n2. Purge/spellsteal zijn {SPELL:1248689} (+100% attack speed) zodra die opstaat.|n3. {SPELL:1225787} stuitert naar een speler in de buurt — spreid.",
	DGN_TIP_MT_SERANEL_TANK = "Tank: een niet-gepurgde Ward verdubbelt zijn attack speed — defensive tot 'ie weg is.",
	DGN_TIP_MT_SERANEL_HEALER = "Healer: gemarkeerde spelers tikken; bedenk dat je in de zone niet kunt casten.",

	DGN_TIP_MT_GEMELLUS_STEPS = "1. {SPELL:1223847} (bij de start en op halve health): hij splitst in drieën.|n2. {SPELL:1253709}: gelinkt aan eentje? REN ernaartoe en raak 'm aan — dat verbreekt de link en sloopt zijn absorb-schild.|n3. {SPELL:1224299} trekt je naar binnen — ren er weer uit.",
	DGN_TIP_MT_GEMELLUS_TANK = "Tank: hergroepeer het drietal na elke {SPELL:1223847} zodat gelinkte spelers de hunne kunnen bereiken.",
	DGN_TIP_MT_GEMELLUS_HEALER = "Healer: gelinkte spelers krijgen +20% schade tot ze hun link verbreken.",

	DGN_TIP_MT_DEGENTRIUS_STEPS = "1. {SPELL:1215897}: void-DoTs met verschillende looptijden — loopt de jouwe af, dan schieten er Entropy Orbs vanaf JOUW plek: loop eerst weg van de groep.|n2. {SPELL:1215087} stuitert naar 4 plekken — SOAK een inslag (één speler per plek), anders barst 'ie in Void Destruction.|n3. {SPELL:1280113} verbrijzelt de tank en slingert iedereen binnen 8 yards weg — geef de tank ruimte.",
	DGN_TIP_MT_DEGENTRIUS_TANK = "Tank: defensive voor {SPELL:1280113}; tank 'm weg van de groep.",
	DGN_TIP_MT_DEGENTRIUS_HEALER = "Healer: Entropy-DoTs tikken hard — houd de dragers op de been terwijl ze verkassen.",

	-- Skyreach (batch 3 — Midnight-revamp abilities via DBM + Wowhead) ----------
	DGN_TIP_SR_RANJIT_STEPS = "1. {SPELL:1258148} vliegt in een rechte lijn voor 'm uit — stap opzij.|n2. {SPELL:156793}: een inslag in het midden plus dwalende windhozen die je lanceren — blijf laveren.|n3. {SPELL:153757} raakt iedereen met een bleed — sta vol.|n4. {SPELL:1252733} blaast zijn doelwitten weg — let op wat er achter je is.",
	DGN_TIP_SR_RANJIT_TANK = "Tank: houd 'm uit de vortex-paden.",
	DGN_TIP_SR_RANJIT_HEALER = "Healer: groepsschade plus bleeds na elke {SPELL:153757}.",

	DGN_TIP_SR_ARAKNATH_STEPS = "1. {SPELL:154162}: constructs stralen licht in de boss en HELEN hem — ga in een straal staan om 'm te blokkeren.|n2. {SPELL:154115}: een armslag aan één kant — geraakt worden stapelt een gemene damage-taken-debuff.|n3. {SPELL:154135} raakt iedereen — wees er klaar voor.",
	DGN_TIP_SR_ARAKNATH_TANK = "Tank: soak de stralen nooit zelf — zijn smash valt precies tijdens het soaken.",
	DGN_TIP_SR_ARAKNATH_HEALER = "Healer: straal-soakers tikken gestaag; groepsheal bij {SPELL:154135}.",

	DGN_TIP_SR_RUKHRAN_STEPS = "1. {SPELL:1253527}: 3 seconden veren alle kanten op — verbreek zichtlijn achter een pilaar.|n2. {SPELL:1253510} raakt de groep en summont een Sunwing die iemand fixeert en vuur pulseert — snel doden; gefixeerde speler houdt afstand.|n3. Herhaal — quills achter dekking, vogel snel neer.",
	DGN_TIP_SR_RUKHRAN_TANK = "Tank: defensive voor {SPELL:1253519} (grote klap + burn-DoT).",
	DGN_TIP_SR_RUKHRAN_HEALER = "Healer: pulserende groepsschade zolang een Sunwing leeft — roep om de kill.",

	DGN_TIP_SR_VIRYX_STEPS = "1. {SPELL:154396}: een cast van 3 seconden die de tank sloopt — KICK 'm, elke keer.|n2. {SPELL:1253998}: een Solar Zealot grijpt een speler om 'm van het balkon te gooien — bevrijd ze snel.|n3. {SPELL:1253531} op jou? Ren 'm ruim uit — hij laat Blazing Ground achter.",
	DGN_TIP_SR_VIRYX_TANK = "Tank: elke doorgelaten {SPELL:154396} doet zeer — houd de kick-volgorde strak.",
	DGN_TIP_SR_VIRYX_HEALER = "Healer: {SPELL:1253538} zet vuur-DoTs op meerdere spelers tegelijk.",

	-- Pit of Saron ----------------------------------------------------------------
	DGN_TIP_PS_GARFROST_STEPS = "1. {SPELL:1262029}: de smidse pulseert stapelende frost — VERSTOP JE ACHTER een brok saronite-erts, dat blokkeert de straling.|n2. {SPELL:1261546} beukt alles rond het main target — blijf 5+ yards van de tank; naast erts breekt de slag het erts in plaats van te stunnen.|n3. {SPELL:1261847} raakt iedereen en verbrijzelt AL het erts — nieuw erts volgt via {SPELL:1261286}.|n4. Blijf uit de {SPELL:1261799}.",
	DGN_TIP_PS_GARFROST_TANK = "Tank: parkeer jezelf naast een ertsbrok — {SPELL:1261546} sloopt dan het erts, niet jou.",
	DGN_TIP_PS_GARFROST_HEALER = "Healer: groepspiek bij {SPELL:1261847}; stapelende frost op iedereen zonder dekking.",

	DGN_TIP_PS_KRICKICK_STEPS = "1. {SPELL:1264363}: Ick fixeert en jaagt op een speler, en smijt onderweg Blight en Plague Globs — ren ruim; de rest blijft meppen.|n2. {SPELL:1264027}: Krick teleporteert naar een ritueelcirkel en summont Shades — switch en dood ze.|n3. {SPELL:1264336}: ontwijk de golf en de globs die op je afrollen.|n4. Sta nooit in de Blight ({SPELL:1264299}).",
	DGN_TIP_PS_KRICKICK_TANK = "Tank: {SPELL:1264287} legt een poel op jou — richt 'm naar de rand.",
	DGN_TIP_PS_KRICKICK_HEALER = "Healer: houd de opgejaagde speler op de been; groepsschade bij {SPELL:1264336}.",

	DGN_TIP_PS_TYRANNUS_STEPS = "1. {SPELL:1262772} bevriest Bone Piles rond zijn doelwit — sta bij stapels als je gemarkeerd bent: bevroren stapels kunnen geen adds leveren.|n2. {SPELL:1263406} wekt de overige stapels — Plaguespreaders eerst dood.|n3. Blijf {SPELL:1263756} en Rimefangs {SPELL:1276948} ontwijken.|n4. {SPELL:1276648} = groepsklap + DoT, en geïnfuseerde stapels leveren nare adds.",
	DGN_TIP_PS_TYRANNUS_TANK = "Tank: {SPELL:1262582} lanceert je en stapelt +200% shadow-schade — defensive en schrap zetten.",
	DGN_TIP_PS_TYRANNUS_HEALER = "Healer: groeps-DoTs na {SPELL:1276648}; tankpiek direct na Brand.",

	-- Seat of the Triumvirate --------------------------------------------------------
	DGN_TIP_ST_ZURAAL_STEPS = "1. {SPELL:1268916} raakt alles VOOR hem — sta nooit voor de boss.|n2. {SPELL:1263304} (volle energie): hij sleurt iedereen naar zich toe en barst dan met een knockback — ren op tijd uit; ook de adds worden meegezogen.|n3. {SPELL:1263399} spawnt Coalesced Void-adds — ruim ze vóór Crashing Void.|n4. {SPELL:1263282} laat Void Sludge ({SPELL:244588}) achter — houd de vloer schoon.",
	DGN_TIP_ST_ZURAAL_TANK = "Tank: defensive voor {SPELL:1263440} (driedubbele haal).",
	DGN_TIP_ST_ZURAAL_HEALER = "Healer: grote groepsklap bij {SPELL:1263304}.",

	DGN_TIP_ST_SAPRISH_STEPS = "1. Void Bombs ({SPELL:247175}) landen op spelersplekken — raak ze NIET aan; leg ze aan de randen.|n2. {SPELL:1280064}: schimmen dashen op elke speler af en detoneren bommen die ze kruisen — zorg dat jouw dash-lijn vrij van bommen loopt.|n3. {SPELL:1263523} ontsteekt ALLE bommen tegelijk — hoe minder bommen, hoe zachter.|n4. Kick Shadewings {SPELL:248831} (groepsklap + disorient).",
	DGN_TIP_ST_SAPRISH_TANK = "Tank: houd het drietal bijeen; Darkfangs pounce ({SPELL:245738}) laat zijn slachtoffer bloeden.",
	DGN_TIP_ST_SAPRISH_HEALER = "Healer: pounce-slachtoffers bloeden; groepsknal bij {SPELL:1263523}.",

	DGN_TIP_ST_NEZHAR_STEPS = "1. {SPELL:1263528} slingert iedereen weg — let op je positie bij stormen.|n2. {SPELL:1263538} en de {SPELL:1277358} zaaien chaos — dood tentakels, ontwijk de Umbral Waves uit de poort.|n3. {SPELL:1263532}-zones tikken hard, binnenin erger — eruit, snel.|n4. {SPELL:244750} sloopt de tank — kick 'm als het kan.",
	DGN_TIP_ST_NEZHAR_TANK = "Tank: zet je schrap voor {SPELL:244750} als de kick onderweg is.",
	DGN_TIP_ST_NEZHAR_HEALER = "Healer: {SPELL:1263542} = meerdere rot-DoTs tegelijk.",

	DGN_TIP_ST_LURA_STEPS = "1. Notes of Despair blijven stralen ({SPELL:1265421}) tot ze gesilencet zijn — stuur je {SPELL:1265426} DWARS DOOR de noten (de beam raakt ook teamgenoten in de lijn, dus mik vrij).|n2. {SPELL:1265689}: 20 seconden pijn rond elke actieve noot — breek noten snel.|n3. {SPELL:1264151}: roterende void-stralen — beweeg mee met de gaten.|n4. {SPELL:1266003} is een dodelijke channel van 10 seconden — alle defensives erop en doorhealen.",
	DGN_TIP_ST_LURA_TANK = "Tank: na {SPELL:1266001} vliegt iedereen — hergroepeer snel.",
	DGN_TIP_ST_LURA_HEALER = "Healer: {SPELL:1265421}-groepsklappen plus noot-aura's — noten breken IS het heal-plan.",

	-- Algeth'ar Academy ----------------------------------------------------------------
	DGN_TIP_AA_VEXAMUS_STEPS = "1. {SPELL:385974} zweven naar de boss — soak ze, één speler per orb (kleine tik); elke orb die HIJ absorbeert knalt op de hele groep.|n2. {SPELL:386173}: draag de jouwe weg — hij knapt in een {SPELL:386201}-poel.|n3. Volle energie = {SPELL:388537}: groepsklap plus herhaalde erupties onder spelers — blijf bewegen.",
	DGN_TIP_AA_VEXAMUS_TANK = "Tank: {SPELL:385958} knalt alles voor 'm weg — defensive, richt 'm van de groep af.",
	DGN_TIP_AA_VEXAMUS_HEALER = "Healer: bom-dragers tikken; groepsschade voor elke orb die de boss bereikt.",

	DGN_TIP_AA_ANCIENT_STEPS = "1. {SPELL:388796}: 4 seconden lang ontkiemen zaden onder iedereen — ontwijk; gemiste zaden laten slapende Lashers achter.|n2. Op volle energie ({SPELL:388923}) ontwaken ALLE slapende Lashers tegelijk — ruim ze van tevoren.|n3. {SPELL:388623} gooit een tak die een grote add wordt — dood 'm en KICK z'n {SPELL:396640}.",
	DGN_TIP_AA_ANCIENT_TANK = "Tank: {SPELL:388544} verdubbelt de physical schade die je krijgt — defensive, elke keer.",
	DGN_TIP_AA_ANCIENT_HEALER = "Healer: cleanse {SPELL:389033} (poison) vóór het hoog stapelt.",

	DGN_TIP_AA_CRAWTH_STEPS = "1. {SPELL:377004} erupteert onder elke speler en onderbreekt casts — STOP met casten, spreid daarna.|n2. {SPELL:377034}: ze kijkt iemand aan en vleugelt een kegel die kant op — stap eruit.|n3. {SPELL:377182}: scoor in een doel — het vuurdoel stunt haar en ze krijgt 75% extra schade.",
	DGN_TIP_AA_CRAWTH_TANK = "Tank: defensive voor {SPELL:376997} (klap + 10s bleed).",
	DGN_TIP_AA_CRAWTH_HEALER = "Healer: zware groepsschade na de screech; de tank bloedt.",

	DGN_TIP_AA_DORAGOSA_STEPS = "1. {SPELL:374341} op jou? Loop 'm weg van de groep — hij barst 8 yards breed.|n2. {SPELL:388820} sleurt iedereen naar binnen en explodeert dan — REN ERUIT vóór de knal.|n3. {SPELL:389011} stapelt van elke mechanic die je vangt — op 3 stacks barst het in een Arcane Rift; blijf schoon.|n4. Blijf van de {SPELL:389007}-grond.",
	DGN_TIP_AA_DORAGOSA_TANK = "Tank: defensive voor {SPELL:1282251}.",
	DGN_TIP_AA_DORAGOSA_HEALER = "Healer: let op {SPELL:389011}-stacks — dragers tikken harder per stack.",
	DGN_TIP_AA_ANCIENT_DPS = "DPS: Ruim de slapende Lashers op voor volle energie, anders worden ze allemaal tegelijk wakker. Dood de geworpen tak-add en kick zijn cast.",
	DGN_TIP_AA_CRAWTH_DPS = "DPS: Stop met casten als de grond openbarst - hij onderbreekt je toch - en spreid dan. Scoor in het vuurdoel: dat stunt haar en ze krijgt 75% extra schade.",
	DGN_TIP_AA_DORAGOSA_DPS = "DPS: Loop je debuff weg van de groep; hij barst 8 yards breed. Alles wat je eet stapelt, en bij 3 wordt het een Arcane Rift.",
	DGN_TIP_AA_VEXAMUS_DPS = "DPS: Soak de orbs, een per speler: elke orb die hij opneemt raakt de hele groep. Draag je eigen bolt weg voor hij een plas wordt.",
	DGN_TIP_BV_IKUZZ_DPS = "DPS: Cleave de wortels snel. Gefixeerd? Ren, en leid hem over wortels in plaats van de lege ruimte in - laat hem je niet pakken.",
	DGN_TIP_BV_RUIA_DPS = "DPS: Kick Warden's Wrath in moonkin-vorm. Bewaar je cooldowns voor 40%, als alles elke 8 seconden afgaat.",
	DGN_TIP_BV_TRINITY_DPS = "DPS: Raak alle drie de bosses - ze delen één health-balk, dus cleave. Kick Light Bolt, en neem een cirkel tijdens de beam als je groep een soaker nodig heeft.",
	DGN_TIP_BV_ZIEKKET_DPS = "DPS: Kick Lightspore Shot. Verspil geen schade aan slapende lashers - alleen de beam doodt ze. Neem op Mythic je deel van de orbs.",
	DGN_TIP_DN_HOARDMONGER_DPS = "DPS: Help op de paddenstoelen te stappen, en wissel af zodat niemand te veel gif-stacks krijgt. Blijf van de bottenplekken af.",
	DGN_TIP_DN_NALORAKK_DPS = "DPS: Als de Echoes chargen, help je Zul'jarra af te schermen: één speler per Echo. Met een markering loop je naar de rand, naast de andere Echoes.",
	DGN_TIP_DN_SENTINEL_DPS = "DPS: Verdeel de interrupts zodat elke Winter's Shroud gestopt wordt. Dood de eerste add vlak vóór de storm, de tweede erna.",
	DGN_TIP_MC_MUROJIN_DPS = "DPS: Beide bosses moeten bijna tegelijk sterven - kijk naar de twee balken en wissel op tijd, want een overlevende gaat berserk.",
	DGN_TIP_MC_RAKTUL_DPS = "DPS: Eerst de totems, dan terug naar de boss. In de soul-fase telt je schade nauwelijks - besteed die tijd aan crowd-control en interrupts.",
	DGN_TIP_MC_VORDAZA_DPS = "DPS: De fantomen zijn jouw taak: dood ze voor ze iemand bereiken, maar een voor een - elke dood is groepsschade die niemand kan ontwijken.",
	DGN_TIP_MR_KYSTIA_DPS = "DPS: Eerst Nibbles, niet Kystia. Zakt Nibbles naar 20%, wissel dan naar Kystia en gebruik je cooldowns. Interrupt of stun de kopieën van {SPELL:1264095}.",
	DGN_TIP_MR_LITHIEL_DPS = "DPS: Kick Chaos Bolt en de Wild Imps. Dood elke demon voordat {SPELL:1224478} hem raakt.",
	DGN_TIP_MR_XATHUUX_DPS = "DPS: Wissel naar de bijl zodra hij landt. Bewaar je cooldowns voor {SPELL:474197}: dan krijgt hij 30% meer schade.",
	DGN_TIP_MR_ZAEN_DPS = "DPS: Sta achter een krat vóórdat {SPELL:1218347} afgaat, niet erna. Met {SPELL:1214357} loop je weg van de gewone kratten; op Mythic breng je hem naar een groene krat.",
	DGN_TIP_MT_ARCANOTRON_DPS = "DPS: Onderschep de Energy Orbs tijdens het bijtanken, en bewaar je cooldowns daarvoor: hij krijgt dan +20% schade.",
	DGN_TIP_MT_DEGENTRIUS_DPS = "DPS: Soak elk een Unstable Void Essence-inslag, anders barst hij open. Loopt je Entropy-DoT af? Eerst weg van de groep.",
	DGN_TIP_MT_GEMELLUS_DPS = "DPS: Verbreek je link voor je weer schade doet - alles wat in zijn absorb-schild gaat is verspild.",
	DGN_TIP_MT_SERANEL_DPS = "DPS: Purge of spellsteal de Hastening Ward elke keer. Stap in de Suppression Zone voor de wave en dan eruit - hij silencet je.",
	DGN_TIP_NX_KASRETH_DPS = "DPS: Haal je debuff eraf in een leyline-straal - die korte stun kost minder dan de debuff. Kruis de leylines verder nooit.",
	DGN_TIP_NX_LOTHRAXION_DPS = "DPS: Verstopt hij zich tussen zijn beelden? Zoek de echte en onderbreek hem - schade op de beelden is verspild.",
	DGN_TIP_NX_NYSARRA_DPS = "DPS: Adds gaan altijd voor - alles wat blijft staan geneest haar. Wissel zodra ze verschijnen in plaats van je cast op haar af te maken.",
	DGN_TIP_PS_GARFROST_DPS = "DPS: Erts is dekking: ga achter een brok staan bij de forge-puls. Blijf 5+ yards van de tank zodat de slam jou niet meepakt.",
	DGN_TIP_PS_KRICKICK_DPS = "DPS: Teleporteert Krick naar een ritueelcirkel? Wissel naar de Shades. Gefixeerd door Ick: ren wijd, de rest blijft slaan.",
	DGN_TIP_PS_TYRANNUS_DPS = "DPS: Gemarkeerd? Ga bij Bone Piles staan zodat ze bevriezen; bevroren stapels kunnen geen adds oproepen. Komen ze toch: Plaguespreaders eerst.",
	DGN_TIP_SR_ARAKNATH_DPS = "DPS: Blokkeer de stralen van de constructs met je lichaam - elke straal die aankomt healt hem weer op.",
	DGN_TIP_SR_RANJIT_DPS = "DPS: Een positioneel gevecht, geen doelwit-gevecht: opzij voor de lijn, om de vortexen heen, en let op wat er achter je staat.",
	DGN_TIP_SR_RUKHRAN_DPS = "DPS: Quills betekent pilaar, elke keer. Dood daarna de Sunwing snel; wie hij fixeert houdt afstand.",
	DGN_TIP_SR_VIRYX_DPS = "DPS: Kick de tank-nuke elke keer - het is een cast van 3 seconden. Bevrijd wie de Solar Zealot grijpt voor ze van het balkon gaan.",
	DGN_TIP_ST_LURA_DPS = "DPS: Stuur je straal door de Notes of Despair - die blijven stralen tot ze gedempt zijn - en houd hem weg van je maten, want hij raakt hen ook.",
	DGN_TIP_ST_NEZHAR_DPS = "DPS: Dood de tentakels en kick de tank-nuke als het kan. De zones tikken hard, dus eruit in plaats van uptime pakken.",
	DGN_TIP_ST_SAPRISH_DPS = "DPS: Kick Shadewings cast, en laat je Void Bombs aan de rand vallen - hoe minder bommen, hoe milder de massa-ontsteking.",
	DGN_TIP_ST_ZURAAL_DPS = "DPS: Ruim de Coalesced Void-adds op voor Crashing Void, anders worden ze mee naar binnen getrokken. Nooit voor hem staan.",
	DGN_TIP_VA_ATROXUS_DPS = "DPS: Wissel naar de Toxic Creeper zodra die na elke roar verschijnt. Dood hem, en ga dan terug naar de boss.",
	DGN_TIP_VA_CHARONUS_DPS = "DPS: Sta naast een gravity well voordat de orbs komen. Jaagt er een orb op jou, leid hem er dan meteen in; een speed- of freedom-spell of een defensive helpt als de slow-stacks hoog worden.",
	DGN_TIP_VA_TAZRAH_DPS = "DPS: Blijf op de boss. De Ethereal Shades maken alleen de dash-lijnen, en de huidige gidsen vragen je niet om ze te doden.",
	DGN_TIP_WS_DUO_DPS = "DPS: Verdeel je schade zodat ze bijna tegelijk sterven, en houd Shadow Bolt onderbroken. De Dark Entity uit een curse: crowd-controlen, niet achterna jagen.",
	DGN_TIP_WS_EMBER_DPS = "DPS: Laat je vuurplassen aan de rand vallen zodat het midden schoon blijft, en stap opzij voor de breath in plaats van weg te rennen.",
	DGN_TIP_WS_HEART_DPS = "DPS: Pak een windpijl bij 2-3 stacks, maar houd er een vrij voor de grote klap op volle energie.",
	DGN_TIP_WS_KROLUK_DPS = "DPS: Adds komen rond twee derde en een derde health: meteen erop, Phantasmal Mystic eerst, en blijf hem onderbreken.",
	-- Altar of Fangs (Season 2, patch 12.1) --------------------------------------
	DGN_TIP_AF_RAVI_STEPS = "1. {SPELL:1307894} raakt de hele groep en laat puin vallen. Sta op volle health en stap uit de cirkels op de grond.|n2. Is haar energie op, dan eet Rav'i van een kadaverhoop en krijgt ze een schild ({SPELL:1309522}). Iedereen valt haar aan en breekt het schild snel: de groep krijgt schade tot het breekt.|n3. Eet ze van een hoop met {SPELL:1307921} erop, dan krijgt ze {SPELL:1307765} en slaat ze veel harder. De tank houdt haar weg bij die hopen.|n4. {SPELL:1296220}: ga uit elkaar. Ontwijk de drie golven van {SPELL:1296050}.|n5. Op Mythic en Mythic+: terwijl ze eet, gooit ze brokken vlees (Messy Eater). Stap erin om ze te vangen; elke gemiste brok doet de groep pijn.",
	DGN_TIP_AF_RAVI_QUICK_DPS = "Breek het schild snel, en ga uit elkaar als de drie schoten komen.",
	DGN_TIP_AF_RAVI_QUICK_HEALER = "Heal iedereen vol vóór de stamp en heal door tot het schild weg is.",
	DGN_TIP_AF_RAVI_QUICK_TANK = "Trek haar weg bij de hopen met vers vlees voordat ze eet.",
	DGN_TIP_AF_RAVI_QUICK = "Stamp: De hele groep krijgt een klap en er vallen stenen. Sta op volle health en stap uit de cirkels.|nSchild: Als ze eet, krijgt ze een schild. Iedereen slaat haar hard tot het breekt.|nVlees: De tank houdt haar weg bij het verse vlees, anders slaat ze veel harder.",
	DGN_TIP_AF_RAVI_DPS = "DPS: Wissel naar Rav'i zodra het schild verschijnt en breek het met je burst. Ga uit elkaar voor {SPELL:1296220}.",
	DGN_TIP_AF_RAVI_TANK = "Tank: Sleep Rav'i vóór ze eet naar een kadaverhoop zonder {SPELL:1307921}, zodat ze nooit {SPELL:1307765} krijgt. Gebruik een defensive voor haar zware melee-klappen (Hydrastrike).",
	DGN_TIP_AF_RAVI_HEALER = "Healer: Heal de groep vol vóór {SPELL:1307894}, en heal hard tot het schild breekt. Kun je een disease weghalen, cleanse dan de spelers die door {SPELL:1296050} geraakt zijn.",
	DGN_TIP_AF_COIL_STEPS = "1. Interrupt {SPELL:1310547}. Het komt als drie casts achter elkaar, dus plan drie kicks. Elke gemiste kick maakt de groep zwakker en trager.|n2. Ontwijk {SPELL:1299940}: een charge in een lijn en een gifkegel. Is de kegel op jou gericht, richt hem dan weg van de groep.|n3. {SPELL:1299053}: ranken binden je aan de boss en de schade blijft stijgen. Iedereen rent tegelijk meer dan 10 yards van de boss weg om de ranken te breken.|n4. Daarna splitst de boss in 5 slangen. Sla ze hard: die schade telt mee voor de boss. Smelten ze weer samen ({SPELL:1300686}), sta dan niet in hun pad.|n5. Op Mythic en Mythic+: elke slang jaagt op een speler ({SPELL:1300503}). Ren ervoor weg en slow of stun hem; laat hem je niet aanraken.",
	DGN_TIP_AF_COIL_QUICK_DPS = "Kick als het jouw beurt is en gebruik je grote aanvallen op de slangen.",
	DGN_TIP_AF_COIL_QUICK_HEALER = "Het gif doet het hele gevecht pijn; komen de ranken, zeg dan dat iedereen moet rennen.",
	DGN_TIP_AF_COIL_QUICK_TANK = "Neem een defensive voor de staartklap en trek de slangen bij elkaar.",
	DGN_TIP_AF_COIL_QUICK = "Kicks: De boss cast drie keer achter elkaar. Stop elke cast.|nRanken: Ranken binden je aan de boss. Iedereen rent tegelijk ver van hem weg.|nSlangen: De boss valt uiteen in slangen. Sla ze hard, en ga opzij als ze weer samenkomen.",
	DGN_TIP_AF_COIL_DPS = "DPS: Neem je beurt in de kick-volgorde voor {SPELL:1310547}. Bewaar je grote cooldowns voor de 5 slangen, niet voor de boss.",
	DGN_TIP_AF_COIL_HEALER = "Healer: {SPELL:1299154} is groepsschade die het hele gevecht doortikt. Heal hard zolang de ranken er zijn, maar de echte oplossing is dat iedereen wegrent.",
	DGN_TIP_AF_COIL_TANK = "Tank: Gebruik een defensive voor {SPELL:1298949}. Splitst de boss, trek de slangen dan bij elkaar zodat de groep ze allemaal tegelijk kan raken.",
	DGN_TIP_AF_ZULJAN_STEPS = "1. {SPELL:1300876}: vier slangenkoppen schieten stralen op Zul'jan. Ga in een straal staan, tussen de kop en de boss, om hem te blokken. Spreek vóór de pull af wie welke straal neemt. Elke straal die hem bereikt maakt hem sterker voor de rest van het gevecht.|n2. Een straal blokken geeft je Ritual Venom. Dat barst voor grote schade als het afloopt, dus haal het eerder weg.|n3. Om het weg te halen stap je expres in een {SPELL:1301413}-bijllijn: dat haalt al je gif weg. Zonder gif blijf je uit die lijn.|n4. Gif weghalen laat een bloedplas achter ({SPELL:1301231}). Stap eruit. Ontwijk de stuiterende bijlen van {SPELL:1301111}.|n5. Op Mythic en Mythic+: Ritual Venom stapelt. Haal alles in één bijllijn weg voordat het afloopt.",
	DGN_TIP_AF_ZULJAN_QUICK_DPS = "Sta in je straal en gebruik daarna de bijllijn om je gif weg te halen.",
	DGN_TIP_AF_ZULJAN_QUICK_HEALER = "Heal flink tijdens de stralen en let op wie nog gif heeft.",
	DGN_TIP_AF_ZULJAN_QUICK_TANK = "Gebruik een defensive voor de dubbele klap en leg je bloedplassen aan de rand.",
	DGN_TIP_AF_ZULJAN_QUICK = "Stralen: Slangenkoppen schieten stralen op de boss. Ga in een straal staan zodat hij de boss niet bereikt.|nGif: Een straal geeft je gif. Loop in de lijn van de gegooide bijl om het af te wassen, maar alleen als je gif hebt.|nVloer: Stap uit bloedplassen en ren weg van de stuiterende bijlen.",
	DGN_TIP_AF_ZULJAN_DPS = "DPS: Houd je straalplek het hele ritueel vast. Haal daarna je gif weg in de volgende bijllijn.",
	DGN_TIP_AF_ZULJAN_HEALER = "Healer: Gebruik een grote cooldown tijdens elk ritueel. Let op wie Ritual Venom heeft en zorg dat ze het weghalen voordat het barst.",
	DGN_TIP_AF_ZULJAN_TANK = "Tank: Gebruik een defensive voor {SPELL:1301350}; die raakt je twee keer. Zijn klappen halen ook je gif weg en laten bloedplassen achter, dus leg die aan de rand van de zaal.",
	DGN_TIP_KR_COUNCIL_STEPS = "1. De raad vecht één voor één: Kula, dan Aka'ali, dan Zanazal. Een verslagen raadslid komt af en toe terug voor één ability. Het gevecht is voorbij als Zanazal dood is.|n2. Kula: stap bij haar weg voor {SPELL:266206} en ontwijk de bijlen die daarna rondrollen. {SPELL:266231} laat een willekeurige speler bloeden — gebruik een defensive.|n3. Aka'ali: {SPELL:267494} stormt op één speler af. Iedereen gaat op die speler staan om de schade te delen.|n4. Zanazal: interrupt {SPELL:267273}. Roept hij totems op ({SPELL:267060}), maak dan eerst de Explosive Totem dood, dan de Thundering Totem, dan de Torrent Totem.",
	DGN_TIP_KR_COUNCIL_QUICK_DPS = "Sta in de stack bij de charge, kick het gif, en maak eerst de ontploffende totem dood.",
	DGN_TIP_KR_COUNCIL_QUICK_HEALER = "Heal de bijl-bleed, en zorg dat iedereen vol staat vóór de charge.",
	DGN_TIP_KR_COUNCIL_QUICK_TANK = "Slaat Aka'ali je weg, blijf dan uit haar buurt tot de debuff verdwenen is.",
	DGN_TIP_KR_COUNCIL_QUICK = "Kula: Stap weg van haar draaiaanval en ontwijk de vliegende bijlen.|nAka'ali: Ze stormt op één speler af. Iedereen gaat op die speler staan om de klap te delen.|nZanazal: Kick zijn gifspreuk en maak eerst de ontploffende totem dood.",
	DGN_TIP_KR_COUNCIL_DPS = "DPS: sta in de stack van {SPELL:267494}, blijf {SPELL:267273} kicken, en wissel naar de Explosive Totem zodra hij verschijnt.",
	DGN_TIP_KR_COUNCIL_HEALER = "Healer: heal de bleed van {SPELL:266231} en zet iedereen vol vóór {SPELL:267494}. Bij Zanazal springt {SPELL:1305810} tussen spelers, en Poison Nova tikt op iedereen als hij niet gekickt wordt.",
	DGN_TIP_KR_COUNCIL_TANK = "Tank: {SPELL:266237} slaat je terug en laat je veel meer fysieke schade krijgen. Kite Aka'ali tot de debuff weg is, of gebruik een grote defensive.",
	DGN_TIP_KR_DAZAR_STEPS = "1. Fase 1: Dazar vecht samen met zijn raptor Reban. Maak Reban eerst dood en interrupt zijn {SPELL:269369}, een fear. Reban springt op een speler met {SPELL:269230} en bijt in een kegel — stap eruit.|n2. {SPELL:1303115}: Dazar springt naar twee spelers. Die twee spreiden zodat ze elkaar niet raken.|n3. Op 80% health rijdt Dazar op zijn raptor T'zala. Nu springt {SPELL:1303327} naar vier spelers en raakt ook de hele groep — spreid en sta vol.|n4. {SPELL:1303267} raakt de hele groep en brandt 15 seconden. Direct daarna vallen er speren waar spelers staan — blijf bewegen en ontwijk de Impaling Spear-cirkels.|n5. Op Mythic en Mythic+: {SPELL:1303267} versterkt ook zijn slagen — die sturen een golf goud vooruit. De tank draait hem van de groep af.",
	DGN_TIP_KR_DAZAR_QUICK_DPS = "Maak eerst de kleine raptor dood en kick zijn brul.",
	DGN_TIP_KR_DAZAR_QUICK_HEALER = "Bewaar je grote heals voor de goudklap en de raptorsprongen.",
	DGN_TIP_KR_DAZAR_QUICK_TANK = "Gebruik je grootste defensive voor de zwaardcombo, en houd de koning van de groep af gedraaid.",
	DGN_TIP_KR_DAZAR_QUICK = "Raptor: Maak eerst de kleine raptor dood en kick zijn enge brul.|nRuiter: De koning rijdt op zijn grote raptor. Spreid als hij springt, en zorg dat je vol staat.|nGoud: Een grote vuurklap op iedereen, daarna vallen er speren waar je staat. Blijf bewegen.",
	DGN_TIP_KR_DAZAR_DPS = "DPS: maak Reban eerst dood en kick {SPELL:269369}. Houd ruimte vrij zodat de sprongdoelwitten kunnen spreiden en jij de speren kunt ontwijken.",
	DGN_TIP_KR_DAZAR_HEALER = "Healer: bewaar je grote cooldowns voor {SPELL:1303267} en {SPELL:1303327}. Let op de bleeds van Impaling Spear en {SPELL:1303488}.",
	DGN_TIP_KR_DAZAR_TANK = "Tank: grote defensive voor {SPELL:268586} — de klappen worden sterker naar het eind. Zodra T'zala meedoet, raakt {SPELL:1303488} jou ook en krijg je meer fysieke schade, dus verdeel je cooldowns over beide. Draai Dazar van de groep af.",
	DGN_TIP_KR_MCHIMBA_STEPS = "1. {SPELL:267618}: de boss zuigt één speler leeg. De rest stapt uit de zuurcirkels die hij rondspat. Is het op jou, gebruik dan een defensive. Als het afloopt, blijf je traag en zwak tot je boven 90% health geheald bent.|n2. {SPELL:1311956} kiest een speler en laat brandende grond achter. Leg die aan de rand, weg van de boss en de doodskisten.|n3. {SPELL:1312146} raakt de hele groep en opent kisten: er komen twee Half-Finished Mummies uit. Maak ze dood en interrupt hun Wretched Discharge.|n4. {SPELL:267702}: een speler wordt in een van de kisten opgesloten. Ben jij het, druk dan op de Struggle-knop zodat je kist schudt. De rest: zoek de schuddende kist en klik er snel op. Elke lege kist die hij eerst opent laat een Finished Mummy vrij.",
	DGN_TIP_KR_MCHIMBA_QUICK_DPS = "Kick de mummies en help de schuddende kist zoeken.",
	DGN_TIP_KR_MCHIMBA_QUICK_HEALER = "Heal de leeggezogen speler bijna vol, dan gaat de slow weg.",
	DGN_TIP_KR_MCHIMBA_QUICK_TANK = "Pak de mummies en houd ze naast de boss.",
	DGN_TIP_KR_MCHIMBA_QUICK = "Leegzuigen: Zuigt de boss jou leeg, gebruik dan een defensive. De rest stapt uit de zuurcirkels.|nVuur: Leg je vuurplas aan de rand, weg van de boss en de kisten.|nKist: Een vriend zit opgesloten in een kist. Zoek de kist die schudt en klik er snel op.",
	DGN_TIP_KR_MCHIMBA_DPS = "DPS: kick de Wretched Discharge van de mummies. Ga tijdens {SPELL:267702} naar de kisten en zoek de schuddende — klik niet zomaar ergens op.",
	DGN_TIP_KR_MCHIMBA_HEALER = "Healer: ga meteen naar het doelwit van {SPELL:267618} en heal het daarna boven 90% — dat stopt de slow. Zet de groep vol vóór {SPELL:1312146}. Wretched Discharge is een disease die je kunt dispellen.",
	DGN_TIP_KR_MCHIMBA_TANK = "Tank: pak de mummies op en zet ze bij Mchimba voor cleave. Parkeer ze niet voor een kist.",
	DGN_TIP_KR_SERPENT_STEPS = "1. {SPELL:265773} zet brandend goud op twee spelers. Als het afloopt, laat je een plas {SPELL:265914} achter waar je staat — loop eerst naar de rand en leg hem naast de andere plassen.|n2. {SPELL:265923} wekt de plassen tot Animated Gold dat naar de boss kruipt. Dood, slow of stun ze voordat er één bij hem komt — elke die aankomt geeft hem een schild en meer schade.|n3. {SPELL:1311987}: vijf seconden schade op de hele groep die je ook terugduwt. Sta vol en gebruik een defensive.|n4. Sta nooit in de goudplassen.",
	DGN_TIP_KR_SERPENT_QUICK_DPS = "Maak eerst de goudklodders dood — geen enkele mag bij de boss komen.",
	DGN_TIP_KR_SERPENT_QUICK_HEALER = "Heal de twee spelers met goudbrand, en bewaar een grote heal voor de wind.",
	DGN_TIP_KR_SERPENT_QUICK_TANK = "Gebruik een defensive voor de staartklap, en trek de boss weg van de goudklodders.",
	DGN_TIP_KR_SERPENT_QUICK = "Goud: Als je goudbrand afloopt, laat je een plas achter. Leg die aan de rand, naast de andere plassen.|nAdds: De plassen worden wakker en kruipen naar de boss. Maak ze dood voordat ze hem raken.|nWind: Een harde wind doet iedereen pijn en duwt je terug. Zorg dat je health vol is.",
	DGN_TIP_KR_SERPENT_DPS = "DPS: eerst Animated Gold, dan pas de boss. Gebruik slows, stuns en cleave, en houd alle plassen bij elkaar zodat de adds in één kluitje ontwaken.",
	DGN_TIP_KR_SERPENT_HEALER = "Healer: heal de twee doelwitten van {SPELL:265773} door het branden heen. Gebruik een healing cooldown voor {SPELL:1311987}.",
	DGN_TIP_KR_SERPENT_TANK = "Tank: defensive voor {SPELL:265910}. Als het Animated Gold ontwaakt, trek de boss er dan van weg zodat de DPS meer tijd hebben.",
	DGN_TIP_RL_KOKIA_STEPS = "1. Molten Boulder ({SPELL:372110}): Kokia gooit een brandend rotsblok dat in een rechte lijn rolt en dan ontploft. Stap uit zijn pad en blijf weg bij de plek waar hij stopt. Wie hij raakt, wordt weggeslagen.|n2. Ritual of Blazebinding ({SPELL:372864}): een vuur-add, de Blazebound Firestorm, verschijnt bij een speler en verbrandt iedereen binnen 12 yards. Is hij op jou, stap dan weg van de groep maar blijf dicht bij de boss.|n3. Iedereen wisselt meteen naar de Blazebound Firestorm en interrupt zijn Blaze Volley.|n4. Ga voordat de add doodgaat minstens 20 yards van hem vandaan. Zijn doodsknal (Burnout) raakt heel hard.|n5. Op Mythic en Mythic+: brandende grond ({SPELL:372820}) blijft op de vloer liggen. Stap eruit, en verplaats het gevecht langzaam door de zaal zodat er altijd vrije ruimte is.",
	DGN_TIP_RL_KOKIA_QUICK_DPS = "Sla eerst de vuur-add, kick zijn spells, en ren weg voordat hij doodgaat.",
	DGN_TIP_RL_KOKIA_QUICK_HEALER = "De vuur-add verbrandt iedereen en de tank bloedt, dus heal hard en blijf weg als hij doodgaat.",
	DGN_TIP_RL_KOKIA_QUICK_TANK = "Gebruik een defensive voor elke klappencombo en loop de boss langzaam rond door de zaal.",
	DGN_TIP_RL_KOKIA_QUICK = "Rotsblok: Een vuurrotsblok rolt in een rechte lijn, dus stap opzij.|nVuur-add: Verschijnt er een vuurmonster, dan slaat iedereen erop en stopt zijn spells.|nAdd dood: Ren ver van hem weg voordat hij doodgaat, want hij ontploft.",
	DGN_TIP_RL_KOKIA_DPS = "DPS: wissel naar de Blazebound Firestorm zodra hij spawnt en kick zijn Blaze Volley. Melee: ren 20 yards weg voordat hij doodgaat.",
	DGN_TIP_RL_KOKIA_HEALER = "Healer: de Inferno-cast van de add verbrandt de hele groep, en Searing Blows laat een bleed op de tank achter. Blijf zelf uit de doodsknal van de add.",
	DGN_TIP_RL_KOKIA_TANK = "Tank: defensive voor elke Searing Blows ({SPELL:372858}): vier snelle klappen die een bleed stapelen. Houd Kokia bij de add zodat de DPS kunnen cleaven, maar loop uit zijn doodsknal van 20 yards. Verplaats haar langzaam door de zaal om ruimte vrij te houden.",
	DGN_TIP_RL_KYRAKKA_STEPS = "1. Erkhart vecht op de grond terwijl zijn draak Kyrakka rond het platform vliegt. Sla Kyrakka zodra ze binnen bereik is: zij moet als eerste dood. Ontwijk haar vuurkegel ({SPELL:381525}).|n2. Inferno Spit ({SPELL:381602}): 2 spelers branden 6 seconden, ontploffen dan en laten vuur op de vloer achter ({SPELL:384773}). Ben jij het, loop dan vóór het afloopt naar de rand, weg van de groep.|n3. Winds of Change ({SPELL:381517}): wind duwt spelers en het vuur, in een vaste volgorde (noordwest, zuidwest, zuidoost, noordoost). Loop ertegenin en laat je niet in het vuur blazen. Leg je vuur zo neer dat de wind het van de groep wegblaast.|n4. Zakt een van beiden naar zo'n 40 tot 50% health (gidsen verschillen), dan landt Kyrakka en rijdt Erkhart op haar. Nu krijgen 3 spelers Inferno Spit. Bewaar cooldowns voor dit deel.|n5. Op Mythic en Mythic+: Interrupting Cloudburst ({SPELL:381516}) raakt iedereen en blokkeert je spells 2 seconden. Stop met casten net voordat hij landt.",
	DGN_TIP_RL_KYRAKKA_QUICK_DPS = "Sla eerst de draak, en stop op Mythic met casten net voordat de storm iedereen raakt.",
	DGN_TIP_RL_KYRAKKA_QUICK_HEALER = "Haal de debuff van de tank weg na elke grote klap en heal de brandende spelers.",
	DGN_TIP_RL_KYRAKKA_QUICK_TANK = "Gebruik een defensive voor zijn grote klap, en vraag de healer de debuff weg te halen.",
	DGN_TIP_RL_KYRAKKA_QUICK = "Draak: Sla de draak wanneer je haar kunt bereiken, en ontwijk haar vuuradem.|nVuur: Brand je, loop dan naar de rand zodat je vuur weg van de groep landt.|nWind: De wind duwt jou en het vuur, dus loop ertegenin en blijf uit de vlammen.",
	DGN_TIP_RL_KYRAKKA_DPS = "DPS: sla Kyrakka wanneer je haar kunt bereiken en bewaar burst voor als ze landt. Op Mythic en Mythic+ stoppen casters met casten vóór Interrupting Cloudburst.",
	DGN_TIP_RL_KYRAKKA_HEALER = "Healer: dispel Stormslam van de tank na elke klap, vóór de volgende. Doelwitten van Inferno Spit krijgen zware schade, dus heal ze op. Stop op Mythic en Mythic+ met casten vóór Interrupting Cloudburst.",
	DGN_TIP_RL_KYRAKKA_TANK = "Tank: defensive voor elke Stormslam ({SPELL:381512}). Die laat een stapelende magic-debuff achter waardoor je meer Nature-schade krijgt, dus vraag om een dispel. Haal Erkhart na elke wind snel uit het vuur.",
	DGN_TIP_RL_MELIDRUSSA_STEPS = "1. Hailburst ({SPELL:1307297}): ze raakt de hele groep en gooit een ijsmijn naar elke speler. Sta samen bij één rand zodat de mijnen op één plek landen. Raak nooit een mijn aan: die gooit je omhoog en maakt je aanvallen en spells 20 seconden lang half zo snel.|n2. Chillstorm ({SPELL:1307308}): een vorststorm landt op een speler en trekt iedereen naar het midden. Is hij op jou, ren dan weg van de groep. Blijf uit het midden ({SPELL:372963}): vorstschade is daar dubbel. Na 7 seconden ontploft hij en duwt iedereen weg, dus sta niet met mijnen achter je.|n3. Op 66% en 33% health roept ze Infused Whelps op ({SPELL:373046}). Maak ze snel dood.|n4. Interrupt Frigid Shard, de spell die ze op de tank cast.|n5. Op Mythic en Mythic+: na de whelps verstopt ze zich in een ijsschild (Ice Bulwark) en pulseert ze steeds zwaardere vorstschade op iedereen (Frost Overload). Breek het schild snel en interrupt haar dan. Gidsen zeggen dat de kick werkt zodra het schild weg is.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_DPS = "Maak eerst de babydraakjes dood, en breek op Mythic haar ijsschild.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_HEALER = "Heal de hele groep door de ijsknallen en de storm heen.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_TANK = "Pak de babydraakjes meteen en kick de spell die ze op jou cast.",
	DGN_TIP_RL_MELIDRUSSA_QUICK = "Mijnen: Sta samen bij één rand als ze ijs gooit, en raak de mijnen nooit aan.|nStorm: Is de storm op jou, ren dan weg van iedereen en blijf uit het midden.|nDraakjes: Maak de babydraakjes snel dood, en breek op Mythic ook haar ijsschild.",
	DGN_TIP_RL_MELIDRUSSA_DPS = "DPS: wissel naar de whelps zodra ze spawnen. Bewaar op Mythic en Mythic+ je burst om het ijsschild te breken, en kick daarna Frost Overload.",
	DGN_TIP_RL_MELIDRUSSA_HEALER = "Healer: Hailburst en Chillstorm raken de hele groep, en de storm ontploft aan het eind. Zet iedereen vol vóór de knal. Op Mythic en Mythic+ geeft de schildfase steeds zwaardere vorstschade op iedereen, tot het schild breekt.",
	DGN_TIP_RL_MELIDRUSSA_TANK = "Tank: pak de Infused Whelps meteen op en houd ze bij de boss voor cleave. Hun klappen stapelen Cold Claws op je; te veel stacks bevriezen je, dus ze moeten snel dood. Kick Frigid Shard als niemand anders het doet.",
	DGN_TIP_TS_ADDERIS_STEPS = "1. Storm Blessed schermt een van de twee bosses af, en die boss krijgt bijna geen schade. Sla degene ZONDER schild (Adderis bij de pull) en wissel zodra het schild verspringt.|n2. {SPELL:1311805}: ben je gemarkeerd, loop dan naar de rand en leg je plas daar. De plassen silencen je, dus blijf eruit.|n3. {SPELL:1289059}: iedereen wordt teruggeslagen. Spreid een beetje en ga zo staan dat de duw je niet in een plas gooit.|n4. {SPELL:1288049} komt direct na de knockback: ren terug en stack op de boss om de klap te delen, loop daarna samen weg vóór de tweede blast.",
	DGN_TIP_TS_ADDERIS_QUICK_DPS = "Sla alleen de boss zonder schild, en wissel snel als het verspringt.",
	DGN_TIP_TS_ADDERIS_QUICK_HEALER = "Heal de spelers die door wind geraakt worden, en zet iedereen vol vóór de duw.",
	DGN_TIP_TS_ADDERIS_QUICK_TANK = "Gebruik een defensive voor Overload, en houd beide bosses dicht bij elkaar.",
	DGN_TIP_TS_ADDERIS_QUICK = "Schild: Sla de boss zonder schild, en wissel als het schild verspringt.|nPlassen: Ben je gemarkeerd, leg je plas dan aan de rand en blijf uit de plassen.|nDuw: Ren na de duw terug en ga samen op de boss staan om de klap te delen.",
	DGN_TIP_TS_ADDERIS_DPS = "DPS: sla nooit de afgeschermde boss — die krijgt bijna geen schade. Wissel zodra het schild verspringt, ook midden in je rotatie.",
	DGN_TIP_TS_ADDERIS_HEALER = "Healer: spot-heal de spelers die door Gust geraakt worden. De knockback die direct overgaat in de groepssoak is het gevaarlijkste moment — zorg dat iedereen dan al vol staat.",
	DGN_TIP_TS_ADDERIS_TANK = "Tank: defensive voor {SPELL:1311804}. Houd beide bosses dicht bij elkaar zodat de groep kan wisselen zonder door plassen te lopen.",
	DGN_TIP_TS_AVATAR_STEPS = "1. Je wint door de Avatar vol te healen, niet door haar te doden. Maak eerst de Essence Defilers dood: hun {SPELL:1301202} stopt alle healing op haar.|n2. Maak de Corrupted Guardian dood. Hij laat drie Corrupted Lifeforce-orbs achter: drie verschillende DPS pakken er snel elk één. Een gepakte orb healt de Avatar; een gemiste orb ontploft op de hele groep.|n3. Twisted Hexxers: interrupt Flame Shock. {SPELL:1311981} op jou? Loop weg van de groep voordat het afloopt, en laat de zone daar achter.|n4. Zijn de Defilers dood, heal dan de Avatar. Faithless Tormentors spawnen en jagen op de healer: stun en slow ze en breng ze onder 25% health — de Avatar eet ze dan op en healt zichzelf.",
	DGN_TIP_TS_AVATAR_QUICK_DPS = "Maak eerst de Defilers dood, pak daarna elk één orb.",
	DGN_TIP_TS_AVATAR_QUICK_HEALER = "Heal de Avatar zodra de Defilers dood zijn, en blijf wegrennen voor de jagers.",
	DGN_TIP_TS_AVATAR_QUICK_TANK = "Houd de grote add in een hoek, en blijf weg van de orbs.",
	DGN_TIP_TS_AVATAR_QUICK = "Doel: Maak eerst de Defilers dood, heal dan de Avatar vol om te winnen.|nOrbs: Gaat de grote add dood, dan pakken drie DPS snel elk één orb.|nJagers: Stun de adds die op de healer jagen en sla ze laag; de Avatar eet ze dan op.",
	DGN_TIP_TS_AVATAR_DPS = "DPS: maak eerst de Essence Defilers dood, dan de Guardian. Pak elk één orb (die geeft je {SPELL:1300877}, dus gebruik een defensive), kick Flame Shock, en stun en AoE de Tormentors neer.",
	DGN_TIP_TS_AVATAR_HEALER = "Healer: heal de Avatar zodra de Defilers dood zijn — zo win je het gevecht. Tormentors rennen op je af en elke klap verlaagt je healing, dus blijf bewegen. Laat de orbs aan de DPS over.",
	DGN_TIP_TS_AVATAR_TANK = "Tank: houd de Corrupted Guardian in een hoek, weg van de groep, en gebruik een defensive voor Tainted Strike. Pak geen orbs: door {SPELL:1300877} krijg je veel meer fysieke schade.",
	DGN_TIP_TS_GALVAZZT_STEPS = "1. {SPELL:1291618}: drie torens schieten stralen naar Galvazzt. Ga in een straal staan, tussen de toren en de boss, zodat hij geen energie krijgt.|n2. Verdeel de stralen: één speler per straal, en wissel af tussen de rondes. Een straal blokkeren geeft je {SPELL:266923}: schade over tijd en meer fysieke schade.|n3. Laat nooit een straal open. Op volle energie cast hij Consume Charge, dat de groep hard raakt en vaak een wipe wordt.|n4. {SPELL:1309525}: schade op de hele groep, en het laat een {SPELL:1291815} achter op de grond. Stap eruit.",
	DGN_TIP_TS_GALVAZZT_QUICK_DPS = "Blijf in je straal, ook als je de boss van daar niet kunt raken.",
	DGN_TIP_TS_GALVAZZT_QUICK_HEALER = "Houd de spelers in de stralen in leven.",
	DGN_TIP_TS_GALVAZZT_QUICK_TANK = "Blijf uit de stralen, en verplaats de boss weg van de zones op de grond.",
	DGN_TIP_TS_GALVAZZT_QUICK = "Stralen: Ga in een straal staan, tussen de toren en de boss, zodat hij niet oplaadt.|nBeurten: Eén speler per straal, wissel af, en laat nooit een straal open.|nVloer: Stap na de grote groepsklap uit de zone op de grond.",
	DGN_TIP_TS_GALVAZZT_DPS = "DPS: je straal gaat vóór je schade — stap er niet uit om de boss te raken. Wissel af met de anderen en gebruik een defensive als je aan de beurt bent.",
	DGN_TIP_TS_GALVAZZT_HEALER = "Healer: de straal-soakers krijgen gestage schade — houd ze hoog, en neem zelf een straal als dat nodig is. Heb een cooldown klaar voor {SPELL:1309525}.",
	DGN_TIP_TS_GALVAZZT_TANK = "Tank: soak de stralen niet — door {SPELL:266923} krijg je veel meer fysieke schade. Verplaats de boss weg van elke {SPELL:1291815}, naar een plek waar de stralen makkelijk bereikbaar blijven.",
	DGN_TIP_TS_MEREKTHA_STEPS = "1. {SPELL:1290029}: slangen binden een paar spelers vast. Ben je gemarkeerd, ga dan dicht bij de anderen bij de boss staan, zodat één AoE-stun of crowd control alle knopen breekt. Maak daarna de slangen dood.|n2. {SPELL:1289109}: ben je gemarkeerd, loop dan naar de rand van de zaal en leg de plas daar, niet in het midden.|n3. {SPELL:1293048}: schade op de hele groep plus een knockback. Sta niet waar de duw je in een plas gooit.|n4. {SPELL:1289205} en {SPELL:264172}: er komen adds uit eieren, daarna gaat ze onder de grond en kun je haar niet raken. Ontwijk haar pad (dat stunt je), interrupt Poison Spit van de Toxic Vipers, en maak alle adds dood — dan komt ze weer boven.",
	DGN_TIP_TS_MEREKTHA_QUICK_DPS = "Gaat ze onder de grond, maak dan snel alle adds dood; dan komt ze terug.",
	DGN_TIP_TS_MEREKTHA_QUICK_HEALER = "Bewaar een cooldown voor de storm die iedereen raakt.",
	DGN_TIP_TS_MEREKTHA_QUICK_TANK = "Gebruik een defensive voor haar grote beet, en pak de adds als ze onder de grond gaat.",
	DGN_TIP_TS_MEREKTHA_QUICK = "Slangen: Binden slangen je vast, ga dan dicht bij de anderen staan zodat één stun iedereen bevrijdt.|nSpuug: Ben je gemarkeerd, leg je plas dan aan de rand van de zaal.|nOndergronds: Ze verstopt zich onder de grond. Ontwijk haar pad en maak alle adds dood om haar terug te halen.",
	DGN_TIP_TS_MEREKTHA_DPS = "DPS: bevrijd eerst vastgebonden spelers met een stun of AoE crowd control. Maak tijdens Burrow elke add snel dood — de fase stopt als ze allemaal dood zijn — en kick Poison Spit.",
	DGN_TIP_TS_MEREKTHA_HEALER = "Healer: {SPELL:1293048} raakt de hele groep — plan er een cooldown voor. Komt er een Poison Spit door, dispel dan het gif als je dat kunt.",
	DGN_TIP_TS_MEREKTHA_TANK = "Tank: defensive voor elke {SPELL:1290797}. Pak tijdens Burrow de adds op en parkeer de Storm Serpent aan de rand, want die laat ook plassen achter.",
})

-- Fase 6 (12 jun): deDE/frFR/esES/ptBR — mens-kwaliteit, game-termen en
-- eigennamen in het Engels (proper-names-policy); spellnamen lokaliseren
-- zichzelf via de {SPELL:id}-tokens.
merge(ns._mhLocales and ns._mhLocales.deDE, {
	-- Windrunner Spire ----------------------------------------------------------
	DGN_TIP_WS_DUO_STEPS = "1. Zwei Bosse — mache ihnen gleichmäßig Schaden, damit sie etwa gleichzeitig sterben.|n2. Unterbrich Shadow Bolt; tritt aus den Spuckkreisen ({SPELL:472745}) — verschwende keinen Bodenplatz.|n3. Verflucht ({SPELL:474105})? Schnell bannen lassen — oder die Dark Entity, die daraus spawnt, mit CC belegen, bis sie verschwindet.|n4. Von {SPELL:472793} während des Schreis gehakt? Stell dich so, dass du DURCH die Geisterdame gezogen wirst — das bricht ihren Zauber.",
	DGN_TIP_WS_DUO_TANK = "Tank: Defensive für {SPELL:472888}; verschiebe die Bosse, wenn der Boden zu voll wird.",
	DGN_TIP_WS_DUO_HEALER = "Heiler: viel Gruppenschaden während {SPELL:472736}; banne {SPELL:474105} schnell.",

	DGN_TIP_WS_EMBER_STEPS = "1. Feuer = schlecht. Lege die Feuerpfützen ({SPELL:466556}) an die Ränder, halte die Mitte sauber.|n2. Bei voller Energie: lauf ZUM Boss für {SPELL:465904} und weiche danach jedem Fire Breath aus.|n3. Alte Pfützen spawnen Feuerhosen — bleib in Bewegung.",
	DGN_TIP_WS_EMBER_TANK = "Tank: Defensive für {SPELL:466064}.",
	DGN_TIP_WS_EMBER_HEALER = "Heiler: schwerer Gruppenschaden während {SPELL:465904}.",

	DGN_TIP_WS_KROLUK_STEPS = "1. Braune Kreise = schlecht, raus da.|n2. Stell dich zu einem Mitspieler, bevor {SPELL:1253026} abläuft (überlappe die lila Kreise).|n3. Fixiert oder Sprungziel ({SPELL:1283247})? Lauf damit WEG von der Gruppe.|n4. Spawnen Adds (etwa bei zwei Dritteln und einem Drittel Leben): schnell töten — den Phantasmal Mystic zuerst, und unterbrich ihn weiter.",
	DGN_TIP_WS_KROLUK_TANK = "Tank: Defensive für {SPELL:467620}; sei bereit, den zweiten {SPELL:1283247} aufzufangen.",
	DGN_TIP_WS_KROLUK_HEALER = "Heiler: Gruppenschaden während {SPELL:472043}.",

	DGN_TIP_WS_HEART_STEPS = "1. Ticken die {SPELL:1216042}-Stapel auf dir? Tritt bei 2-3 Stapeln auf einen Windpfeil (Turbulent Arrow) — er entfernt den DoT und springt dich über die wachsende Schockwelle.|n2. Halte einen Pfeil für den großen Knall bei voller Energie frei ({SPELL:468429}).|n3. Verteilt euch leicht für {SPELL:1253979} und nutzt die großen Kreise, um den elektrischen Boden zu räumen.|n4. Ziel von {SPELL:474528}? Bleib stehen und lass die anderen wegtreten; alle anderen: raus aus dem Frontalkegel.",
	DGN_TIP_WS_HEART_TANK = "Tank: Defensive für {SPELL:472662}; richte den Rückstoß WEG von den Pfützen.",
	DGN_TIP_WS_HEART_HEALER = "Heiler: Spieler mit hohen {SPELL:1216042}-Stapeln zuerst hochheilen; extra Heilung nach {SPELL:1253979}.",

	-- Maisara Caverns ------------------------------------------------------------
	DGN_TIP_MC_MUROJIN_STEPS = "1. Zwei Bosse (Jäger und Vogel) — töte sie dicht beieinander, sonst geht der Überlebende in Berserkerwut.|n2. Eisfallen ({SPELL:1243741}), grüne Kreise ({SPELL:1243900}) und der frontale {SPELL:1260643} = schlecht, bleib raus.|n3. Ziel von {SPELL:1249478} (dem Sturzflug)? Lauf IN eine Eisfalle — das Einfrieren stoppt den Sturzflug. Alle anderen: weg von diesem Spieler.",
	DGN_TIP_MC_MUROJIN_TANK = "Tank: Defensive für {SPELL:1266480}.",
	DGN_TIP_MC_MUROJIN_HEALER = "Heiler: banne {SPELL:1246666} (Krankheit) — schwerer Gruppenschaden.",

	DGN_TIP_MC_VORDAZA_STEPS = "1. Der Boss spawnt Unstable Phantoms ({SPELL:1251204}), die Spieler jagen. TÖTE sie, bevor sie jemanden erreichen — ein Phantom, das sein Ziel erreicht (oder ein anderes Phantom berührt), explodiert mit schwerem Schaden in der Nähe.|n2. Jedes getötete Phantom schreit: unvermeidbarer Gruppenschaden — töte sie also EINZELN.|n3. Weiche der Frontalwelle von {SPELL:1252054} aus (sie stößt dich weg), den schwebenden Orbs und Soulrot.|n4. Steckt jemand in einem Deathshroud? Schlag ihn schnell frei; unterbrich {SPELL:1250708} und weiche währenddessen den Swirls aus.",
	DGN_TIP_MC_VORDAZA_TANK = "Tank: Defensive für {SPELL:1251554}.",
	DGN_TIP_MC_VORDAZA_HEALER = "Heiler: jedes getötete Phantom schreit ({SPELL:1251813}) = Gruppenschaden — heile zwischen den gestaffelten Kills.",

	DGN_TIP_MC_RAKTUL_STEPS = "1. Der Boss springt auf drei Spieler ({SPELL:1252676}) und hinterlässt Soulbind Totems — verteilt euch, damit die Totems getrennt landen, werdet nicht zerquetscht, und zerstört die Totems schnell.|n2. Bleib aus dem Chill-of-Death-Boden.|n3. Seelenphase ({SPELL:1253788}): du wirst aus deinem Körper gezogen — CC und unterbrich die großen Adds, während du zu deinem Körper zurückläufst.|n4. Weiche den Swirls des Deathgorged Vessel aus.",
	DGN_TIP_MC_RAKTUL_TANK = "Tank: Defensive für {SPELL:1251023}; lege die Pfützen WEG von der Gruppe.",
	DGN_TIP_MC_RAKTUL_HEALER = "Heiler: schwerer Gruppenschaden während Deathgorged Vessel und wenn Totems zerbrechen.",

	-- Murder Row -----------------------------------------------------------------
	DGN_TIP_MR_KYSTIA_STEPS = "1. Töte zuerst Nibbles. Kystia hat einen Fel-Schild und erleidet fast keinen Schaden, solange Nibbles über 20% Leben hat.|n2. Bei 20% wendet sich Nibbles mit {SPELL:1230304} gegen Kystia: Kystia ist betäubt und erleidet kurz viel mehr Schaden. Wechsle jetzt auf Kystia und nutze deine großen Cooldowns.|n3. {SPELL:1264095}: Kopien von Kystia erscheinen und wirken Felstorm. Unterbrich, stunne oder kontrolliere jede Kopie.|n4. Bleib aus Nibbles' {SPELL:1253811}-Kegel und aus dem Feuer, das er am Boden hinterlässt.|n5. Auf Heroisch und höher: {SPELL:474240} - sie springt zu einem Spieler und explodiert. Geh von ihr weg.",
	DGN_TIP_MR_KYSTIA_QUICK_DPS = "Schlag zuerst das Pet, dann den Boss, wenn das Pet wenig Leben hat.",
	DGN_TIP_MR_KYSTIA_QUICK_HEALER = "Nimm den Spuck-Debuff schnell von den Spielern und heb eine große Heilung für den Wechsel auf.",
	DGN_TIP_MR_KYSTIA_QUICK_TANK = "Dreh den Feuerkegel des Pets von der Gruppe weg.",
	DGN_TIP_MR_KYSTIA_QUICK = "Pet zuerst: Schlag zuerst das Pet Nibbles. Der Boss hat einen Schild und erleidet fast keinen Schaden.|nWechsel: Wenn Nibbles wenig Leben hat, betäubt sie den Boss. Jetzt schlägst du den Boss hart.|nKopien: Kopien des Bosses erscheinen. Kicke oder stunne jede einzelne.",
	DGN_TIP_MR_KYSTIA_TANK = "Tank: Dreh Nibbles' {SPELL:1253811}-Kegel von der Gruppe weg. Halte Kystia und Nibbles nah beieinander, damit deine Gruppe beide mit Cleave treffen kann. Kystias Chaos Barrage trifft dich hart, halte also eine Defensive bereit.",
	DGN_TIP_MR_KYSTIA_HEALER = "Heiler: Banne Corroding Spittle (Magie) schnell, vor allem während {SPELL:1264095}. Heb einen Heil-Cooldown für das Burn-Fenster nach {SPELL:1230304} auf: Die betäubte Kystia schickt Fel-Explosionen auf die Gruppe.",

	DGN_TIP_MR_ZAEN_STEPS = "1. Kisten fallen auf Spieler ({SPELL:474765}). Tritt aus den Markierungen. Die gelandeten Kisten sind deine Deckung.|n2. {SPELL:1218347}: Er zielt auf jeden, den er sehen kann. Versteck dich hinter einer Kiste, bevor er schießt, damit er dich nicht sieht. Jeder braucht seine eigene Kiste.|n3. Hast du {SPELL:1214357}? Die Bombe explodiert nach 6 Sekunden und zerstört Kisten in deiner Nähe. Trag sie weg von den Kisten, die ihr als Deckung braucht.|n4. {SPELL:474478}: 3 Sekunden schwerer Schaden auf die ganze Gruppe. Sei auf vollem Leben.|n5. Auf Mythisch und Mythic+: Grüne Fel-Kisten (Fel-Infused Freight) schaden der ganzen Gruppe die ganze Zeit. Hast du {SPELL:1214357}, bring es zu einer grünen Kiste, um sie zu zerstören, und lass die normalen Kisten stehen.",
	DGN_TIP_MR_ZAEN_QUICK_DPS = "Steh vor dem großen Schuss hinter einer Kiste, nicht danach.",
	DGN_TIP_MR_ZAEN_QUICK_HEALER = "Nimm dem Tank das Gift ab und sorg dafür, dass alle vor dem Beschuss voll sind.",
	DGN_TIP_MR_ZAEN_QUICK_TANK = "Nutze eine Defensive, wenn er dich sticht, und lass das Gift entfernen.",
	DGN_TIP_MR_ZAEN_QUICK = "Kisten: Kisten fallen vom Himmel. Tritt raus und nutze sie dann als Wände.|nSchuss: Wenn er auf alle zielt, versteck dich hinter einer Kiste, damit er dich nicht sieht.|nBombe: Hast du die Bombe? Trag sie weg von den Kisten, hinter denen ihr euch versteckt.",
	DGN_TIP_MR_ZAEN_TANK = "Tank: Nutze eine Defensive für {SPELL:1222795}. Es hinterlässt auch Heartstop Poison, das dein maximales Leben senkt: Lass es bannen oder entferne es selbst.",
	DGN_TIP_MR_ZAEN_HEALER = "Heiler: Banne Heartstop Poison vom Tank nach {SPELL:1222795}. Heile alle vor {SPELL:474478} voll und heile die Blutung bei jedem, den der Schuss getroffen hat.",

	DGN_TIP_MR_XATHUUX_STEPS = "1. {SPELL:1214637}: Er wirft seine Axt auf einen Spieler. Bist du es, stell dich nah an den Boss, aber weg von den anderen. Die Axt bleibt liegen und schockt alle immer stärker: Zerstöre sie schnell.|n2. Infernal Crush ({SPELL:1295452}): Kreise erscheinen unter Spielern. Verteilt euch, damit ihr euch nicht gegenseitig trefft.|n3. {SPELL:474197}: Schaden auf alle, dann greift er 15 Sekunden lang schneller an und erleidet 30% mehr Schaden. Nutze jetzt deine Cooldowns.|n4. Während der Wut hinterlässt er Feuer, wo er läuft ({SPELL:474234}). Bleib raus. Der Tank führt ihn langsam am Rand des Raums entlang.",
	DGN_TIP_MR_XATHUUX_QUICK_DPS = "Zerstöre zuerst die Axt und heb deine großen Angriffe für die Wut auf.",
	DGN_TIP_MR_XATHUUX_QUICK_HEALER = "Plane eine große Heilung für die Wut ein und heile den Tank vor dem großen Schlag voll.",
	DGN_TIP_MR_XATHUUX_QUICK_TANK = "Nutze eine Defensive für seinen großen Schlag und führ ihn langsam am Rand entlang, wenn er wütet.",
	DGN_TIP_MR_XATHUUX_QUICK = "Axt: Er wirft seine Axt. Leg sie neben den Boss und zerstöre sie schnell.|nKreise: Verteilt euch, wenn Kreise unter euch erscheinen.|nWut: Wenn er wütend wird, erleidet er mehr Schaden. Schlag hart zu und bleib aus seiner Feuerspur.",
	DGN_TIP_MR_XATHUUX_TANK = "Tank: Nutze eine Defensive für {SPELL:473898}; es senkt 8 Sekunden lang die Heilung, die du erhältst. Dreh ihn von der Gruppe weg und stell ihn auf die Axt, damit sie mit Cleave getroffen wird. Während {SPELL:474197} führst du ihn langsam am Rand entlang, damit das Feuer aus der Mitte bleibt.",
	DGN_TIP_MR_XATHUUX_HEALER = "Heiler: {SPELL:474197} und Infernal Crush kommen oft kurz nacheinander, plane also einen Cooldown ein. Der Tank bekommt nach {SPELL:473898} viel weniger Heilung; heile ihn vorher voll. Jede Sekunde, die die Axt lebt, erleidet die Gruppe mehr Schaden.",

	DGN_TIP_MR_LITHIEL_STEPS = "1. Unterbrich jeden Chaos Bolt. Sprecht eine Kick-Reihenfolge ab.|n2. {SPELL:1218203}: Kreise landen auf Spielern. Verteilt euch 6 Meter. Jeder Kreis erschafft Wild Imps: Stunnt oder kickt sie und tötet sie gemeinsam.|n3. {SPELL:474408}: Ein großer Dämon erscheint. Der Tank nimmt ihn auf, alle töten ihn.|n4. {SPELL:1224478}: Eine Welle aus Fel-Feuer rollt durch den Raum. Töte alle Dämonen, bevor sie sie erreicht, sonst werden sie viel schneller. Nimm das Demonic Gateway, damit die Welle dich verfehlt; trifft sie dich, erleidest du mehr Feuerschaden.|n5. Auf Mythisch und Mythic+: Ein Infernal jagt den Tank. Er kann nicht getötet werden und eine Berührung kann dich töten. Der Tank hält ihn von der Gruppe und dem Gateway fern.",
	DGN_TIP_MR_LITHIEL_QUICK_DPS = "Kicke den Boss und die Imps und töte alle Dämonen vor der Welle.",
	DGN_TIP_MR_LITHIEL_QUICK_HEALER = "Alle erleiden den ganzen Kampf Feuerschaden. Heile zuerst jeden, den die Welle getroffen hat.",
	DGN_TIP_MR_LITHIEL_QUICK_TANK = "Schnapp dir die Dämonen schnell. Auf Mythisch führst du den Infernal von allen weg.",
	DGN_TIP_MR_LITHIEL_QUICK = "Kicks: Stoppe jeden Chaos Bolt, den der Boss wirkt.|nImps: Verteilt euch. Kleine Dämonen springen heraus. Stunne sie und töte sie schnell.|nWelle: Töte alle Dämonen vor der Feuerwelle und nimm dann das Portal, damit sie dich verfehlt.",
	DGN_TIP_MR_LITHIEL_TANK = "Tank: Nimm den Vilefiend schnell auf, er trifft dich hart. Halte die Wild Imps zusammen, damit sie mit Cleave getroffen werden. Auf Mythisch kitest du den Infernal weg von der Gruppe und nie in die Nähe des Gateways.",
	DGN_TIP_MR_LITHIEL_HEALER = "Heiler: Im ganzen Kampf gibt es ständigen Feuerschaden auf der Gruppe. Wer von {SPELL:1224478} getroffen wird, brennt weiter und erleidet mehr Feuerschaden: Heile diese Spieler zuerst.",

	-- Den of Nalorakk -----------------------------------------------------------
	DGN_TIP_DN_HOARDMONGER_STEPS = "1. {SPELL:1234233}: Er wirft ein paar Sekunden lang verdorbenes Essen. Weiche den Einschlägen aus. Danach wachsen grüne Rotten Mushrooms auf dem Boden.|n2. Tritt auf jeden Pilz, bevor er platzt (etwa 12 Sekunden). Verteilt euch, damit keiner übersehen wird. Jeder Pilz gibt dir ein Gift, also wechselt euch ab.|n3. {SPELL:1253268} ist ein Frontalkegel. Tritt aus dem angezeigten Bereich. {SPELL:1235118} trifft die ganze Gruppe, also bleib voll.|n4. Dreimal läuft er zu einem Haufen aus Fleisch, Knochen oder Pilzen und bekommt eine neue Fähigkeit. Fleisch macht sein Brüllen stärker. Knochen geben einen Schlag, der zerbrochene Knochen am Boden hinterlässt ({SPELL:1235405}): Bleib davon runter. Pilze bedeuten mehr Pilze zum Drauftreten.|n5. Auf Mythisch und Mythic+: Jede neue Fähigkeit bleibt für den Rest des Kampfes, sie addieren sich also. Guides nehmen zuerst Fleisch, dann Knochen, zuletzt Pilze.",
	DGN_TIP_DN_HOARDMONGER_QUICK_DPS = "Hilf beim Treten auf die Pilze und wechsle dich mit den anderen ab.",
	DGN_TIP_DN_HOARDMONGER_QUICK_HEALER = "Heile groß, wenn er brüllt, und nimm den Pilz-Soakern das Gift ab, wenn du kannst.",
	DGN_TIP_DN_HOARDMONGER_QUICK_TANK = "Park den Boss neben dem Haufen, den du willst: Fleisch, dann Knochen, dann Pilze.",
	DGN_TIP_DN_HOARDMONGER_QUICK = "Pilze: Tritt auf die grünen Pilze, bevor sie platzen, und wechselt euch ab.|nSchlag: Der Boss schlägt vor sich auf den Boden. Tritt aus diesem Bereich.|nHaufen: Er holt sich Essen von einem Haufen und lernt einen neuen Trick. Bleib von den Knochen weg, die er hinterlässt.",
	DGN_TIP_DN_HOARDMONGER_TANK = "Tank: Er läuft zum nächsten Haufen, also park ihn neben dem, den du willst: zuerst Fleisch, dann Knochen, zuletzt Pilze. Halte die Knochenflecken weg von dort, wo die Gruppe steht.",
	DGN_TIP_DN_HOARDMONGER_HEALER = "Heiler: Nutze einen Heil-Cooldown für {SPELL:1235118}: Es ignoriert Rüstung und trifft alle. Pilz-Soaker bekommen ein Gift (Toxic Spores): Banne es, wenn deine Klasse das kann, und halte sie voll.",

	DGN_TIP_DN_SENTINEL_STEPS = "1. {SPELL:1235623}: Kleine Tornados landen und wandern lange durch den Raum. Steht zusammen, damit sie an einer Stelle landen, und geht dann von ihnen weg.|n2. {SPELL:1235783}: Zwei Eiszapfen stürzen herab. Tritt aus den Kreisen. Aus jedem entsteht ein Add: Fractured Shivercore.|n3. Die Adds wirken Winter's Shroud. Unterbrich es: Jeder Zauber lässt die ganze Gruppe mehr Frostschaden erleiden. Ein totes Add hinterlässt einen Snowdrift: tiefen Schnee, der dich verlangsamt, aber nichts kann dich bewegen, solange du darin stehst.|n4. {SPELL:1235656}: Ein großer Sturm trifft alle und schiebt Spieler herum. Töte ein Add kurz davor und steh in seinem Snowdrift, bis der Sturm endet. Töte dann das andere Add.|n5. Auf Mythisch und Mythic+: Ein sterbendes Add wirft Eissplitter ab (Rimeshatter). Stellt genau einen Spieler in jeden Splitterkreis. Ein verpasster Splitter trifft die ganze Gruppe und wurzelt alle fest.",
	DGN_TIP_DN_SENTINEL_QUICK_DPS = "Wechselt euch beim Stoppen der Add-Zauber ab und tötet das erste Add kurz vor dem Sturm.",
	DGN_TIP_DN_SENTINEL_QUICK_HEALER = "Nimm den Frost-Debuff schnell ab und heile alle während des Sturms.",
	DGN_TIP_DN_SENTINEL_QUICK_TANK = "Stell den Boss auf ein Add und halte ihn von den Tornados fern.",
	DGN_TIP_DN_SENTINEL_QUICK = "Tornados: Steht zusammen, damit sie an einer Stelle landen, und geht dann weg.|nAdds: Zwei Eis-Adds erscheinen. Stoppt ihren Zauber und tötet eins kurz vor dem Sturm.|nSturm: Stell dich in den Schnee, den das tote Add hinterlässt. Dann kann der Sturm dich nicht bewegen.",
	DGN_TIP_DN_SENTINEL_TANK = "Tank: Zieh den Boss auf ein Add, damit die Gruppe es mit Cleave trifft, und halte den Boss von den Tornados fern. Hilf beim Unterbrechen von Winter's Shroud.",
	DGN_TIP_DN_SENTINEL_HEALER = "Heiler: {SPELL:1235548} ist ein magischer Frost-DoT: Banne ihn schnell und heile die, die du nicht bannen kannst. Der Sturm trifft alle, sei also bereit, die Gruppe zu heilen.",

	DGN_TIP_DN_NALORAKK_STEPS = "1. {SPELL:1242860}: Drei Spieler bekommen eine Markierung. Lauf an den Rand, bevor sie endet: Ein Geisterbär (ein Echo) erscheint dort, wo du stehst. Legt alle Echoes zusammen, weg von der Gruppe. Echoes schaden jedem in ihrer Nähe, jedes Mal, wenn er zuschlägt.|n2. {SPELL:1243011}: Nalorakk schlägt Zul'jarra nieder und jedes Echo stürmt auf sie zu. Stellt euch wie eine Mauer um sie und blockt die Angriffe. Ein Echo, das sie erreicht, schadet der ganzen Gruppe.|n3. {SPELL:1243569}: Nalorakk schlägt den Tank immer wieder. Zul'jarra stellt einen Schild auf, der diesen Schaden halbiert: Alle stellen sich hinter ihren Schild.|n4. Direkt danach tritt nur der Tank in Forceful Slam. Alle anderen treten raus. Trifft es stattdessen Zul'jarra, erleidet die ganze Gruppe Schaden.|n5. Auf Mythisch und Mythic+: Ein Echo zu blocken gibt dir auch eine stapelnde Blutung (Spectral Slash). Stellt einen Spieler in jede Angriffsbahn und lasst nie zwei Leute dasselbe Echo blocken.",
	DGN_TIP_DN_NALORAKK_QUICK_DPS = "Stell dich einem Geisterbären in den Weg, eine Person pro Bär.",
	DGN_TIP_DN_NALORAKK_QUICK_HEALER = "Heile den Tank während der großen Treffer kräftig und heile alle vor dem Brüllen voll.",
	DGN_TIP_DN_NALORAKK_QUICK_TANK = "Versteck dich hinter ihrem Schild und nimm den nächsten Schlag allein.",
	DGN_TIP_DN_NALORAKK_QUICK = "Markierung: Bekommst du eine Markierung, lauf an den Rand. Dort erscheint ein Geisterbär.|nAngriff: Die Geisterbären rennen auf Zul'jarra zu. Stell dich in ihren Weg, um sie aufzuhalten.|nSchild: Wenn der Boss den Tank oft schlägt, verstecken sich alle hinter ihrem Schild.",
	DGN_TIP_DN_NALORAKK_TANK = "Tank: {SPELL:1243569} geht auf dich. Steh hinter Zul'jarras Schild und nutze eine Defensive. Tritt dann allein in Forceful Slam, weg von der Gruppe.",
	DGN_TIP_DN_NALORAKK_HEALER = "Heiler: Der Tank erleidet während {SPELL:1243569} große Treffer, danach Forceful Slam. Heile die Gruppe vor Forceful Roar voll. In Mythic+ achte auf die Blutungsstapel bei den Spielern, die Echoes blocken.",

	-- The Blinding Vale -----------------------------------------------------------
	DGN_TIP_BV_TRINITY_STEPS = "1. Die drei Bosse teilen sich einen Lebensbalken. Der Tank stellt sie zusammen und alle treffen alle drei. Kicke Kezkitts Light Bolt.|n2. {SPELL:1234753} trifft den Tank und hinterlässt drei grüne Kreise. Stell dich noch nicht hinein. Lekshi dasht dann durch alle drei Kreise ({SPELL:1234850}) - bleib aus dieser Linie.|n3. Wenn {SPELL:1235564} beginnt, steht in jedem Kreis ein Spieler (der Tank plus zwei andere), bis der Strahl endet. Ein leerer Kreis lässt die ganze Gruppe später großen Schaden erleiden.|n4. Nach dem Strahl werden die Kreise zu brennendem Boden ({SPELL:1235828}). Tritt raus; der Tank zieht die Bosse auf sauberen Boden. {SPELL:1261276} lässt einen zufälligen Spieler bluten: Nutze eine Defensive oder entferne die Blutung.|n5. Auf Mythisch und Mythic+: Nach Thornblade springt Lekshi zu diesem Spieler und versprüht Dornen um ihn herum. Dieser Spieler geht weg von der Gruppe und läuft dann aus den Dornen. Bedrock Slam schickt außerdem Schadenspulse durch die ganze Gruppe.",
	DGN_TIP_BV_TRINITY_QUICK_DPS = "Triff alle drei Bosse zusammen und kicke Kezkitts Bolt.",
	DGN_TIP_BV_TRINITY_QUICK_HEALER = "Halte die Spieler in den Kreisen am Leben und heile den Spieler, der blutet.",
	DGN_TIP_BV_TRINITY_QUICK_TANK = "Nutze eine Defensive für den großen Schlag und zieh dann die drei Bosse vom brennenden Boden.",
	DGN_TIP_BV_TRINITY_QUICK = "Drei Bosse: Sie teilen sich einen Lebensbalken. Stellt sie zusammen und trefft alle drei.|nKreise: Wenn der Strahl kommt, steht in jedem Kreis ein Spieler, bis er aufhört.|nDash: Bleib aus der Linie zwischen den Kreisen und verlass die Kreise, wenn sie brennen.",
	DGN_TIP_BV_TRINITY_TANK = "Tank: Nutze eine Defensive für {SPELL:1234753}. Halte die drei für Cleave zusammen, steh während des Strahls in einem Kreis und zieh die Bosse vor dem nächsten Schlag vom brennenden Boden.",
	DGN_TIP_BV_TRINITY_HEALER = "Heiler: Die drei Kreis-Soaker erleiden tickenden Schaden - halte sie oben und heile die Blutung von {SPELL:1261276}. Auf Mythisch heb einen Cooldown für die Gruppenpulse nach Bedrock Slam auf.",

	DGN_TIP_BV_IKUZZ_STEPS = "1. {SPELL:1236746} trifft alle und stößt dich zurück. Stell dich so hin, dass du nicht über eine Kante oder in Wurzeln fliegst.|n2. {SPELL:1236709}: Er brüllt und schadet der ganzen Gruppe 6 Sekunden lang. Nutze eine Defensive, wenn du wenig Leben hast.|n3. {SPELL:1237091}: Er jagt einen Spieler 10 Sekunden lang. Dieser Spieler rennt und führt ihn über die Wurzeln am Boden - seine Schritte zertreten sie. Erwischt er dich, blutest du und wirst betäubt ({SPELL:1272290}).|n4. Ab 50% Leben rast er: Er bewegt sich schneller und schadet der Gruppe ständig. Heb Cooldowns dafür auf.|n5. Auf Mythisch und Mythic+: Nach dem Stampfen packen Wurzeln ein paar Sekunden später jeden Spieler, und während des Brüllens wachsen mehr Wurzeln. Geh zurück zum Boss, damit die Gruppe die Wurzeln mit Cleave zerstört, oder nutze einen Befreiungszauber.",
	DGN_TIP_BV_IKUZZ_QUICK_DPS = "Zerstöre die Wurzeln schnell, und wenn er dich jagt, lauf über die Wurzeln.",
	DGN_TIP_BV_IKUZZ_QUICK_HEALER = "Heb deine großen Heilungen auf, bis er halbes Leben hat.",
	DGN_TIP_BV_IKUZZ_QUICK_TANK = "Halte den Boss nah bei Spielern, die in Wurzeln feststecken, damit alle sie zerstören können.",
	DGN_TIP_BV_IKUZZ_QUICK = "Stampfen: Er stößt alle zurück. Steh nicht nah an einer Kante.|nJagd: Er jagt einen Spieler. Dieser Spieler läuft über die Wurzeln, damit er sie zertritt.|nHalbes Leben: Er wird schneller und schlägt härter zu. Nutze jetzt deine großen Zauber.",
	DGN_TIP_BV_IKUZZ_TANK = "Tank: Halte Ikuzz nah bei festgewurzelten Spielern, damit alle die Wurzeln mit Cleave treffen können, und weg von Kanten wegen des Rückstoßes.",
	DGN_TIP_BV_IKUZZ_HEALER = "Heiler: Das Stampfen und {SPELL:1236709} treffen die ganze Gruppe. Heb deine großen Cooldowns für die Raserei bei 50% auf, vor allem, wenn er währenddessen brüllt. Ein erwischter Spieler erleidet großen Schaden - heile ihn schnell hoch.",

	DGN_TIP_BV_RUIA_STEPS = "1. Moonkin-Form (100 bis 70%): Kicke Warden's Wrath - es trifft den Tank. Weiche den {SPELL:1240098}-Kreisen aus.|n2. {SPELL:1239825} markiert ein paar Spieler. Geh weg von der Gruppe, bevor es endet: Dann schießen Strahlen aus dir heraus. Bleib aus den Strahlen - sie machen dich stumm.|n3. Bärenform (70 bis 40%): {SPELL:1240222} markiert ein paar Spieler und feuert Kegel auf sie. Markierte Spieler verteilen sich und halten ihren Kegel von anderen fern. Ein zweiter Treffer tut viel mehr weh.|n4. {SPELL:1241058} lässt Spieler bluten, bis sie voll geheilt sind.|n5. Bei 40% Leben, {SPELL:1241067}: Er wirkt all das alle 8 Sekunden, bis er stirbt. Nutze hier deine Cooldowns und Bloodlust.",
	DGN_TIP_BV_RUIA_QUICK_DPS = "Kicke seinen Zauber in Moonkin-Form und heb deine großen Zauber für 40 Prozent auf.",
	DGN_TIP_BV_RUIA_QUICK_HEALER = "Ein blutender Spieler blutet weiter, bis du ihn ganz hochheilst.",
	DGN_TIP_BV_RUIA_QUICK_TANK = "Sorg dafür, dass sein Zauber in Moonkin-Form gekickt wird, und nutze Defensiven in Bärenform.",
	DGN_TIP_BV_RUIA_QUICK = "Moonkin: Kicke seinen Zauber, weiche den Kreisen aus und geh weg von der Gruppe, wenn du die Strahl-Markierung hast.|nBär: Bist du markiert, geh weg, damit dein Kegel niemand anderen trifft.|n40%: Er macht alles auf einmal. Nutze jetzt deine großen Zauber.",
	DGN_TIP_BV_RUIA_TANK = "Tank: In Moonkin-Form ersetzt Warden's Wrath seinen Nahkampf - sorg dafür, dass es gekickt wird. In Bärenform schlägt sein Nahkampf doppelt so hart zu (Mangling Claws), also nutze dort deine Defensiven.",
	DGN_TIP_BV_RUIA_HEALER = "Heiler: {SPELL:1241058} stoppt erst, wenn ein Spieler volles Leben hat - heile ein Ziel voll, dann das nächste. Heb Cooldowns für die 40%-Phase auf.",

	DGN_TIP_BV_ZIEKKET_STEPS = "1. {SPELL:1246372}: Lashers sprießen. Der Tank sammelt sie; alle treffen sie mit Cleave und kicken Lightspore Shot.|n2. Ein Lasher mit 1% Leben versinkt im Boden und kann nicht verletzt werden. Er erwacht beim nächsten {SPELL:1246372} stärker und kann dann weder gekickt noch betäubt werden.|n3. {SPELL:1253690} richtet einen Strahl auf einen Spieler. Bist du es, dreh dich so, dass der Strahl durch jeden schlafenden Lasher geht - das tötet sie endgültig. Er hinterlässt verlangsamende Pfützen ({SPELL:1246753}); tritt heraus.|n4. {SPELL:1247685} trifft den Tank hart, stößt ihn zurück und lässt ihn bluten. Die ganze Gruppe erleidet den ganzen Kampf über pulsierenden Schaden.|n5. Auf Mythisch und Mythic+: {SPELL:1246858} schickt Orbs zu Ziekket. Tritt hinein, bevor sie ihn erreichen, und teilt sie auf (etwa zwei oder drei pro Spieler) - jeder Orb gibt dir einen stapelnden DoT. Ein Orb, der ihn erreicht, schadet der Gruppe und schildet ihn.",
	DGN_TIP_BV_ZIEKKET_QUICK_DPS = "Kicke die Schüsse der Lashers und hör auf, einen Lasher zu schlagen, sobald er schläft.",
	DGN_TIP_BV_ZIEKKET_QUICK_HEALER = "Die ganze Gruppe erleidet den ganzen Kampf Schaden, also heile weiter alle.",
	DGN_TIP_BV_ZIEKKET_QUICK_TANK = "Sammle die Lashers zusammen und nutze eine Defensive für den großen Stachelschlag.",
	DGN_TIP_BV_ZIEKKET_QUICK = "Lashers: Triff sie, bis sie im Boden versinken. Dann schlafen sie.|nStrahl: Zielt der Strahl auf dich, richte ihn durch die schlafenden Lashers. Das tötet sie endgültig.|nOrbs (Mythisch): Berühre die leuchtenden Kugeln, bevor sie den Boss erreichen, und teilt sie auf.",
	DGN_TIP_BV_ZIEKKET_TANK = "Tank: Sammle jede Lasher-Welle für Cleave, nah am Rand. Nutze eine Defensive für {SPELL:1247685} - es stößt dich zurück und lässt dich bluten. Geh aus den Lightsap-Pfützen.",
	DGN_TIP_BV_ZIEKKET_HEALER = "Heiler: Die Gruppe erleidet den ganzen Kampf Schaden, also heile weiter alle. Auf Mythisch achte auf die Orb-Soaker - ihre Stapel tun weh, und ein verpasster Orb trifft die ganze Gruppe.",

	-- Voidscar Arena ----------------------------------------------------------------
	DGN_TIP_VA_TAZRAH_STEPS = "1. {SPELL:1222098}: Ein Schatten dasht in einer Linie durch jeden Spieler. Verteilt euch locker nah am Rand des Raums, damit deine Linie niemand anderen trifft.|n2. {SPELL:1296963} hinterlässt Pfützen am Boden. Leg sie nah am Rand und dicht beieinander ab und steh nie darin.|n3. {SPELL:1300259}: Die Pfützen schießen Orbs ab. Bleib im Raum in Bewegung und weiche jedem Orb aus.|n4. Auf Mythisch und Mythic+: {SPELL:1225011} - zwei Splitter fliegen auf einen Spieler, und jeder platzt am ersten Spieler, den er trifft. Tritt nicht in Splitter, die auf jemand anderen zielen.",
	DGN_TIP_VA_TAZRAH_QUICK_DPS = "Schlag weiter auf den Boss, während du ausweichst.",
	DGN_TIP_VA_TAZRAH_QUICK_HEALER = "Heile alle voll, bevor die Pfützen kommen.",
	DGN_TIP_VA_TAZRAH_QUICK_TANK = "Nutze eine Defensive, wenn er dich zurückstößt, und lande nicht in einer Pfütze.",
	DGN_TIP_VA_TAZRAH_QUICK = "Dash: Ein Geist rennt in einer Linie auf dich zu. Steh nah an der Wand, etwas weg von deinen Freunden.|nPfützen: Leg deine dunklen Pfützen nah an der Wand ab, dicht beieinander. Steh nie darin.|nOrbs: Die Pfützen schießen Kugeln. Lauf weiter durch den Raum und weiche ihnen aus.",
	DGN_TIP_VA_TAZRAH_TANK = "Tank: {SPELL:1297017} trifft dich hart und stößt dich zurück. Nutze eine Defensive und lass dich nicht in eine Pfütze stoßen. Tanke nah an einer Wand und dreh dich langsam durch den Raum, damit die Mitte frei bleibt.",
	DGN_TIP_VA_TAZRAH_HEALER = "Heiler: Heile alle vor jedem {SPELL:1296963}-Zauber voll; {SPELL:1300259} schadet der ganzen Gruppe. Heile Spieler, die ein Dash getroffen hat, es schadet ihnen noch eine Weile.",

	DGN_TIP_VA_ATROXUS_STEPS = "1. {SPELL:1262497} trifft die ganze Gruppe. Etwa 3 Sekunden später kriecht ein Toxic Creeper heraus ({SPELL:1222371}). Töte ihn schnell.|n2. {SPELL:1263977} ist ein Frontalangriff auf einen zufälligen Spieler. Bleib nah am Boss, damit du schnell heraustreten kannst.|n3. {SPELL:1226120} spritzt Gift um den Boss. Weiche den Treffern aus und bleib aus den Giftpfützen, die es hinterlässt.|n4. Auf Mythisch und Mythic+: Der Creeper hat Toxic Aura - sie schadet jedem im Umkreis von 8 Metern, bis er stirbt. Töte ihn noch schneller; Fernkämpfer halten Abstand zu ihm.",
	DGN_TIP_VA_ATROXUS_QUICK_DPS = "Wenn der Creeper herauskommt, schlag ihn zuerst.",
	DGN_TIP_VA_ATROXUS_QUICK_HEALER = "Entferne Gifte vom Tank und von allen, die in einer Pfütze standen.",
	DGN_TIP_VA_ATROXUS_QUICK_TANK = "Der Creeper jagt dich: Lauf von ihm weg, damit er dich nicht beißen kann.",
	DGN_TIP_VA_ATROXUS_QUICK = "Brüllen: Der Boss brüllt und ein kleines Monster, der Creeper, kriecht heraus. Alle schlagen ihn, bis er stirbt.|nAtem: Der Boss atmet auf einen zufälligen Spieler. Steh nah dran und tritt heraus.|nGift: Geh weg von den Giftspritzern und den Pfützen.",
	DGN_TIP_VA_ATROXUS_TANK = "Tank: Der Creeper fixiert dich. Kite ihn und lass dich nicht treffen - jeder Biss gibt einen Stapel Sickening Bite, und die Stapel machen {SPELL:1222642} tödlich. Halte ihn nah am Boss, damit die DPS beide treffen können, und nutze eine Defensive für die Klaue.",
	DGN_TIP_VA_ATROXUS_HEALER = "Heiler: Banne Gifte: das {SPELL:1222642}-Gift auf dem Tank und Mind-Numbing Poison aus den Pfützen. Auf Mythisch und Mythic+ nutze einen Heil-Cooldown, solange der Creeper lebt.",

	DGN_TIP_VA_CHARONUS_STEPS = "1. {SPELL:1282770}: Einige Spieler werden markiert, und ein paar Sekunden später erscheint ein Schwerkraftloch unter ihnen. Es zieht dich hinein und tut weh. Geh raus, aber bleib neben einem - du brauchst es für die Orbs. Seine Mitte gibt Atomized: kurz kein Schaden und keine Heilung.|n2. {SPELL:1263982}: Drei Spieler werden je von einem Orb gejagt. Sein Debuff tut weh und verlangsamt dich jede Sekunde mehr. Lauf an einem Schwerkraftloch vorbei, damit dein Orb dir hinein folgt - das zerstört beide. Bleib nicht darin stehen. Jeder Spieler nutzt ein anderes Loch.|n3. {SPELL:1227264} trifft alle, stößt dich zurück und hinterlässt einen 20-Sekunden-Schadenseffekt. Steht auseinander und achte darauf, dass du nicht in einem Loch landest.|n4. Auf Mythisch und Mythic+: {SPELL:1222758} - Geschosse fliegen auf einen zufälligen Spieler zu und stoßen jeden zurück, den sie berühren. Bist du es, lauf weiter; alle anderen treten aus dem Weg.",
	DGN_TIP_VA_CHARONUS_QUICK_DPS = "Warte neben einem Loch, damit eine Kugel, die dich jagt, schnell hineinfällt.",
	DGN_TIP_VA_CHARONUS_QUICK_HEALER = "Heile zuerst die Spieler, die von einer Kugel gejagt werden.",
	DGN_TIP_VA_CHARONUS_QUICK_TANK = "Nutze eine Defensive für seinen großen Treffer und richte ihn von deinen Freunden weg.",
	DGN_TIP_VA_CHARONUS_QUICK = "Löcher: Dunkle Löcher erscheinen am Boden. Sie ziehen dich hinein, also bleib nah an einem, aber nicht darin.|nOrbs: Jagt dich eine Kugel, lauf an einem Loch vorbei, damit die Kugel hineinfällt.|nStoß: Der Boss stößt alle zurück. Steht auseinander und flieg nicht in ein Loch.",
	DGN_TIP_VA_CHARONUS_TANK = "Tank: {SPELL:1311923} ist ein frontaler Tank-Treffer. Nutze eine Defensive und richte ihn von der Gruppe weg. Halte den Boss in der Mitte der drei Schwerkraftlöcher und dreh ihn nicht durch Spieler.",
	DGN_TIP_VA_CHARONUS_HEALER = "Heiler: Heile zuerst die Spieler mit einem Orb - je länger sie ihn tragen, desto härter trifft er. Nach {SPELL:1227264} hat die ganze Gruppe einen 20-Sekunden-Schadenseffekt, und die Schwerkraftlöcher pulsieren Schaden, solange sie da sind.",

	-- Nexus-Point Xenas ---------------------------------------------------------------
	DGN_TIP_NX_KASRETH_STEPS = "1. {SPELL:1251785} auf dir? Tritt IN einen Leyline-Strahl ({SPELL:1251183}) — er entfernt den Debuff (kurzer Stun, fairer Tausch).|n2. Alle anderen: kreuzt die Leylines NICHT (Schaden + stapelnde Verlangsamung).|n3. Volle Energie = {SPELL:1257509}: große Einschlagzone, mach Platz — danach bleiben Arkanlachen ({SPELL:1264048}) liegen.",
	DGN_TIP_NX_KASRETH_TANK = "Tank: halte den Boss von den Leylines fern.",
	DGN_TIP_NX_KASRETH_HEALER = "Heiler: Sparkburn tickt nach jeder Detonation auf allen.",

	DGN_TIP_NX_NYSARRA_STEPS = "1. Verteilt euch — die Schläge von {SPELL:1249020} splashen 14 Meter.|n2. Tötet die Null-Vanguard-Adds ({SPELL:1252703}) SCHNELL: was noch lebt, wird verschlungen ({SPELL:1271684}), heilt sie und knallt auf die Gruppe.|n3. Weiche den {SPELL:1264439} aus.",
	DGN_TIP_NX_NYSARRA_TANK = "Tank: sie springt dich mit einer Hieb-Kombo an ({SPELL:1247937}) — Defensive, mach dich auf den Finisher gefasst.",
	DGN_TIP_NX_NYSARRA_HEALER = "Heiler: Streuschaden nach {SPELL:1249020}; Gruppenknall, wenn Adds das Verschlingen überleben.",

	DGN_TIP_NX_LOTHRAXION_STEPS = "1. {SPELL:1255503}: verteilt euch — Einschläge splashen 8 Meter und spawnen Fractured Images.|n2. {SPELL:1257567}: er versteckt sich unter seinen Abbildern und alle kanalisieren — finde den ECHTEN Lothraxion und unterbrich ihn.|n3. Abbilder flackern mit Rückstößen umher ({SPELL:1255531}); bleib von den {SPELL:1255310} am Boden weg.",
	DGN_TIP_NX_LOTHRAXION_TANK = "Tank: {SPELL:1255335} ist ein Doppelhieb, der Narben in den Boden kerbt — richte ihn von der Gruppe weg.",
	DGN_TIP_NX_LOTHRAXION_HEALER = "Heiler: Heilig-DoTs nach jeder {SPELL:1255503}; stetiger Schaden, bis der Guile-Interrupt sitzt.",

	-- Magisters' Terrace ---------------------------------------------------------------
	DGN_TIP_MT_ARCANOTRON_STEPS = "1. Beim Auftanken ({SPELL:474345}) werden Energy Orbs zu ihm gezogen — fang sie ab; währenddessen erleidet er +20% Schaden: Burst-Fenster!|n2. Gefesselte Spieler ({SPELL:1214038}) sind verwurzelt (Magie) — bannen oder freischlagen.|n3. {SPELL:1214081} schleudert alle zurück und hinterlässt Rückstände zu seinen Füßen — tritt raus.",
	DGN_TIP_MT_ARCANOTRON_TANK = "Tank: {SPELL:474496} katapultiert dich — halte deinen Rücken frei.",
	DGN_TIP_MT_ARCANOTRON_HEALER = "Heiler: banne {SPELL:1214038} (Magie-Wurzel) schnell.",

	DGN_TIP_MT_SERANEL_STEPS = "1. {SPELL:1225193} pazifiziert alle AUSSERHALB der Suppression Zone ({SPELL:1224903}) — steh für die Welle IN der Zone (aber die Zone stummt dich, also nicht verweilen).|n2. Purge/spellsteal seine {SPELL:1248689} (+100% Angriffstempo), sobald sie aktiv ist.|n3. {SPELL:1225787} springt auf einen Spieler in der Nähe über — verteilt euch.",
	DGN_TIP_MT_SERANEL_TANK = "Tank: eine ungepurgte Ward verdoppelt sein Angriffstempo — Defensive, bis sie weg ist.",
	DGN_TIP_MT_SERANEL_HEALER = "Heiler: markierte Spieler ticken; denk daran, dass du in der Zone nicht zaubern kannst.",

	DGN_TIP_MT_GEMELLUS_STEPS = "1. {SPELL:1223847} (am Anfang und bei halbem Leben): er teilt sich in drei.|n2. {SPELL:1253709}: mit einem verlinkt? RENN hin und berühr ihn — das bricht den Link und entfernt seinen Absorbschild.|n3. {SPELL:1224299} zieht dich hinein — lauf wieder raus.",
	DGN_TIP_MT_GEMELLUS_TANK = "Tank: gruppiere das Trio nach jedem {SPELL:1223847} neu, damit verlinkte Spieler ihren erreichen.",
	DGN_TIP_MT_GEMELLUS_HEALER = "Heiler: verlinkte Spieler erleiden +20% Schaden, bis sie ihren Link brechen.",

	DGN_TIP_MT_DEGENTRIUS_STEPS = "1. {SPELL:1215897}: Leeren-DoTs mit unterschiedlichen Laufzeiten — läuft deiner ab, schießen Entropy Orbs von DEINER Position: geh erst weg von der Gruppe.|n2. {SPELL:1215087} springt zu 4 Stellen — SOAKE einen Einschlag (ein Spieler pro Stelle), sonst bricht er in Void Destruction aus.|n3. {SPELL:1280113} zerschmettert den Tank und schleudert alle im Umkreis von 8 Metern weg — gib dem Tank Raum.",
	DGN_TIP_MT_DEGENTRIUS_TANK = "Tank: Defensive für {SPELL:1280113}; tanke ihn weg von der Gruppe.",
	DGN_TIP_MT_DEGENTRIUS_HEALER = "Heiler: Entropy-DoTs ticken hart — halte die Träger oben, während sie umziehen.",

	-- Skyreach ----------------------------------------------------------------------
	DGN_TIP_SR_RANJIT_STEPS = "1. {SPELL:1258148} fliegt in gerader Linie vor ihm her — tritt zur Seite.|n2. {SPELL:156793}: ein Einschlag in der Mitte plus wandernde Windhosen, die dich hochschleudern — bleib am Laufen.|n3. {SPELL:153757} trifft alle mit einer Blutung — voll bleiben.|n4. {SPELL:1252733} bläst seine Ziele weg — achte darauf, was hinter dir ist.",
	DGN_TIP_SR_RANJIT_TANK = "Tank: halte ihn aus den Vortex-Bahnen.",
	DGN_TIP_SR_RANJIT_HEALER = "Heiler: Gruppenschaden plus Blutungen nach jedem {SPELL:153757}.",

	DGN_TIP_SR_ARAKNATH_STEPS = "1. {SPELL:154162}: Konstrukte strahlen Licht in den Boss und HEILEN ihn — stell dich in einen Strahl, um ihn zu blockieren.|n2. {SPELL:154115}: ein einseitiger Armschlag — getroffen zu werden stapelt einen brutalen Schadensdebuff.|n3. {SPELL:154135} trifft alle — sei bereit.",
	DGN_TIP_SR_ARAKNATH_TANK = "Tank: soake die Strahlen nie selbst — sein Schlag fällt genau in den Soak.",
	DGN_TIP_SR_ARAKNATH_HEALER = "Heiler: Strahl-Soaker ticken stetig; Gruppenheilung bei {SPELL:154135}.",

	DGN_TIP_SR_RUKHRAN_STEPS = "1. {SPELL:1253527}: 3 Sekunden lang fliegen Federn in alle Richtungen — brich die Sichtlinie hinter einer Säule.|n2. {SPELL:1253510} trifft die Gruppe und beschwört einen Sunwing, der jemanden fixiert und Feuer pulsiert — schnell töten; der Fixierte hält Abstand.|n3. Wiederholen — Federn hinter Deckung, Vogel schnell runter.",
	DGN_TIP_SR_RUKHRAN_TANK = "Tank: Defensive für {SPELL:1253519} (großer Schlag + Brand-DoT).",
	DGN_TIP_SR_RUKHRAN_HEALER = "Heiler: pulsierender Gruppenschaden, solange ein Sunwing lebt — ruf nach dem Kill.",

	DGN_TIP_SR_VIRYX_STEPS = "1. {SPELL:154396}: ein 3-Sekunden-Zauber, der den Tank zerlegt — UNTERBRICH ihn, jedes Mal.|n2. {SPELL:1253998}: ein Solar Zealot packt einen Spieler, um ihn vom Balkon zu werfen — befreit ihn schnell.|n3. {SPELL:1253531} auf dir? Lauf ihn weiträumig aus — er hinterlässt Blazing Ground.",
	DGN_TIP_SR_VIRYX_TANK = "Tank: jeder durchgelassene {SPELL:154396} tut weh — haltet die Kick-Reihenfolge straff.",
	DGN_TIP_SR_VIRYX_HEALER = "Heiler: {SPELL:1253538} legt Feuer-DoTs auf mehrere Spieler gleichzeitig.",

	-- Pit of Saron ----------------------------------------------------------------
	DGN_TIP_PS_GARFROST_STEPS = "1. {SPELL:1262029}: die Schmiede pulsiert stapelnden Frost — VERSTECK DICH HINTER einem Saronit-Brocken, er blockt die Strahlung.|n2. {SPELL:1261546} zertrümmert alles um das Hauptziel — bleib 5+ Meter vom Tank weg; neben Erz zerbricht der Schlag das Erz statt zu stunnen.|n3. {SPELL:1261847} trifft alle und zerschmettert ALLES Erz — neues Erz folgt via {SPELL:1261286}.|n4. Bleib aus dem {SPELL:1261799}.",
	DGN_TIP_PS_GARFROST_TANK = "Tank: park dich neben einem Erzbrocken — {SPELL:1261546} zertrümmert dann das Erz, nicht dich.",
	DGN_TIP_PS_GARFROST_HEALER = "Heiler: Gruppenspitze bei {SPELL:1261847}; stapelnder Frost auf allen ohne Deckung.",

	DGN_TIP_PS_KRICKICK_STEPS = "1. {SPELL:1264363}: Ick fixiert und jagt einen Spieler und schleudert dabei Blight und Plague Globs — lauf weiträumig; der Rest haut weiter drauf.|n2. {SPELL:1264027}: Krick teleportiert zu einem Ritualkreis und beschwört Shades — wechseln und töten.|n3. {SPELL:1264336}: weiche der Welle und den anrollenden Globs aus.|n4. Steh nie im Blight ({SPELL:1264299}).",
	DGN_TIP_PS_KRICKICK_TANK = "Tank: {SPELL:1264287} legt eine Pfütze auf dich — richte sie an den Rand.",
	DGN_TIP_PS_KRICKICK_HEALER = "Heiler: halte den Gejagten am Leben; Gruppenschaden bei {SPELL:1264336}.",

	DGN_TIP_PS_TYRANNUS_STEPS = "1. {SPELL:1262772} friert Bone Piles um sein Ziel ein — steh bei Haufen, wenn du markiert bist: gefrorene Haufen können keine Adds liefern.|n2. {SPELL:1263406} erweckt die übrigen Haufen — Plaguespreaders zuerst töten.|n3. Weiche weiter {SPELL:1263756} und Rimefangs {SPELL:1276948} aus.|n4. {SPELL:1276648} = Gruppenschlag + DoT, und infundierte Haufen liefern üblere Adds.",
	DGN_TIP_PS_TYRANNUS_TANK = "Tank: {SPELL:1262582} katapultiert dich und stapelt +200% Schattenschaden — Defensive und festhalten.",
	DGN_TIP_PS_TYRANNUS_HEALER = "Heiler: Gruppen-DoTs nach {SPELL:1276648}; Tank-Spitze direkt nach dem Brand.",

	-- Seat of the Triumvirate --------------------------------------------------------
	DGN_TIP_ST_ZURAAL_STEPS = "1. {SPELL:1268916} trifft alles VOR ihm — steh nie vor dem Boss.|n2. {SPELL:1263304} (volle Energie): er zieht alle heran und explodiert dann mit Rückstoß — lauf rechtzeitig raus; auch die Adds werden hineingezogen.|n3. {SPELL:1263399} spawnt Coalesced-Void-Adds — räum sie vor Crashing Void.|n4. {SPELL:1263282} hinterlässt Void Sludge ({SPELL:244588}) — halte den Boden sauber.",
	DGN_TIP_ST_ZURAAL_TANK = "Tank: Defensive für {SPELL:1263440} (Dreifachhieb).",
	DGN_TIP_ST_ZURAAL_HEALER = "Heiler: großer Gruppenschlag bei {SPELL:1263304}.",

	DGN_TIP_ST_SAPRISH_STEPS = "1. Void Bombs ({SPELL:247175}) landen auf Spielerpositionen — NICHT anfassen; legt sie an die Ränder.|n2. {SPELL:1280064}: Schemen dashen auf jeden Spieler zu und zünden Bomben, die sie kreuzen — leg deine Dash-Linie frei von Bomben.|n3. {SPELL:1263523} zündet ALLE Bomben gleichzeitig — je weniger Bomben, desto sanfter.|n4. Unterbrich Shadewings {SPELL:248831} (Gruppenschlag + Desorientierung).",
	DGN_TIP_ST_SAPRISH_TANK = "Tank: halte das Trio zusammen; Darkfangs Sprung ({SPELL:245738}) lässt sein Opfer bluten.",
	DGN_TIP_ST_SAPRISH_HEALER = "Heiler: Sprung-Opfer bluten; Gruppenknall bei {SPELL:1263523}.",

	DGN_TIP_ST_NEZHAR_STEPS = "1. {SPELL:1263528} schleudert alle zurück — achte auf deine Position bei Stürmen.|n2. {SPELL:1263538} und die {SPELL:1277358} stiften Chaos — töte Tentakel, weiche den Umbral Waves aus dem Tor aus.|n3. {SPELL:1263532}-Zonen ticken hart, innen schlimmer — raus, schnell.|n4. {SPELL:244750} zerlegt den Tank — unterbrich ihn, wenn möglich.",
	DGN_TIP_ST_NEZHAR_TANK = "Tank: mach dich auf {SPELL:244750} gefasst, wenn kein Kick bereit ist.",
	DGN_TIP_ST_NEZHAR_HEALER = "Heiler: {SPELL:1263542} = mehrere Rot-DoTs gleichzeitig.",

	DGN_TIP_ST_LURA_STEPS = "1. Notes of Despair strahlen weiter ({SPELL:1265421}), bis sie gestummt sind — lenke deinen {SPELL:1265426} QUER DURCH die Noten (der Strahl trifft auch Verbündete in der Linie, also ziele frei).|n2. {SPELL:1265689}: 20 Sekunden Schmerz um jede aktive Note — brich Noten schnell.|n3. {SPELL:1264151}: rotierende Leerenstrahlen — beweg dich mit den Lücken.|n4. {SPELL:1266003} ist ein tödlicher 10-Sekunden-Kanal — alle Defensiven rein und durchheilen.",
	DGN_TIP_ST_LURA_TANK = "Tank: nach {SPELL:1266001} fliegt jeder — sammelt euch schnell.",
	DGN_TIP_ST_LURA_HEALER = "Heiler: {SPELL:1265421}-Gruppenschläge plus Noten-Auren — Noten brechen IST der Heilplan.",

	-- Algeth'ar Academy ----------------------------------------------------------------
	DGN_TIP_AA_VEXAMUS_STEPS = "1. {SPELL:385974} schweben zum Boss — soakt sie, ein Spieler pro Orb (kleiner Treffer); jeder Orb, den ER absorbiert, knallt auf die ganze Gruppe.|n2. {SPELL:386173}: trag deine raus — sie platzt in eine {SPELL:386201}-Lache.|n3. Volle Energie = {SPELL:388537}: Gruppenschlag plus wiederholte Eruptionen unter Spielern — bleib in Bewegung.",
	DGN_TIP_AA_VEXAMUS_TANK = "Tank: {SPELL:385958} sprengt alles vor ihm weg — Defensive, dreh ihn von der Gruppe weg.",
	DGN_TIP_AA_VEXAMUS_HEALER = "Heiler: Bombenträger ticken; Gruppenschaden für jeden Orb, der den Boss erreicht.",

	DGN_TIP_AA_ANCIENT_STEPS = "1. {SPELL:388796}: 4 Sekunden lang keimen Samen unter allen — ausweichen; verpasste Samen hinterlassen schlafende Lashers.|n2. Bei voller Energie ({SPELL:388923}) erwachen ALLE schlafenden Lashers gleichzeitig — räum sie vorher.|n3. {SPELL:388623} wirft einen Ast, der ein großes Add wird — töte es und UNTERBRICH seinen {SPELL:396640}.",
	DGN_TIP_AA_ANCIENT_TANK = "Tank: {SPELL:388544} verdoppelt deinen erlittenen Physisch-Schaden — Defensive, jedes Mal.",
	DGN_TIP_AA_ANCIENT_HEALER = "Heiler: entferne {SPELL:389033} (Gift), bevor es hoch stapelt.",

	DGN_TIP_AA_CRAWTH_STEPS = "1. {SPELL:377004} bricht unter jedem Spieler aus und unterbricht Zauber — HÖR AUF zu zaubern, dann verteilt euch.|n2. {SPELL:377034}: sie blickt jemanden an und schlägt einen Kegel in diese Richtung — tritt raus.|n3. {SPELL:377182}: erziel ein Tor — das Feuertor stunnt sie und sie erleidet 75% mehr Schaden.",
	DGN_TIP_AA_CRAWTH_TANK = "Tank: Defensive für {SPELL:376997} (Schlag + 10s-Blutung).",
	DGN_TIP_AA_CRAWTH_HEALER = "Heiler: schwerer Gruppenschaden nach dem Kreischen; der Tank blutet.",

	DGN_TIP_AA_DORAGOSA_STEPS = "1. {SPELL:374341} auf dir? Trag sie weg von der Gruppe — sie platzt 8 Meter breit.|n2. {SPELL:388820} zieht alle hinein und explodiert dann — LAUF RAUS vor dem Knall.|n3. {SPELL:389011} stapelt von jeder Mechanik, die du frisst — bei 3 Stapeln bricht es in einen Arcane Rift aus; bleib sauber.|n4. Bleib vom {SPELL:389007}-Boden weg.",
	DGN_TIP_AA_DORAGOSA_TANK = "Tank: Defensive für {SPELL:1282251}.",
	DGN_TIP_AA_DORAGOSA_HEALER = "Heiler: achte auf {SPELL:389011}-Stapel — Träger ticken pro Stapel härter.",

	-- DPS-Zeilen und Altar of Fangs, nachgetragen 19 Aug 2026.
	--
	-- ⚠️ Diese Gruppe war der schiefste Fall im ganzen Projekt: 129 deutsche Bosstipps
	-- neben 49 englischen, im selben Fenster. Der Grund ist kein Versäumnis an einer
	-- Stelle, sondern das Muster — die DPS-Rolle kam als ein Stapel dazu, nachdem die
	-- Übersetzungsrunde für diesen Dungeon schon gelaufen war, und Altar of Fangs kam
	-- mit Season 2. Eigennamen bleiben englisch (Lashers, Sunwing, Nibbles ...), so wie
	-- im Rest dieser Datei und wie es CLAUDE.md verlangt.
	DGN_TIP_AA_ANCIENT_DPS = "DPS: Räum die schlafenden Lashers vor voller Energie, sonst erwachen sie alle gleichzeitig. Töte das geworfene Ast-Add und unterbrich seinen Zauber.",
	DGN_TIP_AA_CRAWTH_DPS = "DPS: Hör auf zu zaubern, wenn der Boden aufbricht — es unterbricht dich ohnehin — und verteilt euch dann. Erziel ein Tor im Feuertor: das stunnt sie und sie erleidet 75% mehr Schaden.",
	DGN_TIP_AA_DORAGOSA_DPS = "DPS: Trag deinen Debuff weg von der Gruppe; er platzt 8 Meter breit. Jede Mechanik, die du frisst, stapelt — bei 3 Stapeln wird ein Arcane Rift daraus.",
	DGN_TIP_AA_VEXAMUS_DPS = "DPS: Soak die Orbs einzeln, ein Spieler pro Orb: jeder Orb, den er aufnimmt, trifft die ganze Gruppe. Trag deinen eigenen Blitz raus, bevor er sich sammelt.",

	-- Altar of Fangs (Season 2) --------------------------------------------------
	DGN_TIP_AF_COIL_STEPS = "1. Unterbrich {SPELL:1310547}. Es kommt als drei Zauber hintereinander, also plant drei Kicks. Jeder verpasste Kick macht die Gruppe schwächer und langsamer.|n2. Weiche {SPELL:1299940} aus: ein Ansturm in einer Linie und ein Giftkegel. Zielt der Kegel auf dich, richte ihn von der Gruppe weg.|n3. {SPELL:1299053}: Ranken binden dich an den Boss und der Schaden steigt immer weiter. Alle laufen gleichzeitig mehr als 10 Meter vom Boss weg, um die Ranken zu zerreißen.|n4. Der Boss teilt sich dann in 5 Schlangen. Schlag hart auf sie ein: Dieser Schaden zählt gegen den Boss. Wenn sie wieder verschmelzen ({SPELL:1300686}), steh nicht in ihrem Weg.|n5. Auf Mythisch und Mythic+: Jede Schlange jagt einen Spieler ({SPELL:1300503}). Lauf vor ihr weg und verlangsame oder stunne sie; lass sie dich nicht berühren.",
	DGN_TIP_AF_COIL_QUICK_DPS = "Kicke, wenn du dran bist, und nutze deine großen Angriffe auf die Schlangen.",
	DGN_TIP_AF_COIL_QUICK_HEALER = "Das Gift tut den ganzen Kampf weh; wenn die Ranken kommen, sag allen, dass sie laufen sollen.",
	DGN_TIP_AF_COIL_QUICK_TANK = "Nutze eine Defensive für den Schwanzschlag und zieh die Schlangen zusammen.",
	DGN_TIP_AF_COIL_QUICK = "Kicks: Der Boss zaubert dreimal hintereinander. Stoppe jeden Zauber.|nRanken: Ranken binden dich an den Boss. Alle laufen gleichzeitig weit von ihm weg.|nSchlangen: Der Boss zerfällt in Schlangen. Schlag hart auf sie ein und geh aus dem Weg, wenn sie sich wieder vereinen.",
	DGN_TIP_AF_COIL_DPS = "DPS: Übernimm deinen Platz in der Kick-Reihenfolge für {SPELL:1310547}. Heb deine großen Cooldowns für die 5 Schlangen auf, nicht für den Boss.",
	DGN_TIP_AF_COIL_HEALER = "Heiler: {SPELL:1299154} ist Gruppenschaden, der den ganzen Kampf über tickt. Heile kräftig, solange die Ranken da sind, aber die echte Lösung ist, dass alle laufen.",
	DGN_TIP_AF_COIL_TANK = "Tank: Nutze eine Defensive für {SPELL:1298949}. Wenn sich der Boss teilt, zieh die Schlangen zusammen, damit die Gruppe alle gleichzeitig treffen kann.",
	DGN_TIP_AF_RAVI_STEPS = "1. {SPELL:1307894} trifft die ganze Gruppe und lässt Geröll fallen. Sei auf vollem Leben und tritt aus den Kreisen am Boden.|n2. Wenn ihre Energie leer ist, frisst Rav'i von einem Aashaufen und bekommt einen Schild ({SPELL:1309522}). Alle greifen sie an und brechen den Schild schnell: Bis er bricht, erleidet die Gruppe Schaden.|n3. Frisst sie von einem Haufen mit {SPELL:1307921} darauf, bekommt sie {SPELL:1307765} und schlägt viel härter zu. Der Tank hält sie von diesen Haufen fern.|n4. {SPELL:1296220}: Verteilt euch. Weiche den drei Wellen von {SPELL:1296050} aus.|n5. Auf Mythisch und Mythic+: Während sie frisst, wirft sie Fleischbrocken (Messy Eater). Tritt hinein, um sie zu fangen; jeder verpasste Brocken schadet der Gruppe.",
	DGN_TIP_AF_RAVI_QUICK_DPS = "Brich den Schild schnell und verteilt euch, wenn die drei Schüsse kommen.",
	DGN_TIP_AF_RAVI_QUICK_HEALER = "Heile alle vor dem Stampfen voll und heile, bis der Schild weg ist.",
	DGN_TIP_AF_RAVI_QUICK_TANK = "Zieh sie von den Haufen mit frischem Fleisch weg, bevor sie frisst.",
	DGN_TIP_AF_RAVI_QUICK = "Stampfen: Die ganze Gruppe wird getroffen und Steine fallen. Sei auf vollem Leben und tritt aus den Kreisen.|nSchild: Wenn sie frisst, bekommt sie einen Schild. Alle schlagen fest zu, bis er bricht.|nFleisch: Der Tank hält sie vom frischen Fleisch fern, sonst schlägt sie viel härter zu.",
	DGN_TIP_AF_RAVI_DPS = "DPS: Wechsle auf Rav'i, sobald der Schild erscheint, und brich ihn mit deinem Burst. Verteilt euch für {SPELL:1296220}.",
	DGN_TIP_AF_RAVI_TANK = "Tank: Bevor Rav'i frisst, zieh sie zu einem Aashaufen ohne {SPELL:1307921}, damit sie nie {SPELL:1307765} bekommt. Nutze eine Defensive für ihre schweren Nahkampftreffer (Hydrastrike).",
	DGN_TIP_AF_RAVI_HEALER = "Heiler: Heile die Gruppe vor {SPELL:1307894} voll und heile kräftig, bis der Schild bricht. Kannst du Krankheiten entfernen, reinige Spieler, die von {SPELL:1296050} getroffen wurden.",
	DGN_TIP_AF_ZULJAN_STEPS = "1. {SPELL:1300876}: Vier Schlangenköpfe schießen Strahlen auf Zul'jan. Stell dich in einen Strahl, zwischen Kopf und Boss, um ihn zu blocken. Sprecht vor dem Pull ab, wer welchen Strahl nimmt. Jeder Strahl, der ihn erreicht, macht ihn für den Rest des Kampfes stärker.|n2. Einen Strahl zu blocken gibt dir Ritual Venom. Es platzt mit großem Schaden, wenn es ausläuft, also entferne es vorher.|n3. Dazu trittst du absichtlich in eine {SPELL:1301413}-Axtlinie: Das entfernt dein ganzes Gift. Ohne Gift bleibst du aus dieser Linie raus.|n4. Das Entfernen des Gifts hinterlässt eine Blutlache ({SPELL:1301231}). Tritt heraus. Weiche den springenden Äxten von {SPELL:1301111} aus.|n5. Auf Mythisch und Mythic+: Ritual Venom stapelt sich. Entferne alles auf einmal in einer Axtlinie, bevor es ausläuft.",
	DGN_TIP_AF_ZULJAN_QUICK_DPS = "Stell dich in deinen Strahl und entferne dann dein Gift in der Axtlinie.",
	DGN_TIP_AF_ZULJAN_QUICK_HEALER = "Heile groß während der Strahlen und achte darauf, wer noch Gift hat.",
	DGN_TIP_AF_ZULJAN_QUICK_TANK = "Nutze eine Defensive für den Doppeltreffer und lass deine Blutlachen am Rand.",
	DGN_TIP_AF_ZULJAN_QUICK = "Strahlen: Schlangenköpfe schießen Strahlen auf den Boss. Stell dich in einen, damit er ihn nicht erreicht.|nGift: Ein Strahl gibt dir Gift. Lauf in die Linie der geworfenen Axt, um es abzuwaschen, aber nur, wenn du Gift hast.|nBoden: Tritt aus Blutlachen und lauf vor den springenden Äxten weg.",
	DGN_TIP_AF_ZULJAN_DPS = "DPS: Halte deinen Strahlplatz während des ganzen Rituals. Entferne danach dein Gift in der nächsten Axtlinie.",
	DGN_TIP_AF_ZULJAN_HEALER = "Heiler: Nutze in jedem Ritual einen großen Cooldown. Achte darauf, wer Ritual Venom hat, und sorg dafür, dass es entfernt wird, bevor es platzt.",
	DGN_TIP_AF_ZULJAN_TANK = "Tank: Nutze eine Defensive für {SPELL:1301350}; es trifft dich zweimal. Seine Treffer entfernen auch dein Gift und hinterlassen Blutlachen, also leg die am Rand des Raums ab.",

	DGN_TIP_BV_IKUZZ_DPS = "DPS: Zerstöre die Wurzeln schnell mit Cleave. Fixiert? Lauf und führ ihn über Wurzeln statt ins Leere - lass dich nicht erwischen.",
	DGN_TIP_BV_RUIA_DPS = "DPS: Kicke Warden's Wrath in Moonkin-Form. Heb deine Cooldowns für 40% auf, wenn alles alle 8 Sekunden kommt.",
	DGN_TIP_BV_TRINITY_DPS = "DPS: Triff alle drei Bosse - sie teilen sich einen Lebensbalken, also nutze Cleave. Kicke Light Bolt und nimm während des Strahls einen Kreis, wenn deine Gruppe einen Soaker braucht.",
	DGN_TIP_BV_ZIEKKET_DPS = "DPS: Kicke Lightspore Shot. Verschwende keinen Schaden an schlafenden Lashers - nur der Strahl tötet sie. Auf Mythisch nimm deinen Anteil an Orbs.",

	DGN_TIP_DN_HOARDMONGER_DPS = "DPS: Hilf beim Treten auf die Pilze und wechselt euch ab, damit niemand zu viele Giftstapel bekommt. Bleib von den Knochenflecken runter.",
	DGN_TIP_DN_NALORAKK_DPS = "DPS: Wenn die Echoes angreifen, hilf, Zul'jarra abzuschirmen: ein Spieler pro Echo. Mit Markierung läufst du an den Rand neben die anderen Echoes.",
	DGN_TIP_DN_SENTINEL_DPS = "DPS: Teilt die Unterbrechungen auf, damit jeder Winter's Shroud gestoppt wird. Töte das erste Add kurz vor dem Sturm, das zweite danach.",

	DGN_TIP_MC_MUROJIN_DPS = "DPS: Beide Bosse müssen kurz nacheinander sterben — behalt beide Lebensbalken im Auge und wechsle früh, denn ein allein Überlebender geht in den Berserker.",
	DGN_TIP_MC_RAKTUL_DPS = "DPS: Erst die Totems, dann zurück auf den Boss. In der Seelenphase zählt dein Schaden kaum — nutz die Zeit für Crowd-Control und Unterbrechungen.",
	DGN_TIP_MC_VORDAZA_DPS = "DPS: Die Phantome sind dein Job: töte sie, bevor sie jemanden erreichen, aber eins nach dem anderen — jeder Tod ist Gruppenschaden, dem niemand ausweichen kann.",

	DGN_TIP_MR_KYSTIA_DPS = "DPS: Zuerst Nibbles, nicht Kystia. Erreicht Nibbles 20%, wechsle auf Kystia und nutze deine Cooldowns. Unterbrich oder stunne die Kopien von {SPELL:1264095}.",
	DGN_TIP_MR_LITHIEL_DPS = "DPS: Kicke Chaos Bolt und die Wild Imps. Töte jeden Dämon, bevor {SPELL:1224478} ihn berührt.",
	DGN_TIP_MR_XATHUUX_DPS = "DPS: Wechsle auf die Axt, sobald sie landet. Heb deine Cooldowns für {SPELL:474197} auf: Dann erleidet er 30% mehr Schaden.",
	DGN_TIP_MR_ZAEN_DPS = "DPS: Steh hinter einer Kiste, bevor {SPELL:1218347} feuert, nicht danach. Mit {SPELL:1214357} gehst du weg von den normalen Kisten; auf Mythisch bringst du es zu einer grünen Kiste.",

	DGN_TIP_MT_ARCANOTRON_DPS = "DPS: Fang die Energy Orbs während des Auftankens ab und spar deine Cooldowns dafür auf: in diesem Fenster erleidet er +20% Schaden.",
	DGN_TIP_MT_DEGENTRIUS_DPS = "DPS: Soak je einen Einschlag der Unstable Void Essence, sonst bricht sie aus. Wenn dein Entropy-DoT gleich ausläuft, geh vorher aus der Gruppe raus.",
	DGN_TIP_MT_GEMELLUS_DPS = "DPS: Brich deine Verbindung, bevor du weitermachst — jeder Punkt, der in seinen Absorb-Schild geht, ist verschenkt.",
	DGN_TIP_MT_SERANEL_DPS = "DPS: Dispell oder stiehl den Hastening Ward jedes Mal, wenn er landet. Geh für die Welle in die Suppression Zone und dann wieder raus — sie macht dich stumm.",

	DGN_TIP_NX_KASRETH_DPS = "DPS: Entfern deinen Debuff, indem du in einen Leyline-Strahl trittst — der kurze Stun kostet weniger, als ihn zu behalten. Sonst kreuz niemals eine Leyline.",
	DGN_TIP_NX_LOTHRAXION_DPS = "DPS: Wenn er sich zwischen seinen Abbildern versteckt, find das echte und unterbrich ihn — Schaden auf die Abbilder ist verschenkt.",
	DGN_TIP_NX_NYSARRA_DPS = "DPS: Adds vor Boss, immer — sie heilt sich an jedem, den du stehen lässt. Wechsle, sobald sie erscheinen, statt deinen Zauber auf ihr zu Ende zu bringen.",

	DGN_TIP_PS_GARFROST_DPS = "DPS: Erz ist Deckung: stell dich für den Schmiedepuls hinter einen Brocken. Halt 5+ Meter Abstand zum Tank, damit der Schlag dich nicht mitnimmt.",
	DGN_TIP_PS_KRICKICK_DPS = "DPS: Wenn Krick sich zu einem Ritualkreis teleportiert, wechsle auf die Shades. Von Ick fixiert? Lauf weit außen — alle anderen schlagen weiter.",
	DGN_TIP_PS_TYRANNUS_DPS = "DPS: Markiert? Stell dich neben Bone Piles, damit sie einfrieren; gefrorene Haufen können keine Adds erwecken. Erheben sich doch welche, sterben die Plaguespreader zuerst.",

	DGN_TIP_SR_ARAKNATH_DPS = "DPS: Blockier die Konstrukt-Strahlen mit deinem Körper — jeder Strahl, der ankommt, heilt ihn wieder hoch.",
	DGN_TIP_SR_RANJIT_DPS = "DPS: Ein Positionskampf, kein Zielkampf: tritt für die Linie zur Seite, web dich um die Wirbel und achte darauf, was hinter dir liegt, wenn er wegschleudert.",
	DGN_TIP_SR_RUKHRAN_DPS = "DPS: Quills heißt Säule, jedes Mal. Töte danach den Sunwing schnell; wen er fixiert, der hält Abstand.",
	DGN_TIP_SR_VIRYX_DPS = "DPS: Unterbrich den Tank-Nuke wirklich jedes Mal — es ist ein 3-Sekunden-Zauber. Befrei jeden, den der Solar Zealot packt, bevor er über den Balkon geht.",

	DGN_TIP_ST_LURA_DPS = "DPS: Führ deinen Strahl durch die Notes of Despair — die strahlen weiter, bis sie verstummt sind — und halt ihn von Verbündeten weg, denn er trifft sie auch.",
	DGN_TIP_ST_NEZHAR_DPS = "DPS: Töte die Tentakel und unterbrich den Tank-Nuke, wann immer es geht. Die Zonen ticken hart, also raus damit, statt auf Uptime zu spielen.",
	DGN_TIP_ST_SAPRISH_DPS = "DPS: Unterbrich den Zauber des Shadewing und setz deine Void Bombs an den Rand — je weniger Bomben auf dem Boden liegen, desto milder die Massenzündung.",
	DGN_TIP_ST_ZURAAL_DPS = "DPS: Räum die Coalesced-Void-Adds vor Crashing Void, sonst werden sie mit dir hineingezogen. Steh nie vor ihm.",

	DGN_TIP_VA_ATROXUS_DPS = "DPS: Wechsle auf den Toxic Creeper, sobald er nach jedem Brüllen erscheint. Töte ihn und geh dann zurück auf den Boss.",
	DGN_TIP_VA_CHARONUS_DPS = "DPS: Bevor die Orbs kommen, stell dich neben ein Schwerkraftloch. Jagt dich ein Orb, führ ihn sofort hinein; ein Tempo- oder Befreiungszauber oder eine Defensive hilft, wenn die Verlangsamung hoch stapelt.",
	DGN_TIP_VA_TAZRAH_DPS = "DPS: Bleib auf dem Boss. Die Ethereal Shades machen nur die Dash-Linien, und aktuelle Guides verlangen nicht, dass du sie tötest.",

	DGN_TIP_WS_DUO_DPS = "DPS: Teil deinen Schaden so auf, dass beide kurz nacheinander sterben, und halt Shadow Bolt unterbrochen. Kontrolliere die Dark Entity, die ein Fluch beschwört, statt sie zu jagen.",
	DGN_TIP_WS_EMBER_DPS = "DPS: Setz deine Feuerpfützen an den Rand, damit die Mitte sauber bleibt, und tritt zur Seite aus dem Atem, statt aus der Reichweite zu laufen.",
	DGN_TIP_WS_HEART_DPS = "DPS: Nimm bei 2-3 Stapeln eine Windpfeil-Fahrt, aber lass eine für die Explosion bei voller Energie frei.",
	DGN_TIP_WS_KROLUK_DPS = "DPS: Adds kommen bei etwa zwei Dritteln und einem Drittel Leben: wechsle sofort drauf, Phantasmal Mystic zuerst, und halt ihn unterbrochen.",
	DGN_TIP_KR_COUNCIL_STEPS = "1. Der Rat kämpft einer nach dem anderen: Kula, dann Aka'ali, dann Zanazal. Ein besiegtes Ratsmitglied kommt ab und zu zurück, um eine Fähigkeit einzusetzen. Der Kampf endet, wenn Zanazal stirbt.|n2. Kula: Geh für {SPELL:266206} von ihr weg und weiche danach den herumrollenden Äxten aus. {SPELL:266231} lässt einen zufälligen Spieler bluten — nutze eine Defensive.|n3. Aka'ali: {SPELL:267494} stürmt auf einen Spieler. Alle stellen sich auf diesen Spieler, um den Schaden zu teilen.|n4. Zanazal: Unterbrich {SPELL:267273}. Wenn er Totems ruft ({SPELL:267060}), töte zuerst das Explosive Totem, dann das Thundering Totem, dann das Torrent Totem.",
	DGN_TIP_KR_COUNCIL_QUICK_DPS = "Steh beim Ansturm im Stack, kick das Gift und töte zuerst das explodierende Totem.",
	DGN_TIP_KR_COUNCIL_QUICK_HEALER = "Heile die Axt-Blutung und bring alle vor dem Ansturm auf volles Leben.",
	DGN_TIP_KR_COUNCIL_QUICK_TANK = "Wenn Aka'ali dich wegschlägt, lauf vor ihr weg, bis der Debuff weg ist.",
	DGN_TIP_KR_COUNCIL_QUICK = "Kula: Geh weg, wenn sie sich dreht, und weiche den fliegenden Äxten aus.|nAka'ali: Sie stürmt auf einen Spieler. Alle stellen sich zu diesem Spieler, um den Treffer zu teilen.|nZanazal: Kick seinen Giftzauber und töte zuerst das explodierende Totem.",
	DGN_TIP_KR_COUNCIL_DPS = "DPS: Steh im Stack für {SPELL:267494}, kick weiter {SPELL:267273} und wechsle aufs Explosive Totem, sobald es erscheint.",
	DGN_TIP_KR_COUNCIL_HEALER = "Heiler: Heile die Blutung von {SPELL:266231} und bring alle vor {SPELL:267494} hoch. Bei Zanazal springt {SPELL:1305810} zwischen Spielern, und Poison Nova tickt auf allen, wenn sie nicht gekickt wird.",
	DGN_TIP_KR_COUNCIL_TANK = "Tank: {SPELL:266237} stößt dich zurück und lässt dich viel mehr körperlichen Schaden erleiden. Kite Aka'ali, bis der Debuff weg ist, oder nutze eine große Defensive.",
	DGN_TIP_KR_DAZAR_STEPS = "1. Phase 1: Dazar kämpft mit seinem Raptor Reban. Töte zuerst Reban und unterbrich sein {SPELL:269369}, eine Furcht. Reban springt mit {SPELL:269230} auf einen Spieler und beißt in einem Kegel — tritt da raus.|n2. {SPELL:1303115}: Dazar springt auf zwei Spieler. Diese zwei gehen auseinander, damit sie sich nicht gegenseitig treffen.|n3. Bei 80% Leben reitet Dazar auf seinem Raptor T'zala. Jetzt springt {SPELL:1303327} auf vier Spieler und trifft auch die ganze Gruppe — verteilt euch und seid voll geheilt.|n4. {SPELL:1303267} trifft die ganze Gruppe und brennt 15 Sekunden lang. Direkt danach fallen Speere, wo Spieler stehen — bleib in Bewegung und weiche den Kreisen von Impaling Spear aus.|n5. Auf Mythisch und Mythic+: {SPELL:1303267} verstärkt auch seine Schläge — sie schicken eine Goldwelle nach vorne. Der Tank dreht ihn von der Gruppe weg.",
	DGN_TIP_KR_DAZAR_QUICK_DPS = "Töte zuerst den kleinen Raptor und kick sein Brüllen.",
	DGN_TIP_KR_DAZAR_QUICK_HEALER = "Spar deine großen Heilungen für den Goldtreffer und die Raptorsprünge.",
	DGN_TIP_KR_DAZAR_QUICK_TANK = "Nutze deine größte Defensive für die Schwertkombo und halte den König weggedreht.",
	DGN_TIP_KR_DAZAR_QUICK = "Raptor: Töte zuerst den kleinen Raptor und kick sein gruseliges Brüllen.|nBeritten: Der König reitet seinen großen Raptor. Halte Abstand, wenn er springt, und sei voll geheilt.|nGold: Ein großer Feuertreffer auf alle, dann fallen Speere, wo du stehst. Bleib in Bewegung.",
	DGN_TIP_KR_DAZAR_DPS = "DPS: Töte zuerst Reban und kick {SPELL:269369}. Halte Platz frei, damit die Sprungziele auseinandergehen und du den Speeren ausweichen kannst.",
	DGN_TIP_KR_DAZAR_HEALER = "Heiler: Spar deine großen Cooldowns für {SPELL:1303267} und {SPELL:1303327}. Achte auf die Blutungen von Impaling Spear und {SPELL:1303488}.",
	DGN_TIP_KR_DAZAR_TANK = "Tank: Große Defensive für {SPELL:268586} — die Treffer werden gegen Ende stärker. Sobald T'zala dabei ist, trifft {SPELL:1303488} dich auch und lässt dich mehr körperlichen Schaden erleiden, also plane deine Cooldowns für beides. Dreh Dazar von der Gruppe weg.",
	DGN_TIP_KR_MCHIMBA_STEPS = "1. {SPELL:267618}: Der Boss saugt einen Spieler aus. Alle anderen treten aus den Säurekreisen, die er verspritzt. Bist du es, nutze eine Defensive. Danach bleibst du langsam und schwach, bis du über 90% Leben geheilt bist.|n2. {SPELL:1311956} zielt auf einen Spieler und hinterlässt brennenden Boden. Leg ihn am Rand ab, weg vom Boss und den Särgen.|n3. {SPELL:1312146} trifft die ganze Gruppe und öffnet Särge: Zwei Half-Finished Mummies kommen heraus. Töte sie und unterbrich ihr Wretched Discharge.|n4. {SPELL:267702}: Ein Spieler wird in einen der Särge gesperrt. Bist du es, drück den Struggle-Knopf, damit dein Sarg wackelt. Alle anderen: Such den wackelnden Sarg und klick ihn schnell an. Jeder leere Sarg, den er vorher öffnet, lässt eine Finished Mummy frei.",
	DGN_TIP_KR_MCHIMBA_QUICK_DPS = "Kick die Mumien und hilf, den wackelnden Sarg zu finden.",
	DGN_TIP_KR_MCHIMBA_QUICK_HEALER = "Heile den ausgesaugten Spieler fast voll, das nimmt die Verlangsamung weg.",
	DGN_TIP_KR_MCHIMBA_QUICK_TANK = "Schnapp dir die Mumien und halte sie neben dem Boss.",
	DGN_TIP_KR_MCHIMBA_QUICK = "Aussaugen: Saugt der Boss dich aus, nutze eine Defensive. Alle anderen treten aus den Säurekreisen.|nFeuer: Leg deine Feuerpfütze an den Rand, weg vom Boss und den Särgen.|nSarg: Ein Freund wird in einen Sarg gesperrt. Such den, der wackelt, und klick ihn schnell an.",
	DGN_TIP_KR_MCHIMBA_DPS = "DPS: Kick das Wretched Discharge der Mumien. Geh während {SPELL:267702} zu den Särgen und such den wackelnden — klick nicht wahllos.",
	DGN_TIP_KR_MCHIMBA_HEALER = "Heiler: Wechsle sofort auf das Ziel von {SPELL:267618} und heile es danach über 90% — das beendet die Verlangsamung. Bring die Gruppe vor {SPELL:1312146} hoch. Wretched Discharge ist eine Krankheit, die du bannen kannst.",
	DGN_TIP_KR_MCHIMBA_TANK = "Tank: Nimm die Mumien auf und stapel sie für Cleave nahe bei Mchimba. Park sie nicht vor einem Sarg.",
	DGN_TIP_KR_SERPENT_STEPS = "1. {SPELL:265773} legt brennendes Gold auf zwei Spieler. Wenn es endet, hinterlässt du dort, wo du stehst, eine Pfütze aus {SPELL:265914} — geh vorher an den Rand und leg sie neben die anderen Pfützen.|n2. {SPELL:265923} erweckt die Pfützen als Animated Gold, das zum Boss kriecht. Töte, verlangsame oder betäube es, bevor eins ihn erreicht — jedes, das ankommt, gibt ihm einen Schild und mehr Schaden.|n3. {SPELL:1311987}: fünf Sekunden Schaden auf die ganze Gruppe, der dich auch zurückschiebt. Sei voll geheilt und nutze eine Defensive.|n4. Steh nie in den Goldpfützen.",
	DGN_TIP_KR_SERPENT_QUICK_DPS = "Töte zuerst die Goldklumpen — keiner darf den Boss erreichen.",
	DGN_TIP_KR_SERPENT_QUICK_HEALER = "Heile die zwei Spieler mit Goldbrand und spar dir eine große Heilung für den Wind auf.",
	DGN_TIP_KR_SERPENT_QUICK_TANK = "Nutze eine Defensive für den Schwanzschlag und zieh den Boss von den Goldklumpen weg.",
	DGN_TIP_KR_SERPENT_QUICK = "Gold: Wenn dein Goldbrand endet, bleibt eine Pfütze liegen. Leg sie am Rand neben die anderen Pfützen.|nAdds: Die Pfützen erwachen und kriechen zum Boss. Töte sie, bevor sie ihn berühren.|nWind: Ein starker Wind trifft alle und schiebt dich zurück. Sei voll geheilt.",
	DGN_TIP_KR_SERPENT_DPS = "DPS: Erst Animated Gold, dann der Boss. Nutze Verlangsamungen, Stuns und Cleave, und halte alle Pfützen zusammen, damit die Adds als ein Haufen erwachen.",
	DGN_TIP_KR_SERPENT_HEALER = "Heiler: Heile die zwei Ziele von {SPELL:265773} durch das Brennen. Nutze einen Heil-Cooldown für {SPELL:1311987}.",
	DGN_TIP_KR_SERPENT_TANK = "Tank: Defensive für {SPELL:265910}. Wenn das Animated Gold erwacht, zieh den Boss davon weg, damit die DPS mehr Zeit haben.",
	DGN_TIP_RL_KOKIA_STEPS = "1. Molten Boulder ({SPELL:372110}): Kokia wirft einen brennenden Felsbrocken, der geradeaus rollt und dann explodiert. Tritt aus seiner Bahn und bleib weg von der Stelle, an der er stoppt. Er stößt jeden zurück, den er berührt.|n2. Ritual of Blazebinding ({SPELL:372864}): Ein Feuer-Add, der Blazebound Firestorm, erscheint bei einem Spieler und verbrennt jeden im Umkreis von 12 Metern. Bist du es, geh von der Gruppe weg, bleib aber nah am Boss.|n3. Alle wechseln sofort auf den Blazebound Firestorm und unterbrechen seine Blaze Volley.|n4. Bevor das Add stirbt, geh mindestens 20 Meter davon weg. Seine Todesexplosion (Burnout) trifft sehr hart.|n5. Auf Mythisch und Mythic+: Brennender Boden ({SPELL:372820}) bleibt liegen. Tritt raus und bewege den Kampf langsam durch den Raum, damit immer Platz frei ist.",
	DGN_TIP_RL_KOKIA_QUICK_DPS = "Schlag zuerst das Feuer-Add, kick seine Zauber und lauf weg, bevor es stirbt.",
	DGN_TIP_RL_KOKIA_QUICK_HEALER = "Das Feuer-Add verbrennt alle und der Tank blutet, also heil kräftig und bleib weg, wenn es stirbt.",
	DGN_TIP_RL_KOKIA_QUICK_TANK = "Nutze eine Defensive für jede Schlagkombo und führ den Boss langsam durch den Raum.",
	DGN_TIP_RL_KOKIA_QUICK = "Felsbrocken: Ein Feuerbrocken rollt geradeaus, also geh ihm aus dem Weg.|nFeuer-Add: Erscheint ein Feuermonster, schlagen alle drauf und stoppen seine Zauber.|nAdd stirbt: Lauf weit weg, bevor es stirbt, denn es explodiert.",
	DGN_TIP_RL_KOKIA_DPS = "DPS: Wechsle auf den Blazebound Firestorm, sobald er erscheint, und kick seine Blaze Volley. Nahkämpfer: Lauf 20 Meter raus, bevor er stirbt.",
	DGN_TIP_RL_KOKIA_HEALER = "Heiler: Der Inferno-Zauber des Adds verbrennt die ganze Gruppe, und Searing Blows hinterlässt eine Blutung auf dem Tank. Bleib selbst aus der Todesexplosion des Adds.",
	DGN_TIP_RL_KOKIA_TANK = "Tank: Nutze eine Defensive für jedes Searing Blows ({SPELL:372858}): vier schnelle Treffer, die eine Blutung stapeln. Halte Kokia nahe am Add, damit die DPS cleaven können, aber geh aus seiner 20-Meter-Todesexplosion raus. Bewege sie langsam durch den Raum, damit Platz frei bleibt.",
	DGN_TIP_RL_KYRAKKA_STEPS = "1. Erkhart kämpft am Boden, während seine Drachin Kyrakka um die Plattform fliegt. Schlag Kyrakka, wann immer sie in Reichweite ist: Sie soll zuerst sterben. Weiche ihrem Feuerkegel aus ({SPELL:381525}).|n2. Inferno Spit ({SPELL:381602}): 2 Spieler brennen 6 Sekunden lang, dann explodieren sie und hinterlassen Feuer am Boden ({SPELL:384773}). Bist du es, geh vor dem Ende an den Rand, weg von der Gruppe.|n3. Winds of Change ({SPELL:381517}): Wind schiebt Spieler und das Feuer in fester Reihenfolge (Nordwest, Südwest, Südost, Nordost). Lauf dagegen an und lass dich nicht ins Feuer wehen. Leg dein Feuer dort ab, wo der Wind es von der Gruppe wegträgt.|n4. Wenn einer der beiden etwa 40 bis 50% Leben erreicht (Guides sind sich uneinig), landet Kyrakka und Erkhart reitet auf ihr. Jetzt bekommen 3 Spieler Inferno Spit. Spar Cooldowns für diesen Teil.|n5. Auf Mythisch und Mythic+: Interrupting Cloudburst ({SPELL:381516}) trifft alle und sperrt deine Zauber für 2 Sekunden. Hör kurz vorher auf zu zaubern.",
	DGN_TIP_RL_KYRAKKA_QUICK_DPS = "Schlag zuerst die Drachin; auf Mythisch hörst du kurz vor dem großen Sturm auf zu zaubern.",
	DGN_TIP_RL_KYRAKKA_QUICK_HEALER = "Entferne den Debuff vom Tank nach jedem großen Schlag und heile die brennenden Spieler.",
	DGN_TIP_RL_KYRAKKA_QUICK_TANK = "Nutze eine Defensive für seinen großen Schlag und bitte den Heiler, den Debuff zu entfernen.",
	DGN_TIP_RL_KYRAKKA_QUICK = "Drache: Schlag die Drachin, wann immer du sie erreichst, und weiche ihrem Feueratem aus.|nFeuer: Brennst du, geh an den Rand, damit dein Feuer weg von der Gruppe landet.|nWind: Der Wind schiebt dich und das Feuer, also lauf dagegen an und bleib aus den Flammen.",
	DGN_TIP_RL_KYRAKKA_DPS = "DPS: Schlag Kyrakka, wann immer du sie erreichst, und spar Burst für ihre Landung. Auf Mythisch und Mythic+ hören Caster vor Interrupting Cloudburst auf zu zaubern.",
	DGN_TIP_RL_KYRAKKA_HEALER = "Heiler: Banne Stormslam nach jedem Treffer vom Tank, vor dem nächsten. Ziele von Inferno Spit erleiden schweren Schaden, also heile sie hoch. Auf Mythisch und Mythic+ hör vor Interrupting Cloudburst auf zu zaubern.",
	DGN_TIP_RL_KYRAKKA_TANK = "Tank: Nutze eine Defensive für jedes Stormslam ({SPELL:381512}). Es hinterlässt einen stapelnden Magie-Debuff, durch den du mehr Naturschaden erleidest, also bitte um einen Bann. Zieh Erkhart nach jedem Wind schnell aus dem Feuer.",
	DGN_TIP_RL_MELIDRUSSA_STEPS = "1. Hailburst ({SPELL:1307297}): Sie trifft die ganze Gruppe und wirft eine Eismine auf jeden Spieler. Stellt euch zusammen an einen Rand, damit die Minen an einer Stelle landen. Berühr nie eine Mine: Sie wirft dich hoch und verlangsamt deine Angriffe und Zauber 20 Sekunden lang um die Hälfte.|n2. Chillstorm ({SPELL:1307308}): Ein Froststurm landet auf einem Spieler und zieht alle zu seiner Mitte. Bist du es, lauf von der Gruppe weg. Bleib aus der Mitte ({SPELL:372963}): Dort ist der Frostschaden verdoppelt. Nach 7 Sekunden explodiert er und stößt alle weg, also steh nicht mit Minen im Rücken.|n3. Bei 66% und 33% Leben ruft sie Infused Whelps ({SPELL:373046}). Töte sie schnell.|n4. Unterbrich Frigid Shard, den Zauber, den sie auf den Tank wirkt.|n5. Auf Mythisch und Mythic+: Nach den Whelps versteckt sie sich in einem Eisschild (Ice Bulwark) und pulsiert Frostschaden auf alle, der immer weiter wächst (Frost Overload). Brich den Schild schnell, dann unterbrich sie. Laut Guides wirkt der Kick, sobald der Schild weg ist.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_DPS = "Töte zuerst die Babydrachen, und auf Mythisch brich ihren Eisschild.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_HEALER = "Heile die ganze Gruppe durch die Eisexplosionen und den Sturm.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_TANK = "Schnapp dir die Babydrachen sofort und kick den Zauber, den sie auf dich wirkt.",
	DGN_TIP_RL_MELIDRUSSA_QUICK = "Minen: Stell dich mit allen an einen Rand, wenn sie Eis wirft, und berühr nie die Minen.|nSturm: Ist der Sturm auf dir, lauf von allen weg und bleib aus seiner Mitte.|nWelpen: Töte die Babydrachen schnell, und auf Mythisch brich auch ihren Eisschild.",
	DGN_TIP_RL_MELIDRUSSA_DPS = "DPS: Wechsle auf die Whelps, sobald sie erscheinen. Auf Mythisch und Mythic+ spar Burst, um den Eisschild zu brechen, dann kick Frost Overload.",
	DGN_TIP_RL_MELIDRUSSA_HEALER = "Heiler: Hailburst und Chillstorm treffen die ganze Gruppe, und der Sturm explodiert am Ende. Bring alle vor der Explosion hoch. Auf Mythisch und Mythic+ bringt die Schildphase Frostschaden auf alle, der wächst, bis der Schild bricht.",
	DGN_TIP_RL_MELIDRUSSA_TANK = "Tank: Nimm die Infused Whelps sofort auf und halte sie für Cleave am Boss. Ihre Treffer stapeln Cold Claws auf dir; zu viele Stapel frieren dich ein, also müssen sie schnell sterben. Kick Frigid Shard, wenn es sonst keiner tut.",
	DGN_TIP_TS_ADDERIS_STEPS = "1. Storm Blessed legt einen Schild auf einen der beiden Bosse, und dieser Boss nimmt fast keinen Schaden. Schlag den OHNE Schild (beim Pull Adderis) und wechsle, sobald der Schild wandert.|n2. {SPELL:1311805}: Bist du markiert, geh an den Rand und leg deine Pfütze dort ab. Die Pfützen bringen dich zum Schweigen, also bleib draußen.|n3. {SPELL:1289059}: Alle werden zurückgestoßen. Verteilt euch etwas und stell dich so, dass der Stoß dich nicht in eine Pfütze wirft.|n4. {SPELL:1288049} kommt direkt nach dem Rückstoß: Lauf zurück und stack dich am Boss, um den Treffer zu teilen, und geht vor der zweiten Explosion gemeinsam raus.",
	DGN_TIP_TS_ADDERIS_QUICK_DPS = "Schlag nur den Boss ohne Schild und wechsle schnell, wenn der Schild wandert.",
	DGN_TIP_TS_ADDERIS_QUICK_HEALER = "Heile die Spieler, die der Wind trifft, und bring alle vor dem Stoß auf volles Leben.",
	DGN_TIP_TS_ADDERIS_QUICK_TANK = "Nutze eine Defensive für Overload und halte beide Bosse nah beieinander.",
	DGN_TIP_TS_ADDERIS_QUICK = "Schild: Schlag den Boss ohne Schild und wechsle, wenn der Schild springt.|nPfützen: Bist du markiert, leg deine Pfütze am Rand ab und bleib aus Pfützen raus.|nStoß: Lauf nach dem Stoß zurück und stell dich mit allen auf den Boss, um den Treffer zu teilen.",
	DGN_TIP_TS_ADDERIS_DPS = "DPS: Schlag nie den geschützten Boss — er nimmt fast keinen Schaden. Wechsle, sobald der Schild wandert, auch mitten in deiner Rotation.",
	DGN_TIP_TS_ADDERIS_HEALER = "Heiler: Heile gezielt die Spieler, die Gust trifft. Der Rückstoß direkt in das Gruppen-Soak ist der gefährlichste Moment — bring vorher alle auf volles Leben.",
	DGN_TIP_TS_ADDERIS_TANK = "Tank: Nutze eine Defensive für {SPELL:1311804}. Halte beide Bosse nah beieinander, damit die Gruppe wechseln kann, ohne durch Pfützen zu laufen.",
	DGN_TIP_TS_AVATAR_STEPS = "1. Du gewinnst, indem du den Avatar auf volles Leben heilst, nicht indem du ihn tötest. Töte zuerst die Essence Defilers: Ihr {SPELL:1301202} stoppt jede Heilung am Avatar.|n2. Töte den Corrupted Guardian. Er hinterlässt drei Kugeln (Corrupted Lifeforce): Drei verschiedene DPS schnappen sich schnell je eine. Eine geschnappte Kugel heilt den Avatar; eine verpasste Kugel explodiert auf der ganzen Gruppe.|n3. Twisted Hexxers: Unterbrich Flame Shock. Hast du {SPELL:1311981}? Geh vor dem Ende von der Gruppe weg und lass die Zone dort liegen.|n4. Sind die Defilers tot, heile den Avatar. Faithless Tormentors erscheinen und jagen den Heiler: Betäube und verlangsame sie und bring sie unter 25% Leben — dann frisst der Avatar sie und heilt sich selbst.",
	DGN_TIP_TS_AVATAR_QUICK_DPS = "Töte zuerst die Defilers, dann schnapp dir je eine Kugel.",
	DGN_TIP_TS_AVATAR_QUICK_HEALER = "Heile den Avatar, sobald die Defilers tot sind, und lauf weiter vor den Jägern weg.",
	DGN_TIP_TS_AVATAR_QUICK_TANK = "Halte das große Add in einer Ecke und bleib weg von den Kugeln.",
	DGN_TIP_TS_AVATAR_QUICK = "Ziel: Töte zuerst die Defilers, dann heile den Avatar ganz voll, um zu gewinnen.|nKugeln: Stirbt das große Add, schnappen sich drei DPS schnell je eine Kugel.|nJäger: Betäube die Adds, die den Heiler jagen, und schlag sie runter; dann frisst der Avatar sie.",
	DGN_TIP_TS_AVATAR_DPS = "DPS: Töte zuerst die Essence Defilers, dann den Guardian. Schnapp dir je eine Kugel (sie gibt dir {SPELL:1300877}, also nutze eine Defensive), kick Flame Shock und bring die Tormentors mit Stuns und AoE runter.",
	DGN_TIP_TS_AVATAR_HEALER = "Heiler: Heile den Avatar, sobald die Defilers tot sind — so gewinnt ihr den Kampf. Die Tormentors rennen auf dich zu und jeder Treffer senkt deine Heilung, also bleib in Bewegung. Überlass die Kugeln den DPS.",
	DGN_TIP_TS_AVATAR_TANK = "Tank: Halte den Corrupted Guardian in einer Ecke weg von der Gruppe und nutze eine Defensive für Tainted Strike. Schnapp dir keine Kugeln: {SPELL:1300877} lässt dich viel mehr körperlichen Schaden erleiden.",
	DGN_TIP_TS_GALVAZZT_STEPS = "1. {SPELL:1291618}: Drei Türme schießen Strahlen auf Galvazzt. Stell dich in einen Strahl, zwischen Turm und Boss, damit er keine Energie bekommt.|n2. Teilt die Strahlen auf: ein Spieler pro Strahl, abwechselnd zwischen den Runden. Einen Strahl zu blocken gibt dir {SPELL:266923}: Schaden über Zeit, und du erleidest mehr körperlichen Schaden.|n3. Lass nie einen Strahl offen. Bei voller Energie wirkt er Consume Charge, das die Gruppe hart trifft und oft auslöscht.|n4. {SPELL:1309525}: Schaden auf die ganze Gruppe, und es hinterlässt ein {SPELL:1291815} am Boden. Tritt da raus.",
	DGN_TIP_TS_GALVAZZT_QUICK_DPS = "Bleib in deinem Strahl, auch wenn du den Boss von dort nicht treffen kannst.",
	DGN_TIP_TS_GALVAZZT_QUICK_HEALER = "Halte die Spieler in den Strahlen am Leben.",
	DGN_TIP_TS_GALVAZZT_QUICK_TANK = "Bleib aus den Strahlen und zieh den Boss von den Zonen am Boden weg.",
	DGN_TIP_TS_GALVAZZT_QUICK = "Strahlen: Stell dich in einen Strahl, zwischen Turm und Boss, damit er sich nicht aufladen kann.|nAbwechseln: Ein Spieler pro Strahl, immer abwechselnd, und nie einen Strahl offen lassen.|nBoden: Tritt nach dem großen Gruppentreffer aus der Zone am Boden.",
	DGN_TIP_TS_GALVAZZT_DPS = "DPS: Dein Strahl geht vor deinem Schaden — tritt nicht raus, um den Boss zu schlagen. Wechsle dich mit den anderen ab und nutze in deiner Runde eine Defensive.",
	DGN_TIP_TS_GALVAZZT_HEALER = "Heiler: Die Strahl-Soaker erleiden stetigen Schaden — halte sie oben und nimm bei Bedarf selbst einen Strahl. Halte einen Cooldown für {SPELL:1309525} bereit.",
	DGN_TIP_TS_GALVAZZT_TANK = "Tank: Soak die Strahlen nicht — {SPELL:266923} lässt dich viel mehr körperlichen Schaden erleiden. Zieh den Boss von jedem {SPELL:1291815} weg, an eine Stelle, wo die Strahlen leicht erreichbar bleiben.",
	DGN_TIP_TS_MEREKTHA_STEPS = "1. {SPELL:1290029}: Schlangen fesseln einige Spieler. Bist du markiert, stell dich nah zu den anderen beim Boss, damit ein AoE-Stun oder Crowd Control jeden Knoten löst. Dann töte die Schlangen.|n2. {SPELL:1289109}: Bist du markiert, geh an den Rand des Raums und leg die Pfütze dort ab, nicht in der Mitte.|n3. {SPELL:1293048}: Schaden auf die ganze Gruppe plus Rückstoß. Steh nicht dort, wo der Stoß dich in eine Pfütze wirft.|n4. {SPELL:1289205} und {SPELL:264172}: Adds schlüpfen, dann gräbt sie sich ein und kann nicht getroffen werden. Weiche ihrem Weg aus (er betäubt dich), unterbrich Poison Spit der Toxic Vipers und töte alle Adds — das holt sie wieder hoch.",
	DGN_TIP_TS_MEREKTHA_QUICK_DPS = "Wenn sie sich eingräbt, töte schnell alle Adds; das holt sie zurück.",
	DGN_TIP_TS_MEREKTHA_QUICK_HEALER = "Spar dir einen Cooldown für den Sturm, der alle trifft.",
	DGN_TIP_TS_MEREKTHA_QUICK_TANK = "Nutze eine Defensive für ihren großen Biss und schnapp dir die Adds, wenn sie sich eingräbt.",
	DGN_TIP_TS_MEREKTHA_QUICK = "Schlangen: Fesseln dich Schlangen, stell dich nah zu den anderen, damit ein Stun alle befreit.|nSpucke: Bist du markiert, leg deine Pfütze am Rand des Raums ab.|nUntergrund: Sie versteckt sich unter dem Boden. Weiche ihrem Weg aus und töte alle Adds, um sie zurückzuholen.",
	DGN_TIP_TS_MEREKTHA_DPS = "DPS: Befreie gefesselte Spieler zuerst mit einem Stun oder AoE-Crowd-Control. Töte während Burrow jedes Add schnell — die Phase endet, wenn alle tot sind — und kick Poison Spit.",
	DGN_TIP_TS_MEREKTHA_HEALER = "Heiler: {SPELL:1293048} trifft die ganze Gruppe — plane einen Cooldown dafür ein. Kommt ein Poison Spit durch, banne das Gift, wenn du kannst.",
	DGN_TIP_TS_MEREKTHA_TANK = "Tank: Nutze eine Defensive für jedes {SPELL:1290797}. Nimm während Burrow die Adds auf und park den Storm Serpent am Rand, weil er auch Pfützen hinterlässt.",
})

merge(ns._mhLocales and ns._mhLocales.frFR, {
	-- Windrunner Spire ----------------------------------------------------------
	DGN_TIP_WS_DUO_STEPS = "1. Deux boss — répartis les dégâts pour qu'ils meurent à peu près en même temps.|n2. Interromps Shadow Bolt ; sors des cercles de crachat ({SPELL:472745}) — ne gaspille pas le sol.|n3. Maudit ({SPELL:474105}) ? Fais-le dissiper vite — ou contrôle la Dark Entity qu'il fait apparaître jusqu'à ce qu'elle disparaisse.|n4. Accroché par {SPELL:472793} pendant le cri ? Place-toi pour être tiré À TRAVERS la dame fantôme — ça brise son incantation.",
	DGN_TIP_WS_DUO_TANK = "Tank : défensif pour {SPELL:472888} ; déplace les boss quand le sol s'encombre.",
	DGN_TIP_WS_DUO_HEALER = "Heal : gros dégâts de groupe pendant {SPELL:472736} ; dissipe {SPELL:474105} vite.",

	DGN_TIP_WS_EMBER_STEPS = "1. Feu = mauvais. Pose les flaques de feu ({SPELL:466556}) sur les bords, garde le centre propre.|n2. À pleine énergie : cours VERS le boss pour {SPELL:465904}, puis esquive chaque Fire Breath.|n3. Les vieilles flaques font naître des tourbillons de feu — continue d'esquiver.",
	DGN_TIP_WS_EMBER_TANK = "Tank : défensif pour {SPELL:466064}.",
	DGN_TIP_WS_EMBER_HEALER = "Heal : lourds dégâts de groupe pendant {SPELL:465904}.",

	DGN_TIP_WS_KROLUK_STEPS = "1. Cercles bruns = mauvais, sors-en.|n2. Colle-toi à un allié avant la fin de {SPELL:1253026} (superpose les cercles violets).|n3. Fixé ou cible du saut ({SPELL:1283247}) ? Emmène-le LOIN du groupe.|n4. Quand des adds apparaissent (vers deux tiers et un tiers de vie) : tue-les vite — le Phantasmal Mystic d'abord, et interromps-le sans cesse.",
	DGN_TIP_WS_KROLUK_TANK = "Tank : défensif pour {SPELL:467620} ; sois prêt à rattraper le second {SPELL:1283247}.",
	DGN_TIP_WS_KROLUK_HEALER = "Heal : dégâts de groupe pendant {SPELL:472043}.",

	DGN_TIP_WS_HEART_STEPS = "1. Les stacks de {SPELL:1216042} te rongent ? Monte sur une flèche de vent (Turbulent Arrow) à 2-3 stacks — elle retire le DoT et te fait sauter par-dessus l'onde de choc.|n2. Garde une flèche pour la grosse explosion à pleine énergie ({SPELL:468429}).|n3. Espacez-vous un peu pour {SPELL:1253979} et utilisez les grands cercles pour nettoyer le sol électrique.|n4. Ciblé par {SPELL:474528} ? Reste immobile et laisse les autres s'écarter ; tous les autres : sortez du cône frontal.",
	DGN_TIP_WS_HEART_TANK = "Tank : défensif pour {SPELL:472662} ; oriente la projection LOIN des flaques.",
	DGN_TIP_WS_HEART_HEALER = "Heal : remonte d'abord les joueurs avec beaucoup de stacks de {SPELL:1216042} ; soins supplémentaires après {SPELL:1253979}.",

	-- Maisara Caverns ------------------------------------------------------------
	DGN_TIP_MC_MUROJIN_STEPS = "1. Deux boss (chasseur et oiseau) — tue-les presque ensemble, sinon le survivant devient fou furieux.|n2. Pièges de glace ({SPELL:1243741}), cercles verts ({SPELL:1243900}) et le {SPELL:1260643} frontal = mauvais, reste dehors.|n3. Ciblé par {SPELL:1249478} (le piqué de l'oiseau) ? Cours DANS un piège de glace — le gel stoppe le piqué. Les autres : éloignez-vous de ce joueur.",
	DGN_TIP_MC_MUROJIN_TANK = "Tank : défensif pour {SPELL:1266480}.",
	DGN_TIP_MC_MUROJIN_HEALER = "Heal : dissipe {SPELL:1246666} (maladie) — lourds dégâts de groupe.",

	DGN_TIP_MC_VORDAZA_STEPS = "1. Le boss invoque des Unstable Phantoms ({SPELL:1251204}) qui poursuivent les joueurs. TUE-les avant qu'ils n'atteignent quelqu'un — un fantôme qui atteint sa cible (ou touche un autre fantôme) explose avec de lourds dégâts de proximité.|n2. Chaque fantôme tué hurle : dégâts de groupe inévitables — tue-les donc UN par UN.|n3. Esquive la vague frontale de {SPELL:1252054} (elle te repousse), les orbes flottants et Soulrot.|n4. Quelqu'un est pris dans un Deathshroud ? Libère-le vite ; interromps {SPELL:1250708} et esquive les swirls pendant ce temps.",
	DGN_TIP_MC_VORDAZA_TANK = "Tank : défensif pour {SPELL:1251554}.",
	DGN_TIP_MC_VORDAZA_HEALER = "Heal : chaque fantôme tué hurle ({SPELL:1251813}) = dégâts de groupe — soigne entre les kills espacés.",

	DGN_TIP_MC_RAKTUL_STEPS = "1. Le boss bondit sur trois joueurs ({SPELL:1252676}) et laisse des Soulbind Totems — espacez-vous pour que les totems tombent séparés, ne te fais pas écraser, et détruis-les vite.|n2. Reste hors du sol Chill of Death.|n3. Phase d'âme ({SPELL:1253788}) : tu es arraché de ton corps — contrôle et interromps les gros adds pendant que tu retournes à ton corps.|n4. Esquive les swirls du Deathgorged Vessel.",
	DGN_TIP_MC_RAKTUL_TANK = "Tank : défensif pour {SPELL:1251023} ; pose les flaques LOIN du groupe.",
	DGN_TIP_MC_RAKTUL_HEALER = "Heal : lourds dégâts de groupe pendant Deathgorged Vessel et quand les totems se brisent.",

	-- Murder Row -----------------------------------------------------------------
	DGN_TIP_MR_KYSTIA_STEPS = "1. Tue Nibbles d'abord. Kystia a un bouclier gangrené et ne prend presque aucun dégât tant que Nibbles est au-dessus de 20% de vie.|n2. À 20%, Nibbles se retourne contre Kystia avec {SPELL:1230304} : Kystia est étourdie et prend beaucoup plus de dégâts pendant un court moment. Passe sur Kystia maintenant et utilise tes gros cooldowns.|n3. {SPELL:1264095} : des copies de Kystia apparaissent et lancent Felstorm. Interromps, étourdis ou contrôle chaque copie.|n4. Reste hors du cône {SPELL:1253811} de Nibbles et hors du feu qu'il laisse au sol.|n5. En Héroïque et plus : {SPELL:474240} - elle saute sur un joueur et explose. Éloigne-toi d'elle.",
	DGN_TIP_MR_KYSTIA_QUICK_DPS = "Frappe d'abord le familier, puis le boss quand le familier a peu de vie.",
	DGN_TIP_MR_KYSTIA_QUICK_HEALER = "Retire vite le crachat des joueurs et garde un gros soin pour le changement de cible.",
	DGN_TIP_MR_KYSTIA_QUICK_TANK = "Oriente le cône de feu du familier loin du groupe.",
	DGN_TIP_MR_KYSTIA_QUICK = "Familier : Frappe d'abord le familier Nibbles, car le boss a un bouclier et ne prend presque rien.|nChangement : Quand Nibbles a peu de vie, elle étourdit le boss, alors frappe le boss fort.|nCopies : Des copies du boss apparaissent, alors interromps ou étourdis chacune.",
	DGN_TIP_MR_KYSTIA_TANK = "Tank : oriente le cône {SPELL:1253811} de Nibbles loin du groupe. Garde Kystia et Nibbles l'une près de l'autre pour que ton groupe puisse taper les deux en même temps. Le Chaos Barrage de Kystia te frappe fort, garde donc un défensif prêt.",
	DGN_TIP_MR_KYSTIA_HEALER = "Heal : dissipe vite Corroding Spittle (magie), surtout pendant {SPELL:1264095}. Garde un cooldown de soin pour la fenêtre de burn après {SPELL:1230304} : Kystia étourdie envoie des salves gangrenées sur le groupe.",

	DGN_TIP_MR_ZAEN_STEPS = "1. Des caisses tombent sur les joueurs ({SPELL:474765}). Sors des marqueurs. Les caisses posées sont ta couverture.|n2. {SPELL:1218347} : il vise tous ceux qu'il peut voir. Cache-toi derrière une caisse avant qu'il tire, pour qu'il ne te voie pas. Chacun a besoin de sa propre caisse.|n3. Tu as {SPELL:1214357} ? La bombe explose après 6 secondes et détruit les caisses près de toi. Éloigne-la des caisses dont vous avez besoin pour vous cacher.|n4. {SPELL:474478} : 3 secondes de gros dégâts sur tout le groupe. Sois pleine vie.|n5. En Mythique et Mythic+ : les caisses vertes gangrenées (Fel-Infused Freight) blessent tout le groupe en continu. Si tu as {SPELL:1214357}, emmène-la vers une caisse verte pour la détruire, et garde les caisses normales.",
	DGN_TIP_MR_ZAEN_QUICK_DPS = "Sois derrière une caisse avant le gros tir, pas après.",
	DGN_TIP_MR_ZAEN_QUICK_HEALER = "Retire le poison du tank et remonte tout le monde avant la fusillade.",
	DGN_TIP_MR_ZAEN_QUICK_TANK = "Utilise un défensif quand il te poignarde et fais retirer le poison.",
	DGN_TIP_MR_ZAEN_QUICK = "Caisses : Des caisses tombent du ciel ; écarte-toi, puis cache-toi derrière.|nTir : Quand il vise tout le monde, cache-toi derrière une caisse pour qu'il ne te voie pas.|nBombe : Si tu as la bombe, porte-la loin des caisses où vous vous cachez.",
	DGN_TIP_MR_ZAEN_TANK = "Tank : utilise un défensif pour {SPELL:1222795}. Il laisse aussi Heartstop Poison, qui réduit ta vie max : fais-le dissiper ou retire-le toi-même.",
	DGN_TIP_MR_ZAEN_HEALER = "Heal : dissipe Heartstop Poison du tank après {SPELL:1222795}. Remonte tout le monde avant {SPELL:474478}, et soigne le saignement de ceux que le tir a touchés.",

	DGN_TIP_MR_XATHUUX_STEPS = "1. {SPELL:1214637} : il lance sa hache sur un joueur. Si c'est toi, place-toi près du boss mais loin des autres. La hache reste et électrise tout le monde de plus en plus fort : détruis-la vite.|n2. Infernal Crush ({SPELL:1295452}) : des cercles apparaissent sous les joueurs. Espacez-vous pour ne pas vous toucher les uns les autres.|n3. {SPELL:474197} : dégâts sur tout le monde, puis pendant 15 secondes il attaque plus vite et prend 30% de dégâts en plus. Utilise tes cooldowns maintenant.|n4. Pendant la rage, il laisse du feu là où il marche ({SPELL:474234}). Reste hors du feu. Le tank le déplace lentement le long du bord de la salle.",
	DGN_TIP_MR_XATHUUX_QUICK_DPS = "Tue la hache d'abord et garde tes grosses attaques pour la rage.",
	DGN_TIP_MR_XATHUUX_QUICK_HEALER = "Prévois un gros soin pour la rage et remonte le tank avant le gros coup.",
	DGN_TIP_MR_XATHUUX_QUICK_TANK = "Utilise un défensif pour son gros coup et déplace-le lentement le long du bord quand il enrage.",
	DGN_TIP_MR_XATHUUX_QUICK = "Hache : Il lance sa hache ; garde-la près du boss et casse-la vite.|nCercles : Écarte-toi des autres quand un cercle apparaît sous toi.|nRage : En colère, il prend plus de dégâts, alors frappe fort et évite sa traînée de feu.",
	DGN_TIP_MR_XATHUUX_TANK = "Tank : utilise un défensif pour {SPELL:473898} ; il réduit tes soins reçus pendant 8 secondes. Tourne-le loin du groupe et place-le sur la hache pour qu'elle prenne les dégâts de zone. Pendant {SPELL:474197}, déplace-le lentement le long du bord pour garder le feu hors du centre.",
	DGN_TIP_MR_XATHUUX_HEALER = "Heal : {SPELL:474197} et Infernal Crush arrivent souvent ensemble, alors prévois un cooldown. Le tank reçoit beaucoup moins de soins après {SPELL:473898} ; remonte-le avant. Chaque seconde où la hache vit, le groupe prend plus de dégâts.",

	DGN_TIP_MR_LITHIEL_STEPS = "1. Interromps chaque Chaos Bolt. Mettez-vous d'accord sur un ordre d'interruptions.|n2. {SPELL:1218203} : des cercles tombent sur les joueurs. Espacez-vous de 6 mètres. Chaque cercle fait apparaître des Wild Imps : étourdis-les ou interromps-les et tuez-les ensemble.|n3. {SPELL:474408} : un gros démon arrive. Le tank le prend, tout le monde le tue.|n4. {SPELL:1224478} : une vague de feu gangrené traverse la salle. Tuez tous les démons avant qu'elle les atteigne, sinon ils deviennent bien plus rapides. Prends le Demonic Gateway pour que la vague te rate ; si elle te touche, tu prends plus de dégâts de feu.|n5. En Mythique et Mythic+ : un Infernal poursuit le tank. Il est intuable et le toucher peut te tuer. Le tank le garde loin du groupe et du portail.",
	DGN_TIP_MR_LITHIEL_QUICK_DPS = "Interromps le boss et les imps, et tue tous les démons avant la vague.",
	DGN_TIP_MR_LITHIEL_QUICK_HEALER = "Tout le monde prend des dégâts de feu tout le combat. Soigne d'abord ceux que la vague a touchés.",
	DGN_TIP_MR_LITHIEL_QUICK_TANK = "Attrape vite les démons. En Mythique, emmène l'Infernal loin de tout le monde.",
	DGN_TIP_MR_LITHIEL_QUICK = "Interruptions : Arrête chaque Chaos Bolt du boss.|nImps : Écarte-toi des autres, puis étourdis et tue vite les petits démons qui sortent.|nVague : Tue tous les démons avant la vague de feu, puis prends le portail pour qu'elle te rate.",
	DGN_TIP_MR_LITHIEL_TANK = "Tank : prends vite le Vilefiend, il frappe fort. Garde les Wild Imps groupés pour qu'on puisse les taper en zone. En Mythique, kite l'Infernal loin du groupe et jamais près du portail.",
	DGN_TIP_MR_LITHIEL_HEALER = "Heal : pendant tout le combat, le groupe subit des dégâts de feu constants. Ceux touchés par {SPELL:1224478} continuent de brûler et prennent plus de dégâts de feu : soigne-les en premier.",

	-- Den of Nalorakk -----------------------------------------------------------
	DGN_TIP_DN_HOARDMONGER_STEPS = "1. {SPELL:1234233} : il lance de la nourriture pourrie pendant quelques secondes. Esquive les impacts. Des Rotten Mushrooms verts poussent ensuite au sol.|n2. Marche sur chaque champignon avant qu'il éclate (environ 12 secondes). Espacez-vous pour n'en rater aucun. Chaque champignon te donne un poison, alors chacun son tour.|n3. {SPELL:1253268} est un cône frontal. Sors de la zone affichée. {SPELL:1235118} frappe tout le groupe, alors reste pleine vie.|n4. Trois fois, il court vers un tas de viande, d'os ou de champignons et gagne une nouvelle attaque. La viande renforce son rugissement. Les os donnent un coup au sol qui laisse des os brisés par terre ({SPELL:1235405}) : n'y marche pas. Les champignons, c'est plus de champignons à écraser.|n5. En Mythique et Mythic+ : chaque nouvelle attaque reste jusqu'à la fin du combat, donc elles s'additionnent. Les guides prennent la viande d'abord, les os ensuite, les champignons en dernier.",
	DGN_TIP_DN_HOARDMONGER_QUICK_DPS = "Aide à marcher sur les champignons, chacun son tour avec les autres.",
	DGN_TIP_DN_HOARDMONGER_QUICK_HEALER = "Soigne fort quand il rugit, et retire le poison de ceux qui marchent sur les champignons si tu peux.",
	DGN_TIP_DN_HOARDMONGER_QUICK_TANK = "Place le boss à côté du tas que tu veux : viande, puis os, puis champignons.",
	DGN_TIP_DN_HOARDMONGER_QUICK = "Champignons : Marche sur les champignons verts avant qu'ils éclatent, chacun son tour.|nCoup au sol : Le boss frappe le sol devant lui, alors sors de cette zone.|nTas : Il prend de la nourriture sur un tas et gagne un nouveau tour, alors évite les os qu'il laisse.",
	DGN_TIP_DN_HOARDMONGER_TANK = "Tank : il court vers le tas le plus proche, alors place-le à côté de celui que tu veux : viande d'abord, os ensuite, champignons en dernier. Garde les zones d'os loin de l'endroit où se tient le groupe.",
	DGN_TIP_DN_HOARDMONGER_HEALER = "Heal : utilise un cooldown de soin sur {SPELL:1235118} : il ignore l'armure et touche tout le monde. Ceux qui marchent sur les champignons prennent un poison (Toxic Spores) : dissipe-le si ta classe le peut, et garde-les pleine vie.",

	DGN_TIP_DN_SENTINEL_STEPS = "1. {SPELL:1235623} : de petites tornades tombent et errent longtemps dans la salle. Restez groupés pour qu'elles tombent au même endroit, puis éloignez-vous d'elles.|n2. {SPELL:1235783} : deux stalactites s'écrasent. Sors des cercles. Chacune laisse un add Fractured Shivercore.|n3. Les adds lancent Winter's Shroud. Interromps-le : chaque incantation fait subir plus de dégâts de givre à tout le groupe. Un add mort laisse un Snowdrift : de la neige profonde qui te ralentit, mais rien ne peut te déplacer tant que tu es dedans.|n4. {SPELL:1235656} : une grosse tempête frappe tout le monde et déplace les joueurs. Tuez un add juste avant et restez dans son Snowdrift jusqu'à la fin de la tempête. Puis tuez l'autre add.|n5. En Mythique et Mythic+ : un add qui meurt lâche des éclats de glace (Rimeshatter). Mettez exactement un joueur dans chaque cercle d'éclat. Un éclat raté frappe tout le groupe et immobilise tout le monde.",
	DGN_TIP_DN_SENTINEL_QUICK_DPS = "Interromps les adds chacun son tour et tue le premier add juste avant la tempête.",
	DGN_TIP_DN_SENTINEL_QUICK_HEALER = "Retire vite le debuff de givre et soigne tout le monde pendant la tempête.",
	DGN_TIP_DN_SENTINEL_QUICK_TANK = "Place le boss sur un add et garde-le loin des tornades.",
	DGN_TIP_DN_SENTINEL_QUICK = "Tornades : Reste avec les autres pour qu'elles tombent au même endroit, puis éloigne-toi.|nAdds : Deux adds de glace apparaissent ; interromps leur sort et tue-en un juste avant la tempête.|nTempête : Reste dans la neige de l'add mort, et la tempête ne pourra pas te déplacer.",
	DGN_TIP_DN_SENTINEL_TANK = "Tank : amène le boss sur un add pour que le groupe le touche en zone, et garde le boss loin des tornades. Aide à interrompre Winter's Shroud.",
	DGN_TIP_DN_SENTINEL_HEALER = "Heal : {SPELL:1235548} est un DoT de givre magique : dissipe-le vite, et soigne ceux que tu ne peux pas dissiper. La tempête frappe tout le monde, alors sois prêt à soigner le groupe.",

	DGN_TIP_DN_NALORAKK_STEPS = "1. {SPELL:1242860} : trois joueurs reçoivent une marque. Va au bord avant qu'elle se termine : un ours fantôme (un Echo) apparaît là où tu es. Mettez tous les Echoes ensemble, loin du groupe. Les Echoes blessent ceux qui sont près d'eux chaque fois qu'il lacère.|n2. {SPELL:1243011} : Nalorakk met Zul'jarra à terre et chaque Echo charge vers elle. Placez-vous autour d'elle comme un mur et bloquez les charges. Un Echo qui l'atteint blesse tout le groupe.|n3. {SPELL:1243569} : Nalorakk frappe le tank encore et encore. Zul'jarra dresse un bouclier qui divise ces dégâts par deux : tout le monde se place derrière son bouclier.|n4. Juste après, le tank seul entre dans Forceful Slam. Tous les autres en sortent. Si ça touche Zul'jarra à la place, tout le groupe prend des dégâts.|n5. En Mythique et Mythic+ : bloquer un Echo te donne aussi un saignement qui se cumule (Spectral Slash). Mettez un joueur dans chaque couloir de charge, et ne laissez jamais deux personnes bloquer le même Echo.",
	DGN_TIP_DN_NALORAKK_QUICK_DPS = "Mets-toi sur le chemin d'un ours fantôme, une personne par ours.",
	DGN_TIP_DN_NALORAKK_QUICK_HEALER = "Soigne fort le tank pendant les gros coups et remonte tout le monde avant le rugissement.",
	DGN_TIP_DN_NALORAKK_QUICK_TANK = "Cache-toi derrière le bouclier de Zul'jarra, puis prends seul le coup suivant.",
	DGN_TIP_DN_NALORAKK_QUICK = "Marques : Si tu as une marque, va au bord, car un ours fantôme y apparaît.|nCharge : Les ours fantômes foncent sur Zul'jarra, alors mets-toi sur leur chemin pour les arrêter.|nBouclier : Quand le boss frappe le tank plein de fois, tout le monde se cache derrière le bouclier de Zul'jarra.",
	DGN_TIP_DN_NALORAKK_TANK = "Tank : {SPELL:1243569} est sur toi. Reste derrière le bouclier de Zul'jarra et utilise un défensif. Puis entre seul dans Forceful Slam, loin du groupe.",
	DGN_TIP_DN_NALORAKK_HEALER = "Heal : le tank prend de gros coups pendant {SPELL:1243569}, puis Forceful Slam. Remonte le groupe avant Forceful Roar. En Mythic+, surveille les stacks de saignement sur les joueurs qui bloquent les Echoes.",

	-- The Blinding Vale -----------------------------------------------------------
	DGN_TIP_BV_TRINITY_STEPS = "1. Les trois boss partagent une seule barre de vie. Le tank les regroupe et tout le monde frappe les trois. Interromps le Light Bolt de Kezkitt.|n2. {SPELL:1234753} frappe le tank et laisse trois cercles verts. N'y va pas encore. Lekshi fonce ensuite à travers les trois cercles ({SPELL:1234850}) - reste hors de cette ligne.|n3. Quand {SPELL:1235564} commence, un joueur se place dans chaque cercle (le tank plus deux autres) jusqu'à la fin du rayon. Un cercle vide fait prendre de gros dégâts à tout le groupe plus tard.|n4. Après le rayon, les cercles deviennent du sol brûlant ({SPELL:1235828}). Sors-en ; le tank déplace les boss sur un sol propre. {SPELL:1261276} fait saigner un joueur au hasard : utilise un défensif ou retire le saignement.|n5. En Mythique et Mythic+ : après Thornblade, Lekshi saute sur ce joueur et projette des épines autour de lui. Ce joueur s'éloigne du groupe, puis sort des épines. Bedrock Slam envoie aussi des vagues de dégâts dans tout le groupe.",
	DGN_TIP_BV_TRINITY_QUICK_DPS = "Frappe les trois boss ensemble et interromps le sort de Kezkitt.",
	DGN_TIP_BV_TRINITY_QUICK_HEALER = "Garde en vie les joueurs dans les cercles et soigne celui qui saigne.",
	DGN_TIP_BV_TRINITY_QUICK_TANK = "Utilise un défensif sur le gros coup, puis sors les trois boss du sol brûlant.",
	DGN_TIP_BV_TRINITY_QUICK = "Trois boss : Ils partagent une barre de vie, alors frappe les trois ensemble.|nCercles : Quand le rayon arrive, un joueur reste dans chaque cercle jusqu'à la fin.|nCharge : Reste hors de la ligne entre les cercles et quitte les cercles quand ils brûlent.",
	DGN_TIP_BV_TRINITY_TANK = "Tank : utilise un défensif pour {SPELL:1234753}. Garde les trois groupés pour les dégâts de zone, reste dans un cercle pendant le rayon, puis sors les boss du sol brûlant avant le coup suivant.",
	DGN_TIP_BV_TRINITY_HEALER = "Heal : les trois joueurs dans les cercles prennent des dégâts réguliers - garde-les en vie, et soigne le saignement de {SPELL:1261276}. En Mythique, garde un cooldown pour les vagues de dégâts de groupe après Bedrock Slam.",

	DGN_TIP_BV_IKUZZ_STEPS = "1. {SPELL:1236746} frappe tout le monde et te repousse. Place-toi pour ne pas voler par-dessus un bord ou dans des racines.|n2. {SPELL:1236709} : il rugit et blesse tout le groupe pendant 6 secondes. Utilise un défensif si tu as peu de vie.|n3. {SPELL:1237091} : il poursuit un joueur pendant 10 secondes. Ce joueur court et le fait passer sur les racines au sol - ses pas les écrasent. S'il t'attrape, tu saignes et tu es étourdi ({SPELL:1272290}).|n4. À partir de 50% de vie, il entre en frénésie : il bouge plus vite et blesse le groupe en continu. Garde tes cooldowns pour ça.|n5. En Mythique et Mythic+ : après le piétinement, des racines attrapent chaque joueur quelques secondes plus tard, et d'autres racines poussent pendant le rugissement. Reviens vers le boss pour que le groupe casse les racines en zone, ou utilise un sort de libération.",
	DGN_TIP_BV_IKUZZ_QUICK_DPS = "Casse vite les racines et, s'il te poursuit, cours sur les racines.",
	DGN_TIP_BV_IKUZZ_QUICK_HEALER = "Garde tes gros soins pour quand il est à mi-vie.",
	DGN_TIP_BV_IKUZZ_QUICK_TANK = "Garde le boss près des joueurs coincés dans les racines, pour que tout le monde puisse les casser.",
	DGN_TIP_BV_IKUZZ_QUICK = "Piétinement : Il repousse tout le monde, alors ne reste pas près d'un bord.|nPoursuite : Il poursuit un joueur, qui court sur les racines pour qu'il les écrase.|nMi-vie : Il devient plus rapide et frappe plus fort, alors utilise tes gros sorts maintenant.",
	DGN_TIP_BV_IKUZZ_TANK = "Tank : garde Ikuzz près des joueurs enracinés pour que tout le monde puisse casser les racines en zone, et loin des bords à cause de la projection.",
	DGN_TIP_BV_IKUZZ_HEALER = "Heal : le piétinement et {SPELL:1236709} touchent tout le groupe. Garde tes gros cooldowns pour la frénésie à 50%, surtout quand il rugit pendant celle-ci. Un joueur attrapé prend de gros dégâts - remonte-le vite.",

	DGN_TIP_BV_RUIA_STEPS = "1. Forme de sélénien (100 à 70%) : interromps Warden's Wrath - il frappe le tank. Esquive les cercles de {SPELL:1240098}.|n2. {SPELL:1239825} marque quelques joueurs. Éloigne-toi du groupe avant la fin : des rayons partent alors de toi. Reste hors des rayons - ils te réduisent au silence.|n3. Forme d'ours (70 à 40%) : {SPELL:1240222} marque quelques joueurs et leur envoie des cônes. Les joueurs marqués s'écartent et gardent leur cône loin des autres. Un deuxième coup fait bien plus mal.|n4. {SPELL:1241058} fait saigner les joueurs jusqu'à ce qu'ils soient soignés à fond.|n5. À 40% de vie, {SPELL:1241067} : il lance tout ça toutes les 8 secondes jusqu'à sa mort. Utilise tes cooldowns et Bloodlust ici.",
	DGN_TIP_BV_RUIA_QUICK_DPS = "Interromps son sort en forme de sélénien et garde tes gros sorts pour 40 pour cent.",
	DGN_TIP_BV_RUIA_QUICK_HEALER = "Un joueur qui saigne continue de saigner jusqu'à ce que tu le soignes complètement.",
	DGN_TIP_BV_RUIA_QUICK_TANK = "Vérifie que son sort est interrompu en forme de sélénien et utilise tes défensifs en forme d'ours.",
	DGN_TIP_BV_RUIA_QUICK = "Sélénien : Interromps son sort, esquive les cercles et éloigne-toi du groupe si tu as la marque du rayon.|nOurs : Si tu es marqué, écarte-toi pour que ton cône ne touche personne d'autre.|n40% : Il fait tout en même temps, alors utilise tes gros sorts maintenant.",
	DGN_TIP_BV_RUIA_TANK = "Tank : en forme de sélénien, sa mêlée est remplacée par Warden's Wrath - vérifie qu'il est interrompu. En forme d'ours, sa mêlée frappe deux fois plus fort (Mangling Claws), alors utilise tes défensifs là.",
	DGN_TIP_BV_RUIA_HEALER = "Heal : {SPELL:1241058} ne s'arrête que quand le joueur est pleine vie - soigne une cible à fond, puis la suivante. Garde tes cooldowns pour la phase à 40%.",

	DGN_TIP_BV_ZIEKKET_STEPS = "1. {SPELL:1246372} : des lashers poussent. Le tank les regroupe ; tout le monde les frappe en zone et interrompt Lightspore Shot.|n2. Un lasher à 1% de vie s'enfonce dans le sol et ne peut plus être blessé. Il se réveille plus fort au {SPELL:1246372} suivant, et ne peut alors plus être interrompu ni étourdi.|n3. {SPELL:1253690} vise un joueur avec un rayon. Si c'est toi, tourne-toi pour que le rayon traverse tous les lashers endormis - ça les tue pour de bon. Il laisse des flaques qui ralentissent ({SPELL:1246753}) ; sors-en.|n4. {SPELL:1247685} frappe fort le tank, le repousse et le fait saigner. Tout le groupe prend des dégâts réguliers pendant tout le combat.|n5. En Mythique et Mythic+ : {SPELL:1246858} envoie des orbes vers Ziekket. Touche-les avant qu'ils l'atteignent, et partagez-les (environ deux ou trois chacun) - chaque orbe te donne un DoT qui se cumule. Un orbe qui l'atteint blesse le groupe et lui donne un bouclier.",
	DGN_TIP_BV_ZIEKKET_QUICK_DPS = "Interromps les tirs des lashers et arrête de frapper un lasher quand il dort.",
	DGN_TIP_BV_ZIEKKET_QUICK_HEALER = "Tout le groupe prend des dégâts pendant tout le combat, alors continue de soigner tout le monde.",
	DGN_TIP_BV_ZIEKKET_QUICK_TANK = "Regroupe les lashers et utilise un défensif sur le gros coup d'épines.",
	DGN_TIP_BV_ZIEKKET_QUICK = "Lashers : Frappe-les jusqu'à ce qu'ils s'enfoncent dans le sol pour dormir.|nRayon : Si le rayon te vise, fais-le passer sur les lashers endormis pour les tuer pour de bon.|nOrbes Mythique : Touche les boules brillantes avant qu'elles atteignent le boss, et partagez-les.",
	DGN_TIP_BV_ZIEKKET_TANK = "Tank : regroupe chaque vague de lashers pour les dégâts de zone, près du bord. Utilise un défensif pour {SPELL:1247685} - il te repousse et te fait saigner. Sors des flaques de Lightsap.",
	DGN_TIP_BV_ZIEKKET_HEALER = "Heal : le groupe prend des dégâts pendant tout le combat, alors continue de soigner tout le monde. En Mythique, surveille ceux qui prennent les orbes - leurs stacks font mal, et un orbe raté frappe tout le groupe.",

	-- Voidscar Arena ----------------------------------------------------------------
	DGN_TIP_VA_TAZRAH_STEPS = "1. {SPELL:1222098} : une ombre fonce en ligne à travers chaque joueur. Écarte-toi un peu des autres, près du bord de la salle, pour que ta ligne ne touche personne d'autre.|n2. {SPELL:1296963} laisse des flaques au sol. Pose-les près du bord et serrées, et ne reste jamais dedans.|n3. {SPELL:1300259} : les flaques tirent des orbes. Continue de bouger dans la salle et esquive chaque orbe.|n4. En Mythique et Mythic+ : {SPELL:1225011} - deux éclats volent vers un joueur, et chacun éclate sur le premier joueur touché. Ne marche pas dans les éclats qui visent quelqu'un d'autre.",
	DGN_TIP_VA_TAZRAH_QUICK_DPS = "Continue de frapper le boss pendant que tu esquives.",
	DGN_TIP_VA_TAZRAH_QUICK_HEALER = "Remonte tout le monde avant l'arrivée des flaques.",
	DGN_TIP_VA_TAZRAH_QUICK_TANK = "Utilise un défensif quand il te repousse et n'atterris pas dans une flaque.",
	DGN_TIP_VA_TAZRAH_QUICK = "Charge : Un fantôme fonce sur toi en ligne, alors reste près du mur, un peu loin de tes amis.|nFlaques : Pose tes flaques sombres près du mur, serrées, et ne reste jamais dedans.|nOrbes : Les flaques tirent des boules, alors continue de marcher dans la salle et esquive-les.",
	DGN_TIP_VA_TAZRAH_TANK = "Tank : {SPELL:1297017} te frappe fort et te repousse. Utilise un défensif et ne te fais pas projeter dans une flaque. Tank près d'un mur et tourne lentement autour de la salle, pour que le centre reste libre.",
	DGN_TIP_VA_TAZRAH_HEALER = "Heal : remonte tout le monde avant chaque {SPELL:1296963} ; {SPELL:1300259} blesse tout le groupe. Soigne les joueurs touchés par une charge, elle continue de leur faire mal un moment.",

	DGN_TIP_VA_ATROXUS_STEPS = "1. {SPELL:1262497} frappe tout le groupe. Environ 3 secondes plus tard, un Toxic Creeper sort en rampant ({SPELL:1222371}). Tue-le vite.|n2. {SPELL:1263977} est un frontal qui vise un joueur au hasard. Reste près du boss pour pouvoir en sortir vite.|n3. {SPELL:1226120} projette du poison autour du boss. Esquive les impacts et reste hors des flaques de poison qu'il laisse.|n4. En Mythique et Mythic+ : le Creeper a Toxic Aura - il blesse tout le monde à moins de 8 mètres jusqu'à sa mort. Tue-le encore plus vite ; les joueurs à distance restent loin de lui.",
	DGN_TIP_VA_ATROXUS_QUICK_DPS = "Quand le Creeper sort, frappe-le en premier.",
	DGN_TIP_VA_ATROXUS_QUICK_HEALER = "Retire les poisons du tank et de tous ceux qui sont restés dans une flaque.",
	DGN_TIP_VA_ATROXUS_QUICK_TANK = "Le Creeper te poursuit : éloigne-toi de lui pour qu'il ne puisse pas te mordre.",
	DGN_TIP_VA_ATROXUS_QUICK = "Rugissement : Le boss rugit et un petit monstre, le Creeper, sort ; tout le monde le frappe jusqu'à sa mort.|nSouffle : Le boss souffle sur un joueur au hasard, alors reste près de lui et sors du souffle.|nPoison : Éloigne-toi des éclaboussures de poison et des flaques.",
	DGN_TIP_VA_ATROXUS_TANK = "Tank : le Creeper se fixe sur toi. Kite-le et ne le laisse pas te frapper - chaque morsure ajoute un stack de Sickening Bite, et les stacks rendent {SPELL:1222642} mortel. Garde-le près du boss pour que les DPS puissent frapper les deux, et utilise un défensif pour la griffe.",
	DGN_TIP_VA_ATROXUS_HEALER = "Heal : dissipe les poisons : le poison de {SPELL:1222642} sur le tank et Mind-Numbing Poison des flaques. En Mythique et Mythic+, utilise un cooldown de soin tant que le Creeper est en vie.",

	DGN_TIP_VA_CHARONUS_STEPS = "1. {SPELL:1282770} : quelques joueurs sont marqués, et quelques secondes plus tard un puits de gravité apparaît sous eux. Il t'aspire et fait mal. Sors-en, mais reste à côté d'un puits - tu en as besoin pour les orbes. Son centre donne Atomized : ni dégâts ni soins pendant un court moment.|n2. {SPELL:1263982} : un orbe poursuit 3 joueurs. Son debuff fait mal et te ralentit un peu plus chaque seconde. Passe à côté d'un puits de gravité pour que ton orbe te suive dedans - ça détruit les deux. Ne t'arrête pas dedans. Chaque joueur utilise un puits différent.|n3. {SPELL:1227264} frappe tout le monde, te repousse et laisse un effet de dégâts de 20 secondes. Écartez-vous les uns des autres, et vérifie que tu n'atterriras pas dans un puits.|n4. En Mythique et Mythic+ : {SPELL:1222758} - des projectiles volent vers un joueur au hasard et repoussent ceux qu'ils touchent. Si c'est toi, continue de courir ; tous les autres sortent de la trajectoire.",
	DGN_TIP_VA_CHARONUS_QUICK_DPS = "Attends à côté d'un trou, pour qu'une boule qui te poursuit tombe vite dedans.",
	DGN_TIP_VA_CHARONUS_QUICK_HEALER = "Soigne d'abord les joueurs poursuivis par une boule.",
	DGN_TIP_VA_CHARONUS_QUICK_TANK = "Utilise un défensif pour son gros coup et oriente-le loin de tes amis.",
	DGN_TIP_VA_CHARONUS_QUICK = "Puits : Des trous sombres apparaissent au sol et t'aspirent, alors reste près d'un trou sans entrer dedans.|nOrbes : Si une boule te poursuit, passe à côté d'un trou pour qu'elle tombe dedans.|nExplosion : Le boss repousse tout le monde, alors écarte-toi et ne vole pas dans un trou.",
	DGN_TIP_VA_CHARONUS_TANK = "Tank : {SPELL:1311923} est un coup frontal sur le tank. Utilise un défensif et oriente-le loin du groupe. Garde le boss au milieu des trois puits de gravité, et ne le tourne pas à travers les joueurs.",
	DGN_TIP_VA_CHARONUS_HEALER = "Heal : soigne d'abord les joueurs avec un orbe - plus ils le gardent longtemps, plus il frappe fort. Après {SPELL:1227264}, tout le groupe a un effet de dégâts de 20 secondes, et les puits de gravité font des dégâts réguliers tant qu'ils durent.",

	-- Nexus-Point Xenas ---------------------------------------------------------------
	DGN_TIP_NX_KASRETH_STEPS = "1. {SPELL:1251785} sur toi ? Entre DANS un rayon de leyline ({SPELL:1251183}) — il retire le debuff (court étourdissement, bon échange).|n2. Tous les autres : ne CROISEZ PAS les leylines (dégâts + ralentissement cumulé).|n3. Pleine énergie = {SPELL:1257509} : grosse zone d'impact, dégage — des flaques arcaniques ({SPELL:1264048}) traînent ensuite.",
	DGN_TIP_NX_KASRETH_TANK = "Tank : garde le boss loin des leylines.",
	DGN_TIP_NX_KASRETH_HEALER = "Heal : Sparkburn tique sur tout le monde après chaque détonation.",

	DGN_TIP_NX_NYSARRA_STEPS = "1. Espacez-vous — les frappes de {SPELL:1249020} éclaboussent à 14 mètres.|n2. Tue les adds Null Vanguard ({SPELL:1252703}) VITE : tout ce qui survit est dévoré ({SPELL:1271684}), la soigne et explose sur le groupe.|n3. Esquive les {SPELL:1264439}.",
	DGN_TIP_NX_NYSARRA_TANK = "Tank : elle te bondit dessus avec un combo de taillades ({SPELL:1247937}) — défensif, prépare-toi au finisher.",
	DGN_TIP_NX_NYSARRA_HEALER = "Heal : dégâts dispersés après {SPELL:1249020} ; explosion de groupe si des adds survivent à la dévoration.",

	DGN_TIP_NX_LOTHRAXION_STEPS = "1. {SPELL:1255503} : espacez-vous — les impacts éclaboussent à 8 mètres et font naître des Fractured Images.|n2. {SPELL:1257567} : il se cache parmi ses reflets et tous canalisent — trouve le VRAI Lothraxion et interromps-le.|n3. Les reflets scintillent en projetant ({SPELL:1255531}) ; évite les {SPELL:1255310} au sol.",
	DGN_TIP_NX_LOTHRAXION_TANK = "Tank : {SPELL:1255335} est une double taillade qui grave des cicatrices au sol — oriente-la loin du groupe.",
	DGN_TIP_NX_LOTHRAXION_HEALER = "Heal : DoT sacrés après chaque {SPELL:1255503} ; dégâts réguliers jusqu'à ce que l'interrupt du Guile passe.",

	-- Magisters' Terrace ---------------------------------------------------------------
	DGN_TIP_MT_ARCANOTRON_STEPS = "1. Quand il refait le plein ({SPELL:474345}), des Energy Orbs sont attirés vers lui — intercepte-les ; pendant ce temps il subit +20% de dégâts : fenêtre de burst !|n2. Les joueurs enchaînés ({SPELL:1214038}) sont enracinés (magie) — dissipe ou libère-les.|n3. {SPELL:1214081} projette tout le monde et laisse des résidus à ses pieds — sors-en.",
	DGN_TIP_MT_ARCANOTRON_TANK = "Tank : {SPELL:474496} t'envoie voler — garde ton dos dégagé.",
	DGN_TIP_MT_ARCANOTRON_HEALER = "Heal : dissipe {SPELL:1214038} (racine magique) vite.",

	DGN_TIP_MT_SERANEL_STEPS = "1. {SPELL:1225193} pacifie tous ceux HORS de la Suppression Zone ({SPELL:1224903}) — entre DANS la zone pour la vague (mais la zone te réduit au silence, n'y campe pas).|n2. Purge/vole sa {SPELL:1248689} (+100% de vitesse d'attaque) dès qu'elle est active.|n3. {SPELL:1225787} rebondit vers un joueur proche — espacez-vous.",
	DGN_TIP_MT_SERANEL_TANK = "Tank : une Ward non purgée double sa vitesse d'attaque — défensif jusqu'à sa fin.",
	DGN_TIP_MT_SERANEL_HEALER = "Heal : les joueurs marqués tiquent ; rappelle-toi qu'on ne lance rien dans la zone.",

	DGN_TIP_MT_GEMELLUS_STEPS = "1. {SPELL:1223847} (au début et à mi-vie) : il se divise en trois.|n2. {SPELL:1253709} : lié à l'un d'eux ? COURS le toucher — ça brise le lien et retire son bouclier d'absorption.|n3. {SPELL:1224299} t'aspire — ressors en courant.",
	DGN_TIP_MT_GEMELLUS_TANK = "Tank : regroupe le trio après chaque {SPELL:1223847} pour que les joueurs liés atteignent le leur.",
	DGN_TIP_MT_GEMELLUS_HEALER = "Heal : les joueurs liés subissent +20% de dégâts tant que leur lien tient.",

	DGN_TIP_MT_DEGENTRIUS_STEPS = "1. {SPELL:1215897} : des DoT du Vide aux durées différentes — quand le tien expire, des Entropy Orbs partent de TA position : éloigne-toi d'abord du groupe.|n2. {SPELL:1215087} rebondit sur 4 points — ABSORBE un impact (un joueur par point), sinon il éclate en Void Destruction.|n3. {SPELL:1280113} fracasse le tank et projette quiconque à moins de 8 mètres — laisse de l'espace au tank.",
	DGN_TIP_MT_DEGENTRIUS_TANK = "Tank : défensif pour {SPELL:1280113} ; tanke-le loin du groupe.",
	DGN_TIP_MT_DEGENTRIUS_HEALER = "Heal : les DoT d'Entropy tiquent fort — garde les porteurs debout pendant qu'ils se replacent.",

	-- Skyreach ----------------------------------------------------------------------
	DGN_TIP_SR_RANJIT_STEPS = "1. {SPELL:1258148} file en ligne droite devant lui — fais un pas de côté.|n2. {SPELL:156793} : un impact au centre plus des tourbillons errants qui te catapultent — slalome.|n3. {SPELL:153757} frappe tout le monde avec un saignement — reste plein.|n4. {SPELL:1252733} souffle ses cibles au loin — regarde ce qu'il y a derrière toi.",
	DGN_TIP_SR_RANJIT_TANK = "Tank : garde-le hors des trajectoires de vortex.",
	DGN_TIP_SR_RANJIT_HEALER = "Heal : dégâts de groupe plus saignements après chaque {SPELL:153757}.",

	DGN_TIP_SR_ARAKNATH_STEPS = "1. {SPELL:154162} : des assemblages canalisent de la lumière dans le boss et le SOIGNENT — mets-toi dans un rayon pour le bloquer.|n2. {SPELL:154115} : un coup de bras d'un seul côté — se faire toucher stacke un débuff de dégâts brutal.|n3. {SPELL:154135} frappe tout le monde — sois prêt.",
	DGN_TIP_SR_ARAKNATH_TANK = "Tank : n'absorbe jamais les rayons toi-même — son coup tombe pile pendant l'absorption.",
	DGN_TIP_SR_ARAKNATH_HEALER = "Heal : les absorbeurs de rayon tiquent en continu ; soin de groupe à {SPELL:154135}.",

	DGN_TIP_SR_RUKHRAN_STEPS = "1. {SPELL:1253527} : 3 secondes de plumes dans tous les sens — brise la ligne de vue derrière un pilier.|n2. {SPELL:1253510} frappe le groupe et invoque un Sunwing qui se fixe sur quelqu'un et pulse du feu — tue-le vite ; le fixé garde ses distances.|n3. Répète — plumes derrière un abri, oiseau à terre rapidement.",
	DGN_TIP_SR_RUKHRAN_TANK = "Tank : défensif pour {SPELL:1253519} (gros coup + DoT de brûlure).",
	DGN_TIP_SR_RUKHRAN_HEALER = "Heal : dégâts de groupe pulsés tant qu'un Sunwing vit — réclame le kill.",

	DGN_TIP_SR_VIRYX_STEPS = "1. {SPELL:154396} : une incantation de 3 secondes qui atomise le tank — INTERROMPS-la, à chaque fois.|n2. {SPELL:1253998} : un Solar Zealot attrape un joueur pour le jeter du balcon — libérez-le vite.|n3. {SPELL:1253531} sur toi ? Emmène-le au large — il laisse du Blazing Ground.",
	DGN_TIP_SR_VIRYX_TANK = "Tank : chaque {SPELL:154396} qui passe fait mal — gardez l'ordre des interrupts carré.",
	DGN_TIP_SR_VIRYX_HEALER = "Heal : {SPELL:1253538} pose des DoT de feu sur plusieurs joueurs à la fois.",

	-- Pit of Saron ----------------------------------------------------------------
	DGN_TIP_PS_GARFROST_STEPS = "1. {SPELL:1262029} : la forge pulse du givre cumulé — CACHE-TOI DERRIÈRE un bloc de saronite, il bloque le rayonnement.|n2. {SPELL:1261546} fracasse tout autour de la cible principale — reste à 5+ mètres du tank ; près du minerai, le coup brise le minerai au lieu d'étourdir.|n3. {SPELL:1261847} frappe tout le monde et brise TOUT le minerai — du neuf arrive via {SPELL:1261286}.|n4. Reste hors du {SPELL:1261799}.",
	DGN_TIP_PS_GARFROST_TANK = "Tank : gare-toi près d'un bloc de minerai — {SPELL:1261546} fracasse alors le minerai, pas toi.",
	DGN_TIP_PS_GARFROST_HEALER = "Heal : pic de groupe à {SPELL:1261847} ; givre cumulé sur quiconque est sans abri.",

	DGN_TIP_PS_KRICKICK_STEPS = "1. {SPELL:1264363} : Ick se fixe sur un joueur et le poursuit en éclaboussant Blight et Plague Globs — cours large ; les autres continuent de taper.|n2. {SPELL:1264027} : Krick se téléporte à un cercle rituel et invoque des Shades — switch et tue-les.|n3. {SPELL:1264336} : esquive la vague et les globs qui roulent vers toi.|n4. Ne reste jamais dans le Blight ({SPELL:1264299}).",
	DGN_TIP_PS_KRICKICK_TANK = "Tank : {SPELL:1264287} pose une flaque sur toi — oriente-la vers le bord.",
	DGN_TIP_PS_KRICKICK_HEALER = "Heal : garde le poursuivi en vie ; dégâts de groupe à {SPELL:1264336}.",

	DGN_TIP_PS_TYRANNUS_STEPS = "1. {SPELL:1262772} gèle les Bone Piles autour de sa cible — tiens-toi près des tas quand tu es marqué : les tas gelés ne lèvent pas d'adds.|n2. {SPELL:1263406} relève les tas restants — tue les Plaguespreaders d'abord.|n3. Continue d'esquiver {SPELL:1263756} et le {SPELL:1276948} de Rimefang.|n4. {SPELL:1276648} = coup de groupe + DoT, et les tas infusés donnent des adds plus méchants.",
	DGN_TIP_PS_TYRANNUS_TANK = "Tank : {SPELL:1262582} te catapulte et stacke +200% de dégâts d'ombre — défensif et accroche-toi.",
	DGN_TIP_PS_TYRANNUS_HEALER = "Heal : DoT de groupe après {SPELL:1276648} ; pic sur le tank juste après le Brand.",

	-- Seat of the Triumvirate --------------------------------------------------------
	DGN_TIP_ST_ZURAAL_STEPS = "1. {SPELL:1268916} touche tout DEVANT lui — ne reste jamais face au boss.|n2. {SPELL:1263304} (pleine énergie) : il aspire tout le monde puis éclate avec projection — sors à temps ; les adds sont aspirés aussi.|n3. {SPELL:1263399} invoque des adds Coalesced Void — nettoie-les avant Crashing Void.|n4. {SPELL:1263282} laisse du Void Sludge ({SPELL:244588}) — garde le sol propre.",
	DGN_TIP_ST_ZURAAL_TANK = "Tank : défensif pour {SPELL:1263440} (triple taillade).",
	DGN_TIP_ST_ZURAAL_HEALER = "Heal : gros coup de groupe à {SPELL:1263304}.",

	DGN_TIP_ST_SAPRISH_STEPS = "1. Les Void Bombs ({SPELL:247175}) tombent sur les positions des joueurs — n'y TOUCHE PAS ; pose-les sur les bords.|n2. {SPELL:1280064} : des ombres dashent vers chaque joueur et font détoner les bombes croisées — trace ta ligne de dash loin des bombes.|n3. {SPELL:1263523} allume TOUTES les bombes d'un coup — moins de bombes, moins de douleur.|n4. Interromps le {SPELL:248831} de Shadewing (coup de groupe + désorientation).",
	DGN_TIP_ST_SAPRISH_TANK = "Tank : garde le trio ensemble ; le bond de Darkfang ({SPELL:245738}) laisse sa victime en sang.",
	DGN_TIP_ST_SAPRISH_HEALER = "Heal : les victimes du bond saignent ; explosion de groupe à {SPELL:1263523}.",

	DGN_TIP_ST_NEZHAR_STEPS = "1. {SPELL:1263528} projette tout le monde — attention où tu es près des tempêtes.|n2. {SPELL:1263538} et les {SPELL:1277358} sèment le chaos — tue les tentacules, esquive les Umbral Waves du portail.|n3. Les zones de {SPELL:1263532} tiquent fort, pire au centre — dehors, vite.|n4. {SPELL:244750} atomise le tank — interromps quand tu peux.",
	DGN_TIP_ST_NEZHAR_TANK = "Tank : encaisse {SPELL:244750} quand aucun interrupt n'est prêt.",
	DGN_TIP_ST_NEZHAR_HEALER = "Heal : {SPELL:1263542} = plusieurs DoT qui rongent en même temps.",

	DGN_TIP_ST_LURA_STEPS = "1. Les Notes of Despair rayonnent ({SPELL:1265421}) jusqu'à être réduites au silence — dirige ton {SPELL:1265426} À TRAVERS les notes (le rayon touche aussi les alliés dans la ligne, vise dégagé).|n2. {SPELL:1265689} : 20 secondes de douleur autour de chaque note active — brise-les vite.|n3. {SPELL:1264151} : rayons du Vide rotatifs — bouge avec les ouvertures.|n4. {SPELL:1266003} est une canalisation mortelle de 10 secondes — tous les défensifs, et soigne à fond.",
	DGN_TIP_ST_LURA_TANK = "Tank : après {SPELL:1266001}, tout le monde valdingue — regroupez-vous vite.",
	DGN_TIP_ST_LURA_HEALER = "Heal : coups de groupe de {SPELL:1265421} plus les auras des notes — briser les notes EST le plan de soin.",

	-- Algeth'ar Academy ----------------------------------------------------------------
	DGN_TIP_AA_VEXAMUS_STEPS = "1. Les {SPELL:385974} dérivent vers le boss — absorbe-les, un joueur par orbe (petit coup) ; chaque orbe qu'IL absorbe explose sur tout le groupe.|n2. {SPELL:386173} : emmène la tienne à l'écart — elle éclate en flaque de {SPELL:386201}.|n3. Pleine énergie = {SPELL:388537} : coup de groupe plus éruptions répétées sous les joueurs — reste en mouvement.",
	DGN_TIP_AA_VEXAMUS_TANK = "Tank : {SPELL:385958} souffle tout devant lui — défensif, oriente-le loin du groupe.",
	DGN_TIP_AA_VEXAMUS_HEALER = "Heal : les porteurs de bombe tiquent ; dégâts de groupe pour chaque orbe qui atteint le boss.",

	DGN_TIP_AA_ANCIENT_STEPS = "1. {SPELL:388796} : pendant 4 secondes, des graines germent sous tout le monde — esquive ; les ratées laissent des Lashers dormants.|n2. À pleine énergie ({SPELL:388923}), TOUS les Lashers dormants se réveillent d'un coup — nettoie-les avant.|n3. {SPELL:388623} lance une branche qui devient un gros add — tue-le et INTERROMPS son {SPELL:396640}.",
	DGN_TIP_AA_ANCIENT_TANK = "Tank : {SPELL:388544} double les dégâts physiques que tu subis — défensif, à chaque fois.",
	DGN_TIP_AA_ANCIENT_HEALER = "Heal : purge {SPELL:389033} (poison) avant qu'il ne grimpe.",

	DGN_TIP_AA_CRAWTH_STEPS = "1. {SPELL:377004} éclate sous chaque joueur et interrompt les incantations — ARRÊTE de lancer, puis espacez-vous.|n2. {SPELL:377034} : elle fixe quelqu'un et balaie un cône dans cette direction — sors-en.|n3. {SPELL:377182} : marque dans un but — le but de feu l'étourdit et elle subit 75% de dégâts en plus.",
	DGN_TIP_AA_CRAWTH_TANK = "Tank : défensif pour {SPELL:376997} (coup + saignement 10 s).",
	DGN_TIP_AA_CRAWTH_HEALER = "Heal : lourds dégâts de groupe après le cri ; le tank saigne.",

	DGN_TIP_AA_DORAGOSA_STEPS = "1. {SPELL:374341} sur toi ? Éloigne-la du groupe — elle éclate sur 8 mètres.|n2. {SPELL:388820} aspire tout le monde puis explose — SORS EN COURANT avant l'éclat.|n3. {SPELL:389011} se cumule à chaque mécanique encaissée — à 3 stacks, ça éclate en Arcane Rift ; reste propre.|n4. Évite le sol {SPELL:389007}.",
	DGN_TIP_AA_DORAGOSA_TANK = "Tank : défensif pour {SPELL:1282251}.",
	DGN_TIP_AA_DORAGOSA_HEALER = "Heal : surveille les stacks de {SPELL:389011} — les porteurs tiquent plus fort par stack.",
	DGN_TIP_KR_COUNCIL_STEPS = "1. Le conseil combat un par un : Kula, puis Aka'ali, puis Zanazal. Un membre vaincu revient de temps en temps pour lancer une technique. Le combat finit quand Zanazal meurt.|n2. Kula : éloigne-toi d'elle pour {SPELL:266206} et esquive les haches qui roulent ensuite. {SPELL:266231} fait saigner un joueur au hasard — utilise un défensif.|n3. Aka'ali : {SPELL:267494} charge un joueur. Tout le monde se colle à ce joueur pour partager les dégâts.|n4. Zanazal : interromps {SPELL:267273}. Quand il appelle des totems ({SPELL:267060}), tue d'abord l'Explosive Totem, puis le Thundering Totem, puis le Torrent Totem.",
	DGN_TIP_KR_COUNCIL_QUICK_DPS = "Reste dans le paquet de la charge, interromps le poison, et tue d'abord le totem qui explose.",
	DGN_TIP_KR_COUNCIL_QUICK_HEALER = "Soigne le saignement des haches, et remonte tout le monde avant la charge.",
	DGN_TIP_KR_COUNCIL_QUICK_TANK = "Quand Aka'ali te repousse, fuis-la jusqu'à la fin du debuff.",
	DGN_TIP_KR_COUNCIL_QUICK = "Kula : Éloigne-toi quand elle tourne et esquive les haches volantes.|nAka'ali : Elle charge un joueur. Tout le monde se met sur ce joueur pour partager le coup.|nZanazal : Interromps son sort de poison et tue d'abord le totem qui explose.",
	DGN_TIP_KR_COUNCIL_DPS = "DPS : reste dans le paquet de {SPELL:267494}, continue d'interrompre {SPELL:267273}, et passe sur l'Explosive Totem dès qu'il apparaît.",
	DGN_TIP_KR_COUNCIL_HEALER = "Heal : soigne le saignement de {SPELL:266231} et remonte tout le monde avant {SPELL:267494}. Sur Zanazal, {SPELL:1305810} rebondit entre les joueurs, et Poison Nova tique sur tout le monde si elle n'est pas interrompue.",
	DGN_TIP_KR_COUNCIL_TANK = "Tank : {SPELL:266237} te repousse et te fait subir beaucoup plus de dégâts physiques. Kite Aka'ali jusqu'à la fin du debuff, ou utilise un gros défensif.",
	DGN_TIP_KR_DAZAR_STEPS = "1. Phase 1 : Dazar combat avec son raptor Reban. Tue Reban d'abord et interromps son {SPELL:269369}, une peur. Reban saute sur un joueur avec {SPELL:269230} et mord en cône — sors-en.|n2. {SPELL:1303115} : Dazar bondit sur deux joueurs. Ces deux-là s'écartent pour ne pas se toucher.|n3. À 80% de vie, Dazar monte son raptor T'zala. Maintenant {SPELL:1303327} bondit sur quatre joueurs et touche aussi tout le groupe — espacez-vous et soyez pleins.|n4. {SPELL:1303267} frappe tout le groupe et brûle pendant 15 secondes. Juste après, des lances tombent là où sont les joueurs — bouge sans arrêt et esquive les cercles d'Impaling Spear.|n5. En Mythique et Mythic+ : {SPELL:1303267} renforce aussi ses coups — ils envoient une vague d'or vers l'avant. Le tank l'oriente loin du groupe.",
	DGN_TIP_KR_DAZAR_QUICK_DPS = "Tue d'abord le petit raptor et interromps son rugissement.",
	DGN_TIP_KR_DAZAR_QUICK_HEALER = "Garde tes gros soins pour le coup d'or et les sauts du raptor.",
	DGN_TIP_KR_DAZAR_QUICK_TANK = "Utilise ton plus gros défensif pour la combo d'épée, et garde le roi tourné loin du groupe.",
	DGN_TIP_KR_DAZAR_QUICK = "Raptor : Tue d'abord le petit raptor et interromps son rugissement qui fait peur.|nMonture : Le roi monte son grand raptor. Écarte-toi quand il saute, et sois à pleine vie.|nOr : Un gros coup de feu sur tout le monde, puis des lances tombent là où tu es. Bouge sans arrêt.",
	DGN_TIP_KR_DAZAR_DPS = "DPS : tue Reban d'abord et interromps {SPELL:269369}. Garde de l'espace libre pour que les cibles des bonds puissent s'écarter et que tu puisses esquiver les lances.",
	DGN_TIP_KR_DAZAR_HEALER = "Heal : garde tes gros cooldowns pour {SPELL:1303267} et {SPELL:1303327}. Surveille les saignements d'Impaling Spear et de {SPELL:1303488}.",
	DGN_TIP_KR_DAZAR_TANK = "Tank : gros défensif pour {SPELL:268586} — les coups sont plus forts vers la fin. Une fois T'zala en jeu, {SPELL:1303488} te touche aussi et augmente tes dégâts physiques subis, alors répartis tes cooldowns entre les deux. Oriente Dazar loin du groupe.",
	DGN_TIP_KR_MCHIMBA_STEPS = "1. {SPELL:267618} : le boss draine un joueur. Tous les autres sortent des cercles d'acide qu'il projette. Si c'est toi, utilise un défensif. À la fin, tu restes lent et affaibli jusqu'à être soigné au-dessus de 90% de vie.|n2. {SPELL:1311956} vise un joueur et laisse un sol brûlant. Pose-le au bord, loin du boss et des cercueils.|n3. {SPELL:1312146} frappe tout le groupe et ouvre des cercueils : deux Half-Finished Mummies en sortent. Tue-les et interromps leur Wretched Discharge.|n4. {SPELL:267702} : un joueur est enfermé dans un des cercueils. Si c'est toi, appuie sur le bouton Struggle pour que ton cercueil tremble. Tous les autres : trouvez le cercueil qui tremble et cliquez vite dessus. Chaque cercueil vide qu'il ouvre avant vous libère une Finished Mummy.",
	DGN_TIP_KR_MCHIMBA_QUICK_DPS = "Interromps les momies et aide à trouver le cercueil qui tremble.",
	DGN_TIP_KR_MCHIMBA_QUICK_HEALER = "Soigne le joueur drainé presque à fond, ça enlève le ralentissement.",
	DGN_TIP_KR_MCHIMBA_QUICK_TANK = "Attrape les momies et garde-les à côté du boss.",
	DGN_TIP_KR_MCHIMBA_QUICK = "Drain : Si le boss te draine, utilise un défensif. Les autres sortent des cercles d'acide.|nFeu : Pose ta flaque de feu au bord, loin du boss et des cercueils.|nCercueil : Un ami est enfermé dans un cercueil. Trouve celui qui tremble et clique vite dessus.",
	DGN_TIP_KR_MCHIMBA_DPS = "DPS : interromps le Wretched Discharge des momies. Pendant {SPELL:267702}, va aux cercueils et cherche celui qui tremble — ne clique pas au hasard.",
	DGN_TIP_KR_MCHIMBA_HEALER = "Heal : passe tout de suite sur la cible de {SPELL:267618}, puis remonte-la au-dessus de 90% — ça met fin au ralentissement. Remonte le groupe avant {SPELL:1312146}. Wretched Discharge est une maladie que tu peux dissiper.",
	DGN_TIP_KR_MCHIMBA_TANK = "Tank : récupère les momies et regroupe-les près de Mchimba pour le cleave. Ne les laisse pas devant un cercueil.",
	DGN_TIP_KR_SERPENT_STEPS = "1. {SPELL:265773} pose de l'or brûlant sur deux joueurs. À la fin, tu laisses une flaque de {SPELL:265914} là où tu te tiens — va d'abord au bord et pose-la à côté des autres flaques.|n2. {SPELL:265923} réveille les flaques en Animated Gold qui rampent vers le boss. Tue-les, ralentis-les ou étourdis-les avant qu'ils ne l'atteignent — chacun qui arrive lui donne un bouclier et plus de dégâts.|n3. {SPELL:1311987} : cinq secondes de dégâts sur tout le groupe, qui te repoussent aussi. Sois plein et utilise un défensif.|n4. Ne reste jamais dans les flaques d'or.",
	DGN_TIP_KR_SERPENT_QUICK_DPS = "Tue d'abord les adds d'or — aucun ne doit atteindre le boss.",
	DGN_TIP_KR_SERPENT_QUICK_HEALER = "Soigne les deux joueurs brûlés par l'or, et garde un gros soin pour le vent.",
	DGN_TIP_KR_SERPENT_QUICK_TANK = "Utilise un défensif pour le coup de queue, et éloigne le boss des adds d'or.",
	DGN_TIP_KR_SERPENT_QUICK = "Or : Quand ta brûlure d'or finit, tu laisses une flaque. Pose-la au bord, près des autres flaques.|nAdds : Les flaques se réveillent et rampent vers le boss. Tue-les avant qu'ils ne le touchent.|nVent : Un vent fort blesse tout le monde et te repousse. Sois à pleine vie.",
	DGN_TIP_KR_SERPENT_DPS = "DPS : l'Animated Gold d'abord, le boss ensuite. Utilise ralentissements, étourdissements et cleave, et garde toutes les flaques ensemble pour que les adds se réveillent en un seul paquet.",
	DGN_TIP_KR_SERPENT_HEALER = "Heal : soigne les deux cibles de {SPELL:265773} pendant la brûlure. Garde un cooldown de soin pour {SPELL:1311987}.",
	DGN_TIP_KR_SERPENT_TANK = "Tank : défensif pour {SPELL:265910}. Quand l'Animated Gold se réveille, éloigne le boss pour laisser plus de temps aux DPS.",
	DGN_TIP_RL_KOKIA_STEPS = "1. Molten Boulder ({SPELL:372110}) : Kokia lance un rocher brûlant qui roule en ligne droite puis explose. Sors de sa trajectoire et reste loin de l'endroit où il s'arrête. Il projette tous ceux qu'il touche.|n2. Ritual of Blazebinding ({SPELL:372864}) : un add de feu, le Blazebound Firestorm, apparaît sur un joueur et brûle tout le monde à 12 mètres. Si c'est sur toi, éloigne-toi du groupe mais reste près du boss.|n3. Tout le monde passe tout de suite sur le Blazebound Firestorm et interrompt son Blaze Volley.|n4. Avant la mort de l'add, éloigne-toi d'au moins 20 mètres. Son explosion de mort (Burnout) frappe très fort.|n5. En Mythique et Mythic+ : un sol brûlant ({SPELL:372820}) reste par terre. Sors-en, et déplace le combat lentement dans la salle pour qu'il y ait toujours de la place libre.",
	DGN_TIP_RL_KOKIA_QUICK_DPS = "Frappe d'abord l'add de feu, interromps ses sorts, et éloigne-toi avant qu'il meure.",
	DGN_TIP_RL_KOKIA_QUICK_HEALER = "L'add de feu brûle tout le monde et le tank saigne, alors soigne fort et reste loin quand il meurt.",
	DGN_TIP_RL_KOKIA_QUICK_TANK = "Utilise un défensif pour chaque combo de coups et promène le boss lentement dans la salle.",
	DGN_TIP_RL_KOKIA_QUICK = "Rocher : Un rocher de feu roule en ligne droite, alors sors de son chemin.|nMonstre : Quand un monstre de feu apparaît, tout le monde le frappe et coupe ses sorts.|nExplosion : Cours loin du monstre avant qu'il meure, car il explose.",
	DGN_TIP_RL_KOKIA_DPS = "DPS : passe sur le Blazebound Firestorm dès qu'il apparaît et interromps son Blaze Volley. Mêlée : éloigne-toi de 20 mètres avant sa mort.",
	DGN_TIP_RL_KOKIA_HEALER = "Heal : l'incantation Inferno de l'add brûle tout le groupe, et Searing Blows laisse un saignement sur le tank. Reste toi aussi hors de l'explosion de mort de l'add.",
	DGN_TIP_RL_KOKIA_TANK = "Tank : utilise un défensif pour chaque Searing Blows ({SPELL:372858}) : quatre coups rapides qui cumulent un saignement. Garde Kokia près de l'add pour que les DPS puissent cleave, mais sors de son explosion de mort à 20 mètres. Déplace-la lentement dans la salle pour garder de la place.",
	DGN_TIP_RL_KYRAKKA_STEPS = "1. Erkhart combat au sol pendant que son dragon Kyrakka vole autour de la plateforme. Frappe Kyrakka dès qu'elle est à portée : elle doit mourir en premier. Esquive son cône de feu ({SPELL:381525}).|n2. Inferno Spit ({SPELL:381602}) : 2 joueurs brûlent pendant 6 secondes, puis explosent et laissent du feu au sol ({SPELL:384773}). Si c'est toi, va au bord, loin du groupe, avant la fin.|n3. Winds of Change ({SPELL:381517}) : le vent pousse les joueurs et le feu, dans un ordre fixe (nord-ouest, sud-ouest, sud-est, nord-est). Marche contre le vent et ne te fais pas pousser dans le feu. Pose ton feu là où le vent l'emporte loin du groupe.|n4. Quand l'un d'eux atteint environ 40 à 50% de vie (les guides varient), Kyrakka se pose et Erkhart la monte. Maintenant 3 joueurs ont Inferno Spit. Garde tes cooldowns pour cette partie.|n5. En Mythique et Mythic+ : Interrupting Cloudburst ({SPELL:381516}) frappe tout le monde et bloque tes sorts pendant 2 secondes. Arrête d'incanter juste avant l'impact.",
	DGN_TIP_RL_KYRAKKA_QUICK_DPS = "Frappe d'abord le dragon, et en Mythique arrête d'incanter juste avant que l'orage frappe tout le monde.",
	DGN_TIP_RL_KYRAKKA_QUICK_HEALER = "Enlève le debuff du tank après chaque gros coup et soigne les joueurs qui brûlent.",
	DGN_TIP_RL_KYRAKKA_QUICK_TANK = "Utilise un défensif pour son gros coup, et demande au heal d'enlever le debuff.",
	DGN_TIP_RL_KYRAKKA_QUICK = "Dragon : Frappe le dragon dès que tu peux l'atteindre, et esquive son souffle de feu.|nFeu : Si tu brûles, va au bord pour que ton feu tombe loin du groupe.|nVent : Le vent te pousse, toi et le feu, alors marche contre lui et reste hors des flammes.",
	DGN_TIP_RL_KYRAKKA_DPS = "DPS : frappe Kyrakka dès que tu peux l'atteindre et garde ton burst pour quand elle se pose. En Mythique et Mythic+, les casters arrêtent d'incanter avant Interrupting Cloudburst.",
	DGN_TIP_RL_KYRAKKA_HEALER = "Heal : dissipe Stormslam sur le tank après chaque coup, avant le suivant. Les cibles d'Inferno Spit prennent de gros dégâts, alors remonte-les. En Mythique et Mythic+, arrête d'incanter avant Interrupting Cloudburst.",
	DGN_TIP_RL_KYRAKKA_TANK = "Tank : utilise un défensif pour chaque Stormslam ({SPELL:381512}). Il laisse un debuff magique cumulable qui augmente tes dégâts de nature subis, alors demande une dissipation. Sors vite Erkhart du feu après chaque vent.",
	DGN_TIP_RL_MELIDRUSSA_STEPS = "1. Hailburst ({SPELL:1307297}) : elle frappe tout le groupe et lance une mine de glace sur chaque joueur. Restez ensemble près d'un bord pour que les mines tombent au même endroit. Ne touche jamais une mine : elle te projette en l'air et ralentit tes attaques et tes sorts de moitié pendant 20 secondes.|n2. Chillstorm ({SPELL:1307308}) : une tempête de givre tombe sur un joueur et attire tout le monde vers son centre. Si c'est toi, éloigne-toi du groupe. Reste hors du centre ({SPELL:372963}) : les dégâts de givre y sont doublés. Après 7 secondes, elle explose et repousse tout le monde, alors ne te place pas avec des mines dans le dos.|n3. À 66% et 33% de vie, elle appelle des Infused Whelps ({SPELL:373046}). Tue-les vite.|n4. Interromps Frigid Shard, le sort qu'elle lance sur le tank.|n5. En Mythique et Mythic+ : après les dragonnets, elle se cache dans un bouclier de glace (Ice Bulwark) et envoie sur tout le monde des dégâts de givre qui augmentent sans cesse (Frost Overload). Brise vite le bouclier, puis interromps-la. Les guides disent que l'interruption marche une fois le bouclier tombé.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_DPS = "Tue d'abord les bébés dragons, et en Mythique brise son bouclier de glace.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_HEALER = "Soigne tout le groupe pendant les explosions de glace et la tempête.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_TANK = "Attrape tout de suite les bébés dragons et interromps le sort qu'elle te lance.",
	DGN_TIP_RL_MELIDRUSSA_QUICK = "Mines : Restez ensemble près d'un bord quand elle lance la glace, et ne touche jamais les mines.|nTempête : Si la tempête est sur toi, éloigne-toi de tout le monde et reste hors de son centre.|nDragonnets : Tue vite les bébés dragons, et en Mythique brise aussi son bouclier de glace.",
	DGN_TIP_RL_MELIDRUSSA_DPS = "DPS : passe sur les dragonnets dès qu'ils apparaissent. En Mythique et Mythic+, garde ton burst pour briser le bouclier de glace, puis interromps Frost Overload.",
	DGN_TIP_RL_MELIDRUSSA_HEALER = "Heal : Hailburst et Chillstorm frappent tout le groupe, et la tempête explose à la fin. Remonte tout le monde avant l'explosion. En Mythique et Mythic+, la phase de bouclier ajoute sur tout le monde des dégâts de givre qui augmentent jusqu'à ce que le bouclier cède.",
	DGN_TIP_RL_MELIDRUSSA_TANK = "Tank : récupère tout de suite les Infused Whelps et garde-les sur le boss pour le cleave. Leurs coups cumulent Cold Claws sur toi ; trop de stacks te gèlent, donc ils doivent mourir vite. Interromps Frigid Shard si personne d'autre ne le fait.",
	DGN_TIP_TS_ADDERIS_STEPS = "1. Storm Blessed protège l'un des deux boss, et ce boss ne subit presque aucun dégât. Frappe celui SANS bouclier (Adderis au pull) et change dès que le bouclier passe à l'autre.|n2. {SPELL:1311805} : si tu es marqué, va au bord et pose ta flaque là-bas. Les flaques te réduisent au silence, alors reste dehors.|n3. {SPELL:1289059} : tout le monde est repoussé. Écartez-vous un peu et place-toi pour que la poussée ne te jette pas dans une flaque.|n4. {SPELL:1288049} arrive juste après la projection : reviens et colle-toi au boss pour partager le coup, puis sortez ensemble avant la deuxième explosion.",
	DGN_TIP_TS_ADDERIS_QUICK_DPS = "Frappe seulement le boss sans bouclier, et change vite quand il bouge.",
	DGN_TIP_TS_ADDERIS_QUICK_HEALER = "Soigne les joueurs touchés par le vent, et remonte tout le monde avant la poussée.",
	DGN_TIP_TS_ADDERIS_QUICK_TANK = "Utilise un défensif pour Overload, et garde les deux boss proches l'un de l'autre.",
	DGN_TIP_TS_ADDERIS_QUICK = "Bouclier : Frappe le boss sans bouclier, et change quand le bouclier saute.|nFlaques : Si tu es marqué, pose ta flaque au bord et reste hors des flaques.|nPoussée : Après la poussée, reviens et colle-toi aux autres sur le boss pour partager le coup.",
	DGN_TIP_TS_ADDERIS_DPS = "DPS : ne frappe jamais le boss protégé — il ne subit presque aucun dégât. Change dès que le bouclier bouge, même au milieu de ta rotation.",
	DGN_TIP_TS_ADDERIS_HEALER = "Heal : soigne les joueurs touchés par Gust. La projection suivie tout de suite du coup à partager est le moment le plus dangereux — remonte tout le monde avant.",
	DGN_TIP_TS_ADDERIS_TANK = "Tank : utilise un défensif pour {SPELL:1311804}. Garde les deux boss proches l'un de l'autre pour que le groupe puisse changer de cible sans traverser les flaques.",
	DGN_TIP_TS_AVATAR_STEPS = "1. Tu gagnes en soignant l'Avatar à pleine vie, pas en la tuant. Tue d'abord les Essence Defilers : leur {SPELL:1301202} bloque tous les soins sur elle.|n2. Tue le Corrupted Guardian. Il laisse trois orbes de Corrupted Lifeforce : trois DPS différents en prennent un chacun, vite. Un orbe pris soigne l'Avatar ; un orbe raté explose sur tout le groupe.|n3. Twisted Hexxers : interromps Flame Shock. Tu as {SPELL:1311981} ? Éloigne-toi du groupe avant la fin, et laisse sa zone là-bas.|n4. Une fois les Defilers morts, soigne l'Avatar. Des Faithless Tormentors apparaissent et poursuivent le heal : étourdis-les, ralentis-les et descends-les sous 25% de vie — l'Avatar les dévore alors et se soigne.",
	DGN_TIP_TS_AVATAR_QUICK_DPS = "Tue d'abord les Defilers, puis prenez un orbe chacun.",
	DGN_TIP_TS_AVATAR_QUICK_HEALER = "Soigne l'Avatar une fois les Defilers morts, et fuis sans arrêt les chasseurs.",
	DGN_TIP_TS_AVATAR_QUICK_TANK = "Garde le gros add dans un coin, et reste loin des orbes.",
	DGN_TIP_TS_AVATAR_QUICK = "But : Tue d'abord les Defilers, puis soigne l'Avatar à fond pour gagner.|nOrbes : Quand le gros add meurt, trois DPS prennent chacun un orbe, vite.|nChasseurs : Étourdis les adds qui chassent le heal et descends leur vie ; l'Avatar les mange alors.",
	DGN_TIP_TS_AVATAR_DPS = "DPS : tue d'abord les Essence Defilers, puis le Guardian. Prends un orbe chacun (il te donne {SPELL:1300877}, donc utilise un défensif), interromps Flame Shock, et étourdis les Tormentors puis tue-les en zone.",
	DGN_TIP_TS_AVATAR_HEALER = "Heal : soigne l'Avatar dès que les Defilers sont morts — c'est comme ça qu'on gagne. Les Tormentors foncent sur toi et chaque coup réduit tes soins, alors reste en mouvement. Laisse les orbes aux DPS.",
	DGN_TIP_TS_AVATAR_TANK = "Tank : garde le Corrupted Guardian dans un coin loin du groupe et utilise un défensif pour Tainted Strike. Ne prends pas d'orbe : {SPELL:1300877} te fait subir beaucoup plus de dégâts physiques.",
	DGN_TIP_TS_GALVAZZT_STEPS = "1. {SPELL:1291618} : trois tours tirent des rayons sur Galvazzt. Place-toi dans un rayon, entre la tour et le boss, pour qu'il ne gagne pas d'énergie.|n2. Partagez les rayons : un joueur par rayon, et relayez-vous entre les séries. Bloquer un rayon te donne {SPELL:266923} : des dégâts sur la durée et plus de dégâts physiques subis.|n3. Ne laisse jamais un rayon libre. À pleine énergie, il lance Consume Charge, qui frappe fort le groupe et le tue souvent.|n4. {SPELL:1309525} : dégâts sur tout le groupe, et {SPELL:1291815} reste au sol. Sors-en.",
	DGN_TIP_TS_GALVAZZT_QUICK_DPS = "Reste dans ton rayon, même si tu ne peux pas frapper le boss de là.",
	DGN_TIP_TS_GALVAZZT_QUICK_HEALER = "Garde en vie les joueurs dans les rayons.",
	DGN_TIP_TS_GALVAZZT_QUICK_TANK = "Reste hors des rayons, et éloigne le boss des zones au sol.",
	DGN_TIP_TS_GALVAZZT_QUICK = "Rayons : Mets-toi dans un rayon, entre la tour et le boss, pour qu'il ne se charge pas.|nRelais : Un joueur par rayon, relayez-vous, et ne laissez jamais un rayon libre.|nSol : Après le gros coup sur le groupe, sors de la zone au sol.",
	DGN_TIP_TS_GALVAZZT_DPS = "DPS : ton rayon passe avant tes dégâts — n'en sors pas pour frapper le boss. Relaie-toi avec les autres et utilise un défensif pendant ton tour.",
	DGN_TIP_TS_GALVAZZT_HEALER = "Heal : ceux qui bloquent les rayons prennent des dégâts constants — garde-les hauts, et prends un rayon toi-même si besoin. Garde un cooldown prêt pour {SPELL:1309525}.",
	DGN_TIP_TS_GALVAZZT_TANK = "Tank : ne prends pas les rayons — {SPELL:266923} te fait subir beaucoup plus de dégâts physiques. Éloigne le boss de chaque {SPELL:1291815}, vers un endroit où les rayons restent faciles à atteindre.",
	DGN_TIP_TS_MEREKTHA_STEPS = "1. {SPELL:1290029} : des serpents ligotent certains joueurs. Si tu es marqué, colle-toi aux autres près du boss, pour qu'un seul étourdissement de zone ou contrôle brise tous les nœuds. Puis tue les serpents.|n2. {SPELL:1289109} : si tu es marqué, va au bord de la salle et pose la flaque là-bas, pas au milieu.|n3. {SPELL:1293048} : dégâts sur tout le groupe plus une projection. Ne reste pas là où la poussée te jette dans une flaque.|n4. {SPELL:1289205} et {SPELL:264172} : des adds éclosent, puis elle s'enfouit sous terre et ne peut plus être frappée. Esquive son trajet (il étourdit), interromps Poison Spit des Toxic Vipers, et tue tous les adds — ça la fait remonter.",
	DGN_TIP_TS_MEREKTHA_QUICK_DPS = "Quand elle passe sous terre, tue vite tous les adds ; ça la fait revenir.",
	DGN_TIP_TS_MEREKTHA_QUICK_HEALER = "Garde un cooldown pour la tempête qui touche tout le monde.",
	DGN_TIP_TS_MEREKTHA_QUICK_TANK = "Utilise un défensif pour sa grosse morsure, et attrape les adds quand elle passe sous terre.",
	DGN_TIP_TS_MEREKTHA_QUICK = "Serpents : Si des serpents t'attachent, colle-toi aux autres pour qu'un seul étourdissement libère tout le monde.|nCrachat : Si tu es marqué, pose ta flaque au bord de la salle.|nSous terre : Elle se cache sous le sol. Esquive son trajet et tue tous les adds pour la faire revenir.",
	DGN_TIP_TS_MEREKTHA_DPS = "DPS : libère d'abord les joueurs ligotés avec un étourdissement ou un contrôle de zone. Pendant Burrow, tue vite chaque add — la phase finit quand ils sont tous morts — et interromps Poison Spit.",
	DGN_TIP_TS_MEREKTHA_HEALER = "Heal : {SPELL:1293048} frappe tout le groupe — prévois un cooldown. Si un Poison Spit passe, dissipe le poison si tu peux.",
	DGN_TIP_TS_MEREKTHA_TANK = "Tank : utilise un défensif pour chaque {SPELL:1290797}. Pendant Burrow, récupère les adds et place le Storm Serpent au bord, car il laisse aussi des flaques.",
})

merge(ns._mhLocales and ns._mhLocales.esES, {
	-- Windrunner Spire ----------------------------------------------------------
	DGN_TIP_WS_DUO_STEPS = "1. Dos jefes — repárteles el daño para que mueran casi a la vez.|n2. Interrumpe Shadow Bolt; sal de los círculos de escupitajo ({SPELL:472745}) — no malgastes suelo.|n3. ¿Maldito ({SPELL:474105})? Que te lo disipen rápido — o controla a la Dark Entity que genera hasta que desaparezca.|n4. ¿Enganchado por {SPELL:472793} durante el grito? Colócate para que te arrastre A TRAVÉS de la dama fantasma — eso rompe su lanzamiento.",
	DGN_TIP_WS_DUO_TANK = "Tanque: defensivo para {SPELL:472888}; mueve a los jefes cuando el suelo se llene.",
	DGN_TIP_WS_DUO_HEALER = "Sanador: mucho daño de grupo durante {SPELL:472736}; disipa {SPELL:474105} rápido.",

	DGN_TIP_WS_EMBER_STEPS = "1. Fuego = malo. Deja los charcos de fuego ({SPELL:466556}) en los bordes, mantén el centro limpio.|n2. Con energía llena: corre HACIA el jefe para {SPELL:465904} y luego esquiva cada Fire Breath.|n3. Los charcos viejos generan remolinos de fuego — sigue esquivando.",
	DGN_TIP_WS_EMBER_TANK = "Tanque: defensivo para {SPELL:466064}.",
	DGN_TIP_WS_EMBER_HEALER = "Sanador: daño de grupo pesado durante {SPELL:465904}.",

	DGN_TIP_WS_KROLUK_STEPS = "1. Círculos marrones = malos, sal de ahí.|n2. Júntate con un aliado antes de que termine {SPELL:1253026} (superpón los círculos morados).|n3. ¿Fijado u objetivo del salto ({SPELL:1283247})? Llévalo LEJOS del grupo.|n4. Cuando salgan adds (hacia dos tercios y un tercio de vida): mátalos rápido — primero el Phantasmal Mystic, y no dejes de interrumpirlo.",
	DGN_TIP_WS_KROLUK_TANK = "Tanque: defensivo para {SPELL:467620}; prepárate para recoger el segundo {SPELL:1283247}.",
	DGN_TIP_WS_KROLUK_HEALER = "Sanador: daño de grupo durante {SPELL:472043}.",

	DGN_TIP_WS_HEART_STEPS = "1. ¿Te hacen tictac los stacks de {SPELL:1216042}? Pisa una flecha de viento (Turbulent Arrow) con 2-3 stacks — quita el DoT y te salta por encima de la onda expansiva.|n2. Guarda una flecha para el estallido grande a energía llena ({SPELL:468429}).|n3. Sepárate un poco para {SPELL:1253979} y usa los círculos grandes para limpiar el suelo eléctrico.|n4. ¿Objetivo de {SPELL:474528}? Quédate quieto y deja que los demás se aparten; el resto: fuera del cono frontal.",
	DGN_TIP_WS_HEART_TANK = "Tanque: defensivo para {SPELL:472662}; apunta el empujón LEJOS de los charcos.",
	DGN_TIP_WS_HEART_HEALER = "Sanador: cura primero a los jugadores con muchos stacks de {SPELL:1216042}; curación extra tras {SPELL:1253979}.",

	-- Maisara Caverns ------------------------------------------------------------
	DGN_TIP_MC_MUROJIN_STEPS = "1. Dos jefes (cazador y ave) — mátalos casi juntos, o el superviviente se enfurece.|n2. Trampas de hielo ({SPELL:1243741}), círculos verdes ({SPELL:1243900}) y el {SPELL:1260643} frontal = malos, quédate fuera.|n3. ¿Objetivo de {SPELL:1249478} (el picado del ave)? Corre HACIA una trampa de hielo — la congelación detiene el picado. Los demás: alejaos de ese jugador.",
	DGN_TIP_MC_MUROJIN_TANK = "Tanque: defensivo para {SPELL:1266480}.",
	DGN_TIP_MC_MUROJIN_HEALER = "Sanador: disipa {SPELL:1246666} (enfermedad) — daño de grupo pesado.",

	DGN_TIP_MC_VORDAZA_STEPS = "1. El jefe genera Unstable Phantoms ({SPELL:1251204}) que persiguen a los jugadores. MÁTALOS antes de que alcancen a alguien — un fantasma que llega a su objetivo (o toca a otro fantasma) estalla con daño pesado cercano.|n2. Cada fantasma muerto grita: daño de grupo inevitable — mátalos de UNO en UNO.|n3. Esquiva la oleada frontal de {SPELL:1252054} (te empuja), los orbes flotantes y Soulrot.|n4. ¿Alguien envuelto en un Deathshroud? Sácalo rápido; interrumpe {SPELL:1250708} y esquiva los remolinos mientras tanto.",
	DGN_TIP_MC_VORDAZA_TANK = "Tanque: defensivo para {SPELL:1251554}.",
	DGN_TIP_MC_VORDAZA_HEALER = "Sanador: cada fantasma muerto grita ({SPELL:1251813}) = daño de grupo — cura entre los kills escalonados.",

	DGN_TIP_MC_RAKTUL_STEPS = "1. El jefe salta sobre tres jugadores ({SPELL:1252676}) y deja Soulbind Totems — separaos para que los tótems caigan apartados, que no te aplaste, y destrúyelos rápido.|n2. Quédate fuera del suelo de Chill of Death.|n3. Fase de alma ({SPELL:1253788}): te arrancan del cuerpo — controla e interrumpe a los adds grandes mientras vuelves corriendo a tu cuerpo.|n4. Esquiva los remolinos del Deathgorged Vessel.",
	DGN_TIP_MC_RAKTUL_TANK = "Tanque: defensivo para {SPELL:1251023}; deja los charcos LEJOS del grupo.",
	DGN_TIP_MC_RAKTUL_HEALER = "Sanador: daño de grupo pesado durante Deathgorged Vessel y cuando los tótems se rompen.",

	-- Murder Row -----------------------------------------------------------------
	DGN_TIP_MR_KYSTIA_STEPS = "1. Mata primero a Nibbles. Kystia tiene un escudo vil y casi no recibe daño mientras Nibbles esté por encima del 20% de vida.|n2. Al 20%, Nibbles se vuelve contra Kystia con {SPELL:1230304}: Kystia queda aturdida y recibe mucho más daño durante un rato. Cambia a Kystia ya y usa tus cooldowns grandes.|n3. {SPELL:1264095}: aparecen copias de Kystia que lanzan Felstorm. Interrumpe, aturde o controla a cada copia.|n4. Quédate fuera del cono {SPELL:1253811} de Nibbles y del fuego que deja en el suelo.|n5. En Heroico o más difícil: {SPELL:474240} - salta sobre un jugador y explota. Aléjate de ella.",
	DGN_TIP_MR_KYSTIA_QUICK_DPS = "Pega primero a la mascota y luego al jefe cuando la mascota tenga poca vida.",
	DGN_TIP_MR_KYSTIA_QUICK_HEALER = "Quita rápido el debuff de escupitajo a los jugadores y guarda una cura grande para el cambio.",
	DGN_TIP_MR_KYSTIA_QUICK_TANK = "Apunta el cono de fuego de la mascota lejos del grupo.",
	DGN_TIP_MR_KYSTIA_QUICK = "Mascota primero: pega primero a la mascota Nibbles. El jefe tiene un escudo y casi no recibe daño.|nCambio: cuando Nibbles tiene poca vida, aturde al jefe. Ahora pega fuerte al jefe.|nCopias: aparecen copias del jefe. Interrumpe o aturde a cada una.",
	DGN_TIP_MR_KYSTIA_TANK = "Tanque: apunta el cono {SPELL:1253811} de Nibbles lejos del grupo. Mantén juntos a Kystia y a Nibbles para que el grupo pueda golpear a los dos con daño en área. El Chaos Barrage de Kystia te pega fuerte, así que ten un defensivo listo.",
	DGN_TIP_MR_KYSTIA_HEALER = "Sanador: disipa Corroding Spittle (magia) rápido, sobre todo durante {SPELL:1264095}. Guarda un cooldown de curación para la ventana de daño tras {SPELL:1230304}: Kystia aturdida lanza estallidos viles al grupo.",

	DGN_TIP_MR_ZAEN_STEPS = "1. Caen cajas sobre los jugadores ({SPELL:474765}). Sal de las marcas. Las cajas que caen son tu cobertura.|n2. {SPELL:1218347}: apunta a todos los que puede ver. Escóndete tras una caja antes de que dispare, para que no te vea. Cada uno necesita su propia caja.|n3. ¿Tienes {SPELL:1214357}? La bomba explota a los 6 segundos y destruye las cajas cercanas. Llévala lejos de las cajas que necesitas para cubrirte.|n4. {SPELL:474478}: 3 segundos de daño fuerte a todo el grupo. Ten la vida llena.|n5. En Mítico y Mythic+: las cajas verdes viles (Fel-Infused Freight) dañan a todo el grupo sin parar. Si tienes {SPELL:1214357}, llévala a una caja verde para destruirla y conserva las cajas normales.",
	DGN_TIP_MR_ZAEN_QUICK_DPS = "Ponte tras una caja antes del disparo grande, no después.",
	DGN_TIP_MR_ZAEN_QUICK_HEALER = "Quita el veneno al tanque y ten a todos llenos antes de los disparos.",
	DGN_TIP_MR_ZAEN_QUICK_TANK = "Usa un defensivo cuando te apuñale y haz que te quiten el veneno.",
	DGN_TIP_MR_ZAEN_QUICK = "Cajas: caen cajas del cielo. Apártate y luego úsalas como muros.|nDisparo: cuando apunta a todos, escóndete tras una caja para que no te vea.|nBomba: ¿tienes la bomba? Llévala lejos de las cajas donde te escondes.",
	DGN_TIP_MR_ZAEN_TANK = "Tanque: usa un defensivo para {SPELL:1222795}. También deja Heartstop Poison, que baja tu vida máxima: que te lo disipen o quítatelo tú.",
	DGN_TIP_MR_ZAEN_HEALER = "Sanador: disipa Heartstop Poison del tanque tras {SPELL:1222795}. Sube a todos a tope antes de {SPELL:474478} y cura el sangrado de quien reciba el disparo.",

	DGN_TIP_MR_XATHUUX_STEPS = "1. {SPELL:1214637}: lanza su hacha a un jugador. Si eres tú, ponte cerca del jefe pero lejos de los demás. El hacha se queda y electrocuta a todos cada vez más fuerte: destrúyela rápido.|n2. Infernal Crush ({SPELL:1295452}): aparecen círculos bajo los jugadores. Separaos para no daros unos a otros.|n3. {SPELL:474197}: daño a todos y luego, durante 15 segundos, ataca más rápido y recibe un 30% más de daño. Usa tus cooldowns ahora.|n4. Durante la furia deja fuego por donde pasa ({SPELL:474234}). Quédate fuera. El tanque lo lleva despacio por el borde de la sala.",
	DGN_TIP_MR_XATHUUX_QUICK_DPS = "Mata primero el hacha y guarda tus ataques grandes para la furia.",
	DGN_TIP_MR_XATHUUX_QUICK_HEALER = "Planea una cura grande para la furia y ten al tanque a tope antes del golpe grande.",
	DGN_TIP_MR_XATHUUX_QUICK_TANK = "Usa un defensivo para su golpe grande y llévalo despacio por el borde cuando se enfurezca.",
	DGN_TIP_MR_XATHUUX_QUICK = "Hacha: lanza su hacha. Déjala junto al jefe y rómpela rápido.|nCírculos: sepárate cuando aparezcan círculos bajo tus pies.|nFuria: cuando se enfada, recibe más daño. Pega fuerte y quédate fuera de su rastro de fuego.",
	DGN_TIP_MR_XATHUUX_TANK = "Tanque: usa un defensivo para {SPELL:473898}; reduce la curación que recibes durante 8 segundos. Ponlo mirando lejos del grupo y muévelo encima del hacha para que la golpeen con daño en área. Durante {SPELL:474197}, llévalo despacio por el borde para que el fuego no llegue al centro.",
	DGN_TIP_MR_XATHUUX_HEALER = "Sanador: {SPELL:474197} e Infernal Crush suelen llegar juntos, así que planea un cooldown. El tanque recibe mucha menos curación tras {SPELL:473898}; tenlo a tope antes. Cada segundo que el hacha sigue viva, el grupo recibe más daño.",

	DGN_TIP_MR_LITHIEL_STEPS = "1. Interrumpe cada Chaos Bolt. Acordad un orden de interrupciones.|n2. {SPELL:1218203}: caen círculos sobre los jugadores. Separaos 6 metros. Cada círculo crea Wild Imps: atúrdelos o interrúmpelos y matadlos juntos.|n3. {SPELL:474408}: llega un demonio grande. El tanque lo recoge y todos lo matan.|n4. {SPELL:1224478}: una ola de fuego vil cruza la sala. Mata a todos los demonios antes de que los alcance, o se vuelven mucho más rápidos. Usa el Demonic Gateway para que la ola no te dé; si te da, recibes más daño de fuego.|n5. En Mítico y Mythic+: un Infernal persigue al tanque. No se puede matar y tocarlo puede matarte. El tanque lo mantiene lejos del grupo y del portal.",
	DGN_TIP_MR_LITHIEL_QUICK_DPS = "Interrumpe al jefe y a los imps, y mata a todos los demonios antes de la ola.",
	DGN_TIP_MR_LITHIEL_QUICK_HEALER = "Todos reciben daño de fuego todo el combate. Cura primero a quien le dio la ola.",
	DGN_TIP_MR_LITHIEL_QUICK_TANK = "Recoge rápido a los demonios. En Mítico, lleva al Infernal lejos de todos.",
	DGN_TIP_MR_LITHIEL_QUICK = "Interrupciones: interrumpe cada Chaos Bolt que lance el jefe.|nImps: separaos. Salen demonios pequeños. Atúrdelos y mátalos rápido.|nOla: mata a todos los demonios antes de la ola de fuego y luego cruza el portal para que no te dé.",
	DGN_TIP_MR_LITHIEL_TANK = "Tanque: recoge rápido al Vilefiend, te pega fuerte. Mantén juntos a los Wild Imps para que se les pueda hacer daño en área. En Mítico, lleva al Infernal lejos del grupo y nunca cerca del portal.",
	DGN_TIP_MR_LITHIEL_HEALER = "Sanador: todo el combate hay daño de fuego constante sobre el grupo. Quien reciba {SPELL:1224478} sigue ardiendo y recibe más daño de fuego: cúralo primero.",

	-- Den of Nalorakk -----------------------------------------------------------
	DGN_TIP_DN_HOARDMONGER_STEPS = "1. {SPELL:1234233}: lanza comida podrida durante unos segundos. Esquiva los impactos. Luego crecen Rotten Mushrooms verdes en el suelo.|n2. Pisa cada seta antes de que reviente (unos 12 segundos). Separaos para que no se escape ninguna. Cada seta te da un veneno, así que turnaos.|n3. {SPELL:1253268} es un cono frontal. Sal de la zona que marca. {SPELL:1235118} golpea a todo el grupo, así que mantente con la vida alta.|n4. Tres veces corre a un montón de carne, huesos o setas y gana un ataque nuevo. La carne hace más fuerte su rugido. Los huesos le dan un golpe al suelo que deja huesos rotos ({SPELL:1235405}): no los pises. Las setas significan más setas que pisar.|n5. En Mítico y Mythic+: cada ataque nuevo se queda el resto del combate, así que se van sumando. Las guías cogen primero carne, luego huesos y las setas al final.",
	DGN_TIP_DN_HOARDMONGER_QUICK_DPS = "Ayuda a pisar las setas y túrnate con los demás.",
	DGN_TIP_DN_HOARDMONGER_QUICK_HEALER = "Cura fuerte cuando ruja y quita el veneno a quienes pisan setas si puedes.",
	DGN_TIP_DN_HOARDMONGER_QUICK_TANK = "Deja al jefe junto al montón que quieras: carne, luego huesos, luego setas.",
	DGN_TIP_DN_HOARDMONGER_QUICK = "Setas: pisa las setas verdes antes de que revienten, y turnaos.|nGolpe: el jefe golpea el suelo delante de él. Sal de esa zona.|nMontones: coge comida de un montón y aprende un truco nuevo. No pises los huesos que deja.",
	DGN_TIP_DN_HOARDMONGER_TANK = "Tanque: corre al montón más cercano, así que déjalo junto al que quieras: primero carne, luego huesos, setas al final. Mantén las zonas de huesos lejos de donde está el grupo.",
	DGN_TIP_DN_HOARDMONGER_HEALER = "Sanador: usa un cooldown de curación en {SPELL:1235118}: ignora la armadura y golpea a todos. Quienes pisan setas reciben un veneno (Toxic Spores): disípalo si tu clase puede y mantenlos con la vida alta.",

	DGN_TIP_DN_SENTINEL_STEPS = "1. {SPELL:1235623}: caen pequeños tornados que vagan por la sala mucho rato. Poneos juntos para que caigan en un solo sitio y luego alejaos de ellos.|n2. {SPELL:1235783}: caen dos carámbanos. Sal de los círculos. Cada uno deja un add Fractured Shivercore.|n3. Los adds lanzan Winter's Shroud. Interrúmpelo: cada lanzamiento hace que todo el grupo reciba más daño de escarcha. Un add muerto deja un Snowdrift: nieve profunda que te ralentiza, pero nada puede moverte mientras estés en ella.|n4. {SPELL:1235656}: una gran tormenta golpea a todos y los mueve. Mata un add justo antes y quédate en su Snowdrift hasta que acabe la tormenta. Luego mata al otro add.|n5. En Mítico y Mythic+: un add al morir suelta fragmentos de hielo (Rimeshatter). Pon exactamente a un jugador en cada círculo de fragmento. Un fragmento sin cubrir golpea a todo el grupo y enraíza a todos.",
	DGN_TIP_DN_SENTINEL_QUICK_DPS = "Turnaos para cortar los lanzamientos de los adds y mata el primer add justo antes de la tormenta.",
	DGN_TIP_DN_SENTINEL_QUICK_HEALER = "Quita rápido el debuff de escarcha y cura a todos durante la tormenta.",
	DGN_TIP_DN_SENTINEL_QUICK_TANK = "Pon al jefe encima de un add y mantenlo lejos de los tornados.",
	DGN_TIP_DN_SENTINEL_QUICK = "Tornados: poneos juntos para que caigan en un sitio y luego alejaos.|nAdds: aparecen dos adds de hielo. Corta su lanzamiento y mata uno justo antes de la tormenta.|nTormenta: ponte en la nieve que deja el add muerto. Así la tormenta no puede moverte.",
	DGN_TIP_DN_SENTINEL_TANK = "Tanque: lleva al jefe encima de un add para que el grupo le haga daño en área, y mantén al jefe lejos de los tornados. Ayuda a interrumpir Winter's Shroud.",
	DGN_TIP_DN_SENTINEL_HEALER = "Sanador: {SPELL:1235548} es un DoT mágico de escarcha: disípalo rápido y cura a los que no puedas disipar. La tormenta golpea a todos, así que prepárate para curar al grupo.",

	DGN_TIP_DN_NALORAKK_STEPS = "1. {SPELL:1242860}: tres jugadores reciben una marca. Ve al borde antes de que acabe: aparece un oso fantasma (un Echo) donde estás. Junta todos los Echoes, lejos del grupo. Los Echoes dañan a quien esté cerca cada vez que él da un zarpazo.|n2. {SPELL:1243011}: Nalorakk derriba a Zul'jarra y cada Echo carga hacia ella. Rodeadla como un muro y bloquead las cargas. Un Echo que la alcanza daña a todo el grupo.|n3. {SPELL:1243569}: Nalorakk golpea al tanque una y otra vez. Zul'jarra pone un escudo que reduce este daño a la mitad: todos se ponen detrás de su escudo.|n4. Justo después, solo el tanque se mete en Forceful Slam. Todos los demás salen. Si le da a Zul'jarra, todo el grupo recibe daño.|n5. En Mítico y Mythic+: bloquear un Echo también te da un sangrado que se acumula (Spectral Slash). Pon a un jugador en cada carril de carga y nunca dejes que dos personas bloqueen el mismo Echo.",
	DGN_TIP_DN_NALORAKK_QUICK_DPS = "Ponte en el camino de un oso fantasma, una persona por oso.",
	DGN_TIP_DN_NALORAKK_QUICK_HEALER = "Cura fuerte al tanque durante los golpes grandes y sube a todos a tope antes del rugido.",
	DGN_TIP_DN_NALORAKK_QUICK_TANK = "Escóndete tras su escudo y luego recibe tú solo el siguiente golpe.",
	DGN_TIP_DN_NALORAKK_QUICK = "Marcas: si te marcan, ve al borde. Allí aparece un oso fantasma.|nCarga: los osos fantasma corren hacia Zul'jarra. Ponte en su camino para pararlos.|nEscudo: cuando el jefe golpea muchas veces al tanque, todos se esconden tras su escudo.",
	DGN_TIP_DN_NALORAKK_TANK = "Tanque: {SPELL:1243569} va a por ti. Ponte detrás del escudo de Zul'jarra y usa un defensivo. Luego métete solo en Forceful Slam, lejos del grupo.",
	DGN_TIP_DN_NALORAKK_HEALER = "Sanador: el tanque recibe golpes grandes durante {SPELL:1243569} y luego Forceful Slam. Sube al grupo a tope antes de Forceful Roar. En Mythic+, vigila los stacks de sangrado de quienes bloquean Echoes.",

	-- The Blinding Vale -----------------------------------------------------------
	DGN_TIP_BV_TRINITY_STEPS = "1. Los tres jefes comparten una barra de vida. El tanque los junta y todos golpean a los tres. Interrumpe el Light Bolt de Kezkitt.|n2. {SPELL:1234753} golpea al tanque y deja tres círculos verdes. No te pongas en ellos todavía. Luego Lekshi carga a través de los tres círculos ({SPELL:1234850}) - quédate fuera de esa línea.|n3. Cuando empiece {SPELL:1235564}, un jugador se pone en cada círculo (el tanque y dos más) hasta que acabe el rayo. Un círculo vacío hace que todo el grupo reciba mucho daño más tarde.|n4. Tras el rayo, los círculos se vuelven suelo ardiendo ({SPELL:1235828}). Sal; el tanque mueve a los jefes a suelo limpio. {SPELL:1261276} hace sangrar a un jugador al azar: usa un defensivo o quítate el sangrado.|n5. En Mítico y Mythic+: tras Thornblade, Lekshi salta sobre ese jugador y lanza espinas a su alrededor. Ese jugador se aleja del grupo y luego sale de las espinas. Bedrock Slam también manda pulsos de daño a todo el grupo.",
	DGN_TIP_BV_TRINITY_QUICK_DPS = "Pega a los tres jefes a la vez e interrumpe el Light Bolt de Kezkitt.",
	DGN_TIP_BV_TRINITY_QUICK_HEALER = "Mantén vivos a los jugadores de los círculos y cura al que sangra.",
	DGN_TIP_BV_TRINITY_QUICK_TANK = "Usa un defensivo en el golpe grande y luego saca a los tres jefes del suelo ardiendo.",
	DGN_TIP_BV_TRINITY_QUICK = "Tres jefes: comparten una barra de vida. Júntalos y pega a los tres.|nCírculos: cuando llegue el rayo, un jugador se pone en cada círculo hasta que pare.|nCarga: quédate fuera de la línea entre los círculos y sal de ellos cuando ardan.",
	DGN_TIP_BV_TRINITY_TANK = "Tanque: usa un defensivo para {SPELL:1234753}. Mantén a los tres juntos para el daño en área, ponte en un círculo durante el rayo y luego saca a los jefes del suelo ardiendo antes del siguiente golpe.",
	DGN_TIP_BV_TRINITY_HEALER = "Sanador: los tres que están en los círculos reciben daño constante - mantenlos en pie y cura el sangrado de {SPELL:1261276}. En Mítico, guarda un cooldown para los pulsos de grupo tras Bedrock Slam.",

	DGN_TIP_BV_IKUZZ_STEPS = "1. {SPELL:1236746} golpea a todos y te empuja hacia atrás. Colócate para no salir volando por un borde ni caer en las raíces.|n2. {SPELL:1236709}: ruge y daña a todo el grupo durante 6 segundos. Usa un defensivo si tienes poca vida.|n3. {SPELL:1237091}: persigue a un jugador durante 10 segundos. Ese jugador corre y lo lleva por encima de las raíces del suelo: sus pisadas las aplastan. Si te alcanza, sangras y quedas aturdido ({SPELL:1272290}).|n4. Desde el 50% de vida se enfurece: se mueve más rápido y daña al grupo sin parar. Guarda cooldowns para esto.|n5. En Mítico y Mythic+: tras el pisotón, unas raíces atrapan a todos los jugadores unos segundos después, y crecen más raíces durante el rugido. Vuelve junto al jefe para que el grupo rompa las raíces con daño en área, o usa un hechizo de libertad.",
	DGN_TIP_BV_IKUZZ_QUICK_DPS = "Rompe las raíces rápido y, si te persigue, corre sobre las raíces.",
	DGN_TIP_BV_IKUZZ_QUICK_HEALER = "Guarda tus curas grandes para cuando tenga media vida.",
	DGN_TIP_BV_IKUZZ_QUICK_TANK = "Mantén al jefe cerca de los jugadores atrapados en raíces para que todos puedan romperlas.",
	DGN_TIP_BV_IKUZZ_QUICK = "Pisotón: empuja a todos hacia atrás. No te pongas cerca de un borde.|nPersecución: persigue a un jugador. Ese jugador corre sobre las raíces para que él las aplaste.|nMedia vida: se vuelve más rápido y pega más fuerte. Usa ya tus hechizos grandes.",
	DGN_TIP_BV_IKUZZ_TANK = "Tanque: mantén a Ikuzz cerca de los jugadores atrapados en raíces para que todos puedan romperlas con daño en área, y lejos de los bordes por el empujón.",
	DGN_TIP_BV_IKUZZ_HEALER = "Sanador: el pisotón y {SPELL:1236709} golpean a todo el grupo. Guarda tus cooldowns grandes para el frenesí del 50%, sobre todo cuando ruja durante él. Un jugador alcanzado recibe mucho daño - súbelo rápido.",

	DGN_TIP_BV_RUIA_STEPS = "1. Forma de lechúcico (del 100 al 70%): interrumpe Warden's Wrath - golpea al tanque. Esquiva los círculos de {SPELL:1240098}.|n2. {SPELL:1239825} marca a varios jugadores. Aléjate del grupo antes de que acabe: luego salen rayos desde ti. Quédate fuera de los rayos - te silencian.|n3. Forma de oso (del 70 al 40%): {SPELL:1240222} marca a varios jugadores y les lanza conos. Los marcados se separan y mantienen su cono lejos de los demás. Un segundo golpe duele mucho más.|n4. {SPELL:1241058} hace sangrar a los jugadores hasta que se curan al máximo.|n5. Al 40% de vida, {SPELL:1241067}: lanza todo esto cada 8 segundos hasta morir. Usa tus cooldowns y Bloodlust aquí.",
	DGN_TIP_BV_RUIA_QUICK_DPS = "Interrumpe su hechizo en forma de lechúcico y guarda tus hechizos grandes para el 40 por ciento.",
	DGN_TIP_BV_RUIA_QUICK_HEALER = "Un jugador que sangra sigue sangrando hasta que lo curas del todo.",
	DGN_TIP_BV_RUIA_QUICK_TANK = "Asegúrate de que interrumpan su hechizo en forma de lechúcico y usa defensivos en forma de oso.",
	DGN_TIP_BV_RUIA_QUICK = "Lechúcico: interrumpe su hechizo, esquiva los círculos y aléjate del grupo si te marcan con el rayo.|nOso: si te marcan, apártate para que tu cono no dé a nadie más.|n40%: lo hace todo a la vez. Usa ya tus hechizos grandes.",
	DGN_TIP_BV_RUIA_TANK = "Tanque: en forma de lechúcico su cuerpo a cuerpo se cambia por Warden's Wrath - asegúrate de que se interrumpa. En forma de oso su cuerpo a cuerpo pega el doble (Mangling Claws), así que usa ahí tus defensivos.",
	DGN_TIP_BV_RUIA_HEALER = "Sanador: {SPELL:1241058} solo se detiene cuando el jugador tiene la vida al máximo - cura a uno hasta arriba y luego al siguiente. Guarda cooldowns para la fase del 40%.",

	DGN_TIP_BV_ZIEKKET_STEPS = "1. {SPELL:1246372}: brotan lashers. El tanque los junta; todos les hacen daño en área e interrumpen Lightspore Shot.|n2. Un lasher al 1% de vida se hunde en el suelo y no se le puede dañar. Despierta más fuerte en el siguiente {SPELL:1246372}, y entonces no se puede interrumpir ni aturdir.|n3. {SPELL:1253690} apunta un rayo a un jugador. Si eres tú, gírate para que el rayo pase por todos los lashers dormidos - eso los mata para siempre. Deja charcos que ralentizan ({SPELL:1246753}); sal de ellos.|n4. {SPELL:1247685} golpea fuerte al tanque, lo empuja y le hace sangrar. Todo el grupo recibe daño en pulsos todo el combate.|n5. En Mítico y Mythic+: {SPELL:1246858} manda orbes hacia Ziekket. Métete en ellos antes de que le lleguen y repartidlos (unos dos o tres cada uno) - cada orbe te da un DoT que se acumula. Un orbe que le llega daña al grupo y lo escuda.",
	DGN_TIP_BV_ZIEKKET_QUICK_DPS = "Interrumpe los disparos de los lashers y deja de pegar a un lasher cuando duerma.",
	DGN_TIP_BV_ZIEKKET_QUICK_HEALER = "Todo el grupo recibe daño todo el combate, así que sigue curando a todos.",
	DGN_TIP_BV_ZIEKKET_QUICK_TANK = "Junta a los lashers y usa un defensivo en el golpe grande de pinchos.",
	DGN_TIP_BV_ZIEKKET_QUICK = "Lashers: pégales hasta que se hundan en el suelo. Entonces duermen.|nRayo: si el rayo te apunta, pásalo por los lashers dormidos. Eso los mata para siempre.|nOrbes (Mítico): toca las bolas brillantes antes de que lleguen al jefe y repartidlas.",
	DGN_TIP_BV_ZIEKKET_TANK = "Tanque: junta cada oleada de lashers para el daño en área, cerca del borde. Usa un defensivo para {SPELL:1247685} - te empuja y te hace sangrar. Sal de los charcos de Lightsap.",
	DGN_TIP_BV_ZIEKKET_HEALER = "Sanador: el grupo recibe daño todo el combate, así que sigue curando a todos. En Mítico, vigila a quienes cogen orbes - sus stacks duelen, y un orbe perdido golpea a todo el grupo.",

	-- Voidscar Arena ----------------------------------------------------------------
	DGN_TIP_VA_TAZRAH_STEPS = "1. {SPELL:1222098}: una sombra cruza a cada jugador en línea recta. Separaos un poco cerca del borde de la sala, para que tu línea no dé a nadie más.|n2. {SPELL:1296963} deja charcos en el suelo. Suéltalos cerca del borde y juntos, y nunca te quedes en ellos.|n3. {SPELL:1300259}: los charcos disparan orbes. Sigue moviéndote por la sala y esquiva cada orbe.|n4. En Mítico y Mythic+: {SPELL:1225011} - dos fragmentos vuelan hacia un jugador y cada uno estalla en el primer jugador que toca. No te metas en fragmentos dirigidos a otro.",
	DGN_TIP_VA_TAZRAH_QUICK_DPS = "Sigue pegando al jefe mientras esquivas.",
	DGN_TIP_VA_TAZRAH_QUICK_HEALER = "Sube a todos a tope antes de que lleguen los charcos.",
	DGN_TIP_VA_TAZRAH_QUICK_TANK = "Usa un defensivo cuando te empuje y no caigas en un charco.",
	DGN_TIP_VA_TAZRAH_QUICK = "Carga: un fantasma corre hacia ti en línea recta. Ponte cerca de la pared, un poco separado de tus amigos.|nCharcos: suelta tus charcos oscuros cerca de la pared, juntos. Nunca te quedes en ellos.|nOrbes: los charcos disparan bolas. Sigue andando por la sala y esquívalas.",
	DGN_TIP_VA_TAZRAH_TANK = "Tanque: {SPELL:1297017} te pega fuerte y te empuja hacia atrás. Usa un defensivo y que no te lance a un charco. Tanquea cerca de una pared y gira despacio por la sala, para que el centro quede libre.",
	DGN_TIP_VA_TAZRAH_HEALER = "Sanador: sube a todos a tope antes de cada {SPELL:1296963}; {SPELL:1300259} daña a todo el grupo. Cura a quien reciba una carga, porque le sigue haciendo daño un rato.",

	DGN_TIP_VA_ATROXUS_STEPS = "1. {SPELL:1262497} golpea a todo el grupo. Unos 3 segundos después sale arrastrándose un Toxic Creeper ({SPELL:1222371}). Mátalo rápido.|n2. {SPELL:1263977} es un frontal dirigido a un jugador al azar. Quédate cerca del jefe para poder salir rápido.|n3. {SPELL:1226120} salpica veneno alrededor del jefe. Esquiva los impactos y quédate fuera de los charcos de veneno que deja.|n4. En Mítico y Mythic+: el Creeper tiene Toxic Aura - daña a todos a menos de 8 metros hasta que muere. Mátalo aún más rápido; los de distancia se mantienen lejos de él.",
	DGN_TIP_VA_ATROXUS_QUICK_DPS = "Cuando salga el Creeper, pégale a él primero.",
	DGN_TIP_VA_ATROXUS_QUICK_HEALER = "Quita los venenos al tanque y a quien haya pisado un charco.",
	DGN_TIP_VA_ATROXUS_QUICK_TANK = "El Creeper te persigue: aléjate de él para que no te muerda.",
	DGN_TIP_VA_ATROXUS_QUICK = "Rugido: el jefe ruge y sale un bicho pequeño, el Creeper. Todos le pegan hasta que muere.|nAliento: el jefe echa su aliento a un jugador al azar. Quédate cerca y sal de él.|nVeneno: apártate de las salpicaduras de veneno y de los charcos.",
	DGN_TIP_VA_ATROXUS_TANK = "Tanque: el Creeper se fija en ti. Aléjate de él y no dejes que te pegue - cada mordisco suma un stack de Sickening Bite, y los stacks hacen mortal {SPELL:1222642}. Mantenlo cerca del jefe para que los DPS peguen a los dos, y usa un defensivo para el zarpazo.",
	DGN_TIP_VA_ATROXUS_HEALER = "Sanador: disipa venenos: el veneno de {SPELL:1222642} en el tanque y Mind-Numbing Poison de los charcos. En Mítico y Mythic+, usa un cooldown de curación mientras el Creeper esté vivo.",

	DGN_TIP_VA_CHARONUS_STEPS = "1. {SPELL:1282770}: se marca a algunos jugadores y unos segundos después aparece un pozo de gravedad bajo ellos. Te atrae y hace daño. Sal, pero quédate junto a uno - lo necesitas para los orbes. Su centro da Atomized: sin daño y sin curación durante un rato.|n2. {SPELL:1263982}: un orbe persigue a 3 jugadores. Su debuff duele y te ralentiza más cada segundo. Pasa junto a un pozo de gravedad para que tu orbe te siga dentro - eso destruye los dos. No te pares dentro. Cada jugador usa un pozo distinto.|n3. {SPELL:1227264} golpea a todos, te empuja hacia atrás y deja un efecto de daño de 20 segundos. Separaos, y asegúrate de no caer en un pozo.|n4. En Mítico y Mythic+: {SPELL:1222758} - vuelan proyectiles hacia un jugador al azar y empujan a quien tocan. Si eres tú, sigue corriendo; los demás salen de la trayectoria.",
	DGN_TIP_VA_CHARONUS_QUICK_DPS = "Espera junto a un agujero, para que la bola que te persigue caiga rápido.",
	DGN_TIP_VA_CHARONUS_QUICK_HEALER = "Cura primero a los jugadores a los que persigue una bola.",
	DGN_TIP_VA_CHARONUS_QUICK_TANK = "Usa un defensivo para su golpe grande y apúntalo lejos de tus amigos.",
	DGN_TIP_VA_CHARONUS_QUICK = "Pozos: aparecen agujeros oscuros en el suelo. Te atraen, así que quédate cerca de uno pero no dentro.|nOrbes: si una bola te persigue, pasa junto a un agujero para que la bola caiga dentro.|nExplosión: el jefe empuja a todos hacia atrás. Separaos y no salgas volando a un agujero.",
	DGN_TIP_VA_CHARONUS_TANK = "Tanque: {SPELL:1311923} es un golpe frontal al tanque. Usa un defensivo y apúntalo lejos del grupo. Mantén al jefe en medio de los tres pozos de gravedad y no lo gires hacia los jugadores.",
	DGN_TIP_VA_CHARONUS_HEALER = "Sanador: cura primero a los jugadores con un orbe - cuanto más tiempo lo llevan, más fuerte pega. Tras {SPELL:1227264} todo el grupo tiene un efecto de daño de 20 segundos, y los pozos de gravedad dan pulsos de daño mientras duran.",

	-- Nexus-Point Xenas ---------------------------------------------------------------
	DGN_TIP_NX_KASRETH_STEPS = "1. ¿{SPELL:1251785} en ti? Pisa DENTRO de un rayo de leyline ({SPELL:1251183}) — quita el debuff (aturdimiento corto, buen trato).|n2. Los demás: NO crucéis las leylines (daño + ralentización acumulada).|n3. Energía llena = {SPELL:1257509}: gran zona de impacto, despeja — luego quedan charcos arcanos ({SPELL:1264048}).",
	DGN_TIP_NX_KASRETH_TANK = "Tanque: mantén al jefe lejos de las leylines.",
	DGN_TIP_NX_KASRETH_HEALER = "Sanador: Sparkburn hace tictac a todos tras cada detonación.",

	DGN_TIP_NX_NYSARRA_STEPS = "1. Separaos — los golpes de {SPELL:1249020} salpican a 14 metros.|n2. Matad a los adds Null Vanguard ({SPELL:1252703}) RÁPIDO: lo que siga vivo es devorado ({SPELL:1271684}), la cura y estalla sobre el grupo.|n3. Esquiva las {SPELL:1264439}.",
	DGN_TIP_NX_NYSARRA_TANK = "Tanque: te salta encima con un combo de tajos ({SPELL:1247937}) — defensivo, prepárate para el remate.",
	DGN_TIP_NX_NYSARRA_HEALER = "Sanador: daño disperso tras {SPELL:1249020}; estallido de grupo si los adds sobreviven a la devoración.",

	DGN_TIP_NX_LOTHRAXION_STEPS = "1. {SPELL:1255503}: separaos — los impactos salpican a 8 metros y generan Fractured Images.|n2. {SPELL:1257567}: se esconde entre sus reflejos y todos canalizan — encuentra al Lothraxion REAL e interrúmpelo.|n3. Los reflejos parpadean con empujones ({SPELL:1255531}); no pises las {SPELL:1255310} del suelo.",
	DGN_TIP_NX_LOTHRAXION_TANK = "Tanque: {SPELL:1255335} es un tajo doble que graba cicatrices en el suelo — apúntalo lejos del grupo.",
	DGN_TIP_NX_LOTHRAXION_HEALER = "Sanador: DoTs Sagrados tras cada {SPELL:1255503}; daño constante hasta que entre la interrupción del Guile.",

	-- Magisters' Terrace ---------------------------------------------------------------
	DGN_TIP_MT_ARCANOTRON_STEPS = "1. Cuando reposta ({SPELL:474345}), los Energy Orbs son atraídos hacia él — intercéptalos; mientras tanto recibe +20% de daño: ¡ventana de burst!|n2. Los jugadores encadenados ({SPELL:1214038}) quedan enraizados (magia) — disipa o libéralos.|n3. {SPELL:1214081} empuja a todos y deja residuos a sus pies — sal de ahí.",
	DGN_TIP_MT_ARCANOTRON_TANK = "Tanque: {SPELL:474496} te lanza por los aires — mantén la espalda despejada.",
	DGN_TIP_MT_ARCANOTRON_HEALER = "Sanador: disipa {SPELL:1214038} (raíz mágica) rápido.",

	DGN_TIP_MT_SERANEL_STEPS = "1. {SPELL:1225193} pacifica a todos FUERA de la Suppression Zone ({SPELL:1224903}) — entra EN la zona para la oleada (pero la zona te silencia, no te quedes).|n2. Purga/roba su {SPELL:1248689} (+100% de velocidad de ataque) en cuanto esté activa.|n3. {SPELL:1225787} rebota a un jugador cercano — separaos.",
	DGN_TIP_MT_SERANEL_TANK = "Tanque: una Ward sin purgar duplica su velocidad de ataque — defensivo hasta que se vaya.",
	DGN_TIP_MT_SERANEL_HEALER = "Sanador: los jugadores marcados hacen tictac; recuerda que dentro de la zona no se lanza nada.",

	DGN_TIP_MT_GEMELLUS_STEPS = "1. {SPELL:1223847} (al inicio y a media vida): se divide en tres.|n2. {SPELL:1253709}: ¿vinculado a uno? CORRE a tocarlo — eso rompe el vínculo y quita su escudo de absorción.|n3. {SPELL:1224299} te atrae — sal corriendo.",
	DGN_TIP_MT_GEMELLUS_TANK = "Tanque: reagrupa al trío tras cada {SPELL:1223847} para que los vinculados alcancen el suyo.",
	DGN_TIP_MT_GEMELLUS_HEALER = "Sanador: los vinculados reciben +20% de daño hasta romper su vínculo.",

	DGN_TIP_MT_DEGENTRIUS_STEPS = "1. {SPELL:1215897}: DoTs de vacío con duraciones distintas — cuando el tuyo expire, salen Entropy Orbs desde TU posición: apártate antes del grupo.|n2. {SPELL:1215087} rebota en 4 puntos — ABSORBE un impacto (un jugador por punto), o estalla en Void Destruction.|n3. {SPELL:1280113} machaca al tanque y lanza a quien esté a menos de 8 metros — dadle espacio al tanque.",
	DGN_TIP_MT_DEGENTRIUS_TANK = "Tanque: defensivo para {SPELL:1280113}; tanquéalo lejos del grupo.",
	DGN_TIP_MT_DEGENTRIUS_HEALER = "Sanador: los DoTs de Entropy pegan fuerte — mantén en pie a los portadores mientras se recolocan.",

	-- Skyreach ----------------------------------------------------------------------
	DGN_TIP_SR_RANJIT_STEPS = "1. {SPELL:1258148} vuela en línea recta frente a él — hazte a un lado.|n2. {SPELL:156793}: un impacto en el centro más remolinos errantes que te lanzan — sigue sorteando.|n3. {SPELL:153757} golpea a todos con un sangrado — ve lleno.|n4. {SPELL:1252733} lanza lejos a sus objetivos — mira qué hay detrás de ti.",
	DGN_TIP_SR_RANJIT_TANK = "Tanque: mantenlo fuera de las trayectorias de los vórtices.",
	DGN_TIP_SR_RANJIT_HEALER = "Sanador: daño de grupo más sangrados tras cada {SPELL:153757}.",

	DGN_TIP_SR_ARAKNATH_STEPS = "1. {SPELL:154162}: los ensamblajes canalizan luz al jefe y lo CURAN — ponte en un rayo para bloquearlo.|n2. {SPELL:154115}: un brazazo por un solo lado — que te dé acumula un debuff de daño brutal.|n3. {SPELL:154135} golpea a todos — prepárate.",
	DGN_TIP_SR_ARAKNATH_TANK = "Tanque: nunca absorbas los rayos tú — su golpe cae justo durante la absorción.",
	DGN_TIP_SR_ARAKNATH_HEALER = "Sanador: los que absorben rayos hacen tictac constante; curación de grupo en {SPELL:154135}.",

	DGN_TIP_SR_RUKHRAN_STEPS = "1. {SPELL:1253527}: 3 segundos de plumas en todas direcciones — rompe la línea de visión tras un pilar.|n2. {SPELL:1253510} golpea al grupo e invoca un Sunwing que se fija en alguien y pulsa fuego — mátalo rápido; el fijado mantiene distancia.|n3. Repite — plumas tras cobertura, ave abajo rápido.",
	DGN_TIP_SR_RUKHRAN_TANK = "Tanque: defensivo para {SPELL:1253519} (golpazo + DoT de quemadura).",
	DGN_TIP_SR_RUKHRAN_HEALER = "Sanador: daño de grupo pulsante mientras viva un Sunwing — pide su muerte.",

	DGN_TIP_SR_VIRYX_STEPS = "1. {SPELL:154396}: un lanzamiento de 3 segundos que destroza al tanque — INTERRÚMPELO, siempre.|n2. {SPELL:1253998}: un Solar Zealot agarra a un jugador para tirarlo del balcón — liberadlo rápido.|n3. ¿{SPELL:1253531} en ti? Llévalo bien lejos — deja Blazing Ground.",
	DGN_TIP_SR_VIRYX_TANK = "Tanque: cada {SPELL:154396} que se cuele duele — mantened firme el orden de interrupciones.",
	DGN_TIP_SR_VIRYX_HEALER = "Sanador: {SPELL:1253538} pone DoTs de fuego en varios jugadores a la vez.",

	-- Pit of Saron ----------------------------------------------------------------
	DGN_TIP_PS_GARFROST_STEPS = "1. {SPELL:1262029}: la forja pulsa escarcha acumulada — ESCÓNDETE DETRÁS de un bloque de saronita, bloquea la radiación.|n2. {SPELL:1261546} machaca todo alrededor del objetivo principal — quédate a 5+ metros del tanque; junto al mineral, el golpe rompe el mineral en vez de aturdir.|n3. {SPELL:1261847} golpea a todos y destroza TODO el mineral — llega más vía {SPELL:1261286}.|n4. Quédate fuera del {SPELL:1261799}.",
	DGN_TIP_PS_GARFROST_TANK = "Tanque: aparca junto a un bloque de mineral — {SPELL:1261546} romperá el mineral, no a ti.",
	DGN_TIP_PS_GARFROST_HEALER = "Sanador: pico de grupo en {SPELL:1261847}; escarcha acumulada en quien esté sin cobertura.",

	DGN_TIP_PS_KRICKICK_STEPS = "1. {SPELL:1264363}: Ick se fija y persigue a un jugador salpicando Blight y Plague Globs — corre amplio; el resto sigue pegando.|n2. {SPELL:1264027}: Krick se teletransporta a un círculo ritual e invoca Shades — cambiad y matadlos.|n3. {SPELL:1264336}: esquiva la oleada y los globs que ruedan hacia ti.|n4. Nunca pises el Blight ({SPELL:1264299}).",
	DGN_TIP_PS_KRICKICK_TANK = "Tanque: {SPELL:1264287} deja un charco sobre ti — apúntalo al borde.",
	DGN_TIP_PS_KRICKICK_HEALER = "Sanador: mantén vivo al perseguido; daño de grupo en {SPELL:1264336}.",

	DGN_TIP_PS_TYRANNUS_STEPS = "1. {SPELL:1262772} congela los Bone Piles alrededor de su objetivo — ponte junto a montones cuando estés marcado: los congelados no levantan adds.|n2. {SPELL:1263406} levanta los montones restantes — Plaguespreaders primero.|n3. Sigue esquivando {SPELL:1263756} y el {SPELL:1276948} de Rimefang.|n4. {SPELL:1276648} = golpe de grupo + DoT, y los montones infundidos dan adds peores.",
	DGN_TIP_PS_TYRANNUS_TANK = "Tanque: {SPELL:1262582} te catapulta y acumula +200% de daño de sombras — defensivo y agárrate.",
	DGN_TIP_PS_TYRANNUS_HEALER = "Sanador: DoTs de grupo tras {SPELL:1276648}; pico en el tanque justo tras el Brand.",

	-- Seat of the Triumvirate --------------------------------------------------------
	DGN_TIP_ST_ZURAAL_STEPS = "1. {SPELL:1268916} golpea todo lo que tenga DELANTE — nunca te pongas frente al jefe.|n2. {SPELL:1263304} (energía llena): arrastra a todos y luego estalla con empujón — sal a tiempo; los adds también son arrastrados.|n3. {SPELL:1263399} genera adds Coalesced Void — límpialos antes de Crashing Void.|n4. {SPELL:1263282} deja Void Sludge ({SPELL:244588}) — mantén el suelo limpio.",
	DGN_TIP_ST_ZURAAL_TANK = "Tanque: defensivo para {SPELL:1263440} (tajo triple).",
	DGN_TIP_ST_ZURAAL_HEALER = "Sanador: golpe de grupo grande en {SPELL:1263304}.",

	DGN_TIP_ST_SAPRISH_STEPS = "1. Las Void Bombs ({SPELL:247175}) caen en posiciones de jugadores — NO las toques; déjalas en los bordes.|n2. {SPELL:1280064}: sombras se lanzan hacia cada jugador y detonan las bombas que cruzan — traza tu línea libre de bombas.|n3. {SPELL:1263523} enciende TODAS las bombas a la vez — cuantas menos, más suave.|n4. Interrumpe el {SPELL:248831} de Shadewing (golpe de grupo + desorientación).",
	DGN_TIP_ST_SAPRISH_TANK = "Tanque: mantén al trío junto; el salto de Darkfang ({SPELL:245738}) deja sangrando a su víctima.",
	DGN_TIP_ST_SAPRISH_HEALER = "Sanador: las víctimas del salto sangran; estallido de grupo en {SPELL:1263523}.",

	DGN_TIP_ST_NEZHAR_STEPS = "1. {SPELL:1263528} empuja a todos — cuidado con tu posición cerca de tormentas.|n2. {SPELL:1263538} y las {SPELL:1277358} siembran el caos — mata tentáculos, esquiva las Umbral Waves del portal.|n3. Las zonas de {SPELL:1263532} pegan fuerte, dentro peor — fuera, rápido.|n4. {SPELL:244750} destroza al tanque — interrúmpelo cuando puedas.",
	DGN_TIP_ST_NEZHAR_TANK = "Tanque: aguanta {SPELL:244750} cuando no haya interrupción lista.",
	DGN_TIP_ST_NEZHAR_HEALER = "Sanador: {SPELL:1263542} = varios DoTs carcomiendo a la vez.",

	DGN_TIP_ST_LURA_STEPS = "1. Las Notes of Despair siguen irradiando ({SPELL:1265421}) hasta silenciarlas — dirige tu {SPELL:1265426} A TRAVÉS de las notas (el rayo también golpea a aliados en la línea, apunta despejado).|n2. {SPELL:1265689}: 20 segundos de dolor alrededor de cada nota activa — rómpelas rápido.|n3. {SPELL:1264151}: rayos de vacío rotatorios — muévete con los huecos.|n4. {SPELL:1266003} es una canalización letal de 10 segundos — todos los defensivos, y a curar a tope.",
	DGN_TIP_ST_LURA_TANK = "Tanque: tras {SPELL:1266001} todos salen volando — reagrupaos rápido.",
	DGN_TIP_ST_LURA_HEALER = "Sanador: golpes de grupo de {SPELL:1265421} más las auras de las notas — romper notas ES el plan de curación.",

	-- Algeth'ar Academy ----------------------------------------------------------------
	DGN_TIP_AA_VEXAMUS_STEPS = "1. Los {SPELL:385974} derivan hacia el jefe — absorbedlos, un jugador por orbe (golpecito); cada orbe que ÉL absorbe estalla sobre todo el grupo.|n2. {SPELL:386173}: llévate la tuya aparte — revienta en un charco de {SPELL:386201}.|n3. Energía llena = {SPELL:388537}: golpe de grupo más erupciones repetidas bajo los jugadores — sigue moviéndote.",
	DGN_TIP_AA_VEXAMUS_TANK = "Tanque: {SPELL:385958} revienta todo lo que tenga delante — defensivo, apúntalo lejos del grupo.",
	DGN_TIP_AA_VEXAMUS_HEALER = "Sanador: los portadores de bomba hacen tictac; daño de grupo por cada orbe que llegue al jefe.",

	DGN_TIP_AA_ANCIENT_STEPS = "1. {SPELL:388796}: durante 4 segundos germinan semillas bajo todos — esquiva; las falladas dejan Lashers dormidos.|n2. Con energía llena ({SPELL:388923}) despiertan TODOS los Lashers dormidos a la vez — límpialos antes.|n3. {SPELL:388623} lanza una rama que se vuelve un add grande — mátalo e INTERRUMPE su {SPELL:396640}.",
	DGN_TIP_AA_ANCIENT_TANK = "Tanque: {SPELL:388544} duplica el daño físico que recibes — defensivo, cada vez.",
	DGN_TIP_AA_ANCIENT_HEALER = "Sanador: limpia {SPELL:389033} (veneno) antes de que se acumule.",

	DGN_TIP_AA_CRAWTH_STEPS = "1. {SPELL:377004} estalla bajo cada jugador e interrumpe lanzamientos — DEJA de lanzar, luego separaos.|n2. {SPELL:377034}: mira a alguien y barre un cono hacia allí — sal de él.|n3. {SPELL:377182}: marca en una portería — la de fuego la aturde y recibe un 75% más de daño.",
	DGN_TIP_AA_CRAWTH_TANK = "Tanque: defensivo para {SPELL:376997} (golpe + sangrado de 10 s).",
	DGN_TIP_AA_CRAWTH_HEALER = "Sanador: daño de grupo pesado tras el chillido; el tanque sangra.",

	DGN_TIP_AA_DORAGOSA_STEPS = "1. ¿{SPELL:374341} en ti? Aléjala del grupo — estalla en 8 metros.|n2. {SPELL:388820} arrastra a todos y luego explota — SAL CORRIENDO antes del estallido.|n3. {SPELL:389011} se acumula con cada mecánica que comas — a 3 stacks revienta en un Arcane Rift; mantente limpio.|n4. No pises el suelo de {SPELL:389007}.",
	DGN_TIP_AA_DORAGOSA_TANK = "Tanque: defensivo para {SPELL:1282251}.",
	DGN_TIP_AA_DORAGOSA_HEALER = "Sanador: vigila los stacks de {SPELL:389011} — los portadores hacen más tictac por stack.",
	DGN_TIP_KR_COUNCIL_STEPS = "1. El consejo lucha de uno en uno: Kula, luego Aka'ali, luego Zanazal. Un miembro derrotado vuelve de vez en cuando para usar una habilidad. El combate termina cuando muere Zanazal.|n2. Kula: apártate de ella para {SPELL:266206} y esquiva las hachas que ruedan después. {SPELL:266231} hace sangrar a un jugador al azar — usa un defensivo.|n3. Aka'ali: {SPELL:267494} carga contra un jugador. Todos se juntan sobre ese jugador para repartir el daño.|n4. Zanazal: interrumpe {SPELL:267273}. Cuando invoque tótems ({SPELL:267060}), mata primero el Explosive Totem, luego el Thundering Totem y después el Torrent Totem.",
	DGN_TIP_KR_COUNCIL_QUICK_DPS = "Ponte en el grupo de la carga, interrumpe el veneno y mata primero el tótem que explota.",
	DGN_TIP_KR_COUNCIL_QUICK_HEALER = "Cura el sangrado de las hachas y ten a todos llenos antes de la carga.",
	DGN_TIP_KR_COUNCIL_QUICK_TANK = "Cuando Aka'ali te lance lejos, huye de ella hasta que se vaya el debuff.",
	DGN_TIP_KR_COUNCIL_QUICK = "Kula: Apártate de su giro y esquiva las hachas voladoras.|nAka'ali: Carga contra un jugador. Todos se ponen sobre ese jugador para repartir el golpe.|nZanazal: Interrumpe su hechizo de veneno y mata primero el tótem que explota.",
	DGN_TIP_KR_COUNCIL_DPS = "DPS: ponte en el grupo de {SPELL:267494}, sigue interrumpiendo {SPELL:267273} y cambia al Explosive Totem en cuanto aparezca.",
	DGN_TIP_KR_COUNCIL_HEALER = "Sanador: cura el sangrado de {SPELL:266231} y llena a todos antes de {SPELL:267494}. Con Zanazal, {SPELL:1305810} salta entre jugadores, y Poison Nova hace tictac a todos si no se interrumpe.",
	DGN_TIP_KR_COUNCIL_TANK = "Tanque: {SPELL:266237} te empuja hacia atrás y te hace recibir mucho más daño físico. Kitea a Aka'ali hasta que desaparezca el debuff, o usa un defensivo grande.",
	DGN_TIP_KR_DAZAR_STEPS = "1. Fase 1: Dazar lucha con su raptor Reban. Mata primero a Reban e interrumpe su {SPELL:269369}, un miedo. Reban salta sobre un jugador con {SPELL:269230} y muerde en cono — sal de él.|n2. {SPELL:1303115}: Dazar salta hacia dos jugadores. Esos dos se separan para no golpearse entre sí.|n3. Al 80% de vida, Dazar monta a su raptor T'zala. Ahora {SPELL:1303327} salta hacia cuatro jugadores y además golpea a todo el grupo — separaos y tened la vida llena.|n4. {SPELL:1303267} golpea a todo el grupo y quema durante 15 segundos. Justo después caen lanzas donde están los jugadores — sigue moviéndote y esquiva los círculos de Impaling Spear.|n5. En Mítico y Mythic+: {SPELL:1303267} también potencia sus golpes — lanzan una ola de oro hacia delante. El tanque lo orienta lejos del grupo.",
	DGN_TIP_KR_DAZAR_QUICK_DPS = "Mata primero al raptor pequeño e interrumpe su rugido.",
	DGN_TIP_KR_DAZAR_QUICK_HEALER = "Guarda tus curas grandes para el golpe de oro y los saltos del raptor.",
	DGN_TIP_KR_DAZAR_QUICK_TANK = "Usa tu mayor defensivo para el combo de espada y mantén al rey mirando hacia otro lado.",
	DGN_TIP_KR_DAZAR_QUICK = "Raptor: Mata primero al raptor pequeño e interrumpe su rugido de miedo.|nMontado: El rey monta su raptor grande. Separaos cuando salte y tened la vida llena.|nOro: Un gran golpe de fuego a todos y luego caen lanzas donde estás. Sigue moviéndote.",
	DGN_TIP_KR_DAZAR_DPS = "DPS: mata primero a Reban e interrumpe {SPELL:269369}. Deja espacio libre para que los objetivos del salto se separen y puedas esquivar las lanzas.",
	DGN_TIP_KR_DAZAR_HEALER = "Sanador: guarda tus cooldowns grandes para {SPELL:1303267} y {SPELL:1303327}. Vigila los sangrados de Impaling Spear y {SPELL:1303488}.",
	DGN_TIP_KR_DAZAR_TANK = "Tanque: defensivo grande para {SPELL:268586} — los golpes son más fuertes hacia el final. Cuando entra T'zala, {SPELL:1303488} también te golpea y te hace recibir más daño físico, así que reparte tus cooldowns entre ambos. Orienta a Dazar lejos del grupo.",
	DGN_TIP_KR_MCHIMBA_STEPS = "1. {SPELL:267618}: el jefe drena a un jugador. Los demás salen de los círculos de ácido que salpica. Si te toca a ti, usa un defensivo. Al terminar sigues lento y débil hasta que te curen por encima del 90% de vida.|n2. {SPELL:1311956} apunta a un jugador y deja suelo ardiente. Suéltalo en el borde, lejos del jefe y de los ataúdes.|n3. {SPELL:1312146} golpea a todo el grupo y abre ataúdes: salen dos Half-Finished Mummies. Mátalas e interrumpe su Wretched Discharge.|n4. {SPELL:267702}: un jugador queda encerrado en uno de los ataúdes. Si eres tú, pulsa el botón Struggle para que tu ataúd se sacuda. Los demás: buscad el ataúd que se sacude y hacedle clic rápido. Cada ataúd vacío que él abra antes suelta una Finished Mummy.",
	DGN_TIP_KR_MCHIMBA_QUICK_DPS = "Interrumpe a las momias y ayuda a encontrar el ataúd que se sacude.",
	DGN_TIP_KR_MCHIMBA_QUICK_HEALER = "Cura al jugador drenado casi al máximo; eso quita la ralentización.",
	DGN_TIP_KR_MCHIMBA_QUICK_TANK = "Agarra las momias y mantenlas junto al jefe.",
	DGN_TIP_KR_MCHIMBA_QUICK = "Drenaje: Si el jefe te drena, usa un defensivo. Los demás salen de los círculos de ácido.|nFuego: Pon tu charco de fuego en el borde, lejos del jefe y de los ataúdes.|nAtaúd: Un amigo queda encerrado en un ataúd. Busca el que se mueve y hazle clic rápido.",
	DGN_TIP_KR_MCHIMBA_DPS = "DPS: interrumpe el Wretched Discharge de las momias. Durante {SPELL:267702}, ve a los ataúdes y busca el que se sacude — no hagas clic al azar.",
	DGN_TIP_KR_MCHIMBA_HEALER = "Sanador: cambia al objetivo de {SPELL:267618} al instante y cúralo por encima del 90% después — eso quita la ralentización. Llena al grupo antes de {SPELL:1312146}. Wretched Discharge es una enfermedad que puedes disipar.",
	DGN_TIP_KR_MCHIMBA_TANK = "Tanque: recoge las momias y agrúpalas junto a Mchimba para el cleave. No las dejes delante de un ataúd.",
	DGN_TIP_KR_SERPENT_STEPS = "1. {SPELL:265773} pone oro ardiente en dos jugadores. Cuando termina, dejas un charco de {SPELL:265914} donde estás — ve antes al borde y suéltalo junto a los otros charcos.|n2. {SPELL:265923} despierta los charcos como Animated Gold, que se arrastra hacia el jefe. Mátalos, ralentízalos o atúrdelos antes de que alguno llegue — cada uno que llega le da un escudo y más daño.|n3. {SPELL:1311987}: cinco segundos de daño a todo el grupo que además te empuja hacia atrás. Ve con la vida llena y usa un defensivo.|n4. Nunca te quedes en los charcos de oro.",
	DGN_TIP_KR_SERPENT_QUICK_DPS = "Mata primero las manchas de oro — ninguna debe llegar al jefe.",
	DGN_TIP_KR_SERPENT_QUICK_HEALER = "Cura a los dos jugadores que arden con oro y guarda una cura grande para el viento.",
	DGN_TIP_KR_SERPENT_QUICK_TANK = "Usa un defensivo para el coletazo y aleja al jefe de las manchas de oro.",
	DGN_TIP_KR_SERPENT_QUICK = "Oro: Cuando se acaba tu quemadura de oro, dejas un charco. Suéltalo en el borde, junto a los otros charcos.|nAdds: Los charcos despiertan y se arrastran hacia el jefe. Mátalos antes de que lo toquen.|nViento: Un viento fuerte hace daño a todos y te empuja. Ten la vida llena.",
	DGN_TIP_KR_SERPENT_DPS = "DPS: primero el Animated Gold, después el jefe. Usa ralentizaciones, aturdimientos y cleave, y deja todos los charcos juntos para que los adds despierten en un solo grupo.",
	DGN_TIP_KR_SERPENT_HEALER = "Sanador: cura a los dos objetivos de {SPELL:265773} mientras arden. Usa un cooldown de sanación para {SPELL:1311987}.",
	DGN_TIP_KR_SERPENT_TANK = "Tanque: defensivo para {SPELL:265910}. Cuando despierte el Animated Gold, aleja al jefe de él para que los DPS tengan más tiempo.",
	DGN_TIP_RL_KOKIA_STEPS = "1. Molten Boulder ({SPELL:372110}): Kokia lanza una roca ardiente que rueda en línea recta y luego explota. Sal de su camino y aléjate del sitio donde se para. Empuja a quien toque.|n2. Ritual of Blazebinding ({SPELL:372864}): un add de fuego, el Blazebound Firestorm, aparece sobre un jugador y quema a todos a menos de 12 metros. Si te toca a ti, apártate del grupo pero quédate cerca del jefe.|n3. Todos cambian al Blazebound Firestorm de inmediato e interrumpen su Blaze Volley.|n4. Antes de que muera el add, aléjate al menos 20 metros de él. Su explosión al morir (Burnout) pega muy fuerte.|n5. En Mítico y Mythic+: las zonas ardientes ({SPELL:372820}) se quedan en el suelo. Sal de ellas y mueve el combate poco a poco por la sala para que siempre haya espacio libre.",
	DGN_TIP_RL_KOKIA_QUICK_DPS = "Pega primero al add de fuego, interrumpe sus hechizos y aléjate antes de que muera.",
	DGN_TIP_RL_KOKIA_QUICK_HEALER = "El add de fuego quema a todos y el tanque sangra, así que cura fuerte y aléjate cuando muera.",
	DGN_TIP_RL_KOKIA_QUICK_TANK = "Usa un defensivo para cada combo de golpes y mueve al jefe poco a poco por la sala.",
	DGN_TIP_RL_KOKIA_QUICK = "Roca: Una roca de fuego rueda en línea recta, así que apártate de su camino.|nAdd de fuego: Cuando aparece un monstruo de fuego, todos le pegan y cortan sus hechizos.|nMuere el add: Aléjate mucho de él antes de que muera, porque explota.",
	DGN_TIP_RL_KOKIA_DPS = "DPS: cambia al Blazebound Firestorm en cuanto aparezca e interrumpe su Blaze Volley. Cuerpo a cuerpo: alejaos 20 metros antes de que muera.",
	DGN_TIP_RL_KOKIA_HEALER = "Sanador: el lanzamiento Inferno del add quema a todo el grupo, y Searing Blows deja un sangrado en el tanque. Tú también mantente fuera de la explosión del add al morir.",
	DGN_TIP_RL_KOKIA_TANK = "Tanque: usa un defensivo para cada Searing Blows ({SPELL:372858}): cuatro golpes rápidos que acumulan un sangrado. Mantén a Kokia cerca del add para que los DPS hagan cleave, pero sal de su explosión de 20 metros al morir. Muévela poco a poco por la sala para mantener espacio libre.",
	DGN_TIP_RL_KYRAKKA_STEPS = "1. Erkhart lucha en el suelo mientras su dragona Kyrakka vuela alrededor de la plataforma. Pega a Kyrakka siempre que esté a tu alcance: debe morir primero. Esquiva su cono de fuego ({SPELL:381525}).|n2. Inferno Spit ({SPELL:381602}): 2 jugadores arden durante 6 segundos, luego explotan y dejan fuego en el suelo ({SPELL:384773}). Si eres tú, ve al borde, lejos del grupo, antes de que termine.|n3. Winds of Change ({SPELL:381517}): el viento empuja a los jugadores y al fuego, en un orden fijo (noroeste, suroeste, sureste, noreste). Camina en contra y no dejes que te lleve al fuego. Suelta tu fuego donde el viento lo aleje del grupo.|n4. Cuando uno de los dos llega a un 40-50% de vida (las guías no coinciden), Kyrakka aterriza y Erkhart la monta. Ahora 3 jugadores reciben Inferno Spit. Guarda cooldowns para esta parte.|n5. En Mítico y Mythic+: Interrupting Cloudburst ({SPELL:381516}) golpea a todos y bloquea tus hechizos 2 segundos. Deja de lanzar justo antes de que caiga.",
	DGN_TIP_RL_KYRAKKA_QUICK_DPS = "Pega primero a la dragona y, en Mítico, deja de lanzar justo antes de que la tormenta golpee a todos.",
	DGN_TIP_RL_KYRAKKA_QUICK_HEALER = "Quita el debuff del tanque tras cada gran golpe y cura a los jugadores que arden.",
	DGN_TIP_RL_KYRAKKA_QUICK_TANK = "Usa un defensivo para su gran golpe y pide al sanador que te quite el debuff.",
	DGN_TIP_RL_KYRAKKA_QUICK = "Dragón: Pega a la dragona siempre que la alcances y esquiva su aliento de fuego.|nFuego: Si estás ardiendo, ve al borde para que tu fuego caiga lejos del grupo.|nViento: El viento te empuja a ti y al fuego, así que camina en contra y no pises las llamas.",
	DGN_TIP_RL_KYRAKKA_DPS = "DPS: pega a Kyrakka siempre que la alcances y guarda el burst para cuando aterrice. En Mítico y Mythic+, los lanzadores dejan de lanzar antes de Interrupting Cloudburst.",
	DGN_TIP_RL_KYRAKKA_HEALER = "Sanador: disipa Stormslam del tanque tras cada golpe, antes del siguiente. Los objetivos de Inferno Spit reciben mucho daño, así que cúralos. En Mítico y Mythic+, deja de lanzar antes de Interrupting Cloudburst.",
	DGN_TIP_RL_KYRAKKA_TANK = "Tanque: usa un defensivo para cada Stormslam ({SPELL:381512}). Deja un debuff mágico acumulable que te hace recibir más daño de naturaleza, así que pide que te lo disipen. Saca a Erkhart del fuego rápido tras cada viento.",
	DGN_TIP_RL_MELIDRUSSA_STEPS = "1. Hailburst ({SPELL:1307297}): golpea a todo el grupo y lanza una mina de hielo a cada jugador. Poneos juntos cerca de un borde para que las minas caigan en un solo sitio. Nunca toques una mina: te lanza por los aires y reduce a la mitad la velocidad de tus ataques y hechizos durante 20 segundos.|n2. Chillstorm ({SPELL:1307308}): una tormenta de escarcha cae sobre un jugador y atrae a todos hacia su centro. Si te toca a ti, aléjate del grupo. Quédate fuera del centro ({SPELL:372963}): allí el daño de escarcha es el doble. A los 7 segundos explota y empuja a todos, así que no te pongas con minas a tu espalda.|n3. Al 66% y al 33% de vida invoca Infused Whelps ({SPELL:373046}). Mátalos rápido.|n4. Interrumpe Frigid Shard, el hechizo que lanza al tanque.|n5. En Mítico y Mythic+: tras las crías se esconde en un escudo de hielo (Ice Bulwark) y pulsa sobre todos un daño de escarcha que no deja de crecer (Frost Overload). Rompe el escudo rápido y luego interrúmpela. Las guías dicen que la interrupción funciona cuando el escudo ha desaparecido.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_DPS = "Mata primero a los dragoncitos y, en Mítico, rompe su escudo de hielo.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_HEALER = "Cura a todo el grupo durante las explosiones de hielo y la tormenta.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_TANK = "Agarra a los dragoncitos al instante e interrumpe el hechizo que te lanza.",
	DGN_TIP_RL_MELIDRUSSA_QUICK = "Minas: Poneos juntos cerca de un borde cuando lance hielo, y nunca toquéis las minas.|nTormenta: Si la tormenta está sobre ti, aléjate de todos y no te quedes en su centro.|nCrías: Mata rápido a los dragoncitos y, en Mítico, rompe también su escudo de hielo.",
	DGN_TIP_RL_MELIDRUSSA_DPS = "DPS: cambia a las crías en cuanto aparezcan. En Mítico y Mythic+, guarda el burst para romper el escudo de hielo y luego interrumpe Frost Overload.",
	DGN_TIP_RL_MELIDRUSSA_HEALER = "Sanador: Hailburst y Chillstorm golpean a todo el grupo, y la tormenta explota al final. Llena a la gente antes de la explosión. En Mítico y Mythic+, la fase del escudo añade sobre todos un daño de escarcha que crece hasta que se rompe el escudo.",
	DGN_TIP_RL_MELIDRUSSA_TANK = "Tanque: recoge los Infused Whelps al instante y mantenlos sobre el jefe para el cleave. Sus golpes te acumulan Cold Claws; con demasiados stacks te congelas, así que deben morir rápido. Interrumpe Frigid Shard si nadie más lo hace.",
	DGN_TIP_TS_ADDERIS_STEPS = "1. Storm Blessed protege con un escudo a uno de los dos jefes, y ese jefe casi no recibe daño. Pega al que NO tiene el escudo (Adderis al empezar) y cambia en cuanto el escudo se mueva.|n2. {SPELL:1311805}: si estás marcado, ve al borde y deja allí tu charco. Los charcos te silencian, así que quédate fuera de ellos.|n3. {SPELL:1289059}: todos salen empujados. Separaos un poco y colocaos para que el empujón no os lance a un charco.|n4. {SPELL:1288049} llega justo después del empujón: vuelve corriendo y júntate en el jefe para repartir el golpe, luego salid juntos antes de la segunda explosión.",
	DGN_TIP_TS_ADDERIS_QUICK_DPS = "Pega solo al jefe sin escudo y cambia rápido cuando se mueva.",
	DGN_TIP_TS_ADDERIS_QUICK_HEALER = "Cura a los jugadores golpeados por el viento y llena a todos antes del empujón.",
	DGN_TIP_TS_ADDERIS_QUICK_TANK = "Usa un defensivo para Overload y mantén a los dos jefes juntos.",
	DGN_TIP_TS_ADDERIS_QUICK = "Escudo: Pega al jefe sin escudo y cambia cuando el escudo salte.|nCharcos: Si estás marcado, deja tu charco en el borde y no pises charcos.|nEmpujón: Tras el empujón, vuelve y poneos juntos en el jefe para repartir el golpe.",
	DGN_TIP_TS_ADDERIS_DPS = "DPS: nunca pegues al jefe con escudo — casi no recibe daño. Cambia en cuanto se mueva el escudo, aunque estés a mitad de tu rotación.",
	DGN_TIP_TS_ADDERIS_HEALER = "Sanador: cura a los jugadores golpeados por Gust. El empujón que lleva directo al reparto de grupo es el momento más peligroso — ten a todos llenos antes.",
	DGN_TIP_TS_ADDERIS_TANK = "Tanque: usa un defensivo para {SPELL:1311804}. Mantén a los dos jefes juntos para que el grupo pueda cambiar sin cruzar charcos.",
	DGN_TIP_TS_AVATAR_STEPS = "1. Ganas curando al Avatar hasta la vida máxima, no matándolo. Primero mata a los Essence Defilers: su {SPELL:1301202} detiene toda la sanación sobre el Avatar.|n2. Mata al Corrupted Guardian. Deja tres orbes de Corrupted Lifeforce: tres DPS distintos cogen uno cada uno, rápido. Un orbe recogido cura al Avatar; un orbe perdido explota sobre todo el grupo.|n3. Twisted Hexxers: interrumpe Flame Shock. ¿Tienes {SPELL:1311981}? Aléjate del grupo antes de que termine y deja allí su zona.|n4. Cuando los Defilers estén muertos, cura al Avatar. Aparecen Faithless Tormentors que persiguen al sanador: atúrdelos, ralentízalos y bájalos por debajo del 25% de vida — entonces el Avatar se los come y se cura.",
	DGN_TIP_TS_AVATAR_QUICK_DPS = "Mata primero a los Defilers y luego coged un orbe cada uno.",
	DGN_TIP_TS_AVATAR_QUICK_HEALER = "Cura al Avatar cuando mueran los Defilers y sigue huyendo de los perseguidores.",
	DGN_TIP_TS_AVATAR_QUICK_TANK = "Mantén al add grande en una esquina y aléjate de los orbes.",
	DGN_TIP_TS_AVATAR_QUICK = "Objetivo: Mata primero a los Defilers y luego cura al Avatar al máximo para ganar.|nOrbes: Cuando muere el add grande, tres DPS cogen un orbe cada uno, rápido.|nPerseguidores: Aturde a los adds que persiguen al sanador y bájales la vida; luego el Avatar se los come.",
	DGN_TIP_TS_AVATAR_DPS = "DPS: mata primero a los Essence Defilers y luego al Guardian. Coge un orbe por persona (te da {SPELL:1300877}, así que usa un defensivo), interrumpe Flame Shock, y aturde a los Tormentors y mátalos con daño en área.",
	DGN_TIP_TS_AVATAR_HEALER = "Sanador: cura al Avatar en cuanto mueran los Defilers — así se gana el combate. Los Tormentors corren hacia ti y cada golpe reduce tu sanación, así que sigue moviéndote. Deja los orbes a los DPS.",
	DGN_TIP_TS_AVATAR_TANK = "Tanque: mantén al Corrupted Guardian en una esquina lejos del grupo y usa un defensivo para Tainted Strike. No cojas orbes: {SPELL:1300877} te hace recibir mucho más daño físico.",
	DGN_TIP_TS_GALVAZZT_STEPS = "1. {SPELL:1291618}: tres torres disparan rayos a Galvazzt. Ponte en un rayo, entre la torre y el jefe, para que no gane energía.|n2. Repartid los rayos: un jugador por rayo, y turnaos entre series. Bloquear un rayo te da {SPELL:266923}: daño en el tiempo y más daño físico recibido.|n3. Nunca dejes un rayo libre. Con energía llena lanza Consume Charge, que golpea fuerte al grupo y a menudo lo mata entero.|n4. {SPELL:1309525}: daño a todo el grupo, y deja un {SPELL:1291815} en el suelo. Sal de ahí.",
	DGN_TIP_TS_GALVAZZT_QUICK_DPS = "Quédate en tu rayo, aunque desde ahí no puedas pegar al jefe.",
	DGN_TIP_TS_GALVAZZT_QUICK_HEALER = "Mantén con vida a los jugadores de los rayos.",
	DGN_TIP_TS_GALVAZZT_QUICK_TANK = "No te metas en los rayos y aleja al jefe de las zonas del suelo.",
	DGN_TIP_TS_GALVAZZT_QUICK = "Rayos: Ponte en un rayo, entre la torre y el jefe, para que no se cargue.|nTurnos: Un jugador por rayo, turnaos y nunca dejéis un rayo libre.|nSuelo: Tras el gran golpe de grupo, sal de la zona del suelo.",
	DGN_TIP_TS_GALVAZZT_DPS = "DPS: tu rayo va antes que tu daño — no salgas de él para pegar al jefe. Turnaos con los demás y usa un defensivo en tu turno.",
	DGN_TIP_TS_GALVAZZT_HEALER = "Sanador: los que absorben rayos reciben daño constante — mantenlos altos, y coge tú un rayo si hace falta. Ten un cooldown listo para {SPELL:1309525}.",
	DGN_TIP_TS_GALVAZZT_TANK = "Tanque: no absorbas los rayos — {SPELL:266923} te hace recibir mucho más daño físico. Aleja al jefe de cada {SPELL:1291815}, a un sitio donde los rayos sigan siendo fáciles de alcanzar.",
	DGN_TIP_TS_MEREKTHA_STEPS = "1. {SPELL:1290029}: serpientes atan a algunos jugadores. Si estás marcado, ponte cerca de los demás junto al jefe, para que un solo aturdimiento o control de área rompa todos los nudos. Luego mata las serpientes.|n2. {SPELL:1289109}: si estás marcado, ve al borde de la sala y deja allí el charco, no en el centro.|n3. {SPELL:1293048}: daño a todo el grupo más un empujón. No te pongas donde el empujón te lance a un charco.|n4. {SPELL:1289205} y {SPELL:264172}: salen adds de los huevos y ella se mete bajo tierra, donde no se le puede pegar. Esquiva su camino (te aturde), interrumpe el Poison Spit de los Toxic Vipers y mata todos los adds — eso la hace salir.",
	DGN_TIP_TS_MEREKTHA_QUICK_DPS = "Cuando se meta bajo tierra, mata rápido todos los adds; eso la hace volver.",
	DGN_TIP_TS_MEREKTHA_QUICK_HEALER = "Guarda un cooldown para la tormenta que golpea a todos.",
	DGN_TIP_TS_MEREKTHA_QUICK_TANK = "Usa un defensivo para su gran mordisco y agarra los adds cuando se meta bajo tierra.",
	DGN_TIP_TS_MEREKTHA_QUICK = "Serpientes: Si te atan serpientes, ponte cerca de los demás para que un aturdimiento libere a todos.|nEscupitajo: Si estás marcado, deja tu charco en el borde de la sala.|nBajo tierra: Se esconde bajo tierra. Esquiva su camino y mata todos los adds para que vuelva.",
	DGN_TIP_TS_MEREKTHA_DPS = "DPS: libera primero a los jugadores atados con un aturdimiento o control de área. Durante Burrow, mata rápido cada add — la fase termina cuando mueren todos — e interrumpe Poison Spit.",
	DGN_TIP_TS_MEREKTHA_HEALER = "Sanador: {SPELL:1293048} golpea a todo el grupo — planea un cooldown para ello. Si se cuela un Poison Spit, disipa el veneno si puedes.",
	DGN_TIP_TS_MEREKTHA_TANK = "Tanque: usa un defensivo para cada {SPELL:1290797}. Durante Burrow, recoge los adds y deja al Storm Serpent en el borde, porque también deja charcos.",
})

merge(ns._mhLocales and ns._mhLocales.ptBR, {
	-- Windrunner Spire ----------------------------------------------------------
	DGN_TIP_WS_DUO_STEPS = "1. Dois chefes — divida o dano para que morram quase juntos.|n2. Interrompa Shadow Bolt; saia dos círculos de cuspe ({SPELL:472745}) — não desperdice chão.|n3. Amaldiçoado ({SPELL:474105})? Peça dispel rápido — ou controle a Dark Entity que ela gera até sumir.|n4. Fisgado por {SPELL:472793} durante o grito? Posicione-se para ser puxado ATRAVÉS da dama fantasma — isso quebra a conjuração dela.",
	DGN_TIP_WS_DUO_TANK = "Tanque: defensivo para {SPELL:472888}; mova os chefes quando o chão encher.",
	DGN_TIP_WS_DUO_HEALER = "Curandeiro: muito dano de grupo durante {SPELL:472736}; dissipe {SPELL:474105} rápido.",

	DGN_TIP_WS_EMBER_STEPS = "1. Fogo = ruim. Deixe as poças de fogo ({SPELL:466556}) nas bordas, mantenha o centro limpo.|n2. Com energia cheia: corra ATÉ o chefe para {SPELL:465904} e depois desvie de cada Fire Breath.|n3. Poças antigas geram redemoinhos de fogo — continue desviando.",
	DGN_TIP_WS_EMBER_TANK = "Tanque: defensivo para {SPELL:466064}.",
	DGN_TIP_WS_EMBER_HEALER = "Curandeiro: dano de grupo pesado durante {SPELL:465904}.",

	DGN_TIP_WS_KROLUK_STEPS = "1. Círculos marrons = ruins, saia deles.|n2. Junte-se a um aliado antes de {SPELL:1253026} terminar (sobreponha os círculos roxos).|n3. Fixado ou alvo do salto ({SPELL:1283247})? Leve-o para LONGE do grupo.|n4. Quando surgirem adds (perto de dois terços e um terço de vida): mate-os rápido — o Phantasmal Mystic primeiro, e continue interrompendo.",
	DGN_TIP_WS_KROLUK_TANK = "Tanque: defensivo para {SPELL:467620}; esteja pronto para segurar o segundo {SPELL:1283247}.",
	DGN_TIP_WS_KROLUK_HEALER = "Curandeiro: dano de grupo durante {SPELL:472043}.",

	DGN_TIP_WS_HEART_STEPS = "1. Os stacks de {SPELL:1216042} estão batendo em você? Pise numa flecha de vento (Turbulent Arrow) com 2-3 stacks — ela limpa o DoT e te faz saltar por cima da onda de choque.|n2. Guarde uma flecha para a explosão grande na energia cheia ({SPELL:468429}).|n3. Espalhem-se um pouco para {SPELL:1253979} e usem os círculos grandes para limpar o chão elétrico.|n4. Alvo de {SPELL:474528}? Fique parado e deixe os outros saírem; todos os demais: fora do cone frontal.",
	DGN_TIP_WS_HEART_TANK = "Tanque: defensivo para {SPELL:472662}; aponte o empurrão para LONGE das poças.",
	DGN_TIP_WS_HEART_HEALER = "Curandeiro: cure primeiro quem tiver muitos stacks de {SPELL:1216042}; cura extra depois de {SPELL:1253979}.",

	-- Maisara Caverns ------------------------------------------------------------
	DGN_TIP_MC_MUROJIN_STEPS = "1. Dois chefes (caçador e ave) — mate-os quase juntos, ou o sobrevivente enfurece.|n2. Armadilhas de gelo ({SPELL:1243741}), círculos verdes ({SPELL:1243900}) e o {SPELL:1260643} frontal = ruins, fique fora.|n3. Alvo de {SPELL:1249478} (o mergulho da ave)? Corra PARA DENTRO de uma armadilha de gelo — o congelamento para o mergulho. Os demais: afastem-se desse jogador.",
	DGN_TIP_MC_MUROJIN_TANK = "Tanque: defensivo para {SPELL:1266480}.",
	DGN_TIP_MC_MUROJIN_HEALER = "Curandeiro: dissipe {SPELL:1246666} (doença) — dano de grupo pesado.",

	DGN_TIP_MC_VORDAZA_STEPS = "1. O chefe gera Unstable Phantoms ({SPELL:1251204}) que perseguem jogadores. MATE-os antes que alcancem alguém — um fantasma que chega ao alvo (ou toca outro fantasma) estoura com dano pesado por perto.|n2. Cada fantasma morto grita: dano de grupo inevitável — mate-os UM de cada vez.|n3. Desvie da onda frontal de {SPELL:1252054} (ela te empurra), dos orbes flutuantes e de Soulrot.|n4. Alguém preso num Deathshroud? Liberte-o rápido; interrompa {SPELL:1250708} e desvie dos redemoinhos enquanto isso.",
	DGN_TIP_MC_VORDAZA_TANK = "Tanque: defensivo para {SPELL:1251554}.",
	DGN_TIP_MC_VORDAZA_HEALER = "Curandeiro: cada fantasma morto grita ({SPELL:1251813}) = dano de grupo — cure entre as mortes espaçadas.",

	DGN_TIP_MC_RAKTUL_STEPS = "1. O chefe salta sobre três jogadores ({SPELL:1252676}) e deixa Soulbind Totems — espalhem-se para os totens caírem separados, não seja esmagado, e destrua os totens rápido.|n2. Fique fora do chão de Chill of Death.|n3. Fase de alma ({SPELL:1253788}): você é arrancado do corpo — controle e interrompa os adds grandes enquanto corre de volta ao corpo.|n4. Desvie dos redemoinhos do Deathgorged Vessel.",
	DGN_TIP_MC_RAKTUL_TANK = "Tanque: defensivo para {SPELL:1251023}; deixe as poças LONGE do grupo.",
	DGN_TIP_MC_RAKTUL_HEALER = "Curandeiro: dano de grupo pesado durante Deathgorged Vessel e quando os totens quebram.",

	-- Murder Row -----------------------------------------------------------------
	DGN_TIP_MR_KYSTIA_STEPS = "1. Mate Nibbles primeiro. Kystia tem um escudo vil e quase não sofre dano enquanto Nibbles estiver acima de 20% de vida.|n2. Em 20%, Nibbles se volta contra Kystia com {SPELL:1230304}: Kystia fica atordoada e sofre muito mais dano por pouco tempo. Troque para Kystia agora e use seus cooldowns grandes.|n3. {SPELL:1264095}: cópias de Kystia aparecem e conjuram Felstorm. Interrompa, atordoe ou controle cada cópia.|n4. Fique fora do cone {SPELL:1253811} da Nibbles e do fogo que o cone deixa no chão.|n5. No Heroico e acima: {SPELL:474240} - ela salta até um jogador e explode. Afaste-se dela.",
	DGN_TIP_MR_KYSTIA_QUICK_DPS = "Bata primeiro no pet, depois na chefe quando o pet estiver com pouca vida.",
	DGN_TIP_MR_KYSTIA_QUICK_HEALER = "Tire rápido o debuff de cuspe dos jogadores e guarde uma cura grande para a troca.",
	DGN_TIP_MR_KYSTIA_QUICK_TANK = "Aponte o cone de fogo do pet para longe do grupo.",
	DGN_TIP_MR_KYSTIA_QUICK = "Pet primeiro: Bata primeiro no pet Nibbles. A chefe tem um escudo e quase não sofre dano.|nTroca: Quando Nibbles está com pouca vida, ela atordoa a chefe. Agora bata forte na chefe.|nCópias: Aparecem cópias da chefe. Interrompa ou atordoe cada uma.",
	DGN_TIP_MR_KYSTIA_TANK = "Tanque: Aponte o cone {SPELL:1253811} da Nibbles para longe do grupo. Mantenha Kystia e Nibbles bem juntas para o grupo acertar as duas com cleave. O Chaos Barrage de Kystia bate forte em você, então tenha um defensivo pronto.",
	DGN_TIP_MR_KYSTIA_HEALER = "Curandeiro: Dissipe Corroding Spittle (magia) rápido, principalmente durante {SPELL:1264095}. Guarde um cooldown de cura para a janela de burst depois de {SPELL:1230304}: a Kystia atordoada solta rajadas vis no grupo.",

	DGN_TIP_MR_ZAEN_STEPS = "1. Caixas caem sobre os jogadores ({SPELL:474765}). Saia das marcas. As caixas que caem são a sua cobertura.|n2. {SPELL:1218347}: ele mira em todos que consegue ver. Esconda-se atrás de uma caixa antes do tiro, para que ele não te veja. Cada um precisa da sua própria caixa.|n3. Pegou {SPELL:1214357}? A bomba explode depois de 6 segundos e destrói as caixas perto de você. Leve-a para longe das caixas que você precisa para se cobrir.|n4. {SPELL:474478}: 3 segundos de dano pesado no grupo todo. Esteja com a vida cheia.|n5. No Mítico e no Mythic+: caixas verdes vis (Fel-Infused Freight) machucam o grupo todo o tempo inteiro. Se você tiver {SPELL:1214357}, leve-a até uma caixa verde para destruí-la, e preserve as caixas comuns.",
	DGN_TIP_MR_ZAEN_QUICK_DPS = "Fique atrás de uma caixa antes do tiro grande, não depois.",
	DGN_TIP_MR_ZAEN_QUICK_HEALER = "Tire o veneno do tanque e deixe todos com a vida cheia antes dos tiros.",
	DGN_TIP_MR_ZAEN_QUICK_TANK = "Use um defensivo quando ele te apunhalar e peça para tirarem o veneno.",
	DGN_TIP_MR_ZAEN_QUICK = "Caixas: Caixas caem do céu. Saia de baixo e depois use-as como parede.|nTiro: Quando ele mira em todos, esconda-se atrás de uma caixa para ele não te ver.|nBomba: Pegou a bomba? Leve-a para longe das caixas onde vocês se escondem.",
	DGN_TIP_MR_ZAEN_TANK = "Tanque: Use um defensivo para {SPELL:1222795}. Ele também deixa Heartstop Poison, que reduz sua vida máxima: peça dispel ou limpe você mesmo.",
	DGN_TIP_MR_ZAEN_HEALER = "Curandeiro: Dissipe Heartstop Poison do tanque depois de {SPELL:1222795}. Encha a vida de todos antes de {SPELL:474478} e cure o sangramento de quem levou o tiro.",

	DGN_TIP_MR_XATHUUX_STEPS = "1. {SPELL:1214637}: ele arremessa o machado num jogador. Se for você, fique perto do chefe mas longe dos outros. O machado fica lá e dá choques cada vez mais fortes em todos: mate-o rápido.|n2. Infernal Crush ({SPELL:1295452}): aparecem círculos sob os jogadores. Espalhem-se para não acertarem uns aos outros.|n3. {SPELL:474197}: dano em todos, depois por 15 segundos ele ataca mais rápido e sofre 30% a mais de dano. Use seus cooldowns agora.|n4. Durante a fúria ele deixa fogo por onde anda ({SPELL:474234}). Fique fora dele. O tanque o leva devagar pela borda da sala.",
	DGN_TIP_MR_XATHUUX_QUICK_DPS = "Mate o machado primeiro e guarde seus ataques grandes para a fúria.",
	DGN_TIP_MR_XATHUUX_QUICK_HEALER = "Planeje uma cura grande para a fúria e deixe o tanque cheio antes do golpe grande.",
	DGN_TIP_MR_XATHUUX_QUICK_TANK = "Use um defensivo no golpe grande e leve-o devagar pela borda quando ele ficar furioso.",
	DGN_TIP_MR_XATHUUX_QUICK = "Machado: Ele arremessa o machado. Deixe-o ao lado do chefe e quebre-o rápido.|nCírculos: Espalhe-se quando aparecerem círculos embaixo de você.|nFúria: Quando ele fica bravo, sofre mais dano. Bata forte e fique fora do rastro de fogo.",
	DGN_TIP_MR_XATHUUX_TANK = "Tanque: Use um defensivo para {SPELL:473898}; ele reduz a cura que você recebe por 8 segundos. Vire-o para longe do grupo e leve-o para cima do machado para que o machado leve cleave. Durante {SPELL:474197}, leve-o devagar pela borda para que o fogo fique fora do meio.",
	DGN_TIP_MR_XATHUUX_HEALER = "Curandeiro: {SPELL:474197} e Infernal Crush muitas vezes vêm juntos, então planeje um cooldown. O tanque recebe bem menos cura depois de {SPELL:473898}; deixe-o cheio antes. A cada segundo que o machado vive, o grupo sofre mais dano.",

	DGN_TIP_MR_LITHIEL_STEPS = "1. Interrompa todo Chaos Bolt. Combinem uma ordem de interrupção.|n2. {SPELL:1218203}: círculos caem nos jogadores. Espalhem-se 6 metros. Cada círculo gera Wild Imps: atordoe ou interrompa e mate-os juntos.|n3. {SPELL:474408}: chega um demônio grande. O tanque o pega e todos o matam.|n4. {SPELL:1224478}: uma onda de fogo vil atravessa a sala. Mate todos os demônios antes que ela os alcance, ou eles ficam muito mais rápidos. Use o Demonic Gateway para a onda não te pegar; se ela te acertar, você sofre mais dano de fogo.|n5. No Mítico e no Mythic+: um Infernal persegue o tanque. Ele não pode ser morto e tocá-lo pode te matar. O tanque o mantém longe do grupo e do gateway.",
	DGN_TIP_MR_LITHIEL_QUICK_DPS = "Interrompa a chefe e os imps, e mate todos os demônios antes da onda.",
	DGN_TIP_MR_LITHIEL_QUICK_HEALER = "Todos sofrem dano de fogo a luta toda. Cure primeiro quem a onda acertou.",
	DGN_TIP_MR_LITHIEL_QUICK_TANK = "Pegue os demônios rápido. No Mítico, leve o Infernal para longe de todos.",
	DGN_TIP_MR_LITHIEL_QUICK = "Interrupções: Interrompa todo Chaos Bolt que a chefe conjurar.|nImps: Espalhe-se. Saem demoniozinhos. Atordoe e mate-os rápido.|nOnda: Mate todos os demônios antes da onda de fogo, depois use o portal para ela não te pegar.",
	DGN_TIP_MR_LITHIEL_TANK = "Tanque: Pegue o Vilefiend rápido, ele bate forte. Mantenha os Wild Imps juntos para levarem cleave. No Mítico, leve o Infernal para longe do grupo e nunca perto do gateway.",
	DGN_TIP_MR_LITHIEL_HEALER = "Curandeiro: A luta inteira tem dano de fogo constante no grupo. Quem leva {SPELL:1224478} continua queimando e sofre mais dano de fogo: cure essas pessoas primeiro.",

	-- Den of Nalorakk -----------------------------------------------------------
	DGN_TIP_DN_HOARDMONGER_STEPS = "1. {SPELL:1234233}: ele arremessa comida podre por alguns segundos. Desvie dos impactos. Depois nascem Rotten Mushrooms verdes no chão.|n2. Pise em cada cogumelo antes que ele estoure (uns 12 segundos). Espalhem-se para não sobrar nenhum. Cada cogumelo te dá um veneno, então revezem.|n3. {SPELL:1253268} é um cone frontal. Saia da área que ele mostra. {SPELL:1235118} atinge o grupo todo, então fique com a vida cheia.|n4. Três vezes ele corre até uma pilha de carne, ossos ou cogumelos e ganha um golpe novo. Carne deixa o rugido dele mais forte. Ossos dão uma pancada que deixa ossos quebrados no chão ({SPELL:1235405}): fique fora deles. Cogumelos significam mais cogumelos para pisar.|n5. No Mítico e no Mythic+: cada golpe novo fica até o fim da luta, então eles se somam. Os guias pegam carne primeiro, ossos em segundo e cogumelos por último.",
	DGN_TIP_DN_HOARDMONGER_QUICK_DPS = "Ajude a pisar nos cogumelos e reveze com os outros.",
	DGN_TIP_DN_HOARDMONGER_QUICK_HEALER = "Cure forte quando ele rugir e tire o veneno de quem pisa nos cogumelos, se puder.",
	DGN_TIP_DN_HOARDMONGER_QUICK_TANK = "Deixe o chefe ao lado da pilha que você quer: carne, depois ossos, depois cogumelos.",
	DGN_TIP_DN_HOARDMONGER_QUICK = "Cogumelos: Pise nos cogumelos verdes antes que estourem, e revezem.|nPancada: O chefe bate no chão na frente dele. Saia dessa área.|nPilhas: Ele pega comida de uma pilha e ganha um truque novo. Fique fora dos ossos que ele deixa.",
	DGN_TIP_DN_HOARDMONGER_TANK = "Tanque: Ele corre até a pilha mais próxima, então deixe-o ao lado da que você quer: carne primeiro, ossos em segundo, cogumelos por último. Mantenha as áreas de ossos longe de onde o grupo fica.",
	DGN_TIP_DN_HOARDMONGER_HEALER = "Curandeiro: Use um cooldown de cura em {SPELL:1235118}: ignora armadura e atinge todos. Quem pisa nos cogumelos ganha um veneno (Toxic Spores): dissipe se sua classe puder e mantenha essas pessoas com a vida cheia.",

	DGN_TIP_DN_SENTINEL_STEPS = "1. {SPELL:1235623}: pequenos tornados caem e vagam pela sala por muito tempo. Fiquem juntos para que caiam num só lugar, depois afastem-se deles.|n2. {SPELL:1235783}: dois sincelos despencam. Saia dos círculos. Cada um deixa um add Fractured Shivercore.|n3. Os adds conjuram Winter's Shroud. Interrompa: cada conjuração faz o grupo todo sofrer mais dano de gelo. Um add morto deixa um Snowdrift: neve funda que te deixa lento, mas nada consegue te mover enquanto você estiver nela.|n4. {SPELL:1235656}: uma tempestade grande atinge todos e empurra os jogadores. Mate um add logo antes dela e fique no Snowdrift dele até a tempestade acabar. Depois mate o outro add.|n5. No Mítico e no Mythic+: um add que morre solta estilhaços de gelo (Rimeshatter). Coloque exatamente um jogador em cada círculo de estilhaço. Um estilhaço sem ninguém atinge o grupo todo e enraíza todos.",
	DGN_TIP_DN_SENTINEL_QUICK_DPS = "Reveze para interromper os adds e mate o primeiro add logo antes da tempestade.",
	DGN_TIP_DN_SENTINEL_QUICK_HEALER = "Tire rápido o debuff de gelo e cure todos durante a tempestade.",
	DGN_TIP_DN_SENTINEL_QUICK_TANK = "Coloque o chefe em cima de um add e mantenha-o longe dos tornados.",
	DGN_TIP_DN_SENTINEL_QUICK = "Tornados: Fiquem juntos para que caiam num só lugar, depois saiam de perto.|nAdds: Aparecem dois adds de gelo. Interrompa a conjuração deles e mate um logo antes da tempestade.|nTempestade: Fique na neve que o add morto deixa. Assim a tempestade não te move.",
	DGN_TIP_DN_SENTINEL_TANK = "Tanque: Arraste o chefe para cima de um add para o grupo acertar os dois com cleave, e mantenha o chefe longe dos tornados. Ajude a interromper Winter's Shroud.",
	DGN_TIP_DN_SENTINEL_HEALER = "Curandeiro: {SPELL:1235548} é um dano contínuo de gelo mágico: dissipe rápido e cure quem você não conseguir dissipar. A tempestade atinge todos, então esteja pronto para curar o grupo.",

	DGN_TIP_DN_NALORAKK_STEPS = "1. {SPELL:1242860}: três jogadores ganham uma marca. Vá até a borda antes que ela acabe: um urso fantasma (um Echo) aparece onde você está. Juntem todos os Echoes, longe do grupo. Os Echoes machucam quem estiver perto toda vez que ele golpeia.|n2. {SPELL:1243011}: Nalorakk derruba Zul'jarra e cada Echo investe contra ela. Fiquem ao redor dela como uma parede e bloqueiem as investidas. Um Echo que a alcança machuca o grupo todo.|n3. {SPELL:1243569}: Nalorakk bate no tanque sem parar. Zul'jarra ergue um escudo que corta esse dano pela metade: todos ficam atrás do escudo dela.|n4. Logo depois, só o tanque entra em Forceful Slam. Todos os outros saem. Se acertar Zul'jarra, o grupo todo sofre dano.|n5. No Mítico e no Mythic+: bloquear um Echo também te dá um sangramento que acumula (Spectral Slash). Coloque um jogador em cada trilha de investida, e nunca deixe duas pessoas bloquearem o mesmo Echo.",
	DGN_TIP_DN_NALORAKK_QUICK_DPS = "Fique no caminho de um urso fantasma, uma pessoa por urso.",
	DGN_TIP_DN_NALORAKK_QUICK_HEALER = "Cure forte o tanque durante os golpes grandes e encha a vida de todos antes do rugido.",
	DGN_TIP_DN_NALORAKK_QUICK_TANK = "Esconda-se atrás do escudo dela e depois leve a próxima pancada sozinho.",
	DGN_TIP_DN_NALORAKK_QUICK = "Marcas: Se você ganhar uma marca, vá até a borda. Um urso fantasma aparece lá.|nInvestida: Os ursos fantasmas correm até Zul'jarra. Fique no caminho deles para pará-los.|nEscudo: Quando o chefe bate muitas vezes no tanque, todos se escondem atrás do escudo dela.",
	DGN_TIP_DN_NALORAKK_TANK = "Tanque: {SPELL:1243569} é em você. Fique atrás do escudo de Zul'jarra e use um defensivo. Depois entre sozinho em Forceful Slam, longe do grupo.",
	DGN_TIP_DN_NALORAKK_HEALER = "Curandeiro: O tanque leva golpes grandes durante {SPELL:1243569}, e depois Forceful Slam. Encha a vida do grupo antes de Forceful Roar. No Mythic+, fique de olho nos stacks de sangramento de quem bloqueia os Echoes.",

	-- The Blinding Vale -----------------------------------------------------------
	DGN_TIP_BV_TRINITY_STEPS = "1. Os três chefes dividem uma barra de vida. O tanque os junta e todos batem nos três. Interrompa o Light Bolt de Kezkitt.|n2. {SPELL:1234753} atinge o tanque e deixa três círculos verdes. Não fique neles ainda. Depois Lekshi atravessa os três círculos numa arrancada ({SPELL:1234850}) - fique fora dessa linha.|n3. Quando {SPELL:1235564} começar, um jogador fica em cada círculo (o tanque e mais dois) até o feixe acabar. Um círculo vazio faz o grupo todo sofrer muito dano depois.|n4. Depois do feixe os círculos viram chão em chamas ({SPELL:1235828}). Saia; o tanque leva os chefes para chão limpo. {SPELL:1261276} faz um jogador aleatório sangrar: use um defensivo ou limpe o sangramento.|n5. No Mítico e no Mythic+: depois de Thornblade, Lekshi salta até esse jogador e espalha espinhos ao redor dele. Esse jogador se afasta do grupo e depois sai dos espinhos. Bedrock Slam também manda pulsos de dano pelo grupo todo.",
	DGN_TIP_BV_TRINITY_QUICK_DPS = "Bata nos três chefes juntos e interrompa o raio de Kezkitt.",
	DGN_TIP_BV_TRINITY_QUICK_HEALER = "Mantenha vivos os jogadores nos círculos e cure quem estiver sangrando.",
	DGN_TIP_BV_TRINITY_QUICK_TANK = "Use um defensivo na pancada grande e depois tire os três chefes do chão em chamas.",
	DGN_TIP_BV_TRINITY_QUICK = "Três chefes: Eles dividem uma barra de vida. Junte-os e bata nos três.|nCírculos: Quando vier o feixe, um jogador fica em cada círculo até ele parar.|nArrancada: Fique fora da linha entre os círculos e saia deles quando pegarem fogo.",
	DGN_TIP_BV_TRINITY_TANK = "Tanque: Use um defensivo para {SPELL:1234753}. Mantenha os três juntos para cleave, fique num círculo durante o feixe e depois tire os chefes do chão em chamas antes da próxima pancada.",
	DGN_TIP_BV_TRINITY_HEALER = "Curandeiro: Os três que ficam nos círculos sofrem dano contínuo - mantenha-os de pé e cure o sangramento de {SPELL:1261276}. No Mítico, guarde um cooldown para os pulsos de grupo depois de Bedrock Slam.",

	DGN_TIP_BV_IKUZZ_STEPS = "1. {SPELL:1236746} atinge todos e te empurra para trás. Posicione-se para não voar de uma borda nem cair nas raízes.|n2. {SPELL:1236709}: ele ruge e machuca o grupo todo por 6 segundos. Use um defensivo se estiver com pouca vida.|n3. {SPELL:1237091}: ele persegue um jogador por 10 segundos. Esse jogador corre e o leva por cima das raízes no chão - os passos dele as esmagam. Se ele te pegar, você sangra e fica atordoado ({SPELL:1272290}).|n4. A partir de 50% de vida ele entra em frenesi: fica mais rápido e machuca o grupo o tempo todo. Guarde cooldowns para isso.|n5. No Mítico e no Mythic+: alguns segundos depois do pisão, raízes prendem todos os jogadores, e nascem mais raízes durante o rugido. Volte para perto do chefe para o grupo quebrar as raízes com cleave, ou use uma magia de libertação.",
	DGN_TIP_BV_IKUZZ_QUICK_DPS = "Quebre as raízes rápido e, se ele te perseguir, corra por cima das raízes.",
	DGN_TIP_BV_IKUZZ_QUICK_HEALER = "Guarde suas curas grandes para quando ele estiver com metade da vida.",
	DGN_TIP_BV_IKUZZ_QUICK_TANK = "Mantenha o chefe perto dos jogadores presos nas raízes, para todos quebrarem as raízes.",
	DGN_TIP_BV_IKUZZ_QUICK = "Pisão: Ele empurra todos para trás. Não fique perto de uma borda.|nCaçada: Ele persegue um jogador. Esse jogador corre por cima das raízes para ele esmagá-las.|nMeia vida: Ele fica mais rápido e bate mais forte. Use suas magias grandes agora.",
	DGN_TIP_BV_IKUZZ_TANK = "Tanque: Mantenha Ikuzz perto dos jogadores enraizados para todos quebrarem as raízes com cleave, e longe das bordas por causa do empurrão.",
	DGN_TIP_BV_IKUZZ_HEALER = "Curandeiro: O pisão e {SPELL:1236709} atingem o grupo todo. Guarde seus cooldowns grandes para o frenesi de 50%, principalmente quando ele rugir durante o frenesi. Um jogador pego leva muito dano - encha a vida dele rápido.",

	DGN_TIP_BV_RUIA_STEPS = "1. Forma de moonkin (100 a 70%): interrompa Warden's Wrath - ele acerta o tanque. Desvie dos círculos de {SPELL:1240098}.|n2. {SPELL:1239825} marca alguns jogadores. Afaste-se do grupo antes que acabe: depois saem feixes de você. Fique fora dos feixes - eles te silenciam.|n3. Forma de urso (70 a 40%): {SPELL:1240222} marca alguns jogadores e dispara cones neles. Jogadores marcados se espalham e mantêm o cone longe dos outros. Um segundo acerto dói muito mais.|n4. {SPELL:1241058} faz jogadores sangrarem até serem curados com a vida cheia.|n5. Com 40% de vida, {SPELL:1241067}: ele usa tudo isso a cada 8 segundos até morrer. Use seus cooldowns e Bloodlust aqui.",
	DGN_TIP_BV_RUIA_QUICK_DPS = "Interrompa a magia dele na forma de moonkin e guarde suas magias grandes para 40 por cento.",
	DGN_TIP_BV_RUIA_QUICK_HEALER = "Um jogador sangrando continua sangrando até você curá-lo por completo.",
	DGN_TIP_BV_RUIA_QUICK_TANK = "Garanta que a magia dele seja interrompida na forma de moonkin e use defensivos na forma de urso.",
	DGN_TIP_BV_RUIA_QUICK = "Moonkin: Interrompa a magia dele, desvie dos círculos e afaste-se do grupo se ganhar a marca do feixe.|nUrso: Se você for marcado, afaste-se para o seu cone não acertar mais ninguém.|n40%: Ele faz tudo de uma vez. Use suas magias grandes agora.",
	DGN_TIP_BV_RUIA_TANK = "Tanque: Na forma de moonkin, o corpo a corpo dele é trocado por Warden's Wrath - garanta que seja interrompido. Na forma de urso, o corpo a corpo dele bate duas vezes mais forte (Mangling Claws), então use seus defensivos aí.",
	DGN_TIP_BV_RUIA_HEALER = "Curandeiro: {SPELL:1241058} só para quando o jogador está com a vida cheia - cure um alvo até encher, depois o próximo. Guarde cooldowns para a fase de 40%.",

	DGN_TIP_BV_ZIEKKET_STEPS = "1. {SPELL:1246372}: brotam lashers. O tanque os junta; todos batem neles com cleave e interrompem Lightspore Shot.|n2. Um lasher com 1% de vida afunda no chão e não pode ser ferido. Ele acorda mais forte no próximo {SPELL:1246372}, e aí não pode ser interrompido nem atordoado.|n3. {SPELL:1253690} mira um feixe num jogador. Se for você, vire-se para o feixe passar por todos os lashers adormecidos - isso os mata de vez. Ele deixa poças que deixam lento ({SPELL:1246753}); saia delas.|n4. {SPELL:1247685} bate forte no tanque, empurra e causa sangramento. O grupo todo sofre dano pulsante a luta toda.|n5. No Mítico e no Mythic+: {SPELL:1246858} manda orbes em direção a Ziekket. Entre neles antes que o alcancem e dividam entre vocês (uns dois ou três cada) - cada orbe te dá um dano contínuo que acumula. Um orbe que o alcança machuca o grupo e dá um escudo a ele.",
	DGN_TIP_BV_ZIEKKET_QUICK_DPS = "Interrompa os tiros dos lashers e pare de bater num lasher quando ele dormir.",
	DGN_TIP_BV_ZIEKKET_QUICK_HEALER = "O grupo todo sofre dano a luta toda, então continue curando todos.",
	DGN_TIP_BV_ZIEKKET_QUICK_TANK = "Junte os lashers e use um defensivo no golpe grande de espinhos.",
	DGN_TIP_BV_ZIEKKET_QUICK = "Lashers: Bata neles até afundarem no chão. Aí eles dormem.|nFeixe: Se o feixe mirar em você, aponte-o pelos lashers adormecidos. Isso os mata de vez.|nOrbes: No Mítico, toque nas bolas brilhantes antes que cheguem ao chefe, e dividam entre vocês.",
	DGN_TIP_BV_ZIEKKET_TANK = "Tanque: Junte cada leva de lashers para cleave, perto da borda. Use um defensivo para {SPELL:1247685} - ele te empurra e causa sangramento. Saia das poças de Lightsap.",
	DGN_TIP_BV_ZIEKKET_HEALER = "Curandeiro: O grupo sofre dano a luta toda, então continue curando todos. No Mítico, fique de olho em quem pega os orbes - os stacks doem, e um orbe perdido atinge o grupo todo.",

	-- Voidscar Arena ----------------------------------------------------------------
	DGN_TIP_VA_TAZRAH_STEPS = "1. {SPELL:1222098}: uma sombra atravessa cada jogador em linha. Espalhem-se um pouco perto da borda da sala, para a sua linha não acertar mais ninguém.|n2. {SPELL:1296963} deixa poças no chão. Solte-as perto da borda e bem juntas, e nunca fique nelas.|n3. {SPELL:1300259}: as poças disparam orbes. Continue se movendo pela sala e desvie de cada orbe.|n4. No Mítico e no Mythic+: {SPELL:1225011} - dois estilhaços voam até um jogador, e cada um estoura no primeiro jogador que acertar. Não entre em estilhaços mirados em outra pessoa.",
	DGN_TIP_VA_TAZRAH_QUICK_DPS = "Continue batendo no chefe enquanto desvia.",
	DGN_TIP_VA_TAZRAH_QUICK_HEALER = "Encha a vida de todos antes de virem as poças.",
	DGN_TIP_VA_TAZRAH_QUICK_TANK = "Use um defensivo quando ele te empurrar e não caia numa poça.",
	DGN_TIP_VA_TAZRAH_QUICK = "Arrancada: Um fantasma corre até você em linha. Fique perto da parede, um pouco longe dos amigos.|nPoças: Solte suas poças escuras perto da parede, bem juntas. Nunca fique nelas.|nOrbes: As poças disparam bolas. Continue andando pela sala e desvie delas.",
	DGN_TIP_VA_TAZRAH_TANK = "Tanque: {SPELL:1297017} bate forte e te empurra para trás. Use um defensivo e não seja empurrado para dentro de uma poça. Tanque perto de uma parede e gire devagar pela sala, para o meio ficar livre.",
	DGN_TIP_VA_TAZRAH_HEALER = "Curandeiro: Encha a vida de todos antes de cada {SPELL:1296963}; {SPELL:1300259} machuca o grupo todo. Cure quem levou uma arrancada, ela continua causando dano por um tempo.",

	DGN_TIP_VA_ATROXUS_STEPS = "1. {SPELL:1262497} atinge o grupo todo. Uns 3 segundos depois sai um Toxic Creeper rastejando ({SPELL:1222371}). Mate-o rápido.|n2. {SPELL:1263977} é um frontal mirado num jogador aleatório. Fique perto do chefe para poder sair dele rápido.|n3. {SPELL:1226120} espirra veneno em volta do chefe. Desvie dos impactos e fique fora das poças de veneno que ficam.|n4. No Mítico e no Mythic+: o Creeper tem Toxic Aura - machuca todos a até 8 metros até morrer. Mate-o ainda mais rápido; jogadores à distância ficam longe dele.",
	DGN_TIP_VA_ATROXUS_QUICK_DPS = "Quando o Creeper sair, bata nele primeiro.",
	DGN_TIP_VA_ATROXUS_QUICK_HEALER = "Tire os venenos do tanque e de quem ficou numa poça.",
	DGN_TIP_VA_ATROXUS_QUICK_TANK = "O Creeper te persegue: ande para longe dele para ele não te morder.",
	DGN_TIP_VA_ATROXUS_QUICK = "Rugido: O chefe ruge e sai um monstrinho, o Creeper. Todos batem nele até ele morrer.|nBafo: O chefe solta um bafo num jogador aleatório. Fique perto e saia dele.|nVeneno: Afaste-se dos respingos de veneno e das poças.",
	DGN_TIP_VA_ATROXUS_TANK = "Tanque: O Creeper fixa em você. Kite-o e não deixe que ele te acerte - cada mordida adiciona um stack de Sickening Bite, e os stacks tornam {SPELL:1222642} mortal. Mantenha-o perto do chefe para o DPS bater nos dois, e use um defensivo para a garra.",
	DGN_TIP_VA_ATROXUS_HEALER = "Curandeiro: Dissipe venenos: o veneno de {SPELL:1222642} no tanque e o Mind-Numbing Poison das poças. No Mítico e no Mythic+, use um cooldown de cura enquanto o Creeper estiver vivo.",

	DGN_TIP_VA_CHARONUS_STEPS = "1. {SPELL:1282770}: alguns jogadores são marcados, e alguns segundos depois surge um poço de gravidade embaixo deles. Ele te puxa e machuca. Saia, mas fique ao lado de um - você precisa dele para os orbes. O centro dele dá Atomized: nenhum dano e nenhuma cura por pouco tempo.|n2. {SPELL:1263982}: um orbe persegue 3 jogadores. O debuff dele machuca e te deixa mais lento a cada segundo. Passe ao lado de um poço de gravidade para o seu orbe te seguir para dentro dele - isso destrói os dois. Não pare lá dentro. Cada jogador usa um poço diferente.|n3. {SPELL:1227264} atinge todos, te empurra e deixa um efeito de dano de 20 segundos. Fiquem afastados uns dos outros e garanta que você não vai cair num poço.|n4. No Mítico e no Mythic+: {SPELL:1222758} - projéteis voam em direção a um jogador aleatório e empurram quem tocarem. Se for você, continue correndo; todos os outros saem do caminho.",
	DGN_TIP_VA_CHARONUS_QUICK_DPS = "Espere ao lado de um buraco, para a bola que te persegue cair rápido.",
	DGN_TIP_VA_CHARONUS_QUICK_HEALER = "Cure primeiro os jogadores que têm uma bola atrás deles.",
	DGN_TIP_VA_CHARONUS_QUICK_TANK = "Use um defensivo no golpe grande e aponte-o para longe dos amigos.",
	DGN_TIP_VA_CHARONUS_QUICK = "Poços: Buracos escuros aparecem no chão. Eles te puxam, então fique perto de um, mas não dentro.|nOrbes: Se uma bola te perseguir, passe ao lado de um buraco para a bola cair nele.|nExplosão: O chefe empurra todos para trás. Fique longe dos outros e não voe para dentro de um buraco.",
	DGN_TIP_VA_CHARONUS_TANK = "Tanque: {SPELL:1311923} é um golpe frontal no tanque. Use um defensivo e aponte-o para longe do grupo. Mantenha o chefe no meio dos três poços de gravidade, e não o vire através dos jogadores.",
	DGN_TIP_VA_CHARONUS_HEALER = "Curandeiro: Cure primeiro os jogadores com orbe - quanto mais tempo eles o carregam, mais forte ele bate. Depois de {SPELL:1227264} o grupo todo tem um efeito de dano de 20 segundos, e os poços de gravidade pulsam dano enquanto duram.",

	-- Nexus-Point Xenas ---------------------------------------------------------------
	DGN_TIP_NX_KASRETH_STEPS = "1. {SPELL:1251785} em você? Pise DENTRO de um feixe de leyline ({SPELL:1251183}) — ele limpa o debuff (atordoamento curto, troca justa).|n2. Os demais: NÃO cruzem as leylines (dano + lentidão acumulada).|n3. Energia cheia = {SPELL:1257509}: zona de impacto grande, abra espaço — depois ficam poças arcanas ({SPELL:1264048}).",
	DGN_TIP_NX_KASRETH_TANK = "Tanque: mantenha o chefe longe das leylines.",
	DGN_TIP_NX_KASRETH_HEALER = "Curandeiro: Sparkburn bate em todos depois de cada detonação.",

	DGN_TIP_NX_NYSARRA_STEPS = "1. Espalhem-se — os golpes de {SPELL:1249020} respingam a 14 metros.|n2. Matem os adds Null Vanguard ({SPELL:1252703}) RÁPIDO: o que sobreviver é devorado ({SPELL:1271684}), cura ela e estoura no grupo.|n3. Desvie das {SPELL:1264439}.",
	DGN_TIP_NX_NYSARRA_TANK = "Tanque: ela salta em você com um combo de talhos ({SPELL:1247937}) — defensivo, prepare-se para o golpe final.",
	DGN_TIP_NX_NYSARRA_HEALER = "Curandeiro: dano espalhado depois de {SPELL:1249020}; estouro de grupo se os adds sobreviverem à devoração.",

	DGN_TIP_NX_LOTHRAXION_STEPS = "1. {SPELL:1255503}: espalhem-se — impactos respingam 8 metros e geram Fractured Images.|n2. {SPELL:1257567}: ele se esconde entre os reflexos e todos canalizam — ache o Lothraxion VERDADEIRO e interrompa-o.|n3. Os reflexos piscam por aí com empurrões ({SPELL:1255531}); fique fora das {SPELL:1255310} no chão.",
	DGN_TIP_NX_LOTHRAXION_TANK = "Tanque: {SPELL:1255335} é um talho duplo que grava cicatrizes no chão — aponte-o para longe do grupo.",
	DGN_TIP_NX_LOTHRAXION_HEALER = "Curandeiro: DoTs Sagrados depois de cada {SPELL:1255503}; dano constante até a interrupção do Guile entrar.",

	-- Magisters' Terrace ---------------------------------------------------------------
	DGN_TIP_MT_ARCANOTRON_STEPS = "1. Quando ele reabastece ({SPELL:474345}), Energy Orbs são puxados até ele — intercepte-os; enquanto isso ele recebe +20% de dano: janela de burst!|n2. Jogadores acorrentados ({SPELL:1214038}) ficam enraizados (magia) — dissipe ou liberte-os.|n3. {SPELL:1214081} arremessa todos e deixa resíduo aos pés dele — saia de lá.",
	DGN_TIP_MT_ARCANOTRON_TANK = "Tanque: {SPELL:474496} te lança longe — mantenha as costas livres.",
	DGN_TIP_MT_ARCANOTRON_HEALER = "Curandeiro: dissipe {SPELL:1214038} (raiz mágica) rápido.",

	DGN_TIP_MT_SERANEL_STEPS = "1. {SPELL:1225193} pacifica todos FORA da Suppression Zone ({SPELL:1224903}) — entre NA zona para a onda (mas a zona te silencia, não demore).|n2. Purgue/roube a {SPELL:1248689} dele (+100% de velocidade de ataque) sempre que estiver ativa.|n3. {SPELL:1225787} quica para um jogador próximo — espalhem-se.",
	DGN_TIP_MT_SERANEL_TANK = "Tanque: uma Ward sem purge dobra a velocidade de ataque dele — defensivo até ela sumir.",
	DGN_TIP_MT_SERANEL_HEALER = "Curandeiro: jogadores marcados sofrem dano contínuo; lembre que dentro da zona não se conjura.",

	DGN_TIP_MT_GEMELLUS_STEPS = "1. {SPELL:1223847} (no início e na metade da vida): ele se divide em três.|n2. {SPELL:1253709}: vinculado a um deles? CORRA até ele e toque-o — isso quebra o vínculo e remove o escudo de absorção.|n3. {SPELL:1224299} te puxa — corra para fora de novo.",
	DGN_TIP_MT_GEMELLUS_TANK = "Tanque: reagrupe o trio depois de cada {SPELL:1223847} para os vinculados alcançarem o seu.",
	DGN_TIP_MT_GEMELLUS_HEALER = "Curandeiro: vinculados recebem +20% de dano até quebrarem o vínculo.",

	DGN_TIP_MT_DEGENTRIUS_STEPS = "1. {SPELL:1215897}: DoTs do Vazio com durações diferentes — quando o seu expirar, Entropy Orbs saem da SUA posição: afaste-se do grupo antes.|n2. {SPELL:1215087} quica em 4 pontos — SOAKE um impacto (um jogador por ponto), ou ele estoura em Void Destruction.|n3. {SPELL:1280113} esmaga o tanque e arremessa quem estiver a menos de 8 metros — dê espaço ao tanque.",
	DGN_TIP_MT_DEGENTRIUS_TANK = "Tanque: defensivo para {SPELL:1280113}; tanque-o longe do grupo.",
	DGN_TIP_MT_DEGENTRIUS_HEALER = "Curandeiro: os DoTs de Entropy batem forte — mantenha os portadores de pé enquanto se reposicionam.",

	-- Skyreach ----------------------------------------------------------------------
	DGN_TIP_SR_RANJIT_STEPS = "1. {SPELL:1258148} voa em linha reta à frente dele — dê um passo para o lado.|n2. {SPELL:156793}: um impacto no centro mais redemoinhos errantes que te lançam — continue ziguezagueando.|n3. {SPELL:153757} atinge todos com sangramento — fique cheio.|n4. {SPELL:1252733} sopra os alvos para longe — veja o que há atrás de você.",
	DGN_TIP_SR_RANJIT_TANK = "Tanque: mantenha-o fora das rotas dos vórtices.",
	DGN_TIP_SR_RANJIT_HEALER = "Curandeiro: dano de grupo mais sangramentos depois de cada {SPELL:153757}.",

	DGN_TIP_SR_ARAKNATH_STEPS = "1. {SPELL:154162}: constructos canalizam luz no chefe e o CURAM — fique num feixe para bloqueá-lo.|n2. {SPELL:154115}: um golpe de braço de um lado só — ser atingido acumula um debuff de dano brutal.|n3. {SPELL:154135} atinge todos — esteja pronto.",
	DGN_TIP_SR_ARAKNATH_TANK = "Tanque: nunca soake os feixes você mesmo — o golpe dele cai bem durante o soak.",
	DGN_TIP_SR_ARAKNATH_HEALER = "Curandeiro: quem soaka feixes sofre dano contínuo; cura de grupo no {SPELL:154135}.",

	DGN_TIP_SR_RUKHRAN_STEPS = "1. {SPELL:1253527}: 3 segundos de penas para todo lado — quebre a linha de visão atrás de um pilar.|n2. {SPELL:1253510} atinge o grupo e invoca um Sunwing que fixa em alguém e pulsa fogo — mate-o rápido; o fixado mantém distância.|n3. Repita — penas atrás de cobertura, ave no chão rápido.",
	DGN_TIP_SR_RUKHRAN_TANK = "Tanque: defensivo para {SPELL:1253519} (golpe grande + DoT de queimadura).",
	DGN_TIP_SR_RUKHRAN_HEALER = "Curandeiro: dano de grupo pulsante enquanto um Sunwing viver — peça a morte dele.",

	DGN_TIP_SR_VIRYX_STEPS = "1. {SPELL:154396}: uma conjuração de 3 segundos que arrebenta o tanque — INTERROMPA, toda vez.|n2. {SPELL:1253998}: um Solar Zealot agarra um jogador para jogá-lo da sacada — libertem-no rápido.|n3. {SPELL:1253531} em você? Leve-o bem para longe — ele deixa Blazing Ground.",
	DGN_TIP_SR_VIRYX_TANK = "Tanque: cada {SPELL:154396} que passar dói — mantenham a ordem de interrupções firme.",
	DGN_TIP_SR_VIRYX_HEALER = "Curandeiro: {SPELL:1253538} coloca DoTs de fogo em vários jogadores ao mesmo tempo.",

	-- Pit of Saron ----------------------------------------------------------------
	DGN_TIP_PS_GARFROST_STEPS = "1. {SPELL:1262029}: a forja pulsa gelo acumulado — ESCONDA-SE ATRÁS de um bloco de saronita, ele bloqueia a radiação.|n2. {SPELL:1261546} esmaga tudo ao redor do alvo principal — fique a 5+ metros do tanque; perto do minério, o golpe quebra o minério em vez de atordoar.|n3. {SPELL:1261847} atinge todos e estilhaça TODO o minério — minério novo vem via {SPELL:1261286}.|n4. Fique fora do {SPELL:1261799}.",
	DGN_TIP_PS_GARFROST_TANK = "Tanque: estacione ao lado de um bloco de minério — {SPELL:1261546} esmaga o minério, não você.",
	DGN_TIP_PS_GARFROST_HEALER = "Curandeiro: pico de grupo no {SPELL:1261847}; gelo acumulado em quem ficar sem cobertura.",

	DGN_TIP_PS_KRICKICK_STEPS = "1. {SPELL:1264363}: Ick fixa e persegue um jogador espalhando Blight e Plague Globs — corra largo; o resto continua batendo.|n2. {SPELL:1264027}: Krick teleporta para um círculo ritual e invoca Shades — troquem e matem.|n3. {SPELL:1264336}: desvie da onda e dos globs rolando até você.|n4. Nunca pise no Blight ({SPELL:1264299}).",
	DGN_TIP_PS_KRICKICK_TANK = "Tanque: {SPELL:1264287} deixa uma poça em você — aponte-a para a borda.",
	DGN_TIP_PS_KRICKICK_HEALER = "Curandeiro: mantenha o perseguido vivo; dano de grupo no {SPELL:1264336}.",

	DGN_TIP_PS_TYRANNUS_STEPS = "1. {SPELL:1262772} congela os Bone Piles ao redor do alvo — fique perto de pilhas quando for marcado: pilhas congeladas não levantam adds.|n2. {SPELL:1263406} levanta as pilhas restantes — Plaguespreaders primeiro.|n3. Continue desviando de {SPELL:1263756} e do {SPELL:1276948} do Rimefang.|n4. {SPELL:1276648} = golpe de grupo + DoT, e pilhas infundidas dão adds piores.",
	DGN_TIP_PS_TYRANNUS_TANK = "Tanque: {SPELL:1262582} te catapulta e acumula +200% de dano sombrio — defensivo e segure firme.",
	DGN_TIP_PS_TYRANNUS_HEALER = "Curandeiro: DoTs de grupo depois de {SPELL:1276648}; pico no tanque logo após o Brand.",

	-- Seat of the Triumvirate --------------------------------------------------------
	DGN_TIP_ST_ZURAAL_STEPS = "1. {SPELL:1268916} atinge tudo NA FRENTE dele — nunca fique de frente para o chefe.|n2. {SPELL:1263304} (energia cheia): ele puxa todos e depois estoura com empurrão — saia a tempo; os adds também são puxados.|n3. {SPELL:1263399} gera adds Coalesced Void — limpe-os antes do Crashing Void.|n4. {SPELL:1263282} deixa Void Sludge ({SPELL:244588}) — mantenha o chão limpo.",
	DGN_TIP_ST_ZURAAL_TANK = "Tanque: defensivo para {SPELL:1263440} (talho triplo).",
	DGN_TIP_ST_ZURAAL_HEALER = "Curandeiro: golpe de grupo grande no {SPELL:1263304}.",

	DGN_TIP_ST_SAPRISH_STEPS = "1. As Void Bombs ({SPELL:247175}) caem nas posições dos jogadores — NÃO toque nelas; deixe-as nas bordas.|n2. {SPELL:1280064}: sombras disparam contra cada jogador e detonam bombas que cruzarem — trace sua linha livre de bombas.|n3. {SPELL:1263523} acende TODAS as bombas de uma vez — quanto menos bombas, mais suave.|n4. Interrompa o {SPELL:248831} do Shadewing (golpe de grupo + desorientação).",
	DGN_TIP_ST_SAPRISH_TANK = "Tanque: mantenha o trio junto; o bote do Darkfang ({SPELL:245738}) deixa a vítima sangrando.",
	DGN_TIP_ST_SAPRISH_HEALER = "Curandeiro: vítimas do bote sangram; estouro de grupo no {SPELL:1263523}.",

	DGN_TIP_ST_NEZHAR_STEPS = "1. {SPELL:1263528} arremessa todos — cuidado com a posição perto de tempestades.|n2. {SPELL:1263538} e os {SPELL:1277358} espalham caos — mate tentáculos, desvie das Umbral Waves do portal.|n3. As zonas de {SPELL:1263532} batem forte, dentro é pior — fora, rápido.|n4. {SPELL:244750} arrebenta o tanque — interrompa quando puder.",
	DGN_TIP_ST_NEZHAR_TANK = "Tanque: aguente {SPELL:244750} quando não houver interrupção pronta.",
	DGN_TIP_ST_NEZHAR_HEALER = "Curandeiro: {SPELL:1263542} = vários DoTs roendo ao mesmo tempo.",

	DGN_TIP_ST_LURA_STEPS = "1. As Notes of Despair continuam irradiando ({SPELL:1265421}) até serem silenciadas — direcione seu {SPELL:1265426} ATRAVÉS das notas (o feixe também atinge aliados na linha, mire livre).|n2. {SPELL:1265689}: 20 segundos de dor ao redor de cada nota ativa — quebre as notas rápido.|n3. {SPELL:1264151}: feixes do Vazio rotativos — mova-se com as brechas.|n4. {SPELL:1266003} é uma canalização letal de 10 segundos — todos os defensivos, e cure com tudo.",
	DGN_TIP_ST_LURA_TANK = "Tanque: depois de {SPELL:1266001} todos voam — reagrupem rápido.",
	DGN_TIP_ST_LURA_HEALER = "Curandeiro: golpes de grupo de {SPELL:1265421} mais as auras das notas — quebrar notas É o plano de cura.",

	-- Algeth'ar Academy ----------------------------------------------------------------
	DGN_TIP_AA_VEXAMUS_STEPS = "1. Os {SPELL:385974} derivam até o chefe — soakem, um jogador por orbe (golpe pequeno); cada orbe que ELE absorver estoura no grupo todo.|n2. {SPELL:386173}: leve a sua para longe — ela estoura numa poça de {SPELL:386201}.|n3. Energia cheia = {SPELL:388537}: golpe de grupo mais erupções repetidas sob os jogadores — continue se movendo.",
	DGN_TIP_AA_VEXAMUS_TANK = "Tanque: {SPELL:385958} explode tudo na frente dele — defensivo, aponte-o para longe do grupo.",
	DGN_TIP_AA_VEXAMUS_HEALER = "Curandeiro: portadores de bomba sofrem dano contínuo; dano de grupo por cada orbe que chegar ao chefe.",

	DGN_TIP_AA_ANCIENT_STEPS = "1. {SPELL:388796}: por 4 segundos sementes brotam sob todos — desvie; sementes perdidas deixam Lashers dormentes.|n2. Com energia cheia ({SPELL:388923}) TODOS os Lashers dormentes acordam de uma vez — limpe-os antes.|n3. {SPELL:388623} arremessa um galho que vira um add grande — mate-o e INTERROMPA o {SPELL:396640} dele.",
	DGN_TIP_AA_ANCIENT_TANK = "Tanque: {SPELL:388544} dobra o dano físico que você recebe — defensivo, toda vez.",
	DGN_TIP_AA_ANCIENT_HEALER = "Curandeiro: limpe {SPELL:389033} (veneno) antes de acumular alto.",

	DGN_TIP_AA_CRAWTH_STEPS = "1. {SPELL:377004} explode sob cada jogador e interrompe conjurações — PARE de conjurar, depois espalhem-se.|n2. {SPELL:377034}: ela encara alguém e varre um cone naquela direção — saia dele.|n3. {SPELL:377182}: marque num gol — o gol de fogo a atordoa e ela recebe 75% mais dano.",
	DGN_TIP_AA_CRAWTH_TANK = "Tanque: defensivo para {SPELL:376997} (golpe + sangramento de 10 s).",
	DGN_TIP_AA_CRAWTH_HEALER = "Curandeiro: dano de grupo pesado depois do grito; o tanque sangra.",

	DGN_TIP_AA_DORAGOSA_STEPS = "1. {SPELL:374341} em você? Leve-a para longe do grupo — ela estoura em 8 metros.|n2. {SPELL:388820} puxa todos e depois explode — CORRA PARA FORA antes do estouro.|n3. {SPELL:389011} acumula a cada mecânica que você comer — com 3 stacks vira um Arcane Rift; fique limpo.|n4. Fique fora do chão de {SPELL:389007}.",
	DGN_TIP_AA_DORAGOSA_TANK = "Tanque: defensivo para {SPELL:1282251}.",
	DGN_TIP_AA_DORAGOSA_HEALER = "Curandeiro: vigie os stacks de {SPELL:389011} — portadores sofrem mais por stack.",
	DGN_TIP_KR_COUNCIL_STEPS = "1. O conselho luta um de cada vez: Kula, depois Aka'ali, depois Zanazal. Um conselheiro derrotado volta de vez em quando para usar uma habilidade. A luta acaba quando Zanazal morre.|n2. Kula: afaste-se dela durante {SPELL:266206} e desvie dos machados que rolam por aí depois. {SPELL:266231} faz um jogador aleatório sangrar - use um defensivo.|n3. Aka'ali: {SPELL:267494} investe contra um jogador. Todos se juntam nesse jogador para dividir o dano.|n4. Zanazal: interrompa {SPELL:267273}. Quando ele chamar totens ({SPELL:267060}), mate primeiro o Explosive Totem, depois o Thundering Totem, depois o Torrent Totem.",
	DGN_TIP_KR_COUNCIL_QUICK_DPS = "Fique no grupo da investida, interrompa o veneno e mate primeiro o totem que explode.",
	DGN_TIP_KR_COUNCIL_QUICK_HEALER = "Cure o sangramento dos machados e deixe todos cheios antes da investida.",
	DGN_TIP_KR_COUNCIL_QUICK_TANK = "Quando Aka'ali te jogar longe, corra dela até o debuff sumir.",
	DGN_TIP_KR_COUNCIL_QUICK = "Kula: afaste-se do giro dela e desvie dos machados voadores.|nAka'ali: ela investe contra um jogador. Todos ficam em cima desse jogador para dividir o golpe.|nZanazal: interrompa o feitiço de veneno dele e mate primeiro o totem que explode.",
	DGN_TIP_KR_COUNCIL_DPS = "DPS: fique no grupo de {SPELL:267494}, continue interrompendo {SPELL:267273} e troque para o Explosive Totem assim que ele aparecer.",
	DGN_TIP_KR_COUNCIL_HEALER = "Curandeiro: cure o sangramento de {SPELL:266231} e encha todos antes de {SPELL:267494}. Em Zanazal, {SPELL:1305810} salta entre os jogadores, e Poison Nova bate em todos se não for interrompido.",
	DGN_TIP_KR_COUNCIL_TANK = "Tanque: {SPELL:266237} te joga para trás e faz você sofrer muito mais dano físico. Kite a Aka'ali até o debuff sumir, ou use um defensivo grande.",
	DGN_TIP_KR_DAZAR_STEPS = "1. Fase 1: Dazar luta com seu raptor Reban. Mate Reban primeiro e interrompa o {SPELL:269369} dele, um medo. Reban salta em um jogador com {SPELL:269230} e morde em cone - saia dele.|n2. {SPELL:1303115}: Dazar salta em dois jogadores. Esses dois se espalham para não se atingirem.|n3. Com 80% de vida, Dazar monta seu raptor T'zala. Agora {SPELL:1303327} salta em quatro jogadores e também atinge o grupo todo - espalhem-se e estejam com a vida cheia.|n4. {SPELL:1303267} atinge o grupo todo e queima por 15 segundos. Logo depois, lanças caem onde os jogadores estão - continue se movendo e desvie dos círculos de Impaling Spear.|n5. No Mítico e no Mythic+: {SPELL:1303267} também fortalece os golpes dele - eles mandam uma onda de ouro para a frente. O tanque vira o chefe para longe do grupo.",
	DGN_TIP_KR_DAZAR_QUICK_DPS = "Mate o raptor pequeno primeiro e interrompa o rugido dele.",
	DGN_TIP_KR_DAZAR_QUICK_HEALER = "Guarde suas curas grandes para o golpe de ouro e os saltos do raptor.",
	DGN_TIP_KR_DAZAR_QUICK_TANK = "Use seu maior defensivo para o combo de espada e mantenha o rei virado para longe.",
	DGN_TIP_KR_DAZAR_QUICK = "Raptor: mate o raptor pequeno primeiro e interrompa o rugido assustador dele.|nMontado: o rei monta seu raptor grande. Espalhem-se quando ele saltar e estejam com a vida cheia.|nOuro: um golpe grande de fogo em todos, e depois caem lanças onde você está. Continue se movendo.",
	DGN_TIP_KR_DAZAR_DPS = "DPS: mate Reban primeiro e interrompa {SPELL:269369}. Mantenha espaço livre para os alvos do salto se espalharem e para você desviar das lanças.",
	DGN_TIP_KR_DAZAR_HEALER = "Curandeiro: guarde seus cooldowns grandes para {SPELL:1303267} e {SPELL:1303327}. Fique de olho nos sangramentos de Impaling Spear e {SPELL:1303488}.",
	DGN_TIP_KR_DAZAR_TANK = "Tanque: defensivo grande para {SPELL:268586} - os golpes ficam mais fortes perto do fim. Quando T'zala entra, {SPELL:1303488} também te atinge e faz você sofrer mais dano físico, então planeje seus cooldowns para os dois. Vire Dazar para longe do grupo.",
	DGN_TIP_KR_MCHIMBA_STEPS = "1. {SPELL:267618}: o chefe drena um jogador. Todos os outros saem dos círculos de ácido que ele espalha. Se for em você, use um defensivo. Quando acaba, você fica lento e fraco até ser curado acima de 90% de vida.|n2. {SPELL:1311956} mira um jogador e deixa chão em chamas. Solte-o na borda, longe do chefe e dos caixões.|n3. {SPELL:1312146} atinge o grupo todo e abre caixões: saem duas Half-Finished Mummies. Mate-as e interrompa o Wretched Discharge delas.|n4. {SPELL:267702}: um jogador fica preso em um dos caixões. Se for você, aperte o botão Struggle para seu caixão tremer. Todos os outros: achem o caixão que treme e cliquem nele rápido. Cada caixão vazio que ele abre antes libera uma Finished Mummy.",
	DGN_TIP_KR_MCHIMBA_QUICK_DPS = "Interrompa as múmias e ajude a achar o caixão que treme.",
	DGN_TIP_KR_MCHIMBA_QUICK_HEALER = "Cure o jogador drenado até quase cheio; isso tira a lentidão.",
	DGN_TIP_KR_MCHIMBA_QUICK_TANK = "Pegue as múmias e mantenha-as ao lado do chefe.",
	DGN_TIP_KR_MCHIMBA_QUICK = "Dreno: se o chefe drenar você, use um defensivo. Os outros saem dos círculos de ácido.|nFogo: deixe sua poça de fogo na borda, longe do chefe e dos caixões.|nCaixão: um amigo fica preso num caixão. Ache o que treme e clique nele rápido.",
	DGN_TIP_KR_MCHIMBA_DPS = "DPS: interrompa o Wretched Discharge das múmias. Durante {SPELL:267702}, vá até os caixões e procure o que treme - não clique ao acaso.",
	DGN_TIP_KR_MCHIMBA_HEALER = "Curandeiro: passe para o alvo de {SPELL:267618} na hora e cure-o acima de 90% depois - isso acaba com a lentidão. Encha o grupo antes de {SPELL:1312146}. Wretched Discharge é uma doença que você pode dissipar.",
	DGN_TIP_KR_MCHIMBA_TANK = "Tanque: pegue as múmias e junte-as perto de Mchimba para o cleave. Não as deixe na frente de um caixão.",
	DGN_TIP_KR_SERPENT_STEPS = "1. {SPELL:265773} coloca ouro ardente em dois jogadores. Quando acaba, você deixa uma poça de {SPELL:265914} onde está - vá até a borda antes e solte-a ao lado das outras poças.|n2. {SPELL:265923} desperta as poças como Animated Gold, que rasteja até o chefe. Mate, desacelere ou atordoe-os antes que algum o alcance - cada um que chega dá a ele um escudo e mais dano.|n3. {SPELL:1311987}: cinco segundos de dano no grupo todo, que também empurra você para trás. Esteja com a vida cheia e use um defensivo.|n4. Nunca fique nas poças de ouro.",
	DGN_TIP_KR_SERPENT_QUICK_DPS = "Mate as bolhas de ouro primeiro - nenhuma pode chegar ao chefe.",
	DGN_TIP_KR_SERPENT_QUICK_HEALER = "Cure os dois jogadores com a queimadura de ouro e guarde uma cura grande para o vento.",
	DGN_TIP_KR_SERPENT_QUICK_TANK = "Use um defensivo para o golpe de cauda e puxe o chefe para longe das bolhas de ouro.",
	DGN_TIP_KR_SERPENT_QUICK = "Ouro: quando sua queimadura de ouro acabar, você deixa uma poça. Solte-a na borda, ao lado das outras poças.|nAdds: as poças despertam e rastejam até o chefe. Mate todos antes que toquem nele.|nVento: um vento forte fere todos e empurra você para trás. Esteja com a vida cheia.",
	DGN_TIP_KR_SERPENT_DPS = "DPS: primeiro o Animated Gold, depois o chefe. Use lentidões, atordoamentos e cleave, e mantenha todas as poças juntas para os adds despertarem num bolo só.",
	DGN_TIP_KR_SERPENT_HEALER = "Curandeiro: cure os dois alvos de {SPELL:265773} durante a queimadura. Use um cooldown de cura para {SPELL:1311987}.",
	DGN_TIP_KR_SERPENT_TANK = "Tanque: defensivo para {SPELL:265910}. Quando o Animated Gold despertar, puxe o chefe para longe dele para os DPS terem mais tempo.",
	DGN_TIP_RL_KOKIA_STEPS = "1. Molten Boulder ({SPELL:372110}): Kokia joga uma pedra em chamas que rola em linha reta e depois explode. Saia do caminho dela e fique longe do lugar onde ela para. Ela empurra quem ela tocar.|n2. Ritual of Blazebinding ({SPELL:372864}): um add de fogo, o Blazebound Firestorm, aparece num jogador e queima todos a até 12 metros. Se for em você, afaste-se do grupo, mas fique perto do chefe.|n3. Todos trocam para o Blazebound Firestorm na hora e interrompem o Blaze Volley dele.|n4. Antes de o add morrer, afaste-se pelo menos 20 metros dele. A explosão de morte dele (Burnout) bate muito forte.|n5. No Mítico e no Mythic+: chão em chamas ({SPELL:372820}) fica no piso. Saia dele e mova a luta devagar pela sala para sempre haver espaço livre.",
	DGN_TIP_RL_KOKIA_QUICK_DPS = "Bata primeiro no add de fogo, interrompa os feitiços dele e corra para longe antes de ele morrer.",
	DGN_TIP_RL_KOKIA_QUICK_HEALER = "O add de fogo queima todos e o tanque sangra, então cure forte e fique longe quando ele morrer.",
	DGN_TIP_RL_KOKIA_QUICK_TANK = "Use um defensivo para cada combo de golpes e leve o chefe devagar pela sala.",
	DGN_TIP_RL_KOKIA_QUICK = "Pedra: uma pedra de fogo rola em linha reta, então saia do caminho dela.|nAdd de fogo: quando um monstro de fogo aparecer, todos batem nele e interrompem os feitiços dele.|nAdd morrendo: corra para bem longe dele antes de ele morrer, porque ele explode.",
	DGN_TIP_RL_KOKIA_DPS = "DPS: troque para o Blazebound Firestorm assim que ele surgir e interrompa o Blaze Volley dele. Corpo a corpo: corra 20 metros para fora antes de ele morrer.",
	DGN_TIP_RL_KOKIA_HEALER = "Curandeiro: a conjuração Inferno do add queima o grupo todo, e Searing Blows deixa um sangramento no tanque. Fique você mesmo fora da explosão de morte do add.",
	DGN_TIP_RL_KOKIA_TANK = "Tanque: use um defensivo para cada Searing Blows ({SPELL:372858}): quatro golpes rápidos que acumulam um sangramento. Mantenha Kokia perto do add para os DPS fazerem cleave, mas saia da explosão de morte dele, de 20 metros. Mova-a devagar pela sala para manter espaço livre.",
	DGN_TIP_RL_KYRAKKA_STEPS = "1. Erkhart luta no chão enquanto sua dragoa Kyrakka voa em volta da plataforma. Bata em Kyrakka sempre que ela estiver ao alcance: ela deve morrer primeiro. Desvie do cone de fogo dela ({SPELL:381525}).|n2. Inferno Spit ({SPELL:381602}): 2 jogadores queimam por 6 segundos, depois explodem e deixam fogo no chão ({SPELL:384773}). Se for você, vá até a borda, longe do grupo, antes de acabar.|n3. Winds of Change ({SPELL:381517}): o vento empurra os jogadores e o fogo, numa ordem fixa (noroeste, sudoeste, sudeste, nordeste). Ande contra ele e não seja jogado no fogo. Solte seu fogo onde o vento o leve para longe do grupo.|n4. Quando um deles chegar a uns 40 a 50% de vida (os guias divergem), Kyrakka pousa e Erkhart a monta. Agora 3 jogadores recebem Inferno Spit. Guarde cooldowns para essa parte.|n5. No Mítico e no Mythic+: Interrupting Cloudburst ({SPELL:381516}) atinge todos e bloqueia seus feitiços por 2 segundos. Pare de conjurar logo antes de ele cair.",
	DGN_TIP_RL_KYRAKKA_QUICK_DPS = "Bata na dragoa primeiro, e no Mítico pare de conjurar logo antes de a tempestade atingir todos.",
	DGN_TIP_RL_KYRAKKA_QUICK_HEALER = "Tire o debuff do tanque depois de cada golpe grande e cure os jogadores que estão queimando.",
	DGN_TIP_RL_KYRAKKA_QUICK_TANK = "Use um defensivo para o golpe grande dele e peça ao curandeiro para tirar o debuff.",
	DGN_TIP_RL_KYRAKKA_QUICK = "Dragoa: bata na dragoa sempre que conseguir alcançá-la e desvie do bafo de fogo dela.|nFogo: se você estiver queimando, vá até a borda para seu fogo cair longe do grupo.|nVento: o vento empurra você e o fogo, então ande contra ele e fique fora das chamas.",
	DGN_TIP_RL_KYRAKKA_DPS = "DPS: bata em Kyrakka sempre que conseguir alcançá-la e guarde o burst para quando ela pousar. No Mítico e no Mythic+, casters param de conjurar antes de Interrupting Cloudburst.",
	DGN_TIP_RL_KYRAKKA_HEALER = "Curandeiro: dissipe Stormslam do tanque depois de cada golpe, antes do próximo. Os alvos de Inferno Spit sofrem dano pesado, então cure-os. No Mítico e no Mythic+, pare de conjurar antes de Interrupting Cloudburst.",
	DGN_TIP_RL_KYRAKKA_TANK = "Tanque: use um defensivo para cada Stormslam ({SPELL:381512}). Ele deixa um debuff mágico acumulável que faz você sofrer mais dano de natureza, então peça dispel. Tire Erkhart do fogo rápido depois de cada vento.",
	DGN_TIP_RL_MELIDRUSSA_STEPS = "1. Hailburst ({SPELL:1307297}): ela atinge o grupo todo e joga uma mina de gelo em cada jogador. Fiquem juntos perto de uma borda para as minas caírem num só lugar. Nunca toque numa mina: ela te joga para cima e reduz pela metade a velocidade dos seus ataques e feitiços por 20 segundos.|n2. Chillstorm ({SPELL:1307308}): uma tempestade de gelo cai num jogador e puxa todos para o centro dela. Se for em você, corra para longe do grupo. Fique fora do centro ({SPELL:372963}): lá o dano de gelo é dobrado. Depois de 7 segundos ela explode e empurra todos para longe, então não fique com minas atrás de você.|n3. Com 66% e 33% de vida ela chama Infused Whelps ({SPELL:373046}). Mate-os rápido.|n4. Interrompa Frigid Shard, o feitiço que ela lança no tanque.|n5. No Mítico e no Mythic+: depois dos filhotes ela se esconde num escudo de gelo (Ice Bulwark) e pulsa em todos um dano de gelo que só aumenta (Frost Overload). Quebre o escudo rápido e depois interrompa-a. Os guias dizem que a interrupção funciona quando o escudo some.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_DPS = "Mate os dragõezinhos primeiro, e no Mítico quebre o escudo de gelo dela.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_HEALER = "Cure o grupo todo durante as explosões de gelo e a tempestade.",
	DGN_TIP_RL_MELIDRUSSA_QUICK_TANK = "Pegue os dragõezinhos na hora e interrompa o feitiço que ela lança em você.",
	DGN_TIP_RL_MELIDRUSSA_QUICK = "Minas: fiquem juntos perto de uma borda quando ela jogar gelo, e nunca toque nas minas.|nTempestade: se a tempestade for em você, corra para longe de todos e fique fora do centro dela.|nFilhotes: mate os dragõezinhos rápido, e no Mítico quebre também o escudo de gelo dela.",
	DGN_TIP_RL_MELIDRUSSA_DPS = "DPS: troque para os filhotes assim que surgirem. No Mítico e no Mythic+, guarde o burst para quebrar o escudo de gelo, depois interrompa Frost Overload.",
	DGN_TIP_RL_MELIDRUSSA_HEALER = "Curandeiro: Hailburst e Chillstorm atingem o grupo todo, e a tempestade explode no fim. Encha o pessoal antes da explosão. No Mítico e no Mythic+, a fase do escudo adiciona em todos um dano de gelo que só aumenta até o escudo quebrar.",
	DGN_TIP_RL_MELIDRUSSA_TANK = "Tanque: pegue os Infused Whelps na hora e mantenha-os no chefe para o cleave. Os golpes deles acumulam Cold Claws em você; stacks demais te congelam, então eles precisam morrer rápido. Interrompa Frigid Shard se ninguém mais fizer isso.",
	DGN_TIP_TS_ADDERIS_STEPS = "1. Storm Blessed protege um dos dois chefes, e esse chefe quase não sofre dano. Bata no que está SEM o escudo (Adderis no início) e troque assim que o escudo mudar.|n2. {SPELL:1311805}: se você estiver marcado, vá até a borda e solte sua poça lá. As poças silenciam você, então fique fora delas.|n3. {SPELL:1289059}: todos são empurrados para trás. Espalhem-se um pouco e fiquem num lugar onde o empurrão não te jogue numa poça.|n4. {SPELL:1288049} vem logo depois do empurrão: corra de volta e junte-se no chefe para dividir o golpe, depois saiam juntos antes da segunda explosão.",
	DGN_TIP_TS_ADDERIS_QUICK_DPS = "Bata só no chefe sem o escudo e troque rápido quando ele mudar.",
	DGN_TIP_TS_ADDERIS_QUICK_HEALER = "Cure os jogadores atingidos pelo vento e encha todos antes do empurrão.",
	DGN_TIP_TS_ADDERIS_QUICK_TANK = "Use um defensivo para Overload e mantenha os dois chefes bem próximos.",
	DGN_TIP_TS_ADDERIS_QUICK = "Escudo: bata no chefe sem o escudo e troque quando o escudo pular.|nPoças: se você estiver marcado, solte sua poça na borda e fique fora das poças.|nEmpurrão: depois do empurrão, corra de volta e fiquem juntos no chefe para dividir o golpe.",
	DGN_TIP_TS_ADDERIS_DPS = "DPS: nunca bata no chefe com escudo - ele quase não sofre dano. Troque assim que o escudo mudar, mesmo no meio da sua rotação.",
	DGN_TIP_TS_ADDERIS_HEALER = "Curandeiro: cure os jogadores atingidos por Gust. O empurrão direto para o soak do grupo é o momento mais perigoso - deixe todos cheios antes dele.",
	DGN_TIP_TS_ADDERIS_TANK = "Tanque: use um defensivo para {SPELL:1311804}. Mantenha os dois chefes bem próximos para o grupo trocar de alvo sem correr pelas poças.",
	DGN_TIP_TS_AVATAR_STEPS = "1. Você vence curando o Avatar até a vida cheia, não matando. Primeiro mate os Essence Defilers: o {SPELL:1301202} deles impede toda cura no Avatar.|n2. Mate o Corrupted Guardian. Ele deixa três orbes de Corrupted Lifeforce: três DPS diferentes pegam um cada, rápido. Um orbe pego cura o Avatar; um orbe perdido explode no grupo todo.|n3. Twisted Hexxers: interrompa Flame Shock. Pegou {SPELL:1311981}? Afaste-se do grupo antes de acabar e deixe a zona lá.|n4. Quando os Defilers morrerem, cure o Avatar. Faithless Tormentors surgem e perseguem o curandeiro: atordoe e desacelere-os e leve-os abaixo de 25% de vida - o Avatar então os devora e se cura.",
	DGN_TIP_TS_AVATAR_QUICK_DPS = "Mate os Defilers primeiro, depois pegue um orbe cada.",
	DGN_TIP_TS_AVATAR_QUICK_HEALER = "Cure o Avatar quando os Defilers morrerem e continue fugindo dos perseguidores.",
	DGN_TIP_TS_AVATAR_QUICK_TANK = "Segure o add grande num canto e fique longe dos orbes.",
	DGN_TIP_TS_AVATAR_QUICK = "Objetivo: mate os Defilers primeiro, depois cure o Avatar até a vida cheia para vencer.|nOrbes: quando o add grande morrer, três DPS pegam um orbe cada, rápido.|nPerseguidores: atordoe os adds que perseguem o curandeiro e deixe-os com pouca vida; o Avatar então os devora.",
	DGN_TIP_TS_AVATAR_DPS = "DPS: mate os Essence Defilers primeiro, depois o Guardian. Pegue um orbe cada (ele te dá {SPELL:1300877}, então use um defensivo), interrompa Flame Shock e atordoe e derrube os Tormentors com AoE.",
	DGN_TIP_TS_AVATAR_HEALER = "Curandeiro: cure o Avatar assim que os Defilers morrerem - é assim que se vence a luta. Os Tormentors correm até você e cada golpe reduz sua cura, então continue se movendo. Deixe os orbes para os DPS.",
	DGN_TIP_TS_AVATAR_TANK = "Tanque: segure o Corrupted Guardian num canto, longe do grupo, e use um defensivo para Tainted Strike. Não pegue orbes: {SPELL:1300877} faz você sofrer muito mais dano físico.",
	DGN_TIP_TS_GALVAZZT_STEPS = "1. {SPELL:1291618}: três torres disparam feixes em Galvazzt. Fique num feixe, entre a torre e o chefe, para ele não ganhar energia.|n2. Dividam os feixes: um jogador por feixe, e revezem entre as levas. Bloquear um feixe te dá {SPELL:266923}: dano ao longo do tempo e mais dano físico recebido.|n3. Nunca deixe um feixe livre. Com energia cheia ele conjura Consume Charge, que bate forte no grupo e muitas vezes causa wipe.|n4. {SPELL:1309525}: dano no grupo todo, e deixa {SPELL:1291815} no chão. Saia de lá.",
	DGN_TIP_TS_GALVAZZT_QUICK_DPS = "Fique no seu feixe, mesmo que não consiga bater no chefe de lá.",
	DGN_TIP_TS_GALVAZZT_QUICK_HEALER = "Mantenha vivos os jogadores nos feixes.",
	DGN_TIP_TS_GALVAZZT_QUICK_TANK = "Fique fora dos feixes e tire o chefe das zonas no chão.",
	DGN_TIP_TS_GALVAZZT_QUICK = "Feixes: fique num feixe, entre a torre e o chefe, para ele não carregar.|nRevezamento: um jogador por feixe, revezem e nunca deixem um feixe livre.|nChão: depois do golpe grande no grupo, saia da zona no chão.",
	DGN_TIP_TS_GALVAZZT_DPS = "DPS: seu feixe vem antes do seu dano - não saia dele para bater no chefe. Reveze com os outros e use um defensivo na sua vez.",
	DGN_TIP_TS_GALVAZZT_HEALER = "Curandeiro: quem soaka os feixes sofre dano constante - mantenha-os altos, e pegue um feixe você mesmo se precisar. Tenha um cooldown pronto para {SPELL:1309525}.",
	DGN_TIP_TS_GALVAZZT_TANK = "Tanque: não faça soak dos feixes - {SPELL:266923} faz você sofrer muito mais dano físico. Tire o chefe de cada {SPELL:1291815}, para um lugar onde os feixes continuem fáceis de alcançar.",
